from __future__ import annotations

import os


# Updates are ordinary, readable Python files selected explicitly by the user.
# Their manifest validates platform, version, size and SHA-256 integrity; no
# encrypted loader, signing key, in-memory compilation or hidden executable is used.
_JAI_UPDATE_FORMAT = "JewelryAIApplicationUpdate"
_JAI_UPDATE_PROTOCOL = 3
_JAI_UPDATE_APP_ID = "JewelryAISearch"
_JAI_BUILTIN_VERSION = "0.90.0"
# Free release: the old trial secret was removed, the trial gate no longer exists.
_JAI_TRIAL_SECRET_PARTS = ()
_JAI_BOOTSTRAP_PATH = str(
    globals().get("_JAI_BOOTSTRAP_PATH") or globals().get("__file__", "")
)


def _jai_version_tuple(value):
    import re as _re

    match = _re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", str(value or "").strip())
    if not match:
        raise ValueError("Номер версии должен иметь вид 0.89.1")
    return tuple(int(part) for part in match.groups())


def _jai_update_platform():
    import sys as _sys

    if os.name == "nt":
        return "windows"
    if _sys.platform.startswith("linux"):
        return "linux"
    return "unsupported"


def _jai_source_version(source_bytes):
    import re as _re

    match = _re.search(
        rb'(?m)^APP_VERSION\s*=\s*["\'](\d+\.\d+\.\d+)["\']\s*$',
        source_bytes,
    )
    if not match:
        raise ValueError("В обновлении не найден точный APP_VERSION")
    return match.group(1).decode("ascii")


def _jai_payload_secret():
    # Keep the old local trial secret so a 0.88 trial can be extended in place.
    return bytes.fromhex("".join(_JAI_TRIAL_SECRET_PARTS))


def _jai_disable_failed_update(active_manifest, updates_dir, error):
    try:
        import time as _time

        failed = updates_dir / ("active.failed-%d.json" % int(_time.time()))
        os.replace(active_manifest, failed)
        message = "%s: %s" % (type(error).__name__, error)
        (updates_dir / "last_start_error.txt").write_text(
            message[:4000], encoding="utf-8"
        )
    except Exception:
        pass


def _jai_bootstrap_external_update():
    if __name__ != "__main__" or globals().get("_JAI_UPDATE_OVERLAY_ACTIVE"):
        return
    try:
        import hashlib as _hashlib
        import json as _json
        import pathlib as _pathlib
        import runpy as _runpy

        platform_name = _jai_update_platform()
        if platform_name == "unsupported":
            return
        updates_dir = _pathlib.Path.home() / ".jewelry_ai_search" / "program_updates"
        active_manifest = updates_dir / "active.json"
        if (
            not active_manifest.is_file()
            or active_manifest.is_symlink()
            or active_manifest.stat().st_size > 64 * 1024
        ):
            return
        manifest = _json.loads(active_manifest.read_text(encoding="utf-8"))
        if (
            manifest.get("format") != _JAI_UPDATE_FORMAT
            or manifest.get("protocol") != _JAI_UPDATE_PROTOCOL
            or manifest.get("app_id") != _JAI_UPDATE_APP_ID
            or manifest.get("platform") != platform_name
        ):
            return
        version = str(manifest.get("version") or "")
        if _jai_version_tuple(version) <= _jai_version_tuple(_JAI_BUILTIN_VERSION):
            return
        minimum = str(manifest.get("min_base_version") or _JAI_BUILTIN_VERSION)
        if _jai_version_tuple(minimum) > _jai_version_tuple(_JAI_BUILTIN_VERSION):
            return
        payload = manifest.get("payload")
        if not isinstance(payload, dict) or payload.get("name") != "app.py":
            return
        expected_size = int(payload.get("size", -1))
        expected_hash = str(payload.get("sha256") or "").lower()
        if expected_size < 1 or expected_size > 8 * 1024 * 1024:
            return
        if len(expected_hash) != 64 or any(
            item not in "0123456789abcdef" for item in expected_hash
        ):
            return
        version_dir = updates_dir / "versions" / version
        platform_dir = version_dir / platform_name
        source_path = platform_dir / "app.py"
        for item in (
            updates_dir,
            updates_dir / "versions",
            version_dir,
            platform_dir,
            source_path,
        ):
            if item.is_symlink():
                return
        if not source_path.is_file():
            return
        source_bytes = source_path.read_bytes()
        if (
            len(source_bytes) != expected_size
            or _hashlib.sha256(source_bytes).hexdigest() != expected_hash
            or _jai_source_version(source_bytes) != version
        ):
            return
        try:
            _runpy.run_path(
                str(source_path),
                run_name="__main__",
                init_globals={
                    "_JAI_BOOTSTRAP_PATH": _JAI_BOOTSTRAP_PATH,
                    "_JAI_UPDATE_OVERLAY_ACTIVE": True,
                },
            )
        except SystemExit:
            raise
        except Exception as error:
            _jai_disable_failed_update(active_manifest, updates_dir, error)
            return
        raise SystemExit(0)
    except SystemExit:
        raise
    except Exception:
        return


_jai_bootstrap_external_update()
def _jai_startup_vacuum_if_requested():
    """0.95.0: одноразовое сжатие рабочих баз ДО любых соединений модуля."""
    try:
        import json as _json
        import pathlib as _pathlib
        import sqlite3 as _sqlite3
        app_dir = _pathlib.Path.home() / ".jewelry_ai_search"
        cfg_path = app_dir / "config.json"
        if not cfg_path.is_file():
            return
        cfg = _json.loads(cfg_path.read_text(encoding="utf-8"))
        if not bool(cfg.get("vacuum_on_next_start")):
            return
        cfg["vacuum_on_next_start"] = False
        cfg_path.write_text(_json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")
        for name in ("index.sqlite3", "projects_v2.sqlite3", "ai_fingerprint_cache.sqlite3"):
            path = app_dir / name
            if not path.is_file():
                continue
            try:
                con = _sqlite3.connect(str(path), timeout=30)
                try:
                    con.execute("PRAGMA busy_timeout=15000")
                    try:
                        con.execute("PRAGMA wal_checkpoint(TRUNCATE)")
                    except Exception:
                        pass
                    con.execute("VACUUM")
                finally:
                    con.close()
            except Exception:
                continue
    except Exception:
        pass


_jai_startup_vacuum_if_requested()

