def normalize_ui_language(language: str | None) -> str:
    value = str(language or "").strip().replace("_", "-").casefold()
    return "en" if value == "en" or value.startswith("en-") else DEFAULT_UI_LANGUAGE


def translate_ui_text(value: str, language: str) -> str:
    text = str(value or "")
    if normalize_ui_language(language) == "en":
        return UI_ENGLISH_TRANSLATIONS.get(text, text)
    for russian, english in UI_ENGLISH_TRANSLATIONS.items():
        if text == english:
            return russian
    return text


def developer_support_message(language: str = DEFAULT_UI_LANGUAGE,
                              include_contact: bool = True) -> str:
    if normalize_ui_language(language) == "en":
        message = (
            "Enjoy all features free for 60 days. If Jewelry AI Search helps your "
            "work, you may support its developer with any amount you feel is fair. "
            "Support is voluntary, and you choose the amount yourself.\n\n"
            "To receive a personal activation key or ask about support, contact "
            "the developer. No payment service is connected yet."
        )
        contact = "Developer contact: "
    else:
        message = (
            "Пользуйтесь всеми функциями бесплатно 60 дней. Если Jewelry AI Search "
            "оказалась полезной, вы можете добровольно поддержать разработчика "
            "любой комфортной суммой. Размер поддержки вы определяете сами.\n\n"
            "Для получения персонального ключа или вопросов о поддержке "
            "свяжитесь с разработчиком. Платёжный сервис пока не подключён."
        )
        contact = "Контакт разработчика: "
    return message + ("\n\n" + contact + APP_AUTHOR_EMAIL if include_contact else "")


