def normalize_ui_theme(value: str | None) -> str:
    return "dark" if str(value or "").strip().casefold() == "dark" else "light"


def activate_gallery_theme(value: str | None) -> str:
    selected = normalize_ui_theme(value)
    GALLERY_THEME.clear()
    GALLERY_THEME.update(GALLERY_THEMES[selected])
    return selected

