APPLICATION_UPDATE_DIR = APP_DIR / "program_updates"
APPLICATION_UPDATE_MAX_ARCHIVE_SIZE = 12 * 1024 * 1024
APPLICATION_UPDATE_MAX_PAYLOAD_SIZE = 8 * 1024 * 1024


class ApplicationUpdateError(ValueError):
    pass


def _read_limited_zip_member(archive, info, maximum):
    if info.file_size < 0 or info.file_size > maximum:
        raise ApplicationUpdateError(f"Файл {info.filename} слишком большой")
    with archive.open(info, "r") as stream:
        data = stream.read(maximum + 1)
    if len(data) > maximum or len(data) != info.file_size:
        raise ApplicationUpdateError(f"Неверный размер файла {info.filename}")
    return data


def validate_application_update_archive(archive_path: Path):
    external_handler = globals().get("_JAI_EXTERNAL_UPDATE_HANDLER")
    if external_handler is not None:
        return external_handler(archive_path, APP_VERSION)

    import stat

    archive_path = Path(archive_path)
    if not archive_path.is_file():
        raise ApplicationUpdateError("ZIP обновления не найден")
    if archive_path.stat().st_size > APPLICATION_UPDATE_MAX_ARCHIVE_SIZE:
        raise ApplicationUpdateError("ZIP обновления слишком большой")
    try:
        with zipfile.ZipFile(archive_path, "r") as archive:
            infos = archive.infolist()
            names = [item.filename for item in infos]
            if len(names) != len(set(names)) or set(names) != {
                "manifest.json", "app.py"
            }:
                raise ApplicationUpdateError(
                    "В ZIP должны быть только manifest.json и app.py"
                )
            by_name = {item.filename: item for item in infos}
            for info in infos:
                file_type = (info.external_attr >> 16) & 0o170000
                if info.is_dir() or file_type == stat.S_IFLNK or info.flag_bits & 0x1:
                    raise ApplicationUpdateError(
                        "ZIP содержит недопустимый файл или ссылку"
                    )
            manifest_bytes = _read_limited_zip_member(
                archive, by_name["manifest.json"], 64 * 1024
            )
            payload_bytes = _read_limited_zip_member(
                archive, by_name["app.py"], APPLICATION_UPDATE_MAX_PAYLOAD_SIZE
            )
    except ApplicationUpdateError:
        raise
    except (OSError, zipfile.BadZipFile, RuntimeError, UnicodeError) as error:
        raise ApplicationUpdateError(f"Не удалось прочитать ZIP: {error}") from error

    try:
        manifest = json.loads(manifest_bytes.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ApplicationUpdateError("Повреждён manifest.json") from error
    if not isinstance(manifest, dict):
        raise ApplicationUpdateError("manifest.json должен быть объектом")
    if manifest.get("format") != _JAI_UPDATE_FORMAT:
        raise ApplicationUpdateError("Это не обновление Jewelry AI Search")
    if manifest.get("protocol") != _JAI_UPDATE_PROTOCOL:
        raise ApplicationUpdateError("Версия формата обновления не поддерживается")
    if manifest.get("app_id") != _JAI_UPDATE_APP_ID:
        raise ApplicationUpdateError("Обновление предназначено для другой программы")
    platform_name = _jai_update_platform()
    if manifest.get("platform") != platform_name:
        expected = "Windows" if platform_name == "windows" else "Linux"
        raise ApplicationUpdateError(f"Нужно обновление для {expected}")
    try:
        version = str(manifest.get("version") or "")
        if _jai_version_tuple(version) <= _jai_version_tuple(APP_VERSION):
            raise ApplicationUpdateError(
                f"Версия {version} не новее установленной {APP_VERSION}"
            )
        minimum = str(manifest.get("min_base_version") or "")
        if _jai_version_tuple(minimum) > _jai_version_tuple(_JAI_BUILTIN_VERSION):
            raise ApplicationUpdateError(
                f"Для этого обновления нужна базовая сборка не ниже {minimum}"
            )
    except ApplicationUpdateError:
        raise
    except ValueError as error:
        raise ApplicationUpdateError(str(error)) from error
    payload = manifest.get("payload")
    if not isinstance(payload, dict) or payload.get("name") != "app.py":
        raise ApplicationUpdateError("В манифесте неверно описан app.py")
    expected_hash = str(payload.get("sha256") or "").lower()
    try:
        expected_size = int(payload.get("size", -1))
    except (TypeError, ValueError) as error:
        raise ApplicationUpdateError("В манифесте неверный размер app.py") from error
    if expected_size != len(payload_bytes):
        raise ApplicationUpdateError("Размер app.py не совпадает с манифестом")
    if len(expected_hash) != 64 or any(
        item not in "0123456789abcdef" for item in expected_hash
    ):
        raise ApplicationUpdateError("В манифесте неверная сумма SHA-256")
    if hashlib.sha256(payload_bytes).hexdigest() != expected_hash:
        raise ApplicationUpdateError("SHA-256 не совпадает: обновление повреждено")
    try:
        source_text = payload_bytes.decode("utf-8-sig")
        ast.parse(source_text, filename="app.py")
    except (UnicodeError, SyntaxError) as error:
        raise ApplicationUpdateError(f"Файл app.py в обновлении повреждён: {error}") from error
    if _jai_source_version(payload_bytes) != version:
        raise ApplicationUpdateError("APP_VERSION в app.py не совпадает с манифестом")
    return manifest, payload_bytes


def install_application_update_archive(archive_path: Path):
    manifest, payload_bytes = validate_application_update_archive(archive_path)
    version = str(manifest["version"])
    platform_name = str(manifest["platform"])
    updates_dir = APPLICATION_UPDATE_DIR
    versions_dir = updates_dir / "versions"
    version_dir = versions_dir / version
    platform_dir = version_dir / platform_name
    payload_name = str(manifest["payload"]["name"])
    target = platform_dir / payload_name
    for item in (updates_dir, versions_dir, version_dir, platform_dir):
        if item.exists() and item.is_symlink():
            raise ApplicationUpdateError("Каталог обновлений содержит недопустимую ссылку")
        item.mkdir(parents=True, exist_ok=True)
        try:
            item.chmod(0o700)
        except OSError:
            pass
    if target.exists() and target.is_symlink():
        raise ApplicationUpdateError("Файл обновления является недопустимой ссылкой")

    temporary_payload = platform_dir / (".app-%d-%d.tmp" % (os.getpid(), time.time_ns()))
    temporary_manifest = updates_dir / (".active-%d-%d.tmp" % (os.getpid(), time.time_ns()))
    active_manifest = dict(manifest)
    active_manifest["installed_at"] = datetime.now().astimezone().isoformat(timespec="seconds")
    try:
        with temporary_payload.open("xb") as stream:
            stream.write(payload_bytes)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            temporary_payload.chmod(0o600)
        except OSError:
            pass
        os.replace(temporary_payload, target)
        encoded = json.dumps(active_manifest, ensure_ascii=False, indent=2).encode("utf-8")
        with temporary_manifest.open("xb") as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            temporary_manifest.chmod(0o600)
        except OSError:
            pass
        os.replace(temporary_manifest, updates_dir / "active.json")
    finally:
        for item in (temporary_payload, temporary_manifest):
            try:
                item.unlink(missing_ok=True)
            except OSError:
                pass
    return active_manifest


def application_restart_command():
    if getattr(sys, "frozen", False):
        executable = Path(sys.executable)
        if not executable.is_file():
            raise ApplicationUpdateError("Не найден установленный файл программы")
        if os.name == "nt":
            try:
                with executable.open("rb") as stream:
                    if stream.read(2) != b"MZ":
                        raise ApplicationUpdateError("Файл запуска Windows повреждён")
            except OSError as error:
                raise ApplicationUpdateError(f"Не удалось проверить файл программы: {error}") from error
        return [str(executable)]
    bootstrap = Path(_JAI_BOOTSTRAP_PATH or __file__).resolve()
    if not bootstrap.is_file():
        raise ApplicationUpdateError("Не найден исходный файл установленной программы")
    return [sys.executable, str(bootstrap)]

