# v0.73 lightweight persistent J-AI vector index
# Stores project ids and normalized embeddings. It avoids rebuilding the list on every search.
class JAI_Vector_Index:
    def __init__(self, path=JAI_VECTOR_INDEX_PATH):
        self.path = path
        self.ids = []
        self.vectors = None
        self.signature = ""
        self.load()

    @staticmethod
    def project_signature(projects):
        """Identity of the exact local vector collection stored on disk."""
        h = hashlib.sha1()
        for p in sorted((projects or []),key=lambda x:str(x.get("id",""))):
            v = p.get("embedding")
            if v is None:
                continue
            try:
                dim = int(np.asarray(v).size)
            except Exception:
                dim = 0
            token = "|".join((
                str(p.get("id", "")), str(p.get("project_key", "")),
                str(p.get("source_signature", "")), str(dim),
            ))
            h.update(token.encode("utf-8", "ignore"))
            h.update(b"\n")
        return h.hexdigest()

    def build(self, projects):
        ids=[]; vecs=[]
        for p in projects:
            v=p.get("embedding")
            if v is not None:
                ids.append(p.get("id", len(ids)))
                a=np.asarray(v, dtype=np.float32).reshape(-1)
                n=float(np.linalg.norm(a))
                vecs.append(a/n if n>1e-12 else a)
        if vecs:
            arr=np.vstack(vecs)
            signature=self.project_signature(projects)
            # np.savez(path) silently appends ".npz" to a non-npz filename.  Writing
            # through a file handle keeps the declared jai_vector_index.bin path real,
            # so the index can actually be loaded after an application restart.
            with self.path.open("wb") as fh:
                np.savez_compressed(fh, ids=np.array(ids), vectors=arr,
                                    signature=np.array(signature))
            self.ids=ids; self.vectors=arr; self.signature=signature
        else:
            self.ids=[]; self.vectors=None; self.signature=""
        return len(ids)

    def load(self):
        try:
            if self.path.exists():
                # The index contains only numeric arrays and a text signature. Pickled
                # NumPy objects are unnecessary here and unsafe in a restored archive.
                with np.load(self.path, allow_pickle=False) as d:
                    ids=np.asarray(d["ids"])
                    vectors=np.asarray(d["vectors"],dtype=np.float32)
                    signature=str(d["signature"].item()) if "signature" in d.files else ""
                if ids.ndim != 1 or vectors.ndim != 2 or len(ids) != vectors.shape[0]:
                    raise ValueError("invalid vector index")
                if not np.isfinite(vectors).all():
                    raise ValueError("non-finite vector index")
                self.ids=ids.tolist()
                self.vectors=vectors
                self.signature=signature
        except Exception:
            self.ids=[]; self.vectors=None; self.signature=""

    def matches(self, projects):
        return (self.vectors is not None
                and int(self.vectors.shape[0]) == len(self.ids)
                and self.signature == self.project_signature(projects))

    def search_ids(self, q, limit=300):
        if self.vectors is None or q is None:
            return None
        q=np.asarray(q,dtype=np.float32).reshape(-1)
        if self.vectors.ndim != 2 or self.vectors.shape[1] != q.size:
            return None
        qn=float(np.linalg.norm(q))
        if qn>1e-12: q=q/qn
        scores=self.vectors @ q
        # 0.97.8: top-k через argpartition за O(n), без полной сортировки.
        k=min(int(limit),len(scores))
        if k<=0:
            return set()
        part=np.argpartition(-scores,k-1)[:k]
        idx=part[np.argsort(-scores[part])]
        return {self.ids[int(i)] for i in idx}

JAI_VECTOR_INDEX = JAI_Vector_Index()

