def _short_thought(text, limit=200):
    """0.95.6: ужимает мысль до пары фраз для строки статуса."""
    t=" ".join(str(text or "").split())
    if len(t)<=limit:
        return t
    cut=t[:limit]
    sp=cut.rfind(" ")
    if sp>60:
        cut=cut[:sp]
    return cut+"…"

def _model_field_reliability(model: str, key: str) -> float:
    global _MODEL_RELIABILITY_LOADED
    if not _MODEL_RELIABILITY_LOADED:
        _MODEL_RELIABILITY_LOADED = True
        try:
            con = sqlite3.connect(str(PROJECT_DB_PATH), timeout=10)
            try:
                rows = con.execute(
                    "SELECT model,fact_key,agree,total FROM model_field_accuracy").fetchall()
            finally:
                con.close()
            for m, k, agree, total in rows:
                t = int(total or 0)
                if t >= 4:
                    _MODEL_RELIABILITY_CACHE[(str(m), str(k))] = max(
                        0.60, min(1.10, 0.70 + 0.40 * (int(agree or 0) / t)))
        except Exception:
            pass
    return _MODEL_RELIABILITY_CACHE.get((str(model), str(key)), 1.0)

def _merge_model_fingerprints(models_map):
    """Merges several per-model fingerprint rows into one search-ready record.

    For each canonical evidence value the record with the highest confidence
    wins. Manual tags live in project_manual_labels and are unaffected. The
    merged evidence map is what makes Jewelry AI Search model-agnostic.
    """
    merged_evidence={}
    merged_tags={}
    merged_text_parts=[]
    merged_models=[]
    file_hash=""
    latest_updated=0.0
    # 0.92: подсчёт консенсуса — сколько моделей согласны по каждому факту
    consensus_counts={}
    for model,rec in (models_map or {}).items():
        model_name=str(model or rec.get("model") or "")
        if model_name: merged_models.append(model_name)
        if not file_hash and rec.get("file_hash"):
            file_hash=str(rec["file_hash"])
        try: latest_updated=max(latest_updated,float(rec.get("updated_at") or 0.0))
        except Exception: pass
        for key,items in (rec.get("evidence_map") or {}).items():
            bucket=merged_evidence.setdefault(str(key),[])
            for value,conf,source in items or []:
                cv=canon(str(key),value)
                if not cv: continue
                # 0.92: считаем, сколько моделей дали это значение
                _ck=(str(key),cv)
                consensus_counts[_ck]=consensus_counts.get(_ck,0)+1
                label=str(source)
                if model_name and model_name not in label:
                    label=label+" ["+model_name+"]"
                existing=next((i for i,x in enumerate(bucket) if x[0]==cv),None)
                try: cf=float(conf or 0.0)
                except Exception: cf=0.0
                cf=cf*_model_field_reliability(model_name,str(key))
                if existing is None:
                    bucket.append((cv,cf,label))
                elif float(bucket[existing][1])<cf:
                    bucket[existing]=(cv,cf,label)
        for tk,tv in (rec.get("tags") or {}).items():
            if isinstance(tv,list):
                lst=merged_tags.setdefault(str(tk),[])
                for v in tv:
                    if v not in lst: lst.append(v)
        text=str(rec.get("search_text") or "").strip()
        if text: merged_text_parts.append(text)
    return {
        "file_hash":file_hash,
        "model":",".join(sorted(set(merged_models))),
        "models":sorted(set(merged_models)),
        "tags":merged_tags,
        "vision":{},
        "search_text":" ".join(dict.fromkeys(merged_text_parts)),
        "evidence_map":merged_evidence,
        "updated_at":latest_updated,
        # 0.92: консенсус моделей — только те факты, где 2+ модели согласны
        "consensus_map":{k:v for k,v in consensus_counts.items() if v>=2},
    }


class AIFingerprintCache:
    def __init__(self, path=FINGERPRINT_DB_PATH):
        self.path = path
        self._lock = threading.RLock()
        self._memory = {}
        self._init()

    def _init(self):
        con = sqlite3.connect(self.path, timeout=30)
        try:
            try: con.execute("PRAGMA journal_mode=WAL")
            except Exception: pass
            # 0.91: composite primary key (project_id, model). A second model's card
            # can no longer overwrite the first model's card. Existing single-model
            # databases are migrated in place; the old row's model column is kept.
            tables={row[0] for row in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
            old_rows=None
            if "fingerprints" in tables:
                info=con.execute("PRAGMA table_info(fingerprints)").fetchall()
                cols_now={row[1] for row in info}
                if "search_text" not in cols_now:
                    con.execute("ALTER TABLE fingerprints ADD COLUMN search_text TEXT")
                if "evidence_json" not in cols_now:
                    con.execute("ALTER TABLE fingerprints ADD COLUMN evidence_json TEXT")
                info=con.execute("PRAGMA table_info(fingerprints)").fetchall()
                pk_names=[row[1] for row in info if row[5]]
                if pk_names==["project_id"]:
                    old_rows=con.execute(
                        "SELECT project_id,file_hash,model,tags_json,vision_json,"
                        "search_text,evidence_json,updated_at FROM fingerprints").fetchall()
                    con.execute("DROP TABLE fingerprints")
            con.execute("""CREATE TABLE IF NOT EXISTS fingerprints (
                project_id INTEGER NOT NULL,
                model TEXT NOT NULL DEFAULT '',
                file_hash TEXT,
                tags_json TEXT,
                vision_json TEXT,
                search_text TEXT,
                evidence_json TEXT,
                updated_at REAL,
                PRIMARY KEY (project_id, model)
            )""")
            cols={r[1] for r in con.execute("PRAGMA table_info(fingerprints)").fetchall()}
            if "search_text" not in cols:
                con.execute("ALTER TABLE fingerprints ADD COLUMN search_text TEXT")
            if "evidence_json" not in cols:
                con.execute("ALTER TABLE fingerprints ADD COLUMN evidence_json TEXT")
            if old_rows:
                for row in old_rows:
                    try:
                        con.execute(
                            "INSERT OR REPLACE INTO fingerprints"
                            "(project_id,model,file_hash,tags_json,vision_json,"
                            "search_text,evidence_json,updated_at) VALUES(?,?,?,?,?,?,?,?)",
                            (int(row[0]),str(row[2] or ""),row[1],row[3],row[4],row[5],row[6],row[7]))
                    except Exception:
                        continue
            # Persistent cache of calculated search results. Survives app restart.
            con.execute("""CREATE TABLE IF NOT EXISTS search_cache (
                cache_key TEXT PRIMARY KEY,
                result_json TEXT,
                updated_at REAL
            )""")
            con.commit()
        finally:
            con.close()

    def save(self, project_id, file_hash, model, tags, vision):
        tags = tags or _qwen_tags_from_vision(vision)
        search_text = _fingerprint_search_text(tags, vision)
        evidence_map = _qwen_fingerprint_evidence(vision)
        updated_at = time.time()
        model_str=str(model or "")
        con = sqlite3.connect(self.path, timeout=30)
        try:
            con.execute("""INSERT OR REPLACE INTO fingerprints
            (project_id,model,file_hash,tags_json,vision_json,search_text,evidence_json,updated_at)
            VALUES (?,?,?,?,?,?,?,?)""",
            (int(project_id), model_str, str(file_hash),
             json.dumps(tags or {}, ensure_ascii=False),
             json.dumps(vision or {}, ensure_ascii=False), search_text,
             json.dumps(evidence_map,ensure_ascii=False),updated_at))
            con.commit()
        finally:
            con.close()
        with self._lock:
            self._memory.setdefault(int(project_id),{})[model_str] = {
                "file_hash":str(file_hash), "model":model_str, "tags":tags or {},
                "vision":vision or {}, "search_text":search_text, "evidence_map":evidence_map,
                "updated_at":updated_at,
            }

    def get(self, project_id):
        return self.get_many([project_id]).get(int(project_id))

    def get_many(self, project_ids):
        """Returns {project_id: merged_record} covering every model that has a card.

        0.91: each fingerprint row is one (project_id, model) pair. The returned
        record merges all models' evidence maps by picking the highest confidence
        per canonical value. This is what makes search model-agnostic: switching
        the active Vision model no longer hides the other models' work.
        """
        ids=[]; seen=set()
        for raw in project_ids or []:
            try: pid=int(raw)
            except Exception: continue
            if pid not in seen:
                seen.add(pid); ids.append(pid)
        with self._lock:
            missing=[pid for pid in ids if pid not in self._memory]
        if missing:
            loaded={}
            con=sqlite3.connect(self.path, timeout=30)
            try:
                for pos in range(0,len(missing),800):
                    chunk=missing[pos:pos+800]
                    qs=",".join("?" for _ in chunk)
                    rows=con.execute(f"""SELECT project_id,model,file_hash,tags_json,
                        vision_json,search_text,evidence_json,updated_at FROM fingerprints
                        WHERE project_id IN ({qs})""",chunk).fetchall()
                    for pid,model,file_hash,tags_json,vision_json,search_text,evidence_json,updated_at in rows:
                        tags=json_loads_safe(tags_json,{})
                        vision=json_loads_safe(vision_json,{})
                        evidence=json_loads_safe(evidence_json,{})
                        if not isinstance(evidence,dict) or not evidence:
                            evidence=_qwen_fingerprint_evidence(vision)
                        loaded.setdefault(int(pid),{})[str(model or "")]={
                            "file_hash":str(file_hash or ""), "model":str(model or ""),
                            "tags":tags, "vision":vision,
                            "search_text":str(search_text or "") or _fingerprint_search_text(tags,vision),
                            "evidence_map":evidence,
                            "updated_at":float(updated_at or 0.0),
                        }
            finally:
                con.close()
            with self._lock:
                for pid in missing:
                    self._memory[pid]=loaded.get(pid) or {}
        result={}
        with self._lock:
            for pid in ids:
                models_map=self._memory.get(pid) or {}
                if not models_map:
                    continue
                if len(models_map)==1:
                    only=dict(next(iter(models_map.values())))
                    only["models"]=[only.get("model") or ""]
                    result[pid]=only
                else:
                    result[pid]=_merge_model_fingerprints(models_map)
        return result

    def per_model(self, project_ids):
        """0.93: сырые карточки каждой модели отдельно (без merge).
        Нужны для очереди конфликтов и калибровки ансамбля."""
        ids=[]; seen=set()
        for raw in project_ids or []:
            try: pid=int(raw)
            except Exception: continue
            if pid not in seen:
                seen.add(pid); ids.append(pid)
        with self._lock:
            missing=[pid for pid in ids if pid not in self._memory]
        if missing:
            self.get_many(missing)
        out={}
        with self._lock:
            for pid in ids:
                mm=self._memory.get(pid) or {}
                if mm: out[pid]=dict(mm)
        return out

    def sync_from_projects(self, projects):
        """Backfill the active model's card into the (project_id, model) cache.

        Other models' cards already live in project_vision_runs and are read
        directly by _augment_search_context_with_all_models, so this method
        only handles the legacy case where the active card never got a row.
        """
        candidates=[]
        for p in projects or []:
            if p.get("id") is None or not project_is_currently_analyzed(p):
                continue
            vision=p.get("vision") or {}
            if vision:
                candidates.append(p)
        if not candidates:
            return 0
        pid_list=[int(p["id"]) for p in candidates]
        existing={}
        con=sqlite3.connect(self.path, timeout=30)
        try:
            for pos in range(0,len(pid_list),700):
                chunk=pid_list[pos:pos+700]
                qs=",".join("?" for _ in chunk)
                for pid,model,fhash in con.execute(
                    f"SELECT project_id,model,file_hash FROM fingerprints "
                    f"WHERE project_id IN ({qs})",chunk).fetchall():
                    existing[(int(pid),str(model or ""))]=str(fhash or "")
        finally:
            con.close()
        rows=[]
        for p in candidates:
            pid=int(p["id"]); signature=str(p.get("source_signature") or "")
            model=str(p.get("vision_model") or "")
            vision=p.get("vision") or {}
            if existing.get((pid,model))==signature:
                continue
            tags=_qwen_tags_from_vision(vision)
            rows.append((pid,model,signature,tags,vision,_fingerprint_search_text(tags,vision),
                         _qwen_fingerprint_evidence(vision),time.time()))
        if not rows:
            return 0
        con=sqlite3.connect(self.path, timeout=30)
        try:
            con.executemany("""INSERT OR REPLACE INTO fingerprints
                (project_id,model,file_hash,tags_json,vision_json,search_text,evidence_json,updated_at)
                VALUES (?,?,?,?,?,?,?,?)""",[
                (pid,model,sig,json.dumps(tags,ensure_ascii=False),json.dumps(vision,ensure_ascii=False),
                 text,json.dumps(evidence,ensure_ascii=False),updated)
                for pid,model,sig,tags,vision,text,evidence,updated in rows
            ])
            con.commit()
        finally:
            con.close()
        with self._lock:
            for pid,model,sig,tags,vision,search_text,evidence,updated in rows:
                self._memory.setdefault(int(pid),{})[model]={
                    "file_hash":sig,"model":model,"tags":tags,"vision":vision,
                    "search_text":search_text,"evidence_map":evidence,"updated_at":updated}
        return len(rows)

    def get_search(self, key):
        try:
            con = sqlite3.connect(self.path, timeout=5)
            try:
                row = con.execute("SELECT result_json FROM search_cache WHERE cache_key=?", (str(key),)).fetchone()
                return json.loads(row[0]) if row else None
            finally:
                con.close()
        except Exception:
            return None

    def save_search(self, key, value):
        try:
            con = sqlite3.connect(self.path, timeout=5)
            try:
                con.execute("INSERT OR REPLACE INTO search_cache(cache_key,result_json,updated_at) VALUES(?,?,?)",
                            (str(key), json.dumps(value, ensure_ascii=False), time.time()))
                con.commit()
            finally:
                con.close()
        except Exception:
            pass

    def invalidate_projects(self, project_ids=None, clear_searches=True):
        """Forget source-dependent cards so a disabled ZIP cannot leak into search."""
        ids=[]; seen=set()
        for value in project_ids or []:
            try: pid=int(value)
            except Exception: continue
            if pid not in seen:
                ids.append(pid); seen.add(pid)
        con=sqlite3.connect(self.path,timeout=30)
        try:
            for pos in range(0,len(ids),700):
                chunk=ids[pos:pos+700]; qs=",".join("?" for _ in chunk)
                con.execute(f"DELETE FROM fingerprints WHERE project_id IN ({qs})",chunk)
            if clear_searches:
                con.execute("DELETE FROM search_cache")
            con.commit()
        finally:
            con.close()
        with self._lock:
            for pid in ids:
                self._memory.pop(pid,None)
        return len(ids)

    def count(self):
        try:
            con = sqlite3.connect(self.path, timeout=5)
            try:
                return int(con.execute("SELECT COUNT(*) FROM fingerprints").fetchone()[0])
            finally:
                con.close()
        except Exception:
            return 0

AI_FINGERPRINT_CACHE = AIFingerprintCache()

FACT_INDEX_VERSION = 3
RESULT_LIMIT_DEFAULT = 60
