def count_qwen_results(results):
    """Количество результатов, в которых участвовал Qwen."""
    total = len(results or [])
    qwen = 0
    for item in (results or []):
        try:
            if float(item.get("ai_tag_score") or 0) > 0 or item.get("qwen_used"):
                qwen += 1
        except Exception:
            pass
    return total, qwen



def qwen_search_status_text(results):
    """Текст для AI-чата о влиянии Qwen на результаты."""
    total = len(results or [])
    qwen_count = 0
    for item in (results or []):
        try:
            if float(item.get("ai_tag_score") or 0) > 0 or item.get("qwen_used"):
                qwen_count += 1
        except Exception:
            pass
    return (
        f"J-AI найдено вариантов: {total}\n"
        f"Qwen AI участвовал: {qwen_count}\n"
        f"Локальный поиск без Qwen: {max(0, total-qwen_count)}"
    )



