def append_qwen_final_status(self, items):
    """Единый статус Qwen после любого типа поиска."""
    try:
        total = len(items or [])
        qwen = 0
        for item in (items or []):
            if not isinstance(item, dict):
                continue
            if (
                item.get("qwen_used")
                or item.get("ai_tag_score", 0)
                or item.get("ai_tags")
                or item.get("vision_json")
            ):
                qwen += 1
        self.chat_append(
            "AI",
            f"Статус поиска:\nJ-AI найдено: {total}\nQwen-теги/отпечаток учтены: {qwen}\nЛокальный J-AI без Qwen: {max(0,total-qwen)}",
            "muted"
        )
    except Exception:
        pass

class WindowsTrayIcon:
    """Small Windows-only notification-area icon.

    The tray owns its own Win32 message-loop thread and NEVER calls Tk from that
    thread. Commands are sent back to the Tk main thread through a Queue.
    This keeps the normal Jewelry AI Search startup independent from the tray.
    """
    def __init__(self, command_queue, main_hwnd=0, tooltip="Jewelry AI Search"):
        self.command_queue = command_queue
        self.main_hwnd = int(main_hwnd or 0)
        self.tooltip = str(tooltip or "Jewelry AI Search")[:120]
        self.thread = None
        self.ready = threading.Event()
        self.failed = threading.Event()
        self.error = ""
        self.hwnd = 0
        self._nid = None
        self._wndproc = None
        self._owned_icon = 0
        self._class_name = f"JewelryAITray_{os.getpid()}_{int(time.time()*1000)}"

    def start(self):
        if os.name != "nt" or (self.thread and self.thread.is_alive()):
            return
        self.thread = threading.Thread(target=self._run, name="JewelryAI-Tray", daemon=True)
        self.thread.start()

    def stop(self):
        if os.name != "nt":
            return
        try:
            if self.hwnd:
                ctypes.windll.user32.PostMessageW(int(self.hwnd), 0x0010, 0, 0)  # WM_CLOSE
        except Exception:
            pass
        try:
            if self.thread and self.thread.is_alive():
                self.thread.join(timeout=2.0)
        except Exception:
            pass

    def is_alive(self):
        return bool(self.thread and self.thread.is_alive())

    def _find_local_ico(self):
        roots=[]
        try: roots.append(Path(__file__).resolve().parent)
        except Exception: pass
        try: roots.append(Path(__file__).resolve().parent.parent)
        except Exception: pass
        roots.append(APP_DIR)
        preferred=[]; other=[]
        seen=set()
        for root in roots:
            try:
                for f in root.glob("*.ico"):
                    key=str(f.resolve()).lower()
                    if key in seen: continue
                    seen.add(key)
                    name=f.name.lower()
                    if any(k in name for k in ("jewelry","jewel","ring","logo","icon","search")):
                        preferred.append(f)
                    else:
                        other.append(f)
            except Exception:
                pass
        return (preferred+other)[0] if (preferred or other) else None

    def _load_best_icon(self, user32, shell32, wintypes):
        # 1) EXACT icon already used by the visible Jewelry AI Search window.
        if self.main_hwnd:
            try:
                WM_GETICON=0x007F
                user32.SendMessageW.argtypes=[wintypes.HWND,wintypes.UINT,wintypes.WPARAM,wintypes.LPARAM]
                user32.SendMessageW.restype=ctypes.c_ssize_t
                for which in (2,0,1):  # ICON_SMALL2, SMALL, BIG
                    h=int(user32.SendMessageW(wintypes.HWND(self.main_hwnd),WM_GETICON,which,0) or 0)
                    if h:
                        return h, False
                getcl=getattr(user32,"GetClassLongPtrW",None)
                if getcl:
                    getcl.argtypes=[wintypes.HWND,ctypes.c_int]
                    getcl.restype=ctypes.c_size_t
                    for idx in (-34,-14):  # GCLP_HICONSM, GCLP_HICON
                        h=int(getcl(wintypes.HWND(self.main_hwnd),idx) or 0)
                        if h:
                            return h, False
            except Exception:
                pass

        # 2) Existing custom .ico next to the user's application/launcher.
        ico=self._find_local_ico()
        if ico:
            try:
                IMAGE_ICON=1; LR_LOADFROMFILE=0x0010; LR_DEFAULTSIZE=0x0040
                user32.LoadImageW.argtypes=[wintypes.HINSTANCE,wintypes.LPCWSTR,wintypes.UINT,ctypes.c_int,ctypes.c_int,wintypes.UINT]
                user32.LoadImageW.restype=wintypes.HANDLE
                h=int(user32.LoadImageW(None,str(ico),IMAGE_ICON,0,0,LR_LOADFROMFILE|LR_DEFAULTSIZE) or 0)
                if h:
                    return h, True
            except Exception:
                pass

        # 3) Icon embedded in the Python/launcher executable as last fallback.
        try:
            shell32.ExtractIconExW.argtypes=[wintypes.LPCWSTR,ctypes.c_int,ctypes.POINTER(wintypes.HICON),ctypes.POINTER(wintypes.HICON),wintypes.UINT]
            shell32.ExtractIconExW.restype=wintypes.UINT
            large=wintypes.HICON(); small=wintypes.HICON()
            if shell32.ExtractIconExW(str(Path(sys.executable)),0,ctypes.byref(large),ctypes.byref(small),1):
                if small.value:
                    if large.value:
                        try:user32.DestroyIcon(large)
                        except Exception:pass
                    return int(small.value), True
                if large.value:
                    return int(large.value), True
        except Exception:
            pass

        # 4) Absolute fallback: Windows application icon. The app remains usable even here.
        try:
            user32.LoadIconW.argtypes=[wintypes.HINSTANCE,wintypes.LPCWSTR]
            user32.LoadIconW.restype=wintypes.HICON
            h=int(user32.LoadIconW(None,ctypes.cast(32512,wintypes.LPCWSTR)) or 0)
            if h:
                return h, False
        except Exception:
            pass
        return 0, False

    def _run(self):
        if os.name != "nt":
            self.failed.set(); return
        try:
            from ctypes import wintypes
            user32=ctypes.windll.user32
            shell32=ctypes.windll.shell32
            kernel32=ctypes.windll.kernel32

            LRESULT=ctypes.c_ssize_t
            WNDPROC=ctypes.WINFUNCTYPE(LRESULT,wintypes.HWND,wintypes.UINT,wintypes.WPARAM,wintypes.LPARAM)

            class WNDCLASSW(ctypes.Structure):
                _fields_=[
                    ("style",wintypes.UINT),("lpfnWndProc",WNDPROC),
                    ("cbClsExtra",ctypes.c_int),("cbWndExtra",ctypes.c_int),
                    ("hInstance",wintypes.HINSTANCE),("hIcon",wintypes.HICON),
                    ("hCursor",wintypes.HANDLE),("hbrBackground",wintypes.HBRUSH),
                    ("lpszMenuName",wintypes.LPCWSTR),("lpszClassName",wintypes.LPCWSTR),
                ]

            class GUID(ctypes.Structure):
                _fields_=[("Data1",wintypes.DWORD),("Data2",wintypes.WORD),("Data3",wintypes.WORD),("Data4",ctypes.c_ubyte*8)]

            class NOTIFYICONDATAW(ctypes.Structure):
                _fields_=[
                    ("cbSize",wintypes.DWORD),("hWnd",wintypes.HWND),("uID",wintypes.UINT),
                    ("uFlags",wintypes.UINT),("uCallbackMessage",wintypes.UINT),("hIcon",wintypes.HICON),
                    ("szTip",wintypes.WCHAR*128),("dwState",wintypes.DWORD),("dwStateMask",wintypes.DWORD),
                    ("szInfo",wintypes.WCHAR*256),("uTimeoutOrVersion",wintypes.UINT),
                    ("szInfoTitle",wintypes.WCHAR*64),("dwInfoFlags",wintypes.DWORD),
                    ("guidItem",GUID),("hBalloonIcon",wintypes.HICON),
                ]

            class NOTIFYICONIDENTIFIER(ctypes.Structure):
                _fields_=[
                    ("cbSize",wintypes.DWORD),("hWnd",wintypes.HWND),("uID",wintypes.UINT),("guidItem",GUID),
                ]

            user32.RegisterClassW.argtypes=[ctypes.POINTER(WNDCLASSW)]
            user32.RegisterClassW.restype=wintypes.ATOM
            user32.CreateWindowExW.argtypes=[wintypes.DWORD,wintypes.LPCWSTR,wintypes.LPCWSTR,wintypes.DWORD,
                                             ctypes.c_int,ctypes.c_int,ctypes.c_int,ctypes.c_int,
                                             wintypes.HWND,wintypes.HMENU,wintypes.HINSTANCE,wintypes.LPVOID]
            user32.CreateWindowExW.restype=wintypes.HWND
            user32.DefWindowProcW.argtypes=[wintypes.HWND,wintypes.UINT,wintypes.WPARAM,wintypes.LPARAM]
            user32.DefWindowProcW.restype=LRESULT
            user32.DestroyWindow.argtypes=[wintypes.HWND]; user32.DestroyWindow.restype=wintypes.BOOL
            user32.PostQuitMessage.argtypes=[ctypes.c_int]
            user32.GetMessageW.argtypes=[ctypes.POINTER(wintypes.MSG),wintypes.HWND,wintypes.UINT,wintypes.UINT]
            user32.GetMessageW.restype=wintypes.BOOL
            user32.TranslateMessage.argtypes=[ctypes.POINTER(wintypes.MSG)]
            user32.DispatchMessageW.argtypes=[ctypes.POINTER(wintypes.MSG)]
            user32.CreatePopupMenu.restype=wintypes.HMENU
            user32.AppendMenuW.argtypes=[wintypes.HMENU,wintypes.UINT,ctypes.c_size_t,wintypes.LPCWSTR]
            user32.TrackPopupMenu.argtypes=[wintypes.HMENU,wintypes.UINT,ctypes.c_int,ctypes.c_int,ctypes.c_int,wintypes.HWND,ctypes.c_void_p]
            user32.TrackPopupMenu.restype=wintypes.UINT
            user32.GetCursorPos.argtypes=[ctypes.POINTER(wintypes.POINT)]
            user32.SetForegroundWindow.argtypes=[wintypes.HWND]
            user32.DestroyMenu.argtypes=[wintypes.HMENU]
            user32.RegisterWindowMessageW.argtypes=[wintypes.LPCWSTR]; user32.RegisterWindowMessageW.restype=wintypes.UINT
            shell32.Shell_NotifyIconW.argtypes=[wintypes.DWORD,ctypes.POINTER(NOTIFYICONDATAW)]
            shell32.Shell_NotifyIconW.restype=wintypes.BOOL
            get_icon_rect=getattr(shell32,"Shell_NotifyIconGetRect",None)
            if get_icon_rect:
                try:
                    get_icon_rect.argtypes=[ctypes.POINTER(NOTIFYICONIDENTIFIER),ctypes.POINTER(wintypes.RECT)]
                    get_icon_rect.restype=ctypes.c_long
                except Exception:
                    get_icon_rect=None
            kernel32.GetModuleHandleW.argtypes=[wintypes.LPCWSTR]; kernel32.GetModuleHandleW.restype=wintypes.HMODULE

            WM_CLOSE=0x0010; WM_DESTROY=0x0002; WM_USER=0x0400; WM_TRAY=WM_USER+20
            WM_MOUSEMOVE=0x0200; WM_LBUTTONUP=0x0202; WM_LBUTTONDBLCLK=0x0203; WM_RBUTTONUP=0x0205; WM_NULL=0x0000
            NIM_ADD=0; NIM_DELETE=2; NIF_MESSAGE=1; NIF_ICON=2
            MF_STRING=0; TPM_RIGHTBUTTON=0x0002; TPM_RETURNCMD=0x0100
            CMD_OPEN=1001; CMD_EXIT=1002
            taskbar_created=int(user32.RegisterWindowMessageW("TaskbarCreated") or 0)

            def add_icon():
                hicon,owned=self._load_best_icon(user32,shell32,wintypes)
                if not hicon:
                    raise RuntimeError("Не удалось получить HICON для трея")
                self._owned_icon=hicon if owned else 0
                nid=NOTIFYICONDATAW(); nid.cbSize=ctypes.sizeof(NOTIFYICONDATAW)
                nid.hWnd=wintypes.HWND(self.hwnd); nid.uID=1
                nid.uFlags=NIF_MESSAGE|NIF_ICON; nid.uCallbackMessage=WM_TRAY
                nid.hIcon=wintypes.HICON(hicon)
                if not shell32.Shell_NotifyIconW(NIM_ADD,ctypes.byref(nid)):
                    raise ctypes.WinError()
                self._nid=nid

            def remove_icon():
                try:
                    if self._nid is not None:
                        shell32.Shell_NotifyIconW(NIM_DELETE,ctypes.byref(self._nid))
                except Exception:
                    pass

            def show_menu(owner):
                menu=user32.CreatePopupMenu()
                if not menu:return
                try:
                    user32.AppendMenuW(menu,MF_STRING,CMD_OPEN,"Открыть Jewelry AI Search")
                    user32.AppendMenuW(menu,MF_STRING,CMD_EXIT,"Выход")
                    pt=wintypes.POINT(); user32.GetCursorPos(ctypes.byref(pt)); user32.SetForegroundWindow(owner)
                    cmd=int(user32.TrackPopupMenu(menu,TPM_RIGHTBUTTON|TPM_RETURNCMD,pt.x,pt.y,0,owner,None) or 0)
                    user32.PostMessageW(owner,WM_NULL,0,0)
                    if cmd==CMD_OPEN:self.command_queue.put("SHOW")
                    elif cmd==CMD_EXIT:self.command_queue.put("EXIT")
                finally:
                    try:user32.DestroyMenu(menu)
                    except Exception:pass

            last_left_click=[0.0]
            last_hover_emit=[0.0]

            @WNDPROC
            def wndproc(hwnd,msg,wparam,lparam):
                try:
                    if taskbar_created and msg==taskbar_created:
                        try:
                            self._nid=None; add_icon()
                        except Exception:pass
                        return 0
                    if msg==WM_TRAY:
                        ev=int(lparam)
                        if ev==WM_MOUSEMOVE:
                            # Explorer sends mouse-move notifications while the pointer is over
                            # the tray icon. Throttle them and let Tk own the actual popup.
                            now=time.monotonic()
                            if now-last_hover_emit[0] >= 0.08:
                                last_hover_emit[0]=now
                                pt=wintypes.POINT(); user32.GetCursorPos(ctypes.byref(pt))
                                icon_rect=None
                                if get_icon_rect:
                                    try:
                                        ident=NOTIFYICONIDENTIFIER()
                                        ident.cbSize=ctypes.sizeof(NOTIFYICONIDENTIFIER)
                                        ident.hWnd=wintypes.HWND(self.hwnd); ident.uID=1
                                        rc=wintypes.RECT()
                                        if int(get_icon_rect(ctypes.byref(ident),ctypes.byref(rc)))==0:
                                            icon_rect=(int(rc.left),int(rc.top),int(rc.right),int(rc.bottom))
                                    except Exception:
                                        icon_rect=None
                                if icon_rect:
                                    self.command_queue.put(("HOVER",int(pt.x),int(pt.y),now,*icon_rect))
                                else:
                                    self.command_queue.put(("HOVER",int(pt.x),int(pt.y),now))
                            return 0
                        if ev==WM_LBUTTONUP:
                            # Один левый клик теперь работает как переключатель:
                            # открытое окно -> спрятать, спрятанное -> вернуть.
                            now=time.monotonic()
                            if now-last_left_click[0] >= 0.32:
                                last_left_click[0]=now
                                self.command_queue.put("TOGGLE")
                            return 0
                        if ev==WM_LBUTTONDBLCLK:
                            # Двойной клик не должен давать второй toggle после первого.
                            return 0
                        if ev==WM_RBUTTONUP:
                            show_menu(hwnd); return 0
                    if msg==WM_CLOSE:
                        user32.DestroyWindow(hwnd); return 0
                    if msg==WM_DESTROY:
                        remove_icon(); user32.PostQuitMessage(0); return 0
                except Exception:
                    pass
                return user32.DefWindowProcW(hwnd,msg,wparam,lparam)

            self._wndproc=wndproc
            wc=WNDCLASSW(); wc.style=0; wc.lpfnWndProc=self._wndproc
            wc.cbClsExtra=0; wc.cbWndExtra=0; wc.hInstance=kernel32.GetModuleHandleW(None)
            wc.hIcon=None; wc.hCursor=None; wc.hbrBackground=None; wc.lpszMenuName=None; wc.lpszClassName=self._class_name
            atom=user32.RegisterClassW(ctypes.byref(wc))
            if not atom:
                err=ctypes.get_last_error()
                # 1410 = class already exists; our name is unique, so anything else matters.
                if err not in (0,1410):raise ctypes.WinError(err)
            hwnd=user32.CreateWindowExW(0,self._class_name,self._class_name,0,0,0,0,0,None,None,wc.hInstance,None)
            if not hwnd:raise ctypes.WinError()
            self.hwnd=int(hwnd)
            add_icon()
            self.ready.set()

            msg=wintypes.MSG()
            while True:
                r=user32.GetMessageW(ctypes.byref(msg),None,0,0)
                if r<=0:break
                user32.TranslateMessage(ctypes.byref(msg)); user32.DispatchMessageW(ctypes.byref(msg))

            remove_icon()
            try:
                if self._owned_icon:user32.DestroyIcon(wintypes.HICON(self._owned_icon))
            except Exception:pass
            self.hwnd=0
        except Exception:
            self.error=traceback.format_exc()
            self.failed.set()
            try:(APP_DIR/"tray_error.log").write_text(self.error,encoding="utf-8")
            except Exception:pass
            try:
                if self.hwnd:ctypes.windll.user32.DestroyWindow(int(self.hwnd))
            except Exception:pass
            self.hwnd=0


def norm(s) -> str:
    return re.sub(r"\s+", " ", str(s or "").lower().replace("ё", "е")).strip()


def json_loads_safe(value, default=None):
    if default is None:
        default = {}
    if not value:
        return default
    try:
        return json.loads(value)
    except Exception:
        return default


def load_config() -> dict:
    try:
        return json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}


def save_config(cfg: dict):
    try:
        _tmp=CONFIG_PATH.with_name(CONFIG_PATH.name+".tmp")
        _tmp.write_text(json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(_tmp, CONFIG_PATH)
    except Exception:
        pass


class ApplicationLicenseError(ValueError):
    pass


def _clean_hardware_identifier(value) -> str:
    normalized = re.sub(r"[^A-Z0-9]", "", str(value or "").upper())
    rejected = {"", "NONE", "UNKNOWN", "DEFAULTSTRING", "SYSTEMSERIALNUMBER",
                "TOBEFILLEDBYOEM", "NOTSPECIFIED", "NOTAPPLICABLE", "NULL", "0"}
    if normalized in rejected or (normalized and len(set(normalized)) == 1):
        return ""
    return normalized[:160]


def _windows_firmware_identity_parts() -> list[str]:
    """Read the same SMBIOS identifiers as WMI without external commands."""
    try:
        firmware = ctypes.windll.kernel32.GetSystemFirmwareTable
        firmware.argtypes = (
            ctypes.c_uint32,
            ctypes.c_uint32,
            ctypes.c_void_p,
            ctypes.c_uint32,
        )
        firmware.restype = ctypes.c_uint32
        provider = 0x52534D42  # RSMB: raw SMBIOS firmware tables.
        size = int(firmware(provider, 0, None, 0))
        if size < 8 or size > 1024 * 1024:
            return []
        buffer = (ctypes.c_ubyte * size)()
        copied = int(firmware(provider, 0, buffer, size))
        if copied != size:
            return []
        raw = bytes(buffer)
        table_size = struct.unpack_from("<I", raw, 4)[0]
        if table_size < 4 or table_size > len(raw) - 8:
            return []
        table = raw[8:8 + table_size]
        identifiers = {}
        position = 0
        while position + 4 <= len(table):
            kind, length = table[position], table[position + 1]
            if length < 4 or position + length > len(table):
                break
            formatted = table[position:position + length]
            strings_start = position + length
            strings_end = table.find(b"\x00\x00", strings_start)
            if strings_end < 0:
                break
            values = table[strings_start:strings_end].split(b"\x00")

            def read_string(index: int) -> str:
                if index < 1 or index > len(values):
                    return ""
                return values[index - 1].decode("utf-8", errors="ignore")

            if kind == 1:
                if length >= 24:
                    identifier = formatted[8:24]
                    if identifier not in (b"\x00" * 16, b"\xff" * 16):
                        identifiers["uuid"] = str(uuid.UUID(bytes_le=identifier))
                if length >= 8:
                    # Win32_BIOS.SerialNumber comes from the system serial.
                    identifiers["bios"] = read_string(formatted[7])
            elif kind == 2 and length >= 8:
                identifiers["board"] = read_string(formatted[7])
            elif kind == 127:
                break
            position = strings_end + 2

        result = []
        for label in ("uuid", "board", "bios"):
            clean = _clean_hardware_identifier(identifiers.get(label))
            if clean:
                result.append(label + ":" + clean)
        return result
    except (AttributeError, OSError, ValueError, struct.error, TypeError):
        return []


def _hardware_identity_parts(system_name: str | None = None) -> list[str]:
    system = str(system_name or platform.system()).lower()
    parts = []
    if system.startswith("win"):
        parts.extend(_windows_firmware_identity_parts())
    elif system == "linux":
        candidates = (("uuid", "/sys/class/dmi/id/product_uuid"),
                      ("board", "/sys/class/dmi/id/board_serial"),
                      ("product", "/sys/class/dmi/id/product_serial"))
        for label, filename in candidates:
            try:
                clean = _clean_hardware_identifier(Path(filename).read_text(
                    encoding="utf-8", errors="ignore"))
                if clean:
                    parts.append(label + ":" + clean)
            except OSError:
                continue
        if not parts:
            try:
                interfaces = sorted(Path("/sys/class/net").iterdir(),
                                    key=lambda value: value.name.casefold())
            except OSError:
                interfaces = []
            for interface in interfaces:
                lowered = interface.name.casefold()
                if lowered == "lo" or lowered.startswith(
                        ("docker", "veth", "virbr", "br-", "tun", "tap", "wg")):
                    continue
                try:
                    address = interface.joinpath("address").read_text(
                        encoding="utf-8", errors="ignore")
                except OSError:
                    continue
                clean = _clean_hardware_identifier(address)
                if clean and len(clean) == 12:
                    parts.append("network:" + clean)
    if not parts:
        address = int(uuid.getnode())
        if address:
            parts.append("network:" + f"{address:012X}")
    if not parts:
        raise ApplicationLicenseError("Не удалось определить стабильный код компьютера")
    return sorted(set(parts))


def format_machine_code(raw: str) -> str:
    cleaned = re.sub(r"[\s-]+", "", str(raw or "")).upper()
    if cleaned.startswith("JAI"):
        cleaned = cleaned[3:]
    if not re.fullmatch(r"[A-Z2-7]{32}", cleaned):
        raise ApplicationLicenseError("Код компьютера имеет неверный формат")
    return "JAI-" + "-".join(cleaned[index:index + 4] for index in range(0, 32, 4))


@lru_cache(maxsize=1)
def current_machine_code() -> str:
    system = platform.system().lower()
    identity = "|".join(("JewelryAISearch-Hardware-v1", system,
                         *_hardware_identity_parts(system)))
    digest = hashlib.sha256(identity.encode("utf-8")).digest()[:20]
    return format_machine_code(base64.b32encode(digest).decode("ascii"))


def _license_b64decode(value: str, maximum: int) -> bytes:
    text = str(value or "")
    if len(text) > maximum * 2 or not re.fullmatch(r"[A-Za-z0-9_-]+", text):
        raise ApplicationLicenseError("Лицензионный ключ повреждён")
    try:
        padded = text + "=" * (-len(text) % 4)
        decoded = base64.b64decode(padded, altchars=b"-_", validate=True)
    except (ValueError, TypeError) as error:
        raise ApplicationLicenseError("Лицензионный ключ повреждён") from error
    if len(decoded) > maximum:
        raise ApplicationLicenseError("Лицензионный ключ слишком большой")
    return decoded


def _verify_license_signature(payload: bytes, signature: bytes) -> bool:
    try:
        modulus = int(LICENSE_PUBLIC_MODULUS_HEX, 16)
        width = (modulus.bit_length() + 7) // 8
        number = int.from_bytes(signature, "big")
        if len(signature) != width or number >= modulus:
            return False
        decoded = pow(number, LICENSE_PUBLIC_EXPONENT, modulus).to_bytes(width, "big")
        digest_info = (bytes.fromhex("3031300d060960864801650304020105000420")
                       + hashlib.sha256(payload).digest())
        padding = width - len(digest_info) - 3
        if padding < 8:
            return False
        expected = b"\x00\x01" + b"\xff" * padding + b"\x00" + digest_info
        return hmac.compare_digest(decoded, expected)
    except (TypeError, ValueError, OverflowError):
        return False


def validate_application_license(token: str, machine_code: str | None = None,
                                 today=None) -> dict:
    normalized = re.sub(r"\s+", "", str(token or ""))
    if len(normalized) > 12000:
        raise ApplicationLicenseError("Лицензионный ключ слишком большой")
    sections = normalized.split(".")
    if len(sections) != 3 or sections[0] != LICENSE_TOKEN_PREFIX:
        raise ApplicationLicenseError("Это не лицензионный ключ Jewelry AI Search")
    payload = _license_b64decode(sections[1], 4096)
    signature = _license_b64decode(sections[2], 1024)
    if not _verify_license_signature(payload, signature):
        raise ApplicationLicenseError("Подпись лицензии неверна: ключ изменён или поддельный")
    try:
        license_data = json.loads(payload.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ApplicationLicenseError("Содержимое лицензионного ключа повреждено") from error
    if not isinstance(license_data, dict):
        raise ApplicationLicenseError("Содержимое лицензионного ключа повреждено")
    if (license_data.get("format") != LICENSE_FORMAT
            or license_data.get("protocol") != LICENSE_PROTOCOL
            or license_data.get("app_id") != _JAI_UPDATE_APP_ID
            or license_data.get("key_id") != LICENSE_PUBLIC_KEY_ID):
        raise ApplicationLicenseError("Лицензия предназначена для другой версии программы")
    customer = str(license_data.get("customer") or "").strip()
    if not customer or len(customer) > 160:
        raise ApplicationLicenseError("В лицензии не указан пользователь")
    expected_machine = format_machine_code(machine_code or current_machine_code())
    actual_machine = format_machine_code(str(license_data.get("machine") or ""))
    if not hmac.compare_digest(actual_machine, expected_machine):
        raise ApplicationLicenseError("Лицензия выдана для другого компьютера")
    expires = license_data.get("expires_on")
    if expires not in (None, ""):
        try:
            expiration = datetime.strptime(str(expires), "%Y-%m-%d").date()
        except ValueError as error:
            raise ApplicationLicenseError("В лицензии указан неверный срок действия") from error
        current = today or datetime.now().date()
        if current > expiration:
            raise ApplicationLicenseError(
                f"Срок действия лицензии закончился {expiration.strftime('%d.%m.%Y')}")
    return dict(license_data)


def load_application_license(path: Path | None = None,
                             machine_code: str | None = None) -> dict:
    target = Path(path or LICENSE_PATH)
    if not target.is_file() or target.is_symlink():
        raise ApplicationLicenseError("Программа пока не активирована")
    try:
        if target.stat().st_size > 12000:
            raise ApplicationLicenseError("Файл лицензии слишком большой")
        token = target.read_text(encoding="utf-8-sig")
    except OSError as error:
        raise ApplicationLicenseError(f"Не удалось прочитать лицензию: {error}") from error
    return validate_application_license(token, machine_code=machine_code)


def install_application_license(token: str, path: Path | None = None,
                                machine_code: str | None = None) -> dict:
    details = validate_application_license(token, machine_code=machine_code)
    target = Path(path or LICENSE_PATH)
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists() and target.is_symlink():
        raise ApplicationLicenseError("Файл лицензии не должен быть ссылкой")
    temporary = target.parent / (f".license-{os.getpid()}-{time.time_ns()}.tmp")
    try:
        with temporary.open("x", encoding="utf-8") as stream:
            stream.write(re.sub(r"\s+", "", str(token)) + "\n")
            stream.flush()
            os.fsync(stream.fileno())
        try:
            temporary.chmod(0o600)
        except OSError:
            pass
        os.replace(temporary, target)
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass
    return details


def _trial_state_locations() -> tuple[Path, ...]:
    home = APP_DIR.parent
    if os.name == "nt":
        local = Path(os.environ.get("LOCALAPPDATA") or home / "AppData" / "Local")
        roaming = Path(os.environ.get("APPDATA") or home / "AppData" / "Roaming")
        candidates = (TRIAL_STATE_PATH,
                      local / "JewelryAISearch" / "state" / "trial.jaitrial",
                      roaming / "JewelryAISearch" / "state" / "trial.jaitrial")
    else:
        candidates = (TRIAL_STATE_PATH,
                      home / ".local" / "state" / "jewelry-ai-search" / "trial.jaitrial",
                      home / ".config" / "jewelry-ai-search" / "trial.jaitrial")
    return tuple(dict.fromkeys(candidates))


def _trial_registry_state(write: str | None = None) -> tuple[bool, str | None]:
    if os.name != "nt":
        return False, None
    try:
        import winreg
        name = r"Software\JewelryAISearch"
        if write is not None:
            with winreg.CreateKey(winreg.HKEY_CURRENT_USER, name) as key:
                winreg.SetValueEx(key, "TrialStateV1", 0, winreg.REG_SZ, write)
            return True, write
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, name) as key:
            value, kind = winreg.QueryValueEx(key, "TrialStateV1")
        return True, str(value) if kind == winreg.REG_SZ else None
    except (OSError, ImportError, ValueError):
        return False, None


def _trial_record_signature(record: dict, machine: str) -> str:
    protected = {key: value for key, value in record.items() if key != "signature"}
    payload = json.dumps(protected, ensure_ascii=False, sort_keys=True,
                         separators=(",", ":")).encode("utf-8")
    secret = hashlib.sha256(_jai_payload_secret() + b"|JewelryAITrial-v1|"
                            + machine.encode("ascii")).digest()
    return hmac.new(secret, payload, hashlib.sha256).hexdigest()


def _validate_trial_record(value: str, machine: str) -> dict:
    if len(value) > 12000:
        raise ApplicationLicenseError("Запись пробного периода повреждена")
    try:
        record = json.loads(value)
        if not isinstance(record, dict):
            raise ValueError("not an object")
        started = int(record["started_at"])
        expires = int(record["expires_at"])
        last_seen = int(record["last_seen_at"])
        actual_machine = format_machine_code(str(record.get("machine") or ""))
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
        raise ApplicationLicenseError("Запись пробного периода повреждена") from error
    if (record.get("format") != TRIAL_FORMAT
            or record.get("protocol") != TRIAL_PROTOCOL
            or not hmac.compare_digest(actual_machine, machine)
            or started < 946684800 or started > 32503680000
            or expires - started not in {30 * 86400, TRIAL_DURATION_DAYS * 86400}
            or last_seen < started or last_seen > 32503680000):
        raise ApplicationLicenseError("Запись пробного периода не подходит этому компьютеру")
    signature = str(record.get("signature") or "")
    if not hmac.compare_digest(signature, _trial_record_signature(record, machine)):
        raise ApplicationLicenseError("Запись пробного периода изменена или повреждена")
    return record


def _write_trial_record(record: dict, machine: str) -> None:
    secured = dict(record)
    secured["signature"] = _trial_record_signature(secured, machine)
    contents = json.dumps(secured, ensure_ascii=False, sort_keys=True,
                          separators=(",", ":")) + "\n"
    saved = False
    primary_error = None
    for index, location in enumerate(_trial_state_locations()):
        temporary = location.parent / f".trial-{os.getpid()}-{time.time_ns()}.tmp"
        try:
            location.parent.mkdir(parents=True, exist_ok=True)
            if location.exists() and location.is_symlink():
                raise OSError("Запись пробного периода не должна быть ссылкой")
            with temporary.open("x", encoding="utf-8") as stream:
                stream.write(contents)
                stream.flush()
                os.fsync(stream.fileno())
            try:
                temporary.chmod(0o600)
            except OSError:
                pass
            os.replace(temporary, location)
            saved = True
        except OSError as error:
            if index == 0:
                primary_error = error
        finally:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass
    registry_saved, _ = _trial_registry_state(contents)
    if not saved and not registry_saved:
        raise ApplicationLicenseError(
            "Не удалось сохранить пробный период" +
            (f": {primary_error}" if primary_error is not None else ""))


def load_application_trial(now: int | float | None = None,
                           create: bool = True) -> dict:
    current = int(time.time() if now is None else now)
    machine = current_machine_code()
    found = False
    valid = []
    for location in _trial_state_locations():
        try:
            if not location.exists():
                continue
            found = True
            if location.is_symlink() or not location.is_file() or location.stat().st_size > 12000:
                continue
            valid.append(_validate_trial_record(location.read_text(encoding="utf-8-sig"),
                                                machine))
        except (OSError, UnicodeError, ApplicationLicenseError):
            continue
    registry_found, registry_value = _trial_registry_state()
    if registry_found:
        found = True
        try:
            valid.append(_validate_trial_record(str(registry_value or ""), machine))
        except ApplicationLicenseError:
            pass
    if not valid:
        if found:
            raise ApplicationLicenseError(
                "Запись пробного периода повреждена. Введите персональный лицензионный ключ")
        if not create:
            raise ApplicationLicenseError("Пробный период ещё не запущен")
        record = {"format": TRIAL_FORMAT, "protocol": TRIAL_PROTOCOL,
                  "machine": machine, "started_at": current,
                  "expires_at": current + TRIAL_DURATION_DAYS * 86400,
                  "last_seen_at": current}
    else:
        oldest = min(valid, key=lambda item: int(item["started_at"]))
        record = {key: value for key, value in oldest.items() if key != "signature"}
        # Existing 30-day trials keep their original start and become 60-day trials.
        record["expires_at"] = int(record["started_at"]) + TRIAL_DURATION_DAYS * 86400
        latest_seen = max(int(item["last_seen_at"]) for item in valid)
        if current + TRIAL_CLOCK_ROLLBACK_SECONDS < latest_seen:
            raise ApplicationLicenseError(
                "Системные дата или время переведены назад. "
                "Исправьте часы либо активируйте персональную лицензию")
        record["last_seen_at"] = max(latest_seen, current)
    _write_trial_record(record, machine)
    remaining = int(record["expires_at"]) - max(current, int(record["last_seen_at"]))
    if remaining <= 0:
        ended = datetime.fromtimestamp(int(record["expires_at"])).strftime("%d.%m.%Y")
        raise ApplicationLicenseError(
            f"Бесплатный пробный период закончился {ended}. "
            "Для продолжения работы активируйте персональную лицензию")
    details = dict(record)
    details.update({"_access_mode": "trial", "customer": "Пробный период",
                    "remaining_seconds": remaining,
                    "remaining_days": max(1, (remaining + 86399) // 86400),
                    "expires_on": datetime.fromtimestamp(
                        int(record["expires_at"])).date().isoformat()})
    return details


def load_application_access(now: int | float | None = None,
                            create_trial: bool = True) -> dict:
    # 0.97.0: вечная свободная версия. Проверки пробного периода и лицензионных
    # ключей полностью отключены: программа всегда сообщает о бессрочной лицензии.
    # Уже выданные персональные ключи продолжают работать, но больше не требуются.
    return {
        "_access_mode": "license",
        "customer": "Свободная версия",
        "expires_on": None,
        "machine": current_machine_code(),
        "format": LICENSE_FORMAT,
        "protocol": LICENSE_PROTOCOL,
        "app_id": _JAI_UPDATE_APP_ID,
        "key_id": LICENSE_PUBLIC_KEY_ID,
    }



def _trial_days_text(days: int) -> str:
    value = abs(int(days))
    ending = ("день" if value % 10 == 1 and value % 100 != 11 else
              "дня" if value % 10 in (2, 3, 4) and value % 100 not in (12, 13, 14)
              else "дней")
    return f"{value} {ending}"


def application_license_summary(details: dict) -> str:
    if details.get("_access_mode") == "trial":
        expires = datetime.fromtimestamp(int(details["expires_at"])).strftime("%d.%m.%Y")
        return ("Пробный период: осталось "
                + _trial_days_text(int(details.get("remaining_days", 0)))
                + f" · до {expires} · все функции доступны")
    expires = str(details.get("expires_on") or "")
    if expires:
        try:
            expires = datetime.strptime(expires, "%Y-%m-%d").strftime("%d.%m.%Y")
        except ValueError:
            pass
    return f"{details.get('customer', 'Пользователь')} · " + (
        f"до {expires}" if expires else "бессрочная лицензия")


def localized_trial_days_text(days: int, language: str = DEFAULT_UI_LANGUAGE) -> str:
    value = abs(int(days))
    if normalize_ui_language(language) == "en":
        return f"{value} day" + ("" if value == 1 else "s")
    return _trial_days_text(value)


def localized_license_summary(details: dict,
                              language: str = DEFAULT_UI_LANGUAGE) -> str:
    if normalize_ui_language(language) != "en":
        return application_license_summary(details)
    if details.get("_access_mode") == "trial":
        expires = datetime.fromtimestamp(int(details["expires_at"])).strftime("%d.%m.%Y")
        return ("Free trial: "
                + localized_trial_days_text(int(details.get("remaining_days", 0)), "en")
                + f" remaining · until {expires} · all features enabled")
    expires = str(details.get("expires_on") or "")
    if expires:
        try:
            expires = datetime.strptime(expires, "%Y-%m-%d").strftime("%d.%m.%Y")
        except ValueError:
            pass
    customer = str(details.get("customer") or "User")
    return customer + " · " + (f"valid until {expires}" if expires else "lifetime license")


def _file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def local_database_backup_inventory(app_dir: Path = APP_DIR) -> dict:
    """Describe restorable local state without opening or changing user files."""
    directory = Path(app_dir)
    items = []
    for name in SYSTEM_BACKUP_STATE_FILES:
        path = directory / name
        try:
            if not path.is_file():
                continue
            size = int(path.stat().st_size)
        except OSError:
            continue
        items.append({
            "name": name,
            "path": str(path),
            "size": size,
            "sqlite": name in SYSTEM_BACKUP_SQLITE_TABLES,
        })
    return {
        "directory": str(directory),
        "files": items,
        "bytes": sum(item["size"] for item in items),
        "sqlite_files": sum(1 for item in items if item["sqlite"]),
    }


def _snapshot_sqlite_database(source: Path, destination: Path):
    """Copies a live WAL database as one complete, standalone SQLite file."""
    source = Path(source)
    destination = Path(destination)
    # sqlite3.Connection's own context manager commits/rolls back but does NOT close
    # the connection. Windows then refuses to delete or rename its temporary file.
    with closing(sqlite3.connect(str(source), timeout=30)) as original:
        with closing(sqlite3.connect(str(destination), timeout=30)) as copied:
            original.backup(copied, pages=128, sleep=0.025)
            copied.commit()
            copied.execute("PRAGMA journal_mode=DELETE")
            check = copied.execute("PRAGMA quick_check").fetchone()
            if not check or str(check[0]).lower() != "ok":
                raise RuntimeError(f"Не удалось создать целостную копию базы {source.name}.")


def inspect_system_backup(source: Path) -> dict:
    """Validates the private workstation snapshot without touching live databases."""
    source = Path(source)
    try:
        with zipfile.ZipFile(source, "r") as archive:
            entries = archive.infolist()
            if len(entries) > len(SYSTEM_BACKUP_STATE_FILES) + 1:
                raise RuntimeError("В резервном архиве есть лишние или повторяющиеся файлы.")
            names = [item.filename for item in entries]
            if len(names) != len(set(names)) or "manifest.json" not in names:
                raise RuntimeError("Резервный архив повреждён: отсутствует описание снимка.")
            if archive.getinfo("manifest.json").file_size > 1024 * 1024:
                raise RuntimeError("Описание резервного снимка слишком большое.")
            manifest = json.loads(archive.read("manifest.json").decode("utf-8"))
            if not isinstance(manifest, dict) or manifest.get("format") != SYSTEM_BACKUP_FORMAT:
                if isinstance(manifest, dict) and manifest.get("format") == "JewelryAISharePack":
                    raise RuntimeError("Это архив знаний, а не полный резервный снимок. Используй кнопку «Подключить архив знаний (ZIP)».")
                raise RuntimeError("Это не полный резервный снимок Jewelry AI.")
            expected_names = {"manifest.json"} | {f"state/{name}" for name in SYSTEM_BACKUP_STATE_FILES}
            if not set(names).issubset(expected_names):
                raise RuntimeError("В резервном архиве обнаружены неизвестные файлы.")
            if sum(int(item.file_size or 0) for item in entries) > 5 * 1024 * 1024 * 1024:
                raise RuntimeError("Резервный архив слишком большой для безопасного восстановления.")
            if int(manifest.get("version", 0)) != SYSTEM_BACKUP_VERSION:
                raise RuntimeError("Эта версия резервного снимка пока не поддерживается.")
            file_entries = manifest.get("files") or []
            if not isinstance(file_entries, list):
                raise RuntimeError("Некорректное описание файлов резервного снимка.")
            listed = {}
            for item in file_entries:
                if not isinstance(item, dict):
                    raise RuntimeError("Некорректное описание файла резервного снимка.")
                name = str(item.get("name") or "")
                digest = str(item.get("sha256") or "")
                if (name not in SYSTEM_BACKUP_STATE_FILES or name in listed
                        or not re.fullmatch(r"[0-9a-f]{64}", digest)):
                    raise RuntimeError("Некорректное описание файла резервного снимка.")
                listed[name] = item
            missing = set(SYSTEM_BACKUP_SQLITE_TABLES) - set(listed)
            if missing:
                raise RuntimeError("В резервном снимке отсутствуют обязательные SQLite-базы.")
            if {f"state/{name}" for name in listed} != set(names) - {"manifest.json"}:
                raise RuntimeError("Состав резервного снимка не совпадает с его описанием.")
            for name, item in listed.items():
                info = archive.getinfo(f"state/{name}")
                if int(item.get("size", -1)) != int(info.file_size):
                    raise RuntimeError(f"Размер файла {name} в резервном архиве не совпадает.")
            return manifest
    except zipfile.BadZipFile as error:
        raise RuntimeError("Файл не является целым ZIP-архивом Jewelry AI.") from error


def create_system_backup(destination: Path, app_dir: Path = APP_DIR,
                         root: Path | None = None) -> dict:
    """Creates a private, restorable workstation image without packing customer photos."""
    destination = Path(destination)
    app_dir = Path(app_dir)
    destination.parent.mkdir(parents=True, exist_ok=True)
    required = [app_dir / name for name in SYSTEM_BACKUP_SQLITE_TABLES]
    missing = [path.name for path in required if not path.is_file()]
    if missing:
        raise RuntimeError("Не найдены обязательные рабочие базы: " + ", ".join(missing))

    source_root = str(root or "")
    config_path = app_dir / "config.json"
    if not source_root and config_path.is_file():
        try:
            source_root = str(json.loads(config_path.read_text(encoding="utf-8")).get("root") or "")
        except Exception:
            source_root = ""
    counts = {"projects": 0, "images": 0, "qwen_fingerprints": 0,
              "cached_searches": 0, "deep_variants": 0}
    try:
        with closing(sqlite3.connect(str(app_dir / "projects_v2.sqlite3"), timeout=30)) as connection:
            sql = "SELECT COUNT(*) FROM projects" + (" WHERE root=?" if source_root else "")
            counts["projects"] = int(connection.execute(sql, (source_root,) if source_root else ()).fetchone()[0])
            table = connection.execute("SELECT 1 FROM sqlite_master WHERE type='table' "
                                       "AND name='deep_model_variants'").fetchone()
            if table:
                sql = "SELECT COUNT(*) FROM deep_model_variants" + (" WHERE root=?" if source_root else "")
                counts["deep_variants"] = int(connection.execute(
                    sql, (source_root,) if source_root else ()).fetchone()[0])
        with closing(sqlite3.connect(str(app_dir / "index.sqlite3"), timeout=30)) as connection:
            counts["images"] = int(connection.execute("SELECT COUNT(*) FROM images").fetchone()[0])
        with closing(sqlite3.connect(str(app_dir / "ai_fingerprint_cache.sqlite3"), timeout=30)) as connection:
            counts["qwen_fingerprints"] = int(connection.execute("SELECT COUNT(*) FROM fingerprints").fetchone()[0])
            counts["cached_searches"] = int(connection.execute("SELECT COUNT(*) FROM search_cache").fetchone()[0])
    except sqlite3.Error as error:
        raise RuntimeError(f"Не удалось прочитать рабочие базы для резервного снимка: {error}") from error

    temporary_zip = destination.with_name(destination.name + ".tmp")
    try:
        with tempfile.TemporaryDirectory(prefix="jai-system-backup-", dir=str(app_dir)) as temp_name:
            staging = Path(temp_name)
            files = []
            for name in SYSTEM_BACKUP_STATE_FILES:
                source = app_dir / name
                if not source.is_file():
                    continue
                target = staging / name
                if name in SYSTEM_BACKUP_SQLITE_TABLES:
                    _snapshot_sqlite_database(source, target)
                else:
                    shutil.copy2(source, target)
                files.append({"name": name, "size": target.stat().st_size, "sha256": _file_sha256(target)})
            manifest = {
                "format": SYSTEM_BACKUP_FORMAT,
                "version": SYSTEM_BACKUP_VERSION,
                "app_version": APP_VERSION,
                "created_at": time.time(),
                "source_root": source_root,
                "counts": counts,
                "files": files,
                "privacy": "Private backup: includes local paths, project titles, clients and working indexes.",
            }
            with zipfile.ZipFile(temporary_zip, "w", compression=zipfile.ZIP_DEFLATED,
                                 compresslevel=6, allowZip64=True) as archive:
                archive.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
                for item in files:
                    archive.write(staging / item["name"], f"state/{item['name']}")
        os.replace(temporary_zip, destination)
    finally:
        try:
            if temporary_zip.exists():
                temporary_zip.unlink()
        except Exception:
            pass
    return {**counts, "root": source_root, "files": len(manifest["files"]),
            "bytes": destination.stat().st_size}


def application_installation_dir() -> Path:
    """Returns the visible app/executable directory, including a PyInstaller install."""
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent


def choose_automatic_archive_directory(preferred: Path | None = None,
                                       fallback_app_dir: Path = APP_DIR) -> dict:
    """Uses the install folder when writable and falls back visibly for Program Files."""
    installation = Path(preferred or application_installation_dir())
    candidates = [installation, Path(fallback_app_dir) / "Автоархивы"]
    errors = []
    for index, directory in enumerate(candidates):
        try:
            directory.mkdir(parents=True, exist_ok=True)
            with tempfile.NamedTemporaryFile(prefix="jai-write-check-", suffix=".tmp",
                                             dir=str(directory), delete=True) as probe:
                probe.write(b"ok")
                probe.flush()
            return {"directory": directory, "fallback": bool(index), "installation": installation}
        except Exception as error:
            errors.append(f"{directory}: {error}")
    raise RuntimeError("Не удалось сохранить архивы рядом с программой или в резервной папке: " + "; ".join(errors))


def automatic_archive_names(now: datetime | None = None, suffix: str = "") -> dict:
    timestamp = (now or datetime.now()).strftime("%Y-%m-%d_%H-%M-%S")
    suffix = str(suffix or "")
    return {
        "timestamp": timestamp,
        "system": f"Jewelry_AI_ЛИЧНЫЙ_ПОЛНЫЙ_РЕЗЕРВ_{timestamp}{suffix}.zip",
        "knowledge": f"Jewelry_AI_ЗНАНИЯ_ДЛЯ_ОБМЕНА_{timestamp}{suffix}.zip",
    }


def create_automatic_training_archives(project_db, root: Path,
                                       app_dir: Path = APP_DIR,
                                       installation_dir: Path | None = None,
                                       now: datetime | None = None) -> dict:
    """Saves both updated archive formats after training without overwriting history."""
    root = Path(root)
    if not root.is_dir():
        raise RuntimeError("Рабочая папка архива недоступна; автоматические копии не созданы.")
    target = choose_automatic_archive_directory(installation_dir, app_dir)
    directory = Path(target["directory"])
    selected = None
    for number in range(1, 1001):
        suffix = "" if number == 1 else f"_{number:02d}"
        names = automatic_archive_names(now, suffix)
        system_path = directory / names["system"]
        knowledge_path = directory / names["knowledge"]
        if not system_path.exists() and not knowledge_path.exists():
            selected = (names, system_path, knowledge_path)
            break
    if selected is None:
        raise RuntimeError("Не удалось выбрать свободные имена для автоматических архивов.")
    names, system_path, knowledge_path = selected
    try:
        knowledge_stats = project_db.export_share_pack(root, knowledge_path)
    except Exception as error:
        try:
            if knowledge_path.exists():
                knowledge_path.unlink()
        except Exception:
            pass
        raise RuntimeError(f"Не удалось сохранить переносимый архив знаний: {error}") from error
    try:
        system_stats = create_system_backup(system_path, app_dir, root)
    except Exception as error:
        raise RuntimeError(f"Переносимые знания уже сохранены ({knowledge_path.name}), "
                           f"но полный личный резерв создать не удалось: {error}") from error
    return {
        "directory": str(directory),
        "installation": str(target["installation"]),
        "fallback": bool(target["fallback"]),
        "timestamp": names["timestamp"],
        "system_path": str(system_path),
        "knowledge_path": str(knowledge_path),
        "system_name": system_path.name,
        "knowledge_name": knowledge_path.name,
        "system": system_stats,
        "knowledge": knowledge_stats,
    }


# ---------------- 0.95.0: ревизия диска (удержание старых копий) ----------------
ARCHIVE_RETENTION_DEFAULT = {"system": 3, "knowledge": 6, "updates": 3, "preview_days": 45}


def _archive_retention(cfg=None) -> dict:
    cfg = cfg if isinstance(cfg, dict) else load_config()
    raw = cfg.get("retention") or {}
    out = dict(ARCHIVE_RETENTION_DEFAULT)
    for key in ("system", "knowledge", "updates", "preview_days"):
        try:
            out[key] = max(1, min(365, int(raw.get(key, out[key]))))
        except Exception:
            pass
    return out


def _archive_directories() -> list:
    dirs = []
    try:
        dirs.append(Path(choose_automatic_archive_directory(None, APP_DIR)["directory"]))
    except Exception:
        pass
    dirs.append(APP_DIR / "Автоархивы")
    out = []
    seen = set()
    for directory in dirs:
        key = os.path.normcase(str(directory))
        if key not in seen:
            seen.add(key)
            out.append(Path(directory))
    return out


def prune_automatic_archives(directory, keep_system=3, keep_knowledge=6, dry_run=False):
    """Держим только N последних личных резервов и M последних архивов знаний."""
    directory = Path(directory)
    removed = []
    if not directory.is_dir():
        return removed
    groups = (
        ("system", "Jewelry_AI_ЛИЧНЫЙ_ПОЛНЫЙ_РЕЗЕРВ_*.zip", max(1, int(keep_system))),
        ("knowledge", "Jewelry_AI_ЗНАНИЯ_ДЛЯ_ОБМЕНА_*.zip", max(1, int(keep_knowledge))),
    )
    for kind, pattern, keep in groups:
        files = [p for p in directory.glob(pattern) if p.is_file()]
        files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        for path in files[keep:]:
            try:
                size = path.stat().st_size
            except OSError:
                continue
            if not dry_run:
                try:
                    path.unlink()
                except OSError:
                    continue
            removed.append((kind, path.name, size))
    for path in directory.glob("*.zip.tmp"):
        try:
            if time.time() - path.stat().st_mtime > 86400:
                size = path.stat().st_size
                if not dry_run:
                    path.unlink()
                removed.append(("tmp", path.name, size))
        except OSError:
            continue
    return removed


def prune_program_updates(updates_dir, keep=3, dry_run=False):
    """Старые версии обновлений кроме последних N и активной; мусор аварийных запусков."""
    updates_dir = Path(updates_dir)
    removed = []
    active_version = ""
    active = updates_dir / "active.json"
    if active.is_file():
        try:
            active_version = str(json.loads(active.read_text(encoding="utf-8")).get("version") or "")
        except Exception:
            active_version = ""
    versions_dir = updates_dir / "versions"
    versions = []
    if versions_dir.is_dir():
        for entry in versions_dir.iterdir():
            if not entry.is_dir():
                continue
            try:
                versions.append((_jai_version_tuple(entry.name), entry))
            except ValueError:
                continue
    versions.sort(key=lambda item: item[0], reverse=True)
    protected = {entry.name for _, entry in versions[:max(1, int(keep))]}
    if active_version:
        protected.add(active_version)
    for _, entry in versions:
        if entry.name in protected:
            continue
        size = 0
        for path in entry.rglob("*"):
            if path.is_file():
                try:
                    size += path.stat().st_size
                except OSError:
                    pass
        if not dry_run:
            shutil.rmtree(entry, ignore_errors=True)
        removed.append(("update", entry.name, size))
    for pattern in ("active.failed-*.json", ".active-*.tmp", ".app-*.tmp", "last_start_error.txt"):
        for path in updates_dir.glob(pattern):
            try:
                age = time.time() - path.stat().st_mtime
                if pattern == "last_start_error.txt":
                    if age < 7 * 86400:
                        continue
                elif age <= 86400:
                    continue
                size = path.stat().st_size
                if not dry_run:
                    path.unlink()
                removed.append(("update-junk", path.name, size))
            except OSError:
                continue
    return removed


def prune_preview_caches(max_age_days=45, dry_run=False):
    """Старый центральный кэш превью 3D; превью внутри архива пользователя не трогаем."""
    removed = []
    cutoff = time.time() - max(1, int(max_age_days)) * 86400
    for directory in (BLEND_PREVIEW_CACHE_DIR, RHINO_PREVIEW_CACHE_DIR,
                      STL_PREVIEW_CACHE_DIR, DEEP_PREVIEW_CACHE_DIR):
        directory = Path(directory)
        if not directory.is_dir():
            continue
        for path in directory.rglob("*"):
            if not path.is_file() or path.suffix.lower() not in (".png", ".json"):
                continue
            try:
                if path.stat().st_mtime < cutoff:
                    size = path.stat().st_size
                    if not dry_run:
                        path.unlink()
                    removed.append(("preview", path.name, size))
            except OSError:
                continue
    return removed


def run_disk_revision(cfg=None, dry_run=False, include_previews=True):
    retention = _archive_retention(cfg)
    removed = []
    for directory in _archive_directories():
        removed.extend(prune_automatic_archives(
            directory, retention["system"], retention["knowledge"], dry_run))
    removed.extend(prune_program_updates(
        APPLICATION_UPDATE_DIR, retention["updates"], dry_run))
    if include_previews:
        removed.extend(prune_preview_caches(retention["preview_days"], dry_run))
    return removed, retention



def _replace_path_prefix(value: str, old_root: str, new_root: str) -> str:
    """Rewrites only exact path-prefix matches, never arbitrary text occurrences."""
    original = str(value or "")
    old = str(old_root or "").rstrip("\\/")
    new = str(new_root or "").rstrip("\\/")
    if not old or not original:
        return original
    candidate = original.replace("\\", "/")
    old_candidate = old.replace("\\", "/")
    if candidate.lower() == old_candidate.lower():
        return new
    prefix = old_candidate + "/"
    if not candidate.lower().startswith(prefix.lower()):
        return original
    remainder = candidate[len(prefix):]
    if "\\" in new or re.match(r"^[a-zA-Z]:", new):
        return new + "\\" + remainder.replace("/", "\\")
    return str(Path(new).joinpath(*remainder.split("/")))


def _rewrite_restored_root(staging: Path, old_root: str, new_root: str) -> dict:
    """Moves stored paths to a new drive letter without re-embedding or losing Qwen cards."""
    old_root = str(old_root or "")
    new_root = str(new_root or "")
    if not old_root or not new_root or os.path.normcase(os.path.normpath(old_root)) == os.path.normcase(os.path.normpath(new_root)):
        return {"projects_remapped": 0, "images_remapped": 0}
    staging = Path(staging)
    with closing(sqlite3.connect(str(staging / "projects_v2.sqlite3"), timeout=30)) as connection:
        samples = connection.execute("SELECT representative_paths_json,image_paths_json FROM projects WHERE root=? LIMIT 12",
                                     (old_root,)).fetchall()
    expected_paths = []
    for representatives_json, images_json in samples:
        options = json_loads_safe(representatives_json, []) or json_loads_safe(images_json, [])
        if options:
            expected_paths.append(_replace_path_prefix(options[0], old_root, new_root))
    if expected_paths and not any(Path(path).is_file() for path in expected_paths):
        raise RuntimeError("Выбранная папка не похожа на сохранённый рабочий архив: изображения из резервного снимка в ней не найдены.")
    image_count = 0
    with closing(sqlite3.connect(str(staging / "index.sqlite3"), timeout=30)) as connection:
        for row_id, path, folder in connection.execute("SELECT id,path,folder FROM images").fetchall():
            replacement = _replace_path_prefix(path, old_root, new_root)
            if replacement == str(path):
                continue
            connection.execute("UPDATE images SET path=?,folder=? WHERE id=?",
                               (replacement, _replace_path_prefix(folder, old_root, new_root), int(row_id)))
            image_count += 1
        connection.commit()

    changed_signatures = {}
    project_count = 0
    with closing(sqlite3.connect(str(staging / "projects_v2.sqlite3"), timeout=30)) as connection:
        rows = connection.execute("""SELECT id,folder,image_paths_json,representative_paths_json,
                                  source_signature,vision_signature FROM projects WHERE root=?""", (old_root,)).fetchall()
        for project_id, folder, images_json, representatives_json, old_signature, vision_signature in rows:
            changed_folder = _replace_path_prefix(folder, old_root, new_root)
            images = [_replace_path_prefix(item, old_root, new_root)
                      for item in json_loads_safe(images_json, [])]
            representatives = [_replace_path_prefix(item, old_root, new_root)
                               for item in json_loads_safe(representatives_json, [])]
            new_signature = file_signature(images)
            project_key = hashlib.sha1((new_root.lower() + "|" + changed_folder.lower()).encode("utf-8", "ignore")).hexdigest()
            active_signature = new_signature if str(vision_signature or "") == str(old_signature or "") else vision_signature
            connection.execute("""UPDATE projects SET root=?,project_key=?,folder=?,image_paths_json=?,
                               representative_paths_json=?,source_signature=?,vision_signature=? WHERE id=?""",
                               (new_root, project_key, changed_folder, json.dumps(images, ensure_ascii=False),
                                json.dumps(representatives, ensure_ascii=False), new_signature,
                                active_signature, int(project_id)))
            connection.execute("UPDATE project_vision_runs SET source_signature=? WHERE project_id=? AND source_signature=?",
                               (new_signature, int(project_id), str(old_signature or "")))
            changed_signatures[int(project_id)] = new_signature
            project_count += 1
        connection.execute("UPDATE jewelry_learning_models SET root=? WHERE root=?", (new_root, old_root))
        tables = {str(row[0]) for row in connection.execute(
            "SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        for table in ("deep_model_sources", "deep_model_variants"):
            if table not in tables:
                continue
            for source_path, in connection.execute(
                    f"SELECT DISTINCT source_path FROM {table} WHERE root=?", (old_root,)).fetchall():
                connection.execute(f"UPDATE {table} SET root=?,source_path=? "
                                   "WHERE root=? AND source_path=?",
                                   (new_root, _replace_path_prefix(source_path, old_root, new_root),
                                    old_root, source_path))
        connection.commit()

    with closing(sqlite3.connect(str(staging / "ai_fingerprint_cache.sqlite3"), timeout=30)) as connection:
        connection.executemany("UPDATE fingerprints SET file_hash=? WHERE project_id=?",
                               [(signature, project_id) for project_id, signature in changed_signatures.items()])
        # Old cache keys include the complete source signature. The actual cards and the
        # last visible result survive; only impossible-to-remap query keys are invalidated.
        connection.execute("DELETE FROM search_cache")
        connection.commit()

    for name in ("config.json", "last_search_session.json"):
        target = staging / name
        if not target.is_file():
            continue
        try:
            payload = json.loads(target.read_text(encoding="utf-8"))
            if isinstance(payload, dict) and payload.get("root"):
                payload["root"] = _replace_path_prefix(payload["root"], old_root, new_root)
                target.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as error:
            raise RuntimeError(f"Не удалось обновить путь архива в файле {name}: {error}") from error

    vector_path = staging / "jai_vector_index.bin"
    if vector_path.is_file():
        try:
            with np.load(vector_path, allow_pickle=False) as index:
                ids = np.asarray(index["ids"])
                vectors = np.asarray(index["vectors"])
            with closing(sqlite3.connect(str(staging / "projects_v2.sqlite3"), timeout=30)) as connection:
                rows = connection.execute("SELECT id,project_key,source_signature,dim FROM projects WHERE root=?", (new_root,)).fetchall()
            digest = hashlib.sha1()
            for project_id, project_key, signature, dimension in sorted(rows, key=lambda row: str(row[0])):
                digest.update("|".join((str(project_id), str(project_key or ""),
                                        str(signature or ""), str(int(dimension or 0)))).encode("utf-8", "ignore"))
                digest.update(b"\n")
            with vector_path.open("wb") as stream:
                np.savez_compressed(stream, ids=ids, vectors=vectors, signature=np.array(digest.hexdigest()))
        except Exception as error:
            raise RuntimeError(f"Не удалось перенести готовый векторный индекс: {error}") from error
    return {"projects_remapped": project_count, "images_remapped": image_count}


def restore_system_backup(source: Path, app_dir: Path = APP_DIR,
                          replacement_root: Path | None = None) -> dict:
    """Validates, stages and atomically restores all workstation state with rollback."""
    source = Path(source)
    app_dir = Path(app_dir)
    app_dir.mkdir(parents=True, exist_ok=True)
    manifest = inspect_system_backup(source)
    with tempfile.TemporaryDirectory(prefix="jai-system-restore-", dir=str(app_dir)) as temp_name:
        temporary = Path(temp_name)
        staging = temporary / "staging"
        rollback = temporary / "rollback"
        staging.mkdir()
        rollback.mkdir()
        with zipfile.ZipFile(source, "r") as archive:
            for item in manifest["files"]:
                name = item["name"]
                target = staging / name
                with archive.open(f"state/{name}") as original, target.open("wb") as copied:
                    shutil.copyfileobj(original, copied, length=1024 * 1024)
                if target.stat().st_size != int(item["size"]) or _file_sha256(target) != item["sha256"]:
                    raise RuntimeError(f"Файл {name} повреждён: контрольная сумма не совпадает.")
                table = SYSTEM_BACKUP_SQLITE_TABLES.get(name)
                if table:
                    with closing(sqlite3.connect(str(target), timeout=30)) as connection:
                        check = connection.execute("PRAGMA quick_check").fetchone()
                        exists = connection.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)).fetchone()
                        if not check or str(check[0]).lower() != "ok" or not exists:
                            raise RuntimeError(f"База {name} в резервном снимке повреждена или несовместима.")

        source_root = str(manifest.get("source_root") or "")
        target_root = str(replacement_root or source_root)
        remapped = _rewrite_restored_root(staging, source_root, target_root) if replacement_root else {
            "projects_remapped": 0, "images_remapped": 0,
        }
        config_path = staging / "config.json"
        try:
            config = json.loads(config_path.read_text(encoding="utf-8")) if config_path.is_file() else {}
            if not isinstance(config, dict):
                config = {}
            if target_root:
                config["root"] = target_root
            config["skip_startup_sync_once"] = True
            config_path.write_text(json.dumps(config, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as error:
            raise RuntimeError(f"Не удалось подготовить восстановленные настройки: {error}") from error

        names = list(dict.fromkeys([item["name"] for item in manifest["files"]] + ["config.json"]))
        moved = []
        installed = []
        try:
            for name in names:
                target = app_dir / name
                for suffix in ("", "-wal", "-shm", "-journal") if name in SYSTEM_BACKUP_SQLITE_TABLES else ("",):
                    old_path = Path(str(target) + suffix)
                    if old_path.exists():
                        backup_path = rollback / old_path.name
                        os.replace(old_path, backup_path)
                        moved.append((backup_path, old_path))
                staged = staging / name
                if staged.exists():
                    os.replace(staged, target)
                    installed.append(target)
        except Exception as error:
            for target in reversed(installed):
                try:
                    target.unlink()
                except Exception:
                    pass
            for backup_path, original_path in reversed(moved):
                try:
                    os.replace(backup_path, original_path)
                except Exception:
                    pass
            raise RuntimeError(f"Не удалось восстановить резервный снимок; старая база сохранена: {error}") from error
    return {**(manifest.get("counts") or {}), **remapped,
            "root": target_root, "source_root": source_root, "files": len(names)}


def load_last_search_snapshot(path:Path=LAST_SEARCH_PATH)->dict:
    try:
        data=json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data,dict) and int(data.get("version",0))==1 else {}
    except Exception:
        return {}


def save_last_search_snapshot(snapshot:dict,path:Path=LAST_SEARCH_PATH)->bool:
    tmp=path.with_name(path.name+".tmp")
    try:
        payload=dict(snapshot or {}); payload["version"]=1; payload["saved_at"]=time.time()
        tmp.write_text(json.dumps(payload,ensure_ascii=False,separators=(",",":")),encoding="utf-8")
        os.replace(tmp,path)
        return True
    except Exception:
        try:
            if tmp.exists(): tmp.unlink()
        except Exception: pass
        return False


def format_search_duration(seconds:float)->str:
    try: value=max(0.0,float(seconds))
    except Exception: value=0.0
    if value<1.0:
        return f"{value*1000:.0f} мс"
    if value<60.0:
        return f"{value:.2f} с"
    minutes=int(value//60)
    return f"{minutes} мин {value-minutes*60:.1f} с"


def make_completion_chime()->bytes:
    """Quiet two-note WAV playable directly from memory on Windows."""
    import wave
    sample_rate=22050
    gap=np.zeros(int(sample_rate*0.035),dtype=np.float32)
    notes=[]
    for frequency,duration in ((523.25,0.18),(659.25,0.24)):
        t=np.arange(int(sample_rate*duration),dtype=np.float32)/sample_rate
        fade=np.minimum(np.minimum(t/0.028,(duration-t)/0.09),1.0)
        fade=np.clip(fade,0.0,1.0)
        tone=(np.sin(2*np.pi*frequency*t)*0.11 + np.sin(2*np.pi*frequency*2*t)*0.022)*fade
        notes.append(tone.astype(np.float32))
    samples=np.concatenate((notes[0],gap,notes[1]))
    pcm=np.clip(samples*32767,-32768,32767).astype("<i2")
    stream=BytesIO()
    with wave.open(stream,"wb") as wav:
        wav.setnchannels(1); wav.setsampwidth(2); wav.setframerate(sample_rate)
        wav.writeframes(pcm.tobytes())
    return stream.getvalue()


def catalog_entry(tag: str) -> dict | None:
    t = str(tag or "").strip()
    for x in MODEL_CATALOG:
        if x.get("tag") == t:
            return x
    return None


def ollama_installed_models(timeout=3) -> dict[str, dict]:
    """Возвращает установленные в локальном Ollama модели по их тегам."""
    try:
        with urllib.request.urlopen(OLLAMA_TAGS_URL, timeout=timeout) as r:
            data = json.loads(r.read().decode("utf-8", "replace"))
    except Exception as e:
        raise RuntimeError("Ollama недоступен. Запусти Ollama и попробуй ещё раз.") from e
    out = {}
    for item in data.get("models", []) or []:
        name = str(item.get("name") or item.get("model") or "").strip()
        if name:
            out[name] = item
    return out


def ollama_version(timeout=3) -> str:
    """Версия локального Ollama. Нужна, чтобы отличать проблему модели от старого runtime."""
    try:
        with urllib.request.urlopen(OLLAMA_VERSION_URL, timeout=timeout) as r:
            data = json.loads(r.read().decode("utf-8", "replace"))
        return str(data.get("version") or "").strip()
    except Exception:
        return ""


def _find_ollama_exe() -> str:
    """Ищет команду Ollama для fallback на Windows, Linux и macOS."""
    p = shutil.which("ollama")
    if p:
        return p
    if os.name == "nt":
        candidates = [
            Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "Ollama" / "ollama.exe",
            Path(os.environ.get("ProgramFiles", "")) / "Ollama" / "ollama.exe",
        ]
        for c in candidates:
            try:
                if c and c.exists():
                    return str(c)
            except Exception:
                pass
    return ""


def ollama_pull_model_cli(tag: str, progress_cb=None, timeout=60*60*4):
    """Fallback: запускает `ollama pull` скрыто. Пользователю командная строка не нужна."""
    exe = _find_ollama_exe()
    if not exe:
        raise RuntimeError("Не найдена команда Ollama. Запусти или переустанови Ollama, "
                           "затем повтори скачивание.")
    if progress_cb:
        progress_cb("API не сработал — пробую встроенный fallback Ollama", 0, 0)
    creationflags = 0
    if os.name == "nt" and hasattr(subprocess, "CREATE_NO_WINDOW"):
        creationflags = subprocess.CREATE_NO_WINDOW
    proc = subprocess.Popen(
        [exe, "pull", str(tag).strip()],
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
        text=True, encoding="utf-8", errors="replace",
        creationflags=creationflags,
    )
    started=time.time(); last=""
    try:
        while True:
            if time.time()-started > timeout:
                proc.kill(); raise RuntimeError("Скачивание модели превысило допустимое время.")
            line=proc.stdout.readline() if proc.stdout else ""
            if line:
                last=line.strip()
                if progress_cb: progress_cb(last,0,0)
            if proc.poll() is not None:
                break
            if not line:
                time.sleep(0.05)
        if proc.returncode != 0:
            raise RuntimeError(last or f"ollama pull завершился с кодом {proc.returncode}")
    finally:
        try:
            if proc.stdout: proc.stdout.close()
        except Exception:
            pass




def _probe_image_b64() -> str:
    """Крошечная тестовая картинка для проверки, что Vision-модель реально запускается."""
    img = Image.new("RGB", (96, 96), "white")
    d = ImageDraw.Draw(img)
    d.ellipse((22, 22, 74, 74), outline="black", width=5)
    bio = BytesIO()
    img.save(bio, format="PNG")
    return base64.b64encode(bio.getvalue()).decode("ascii")


def friendly_model_error(message: str) -> str:
    s = str(message or "").strip()
    low = norm(s)
    if "unknown model architecture" in low and "mllama" in low:
        return ("Модель скачана, но текущий движок Ollama не умеет её запустить: архитектура mllama не загрузилась. "
                "Это не ошибка распознавания и не результат анализа — модель вообще не стартовала.")
    if "llama-server process has terminated" in low:
        return "Ollama не смог запустить выбранную модель. Это ошибка запуска движка, а не качество распознавания. " + s
    return s


def ollama_probe_model(model: str, vision: bool = False, timeout: int = 75) -> str:
    """Проверяет не только наличие модели в списке Ollama, но и реальный запуск runner-а."""
    msg = {"role": "user", "content": "Ответь одним словом: OK"}
    if vision:
        msg["images"] = [_probe_image_b64()]
        msg["content"] = "Посмотри на тестовую картинку и ответь одним словом: OK"
    payload = {
        "model": str(model),
        "messages": [msg],
        "stream": False,
        "keep_alive": "2m",
        "options": {"temperature": 0.0},
    }
    req = urllib.request.Request(
        OLLAMA_CHAT_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            data = json.loads(r.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        try:
            detail = e.read().decode("utf-8", "replace")
        except Exception:
            detail = str(e)
        raise RuntimeError(friendly_model_error(f"Ollama вернул ошибку {e.code}: {detail[:700]}")) from e
    except urllib.error.URLError as e:
        raise RuntimeError("Ollama недоступен. Запусти Ollama и попробуй снова.") from e
    content = ((data.get("message") or {}).get("content") or data.get("response") or "").strip()
    return content or "OK"


def is_model_start_error(message: str) -> bool:
    low = norm(message)
    markers = (
        "unknown model architecture", "llama-server process has terminated", "error loading model",
        "model not found", "модель не найдена", "ollama недоступен", "out of memory", "cuda out of memory",
    )
    return any(x in low for x in markers)

def ollama_model_is_installed(tag: str, installed: dict[str, dict] | None = None) -> bool:
    tag = str(tag or "").strip()
    if not tag:
        return False
    if installed is None:
        try:
            installed = ollama_installed_models()
        except Exception:
            return False
    if tag in installed:
        return True
    if ":" not in tag and (tag + ":latest") in installed:
        return True
    if tag.endswith(":latest") and tag[:-7] in installed:
        return True
    return False


def ollama_pull_model(tag: str, progress_cb=None, timeout=60*60*4):
    """Скачивает модель через официальный локальный Ollama API и отдаёт прогресс в callback."""
    payload = {"model": str(tag).strip(), "stream": True}
    req = urllib.request.Request(
        OLLAMA_PULL_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            for raw in r:
                if not raw:
                    continue
                try:
                    msg = json.loads(raw.decode("utf-8", "replace"))
                except Exception:
                    continue
                status = str(msg.get("status") or "").strip()
                completed = int(msg.get("completed") or 0)
                total = int(msg.get("total") or 0)
                if progress_cb:
                    progress_cb(status, completed, total)
                if msg.get("error"):
                    raise RuntimeError(str(msg.get("error")))
    except urllib.error.HTTPError as e:
        try:
            detail = e.read().decode("utf-8", "replace")
        except Exception:
            detail = str(e)
        raise RuntimeError(f"Ollama не смог скачать модель: {detail}") from e
    except urllib.error.URLError as e:
        raise RuntimeError("Не удалось связаться с Ollama. Проверь, что Ollama запущен и есть интернет для скачивания модели.") from e


def human_size(n: int) -> str:
    try:
        n = float(n or 0)
    except Exception:
        return ""
    for unit in ("Б", "КБ", "МБ", "ГБ", "ТБ"):
        if n < 1024.0 or unit == "ТБ":
            return f"{n:.1f} {unit}" if unit != "Б" else f"{int(n)} {unit}"
        n /= 1024.0
    return ""


def open_folder(path: str):
    p = Path(path)
    folder = p if p.is_dir() else p.parent
    try:
        if os.name == "nt":
            os.startfile(str(folder))
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(folder)])
        else:
            subprocess.Popen(["xdg-open", str(folder)])
    except Exception as e:
        messagebox.showerror("Ошибка", f"Не удалось открыть папку:\n{e}")


def open_project(project: dict):
    """Opens a 3D source itself; ordinary gallery projects keep opening folders."""
    source = Path(str((project or {}).get("folder") or ""))
    if source.suffix.lower() not in MODEL_EXTS or not source.is_file():
        open_folder(str(source))
        return
    try:
        if os.name == "nt":
            os.startfile(str(source))
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(source)])
        else:
            subprocess.Popen(["xdg-open", str(source)])
    except Exception as error:
        messagebox.showerror("Ошибка", f"Не удалось открыть 3D-файл:\n{error}")


def _read_blend_bytes(stream, size: int) -> bytes:
    """Some gzip/zstd readers return short reads before reaching EOF."""
    if size < 0 or size > BLEND_PREVIEW_MAX_SCAN_BYTES:
        raise ValueError("Некорректный размер блока Blender.")
    chunks = bytearray()
    while len(chunks) < size:
        chunk = stream.read(size - len(chunks))
        if not chunk:
            raise ValueError("Файл Blender повреждён или обрезан.")
        chunks.extend(chunk)
    return bytes(chunks)


def _skip_blend_bytes(stream, size: int):
    remaining = int(size)
    while remaining:
        chunk = stream.read(min(remaining, 128 * 1024))
        if not chunk:
            raise ValueError("Файл Blender повреждён или обрезан.")
        remaining -= len(chunk)


def extract_blend_preview(path: str | Path) -> Image.Image:
    """Reads the embedded TEST thumbnail without opening or executing a .blend scene."""
    source = Path(path)
    with source.open("rb") as raw:
        compression_magic = raw.read(4)
        raw.seek(0)
        if compression_magic.startswith(b"\x1f\x8b"):
            stream = gzip.GzipFile(fileobj=raw, mode="rb")
        elif compression_magic == b"\x28\xb5\x2f\xfd":
            try:
                import zstandard
            except ImportError as error:
                raise RuntimeError(
                    "Для сжатого файла Blender требуется библиотека zstandard. "
                    "Установите обновлённую версию Jewelry AI Search."
                ) from error
            stream = zstandard.ZstdDecompressor().stream_reader(raw)
        else:
            stream = raw

        try:
            header = _read_blend_bytes(stream, 12)
            if not header.startswith(b"BLENDER"):
                raise ValueError("Это не файл Blender с поддерживаемым форматом.")
            pointer_marker = header[7:8]
            endian_marker = header[8:9]
            if pointer_marker not in {b"_", b"-"} or endian_marker not in {b"v", b"V"}:
                raise ValueError("Некорректный заголовок файла Blender.")
            pointer_size = 8 if pointer_marker == b"-" else 4
            byte_order = "<" if endian_marker == b"v" else ">"
            block_header_size = 16 + pointer_size
            scanned = 12

            while scanned < BLEND_PREVIEW_MAX_SCAN_BYTES:
                block = _read_blend_bytes(stream, block_header_size)
                scanned += block_header_size
                code = block[:4]
                length = struct.unpack(byte_order + "I", block[4:8])[0]
                if code == b"ENDB":
                    break
                if length > BLEND_PREVIEW_MAX_SCAN_BYTES - scanned:
                    raise ValueError("Превью Blender не найдено в безопасной части файла.")

                if code != b"TEST":
                    _skip_blend_bytes(stream, length)
                    scanned += length
                    continue

                if length < 8:
                    raise ValueError("Встроенное превью Blender повреждено.")
                dimensions = _read_blend_bytes(stream, 8)
                width, height = struct.unpack(byte_order + "II", dimensions)
                if not (1 <= width <= BLEND_PREVIEW_MAX_SIDE
                        and 1 <= height <= BLEND_PREVIEW_MAX_SIDE):
                    raise ValueError("Недопустимый размер встроенного превью Blender.")
                pixel_bytes = width * height * 4
                if pixel_bytes > length - 8:
                    raise ValueError("Встроенное превью Blender повреждено.")
                rgba = Image.frombytes("RGBA", (width, height),
                                       _read_blend_bytes(stream, pixel_bytes))
                rgba = rgba.transpose(Image.Transpose.FLIP_TOP_BOTTOM)
                background = Image.new("RGBA", rgba.size, (255, 255, 255, 255))
                background.alpha_composite(rgba)
                return background.convert("RGB")
        finally:
            if stream is not raw:
                stream.close()

    raise ValueError(
        "В файле Blender нет встроенного превью. Откройте его в Blender, "
        "включите сохранение миниатюр и сохраните проект повторно."
    )


def extract_windows_shell_thumbnail(path: str | Path, size: int = 512) -> Image.Image:
    """Returns the real Windows Explorer thumbnail, never a generic file icon."""
    if os.name != "nt":
        raise RuntimeError("Миниатюры Проводника Windows недоступны в этой системе.")
    if not 16 <= int(size) <= BLEND_PREVIEW_MAX_SIDE:
        raise ValueError("Недопустимый размер миниатюры Rhino.")

    class GUID(ctypes.Structure):
        _fields_ = [("Data1", ctypes.c_uint32), ("Data2", ctypes.c_uint16),
                    ("Data3", ctypes.c_uint16), ("Data4", ctypes.c_ubyte * 8)]

    class SIZE(ctypes.Structure):
        _fields_ = [("cx", ctypes.c_long), ("cy", ctypes.c_long)]

    class BITMAP(ctypes.Structure):
        _fields_ = [("bmType", ctypes.c_long), ("bmWidth", ctypes.c_long),
                    ("bmHeight", ctypes.c_long), ("bmWidthBytes", ctypes.c_long),
                    ("bmPlanes", ctypes.c_ushort), ("bmBitsPixel", ctypes.c_ushort),
                    ("bmBits", ctypes.c_void_p)]

    class BITMAPINFOHEADER(ctypes.Structure):
        _fields_ = [("biSize", ctypes.c_uint32), ("biWidth", ctypes.c_long),
                    ("biHeight", ctypes.c_long), ("biPlanes", ctypes.c_ushort),
                    ("biBitCount", ctypes.c_ushort), ("biCompression", ctypes.c_uint32),
                    ("biSizeImage", ctypes.c_uint32), ("biXPelsPerMeter", ctypes.c_long),
                    ("biYPelsPerMeter", ctypes.c_long), ("biClrUsed", ctypes.c_uint32),
                    ("biClrImportant", ctypes.c_uint32)]

    class BITMAPINFO(ctypes.Structure):
        _fields_ = [("bmiHeader", BITMAPINFOHEADER), ("bmiColors", ctypes.c_uint32)]

    ole32 = ctypes.windll.ole32
    shell32 = ctypes.windll.shell32
    gdi32 = ctypes.windll.gdi32
    user32 = ctypes.windll.user32
    initialize = ole32.CoInitializeEx
    initialize.argtypes = [ctypes.c_void_p, ctypes.c_uint32]
    initialize.restype = ctypes.c_long
    init_result = initialize(None, 2)
    must_uninitialize = init_result in (0, 1)
    if not must_uninitialize and (init_result & 0xffffffff) != 0x80010106:
        raise OSError(f"Не удалось подготовить миниатюры Windows: 0x{init_result & 0xffffffff:08X}")

    shell_item = ctypes.c_void_p()
    bitmap_handle = ctypes.c_void_p()
    device_context = ctypes.c_void_p()
    try:
        factory_iid = GUID.from_buffer_copy(bytes.fromhex("798bc1bc16ba2f4480c48a59c30c463b"))
        create_item = shell32.SHCreateItemFromParsingName
        create_item.argtypes = [ctypes.c_wchar_p, ctypes.c_void_p,
                                ctypes.POINTER(GUID), ctypes.POINTER(ctypes.c_void_p)]
        create_item.restype = ctypes.c_long
        result = create_item(str(Path(path).resolve()), None,
                             ctypes.byref(factory_iid), ctypes.byref(shell_item))
        if result < 0 or not shell_item.value:
            raise OSError(f"Проводник не смог открыть файл Rhino: 0x{result & 0xffffffff:08X}")

        vtable = ctypes.cast(shell_item, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
        get_image = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p, SIZE,
                                       ctypes.c_uint32, ctypes.POINTER(ctypes.c_void_p))(vtable[3])
        result = get_image(shell_item, SIZE(int(size), int(size)), 0x08,
                           ctypes.byref(bitmap_handle))
        if result < 0 or not bitmap_handle.value:
            raise ValueError("Для этого Rhino-файла Проводник Windows не нашёл миниатюру.")

        bitmap = BITMAP()
        gdi32.GetObjectW.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
        gdi32.GetObjectW.restype = ctypes.c_int
        if gdi32.GetObjectW(bitmap_handle, ctypes.sizeof(bitmap), ctypes.byref(bitmap)) <= 0:
            raise OSError("Не удалось прочитать миниатюру Rhino из Windows.")
        width, height = int(bitmap.bmWidth), abs(int(bitmap.bmHeight))
        if not (1 <= width <= BLEND_PREVIEW_MAX_SIDE and 1 <= height <= BLEND_PREVIEW_MAX_SIDE):
            raise ValueError("Недопустимый размер миниатюры Rhino.")

        info = BITMAPINFO()
        info.bmiHeader.biSize = ctypes.sizeof(BITMAPINFOHEADER)
        info.bmiHeader.biWidth = width
        info.bmiHeader.biHeight = -height
        info.bmiHeader.biPlanes = 1
        info.bmiHeader.biBitCount = 32
        pixels = ctypes.create_string_buffer(width * height * 4)
        user32.GetDC.argtypes = [ctypes.c_void_p]
        user32.GetDC.restype = ctypes.c_void_p
        device_context = ctypes.c_void_p(user32.GetDC(None))
        if not device_context.value:
            raise OSError("Не удалось открыть графический контекст Windows.")
        gdi32.GetDIBits.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint,
                                    ctypes.c_uint, ctypes.c_void_p,
                                    ctypes.POINTER(BITMAPINFO), ctypes.c_uint]
        gdi32.GetDIBits.restype = ctypes.c_int
        copied = gdi32.GetDIBits(device_context, bitmap_handle, 0, height,
                                pixels, ctypes.byref(info), 0)
        if copied != height:
            raise OSError("Не удалось преобразовать миниатюру Rhino в изображение.")
        image = Image.frombuffer("RGBA", (width, height), pixels.raw, "raw", "BGRA", 0, 1)
        if image.getchannel("A").getextrema() == (0, 0):
            image.putalpha(255)
        background = Image.new("RGBA", image.size, (255, 255, 255, 255))
        background.alpha_composite(image)
        return background.convert("RGB")
    finally:
        if device_context.value:
            user32.ReleaseDC.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            user32.ReleaseDC(None, device_context)
        if bitmap_handle.value:
            gdi32.DeleteObject.argtypes = [ctypes.c_void_p]
            gdi32.DeleteObject(bitmap_handle)
        if shell_item.value:
            vtable = ctypes.cast(shell_item, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
            release = ctypes.WINFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p)(vtable[2])
            release(shell_item)
        if must_uninitialize:
            ole32.CoUninitialize()


def _embedded_rhino_image(payload: bytes) -> Image.Image | None:
    """Finds a valid PNG/JPEG preview near the front of an openNURBS file."""
    signatures = ((b"\x89PNG\r\n\x1a\n", "PNG"), (b"\xff\xd8\xff", "JPEG"))
    for marker, expected in signatures:
        offset = 0
        attempts = 0
        while attempts < 32:
            position = payload.find(marker, offset)
            if position < 0:
                break
            attempts += 1
            offset = position + len(marker)
            try:
                with Image.open(BytesIO(payload[position:])) as image:
                    if image.format != expected:
                        continue
                    width, height = image.size
                    if not (16 <= width <= BLEND_PREVIEW_MAX_SIDE
                            and 16 <= height <= BLEND_PREVIEW_MAX_SIDE):
                        continue
                    rgba = image.convert("RGBA")
                    background = Image.new("RGBA", rgba.size, (255, 255, 255, 255))
                    background.alpha_composite(rgba)
                    return background.convert("RGB")
            except Exception:
                continue
    return None


def _matching_model_image(source: Path) -> Image.Image | None:
    """Use only an image unambiguously named after this exact 3D project."""
    for suffix in ("", "_preview", "-preview", ".preview", "_render", "-render"):
        stem=source.stem+suffix
        for extension in (".png",".jpg",".jpeg",".webp",".bmp",".tif",".tiff"):
            candidate=source.with_name(stem+extension)
            if not candidate.is_file():continue
            try:
                with Image.open(candidate) as image:
                    return ImageOps.exif_transpose(image).convert("RGB")
            except Exception:
                continue
    return None


def _rhino_point_xyz(point) -> tuple[float,float,float]:
    if hasattr(point,"X"):
        result=(float(point.X),float(point.Y),float(point.Z))
    else:
        result=(float(point[0]),float(point[1]),float(point[2]))
    if not all(np.isfinite(value) for value in result):
        raise ValueError("Модель Rhino содержит недопустимые координаты.")
    return result


def _rhino_geometry_meshes(geometry,rhino):
    """Return native meshes and render meshes already saved in 3DM Breps."""
    if geometry is None:return
    if hasattr(geometry,"Vertices") and hasattr(geometry,"Faces"):
        yield geometry
        return
    mesh_type=getattr(rhino,"MeshType",None)
    types=[getattr(mesh_type,name,None) for name in ("Render","Any","Preview","Default","Analysis")]
    types=[value for value in types if value is not None]
    if hasattr(geometry,"GetMesh"):
        for kind in types:
            try:
                mesh=geometry.GetMesh(kind)
                if mesh is not None:
                    yield mesh
                    return
            except Exception:
                continue
    faces=getattr(geometry,"Faces",None)
    if faces is not None:
        for face in faces:
            getter=getattr(face,"GetMesh",None)
            if getter is None:continue
            for kind in types:
                try:
                    mesh=getter(kind)
                    if mesh is not None:
                        yield mesh
                        break
                except Exception:
                    continue
    if type(geometry).__name__.lower()=="subd":
        try:
            mesh=rhino.Mesh.CreateFromSubDControlNet(geometry,False)
            if mesh is not None:yield mesh
        except Exception:
            pass


def _rhino_mesh_triangles(mesh,remaining: int):
    faces=getattr(mesh,"Faces",None)
    if faces is None or remaining<=0:return
    count=len(faces)
    if count<=0:return
    stride=max(1,(count+remaining-1)//remaining)
    for index in range(0,count,stride):
        try:
            if hasattr(faces,"GetFaceVertices"):
                values=faces.GetFaceVertices(index)
                if not values or not values[0]:continue
                points=[_rhino_point_xyz(point) for point in values[1:5]]
            else:
                face=faces[index]
                indices=[]
                for position,name in enumerate(("A","B","C","D")):
                    try:indices.append(int(getattr(face,name)))
                    except (AttributeError,TypeError):
                        try:indices.append(int(face[position]))
                        except (IndexError,KeyError,TypeError):
                            if position==3:indices.append(indices[-1])
                            else:raise
                points=[_rhino_point_xyz(mesh.Vertices[item]) for item in indices]
            yield (points[0],points[1],points[2])
            remaining-=1
            if remaining<=0:return
            if points[3]!=points[2] and points[3]!=points[0]:
                yield (points[0],points[2],points[3])
                remaining-=1
                if remaining<=0:return
        except Exception:
            continue


def _rhino_curve_points(curve,samples: int=72):
    if not hasattr(curve,"PointAt"):return None
    domain=getattr(curve,"Domain",None)
    if domain is None:return None
    try:
        start=float(domain.T0)
        finish=float(domain.T1)
        if not np.isfinite(start) or not np.isfinite(finish) or start==finish:return None
        points=[]
        for parameter in np.linspace(start,finish,int(samples)):
            points.append(_rhino_point_xyz(curve.PointAt(float(parameter))))
        return np.asarray(points,dtype=np.float64)
    except Exception:
        return None


def _render_rhino_curves(curves,size: int=512) -> Image.Image:
    points=np.vstack(curves)
    minimum=points.min(axis=0)
    maximum=points.max(axis=0)
    extent=float(np.max(maximum-minimum))
    if not np.isfinite(extent) or extent<=1e-12:
        raise ValueError("Кривые Rhino не образуют видимого изображения.")
    azimuth=np.deg2rad(34.0)
    elevation=np.deg2rad(-28.0)
    rotate_z=np.array([[np.cos(azimuth),-np.sin(azimuth),0],
                       [np.sin(azimuth),np.cos(azimuth),0],[0,0,1]])
    rotate_x=np.array([[1,0,0],[0,np.cos(elevation),-np.sin(elevation)],
                       [0,np.sin(elevation),np.cos(elevation)]])
    transformed=[((curve-(minimum+maximum)*0.5)/extent)@(rotate_z@rotate_x).T
                 for curve in curves]
    flat=np.vstack([curve[:,:2] for curve in transformed])
    low=flat.min(axis=0)
    high=flat.max(axis=0)
    largest=float(np.max(high-low))
    if largest<=1e-12:
        raise ValueError("Кривые Rhino невозможно отобразить.")
    center=(low+high)*0.5
    factor=int(size)*0.79/largest
    image=Image.new("RGB",(int(size),int(size)),(242,246,252))
    draw=ImageDraw.Draw(image)
    width=max(2,int(size)//220)
    for curve in transformed:
        projection=(curve[:,:2]-center)*factor
        coordinates=[(round(float(point[0])+int(size)/2),
                      round(int(size)/2-float(point[1]))) for point in projection]
        draw.line(coordinates,fill=(128,103,71),width=width,joint="curve")
    return image


def _open_rhino_document(path: str | Path):
    try:
        import rhino3dm
    except ImportError as error:
        raise RuntimeError("Не установлен компонент rhino3dm для чтения геометрии Rhino. "
                           "Установите Rhino или обновлённую версию Jewelry AI Search.") from error
    try:
        document=rhino3dm.File3dm.Read(str(Path(path).resolve()))
    except Exception as error:
        raise RuntimeError(f"Не удалось прочитать геометрию Rhino: {error}") from error
    if document is None:
        raise RuntimeError("Компонент rhino3dm не смог открыть файл Rhino 3DM.")
    return document, rhino3dm


def _rhino_layer_maps(document) -> tuple[dict, dict]:
    by_index = {}
    by_identity = {}
    for position, layer in enumerate(getattr(document, "Layers", ())):
        try:
            index = int(getattr(layer, "Index", position))
        except (TypeError, ValueError):
            index = position
        by_index[index] = layer
        identity = str(getattr(layer, "Id", "") or "").lower()
        if identity:
            by_identity[identity] = layer
    return by_index, by_identity


def _rhino_layer_path(layer) -> str:
    return str(getattr(layer, "FullPath", "") or getattr(layer, "Name", "")
               or "Без названия")


def _rhino_item_visibility(item, layer_maps: tuple[dict, dict]) -> dict:
    attributes = getattr(item, "Attributes", None)
    try:
        index = int(getattr(attributes, "LayerIndex", -1))
    except (TypeError, ValueError):
        index = -1
    by_index, by_identity = layer_maps
    layer = by_index.get(index)
    ancestors = []
    visited = set()
    current = layer
    while current is not None:
        identity = str(getattr(current, "Id", "") or id(current)).lower()
        if identity in visited:
            break
        visited.add(identity)
        ancestors.append(current)
        parent = str(getattr(current, "ParentLayerId", "") or "").lower()
        if not parent or parent in {"00000000-0000-0000-0000-000000000000", "none"}:
            break
        current = by_identity.get(parent)
    hidden_layers = [entry for entry in ancestors
                     if bool(getattr(entry, "Visible", True)) is False]
    mode = str(getattr(attributes, "Mode", "") or "").lower()
    object_hidden = (attributes is not None and
                     (bool(getattr(attributes, "Visible", True)) is False
                      or "hidden" in mode))
    name = str(getattr(attributes, "Name", "") or
               getattr(getattr(item, "Geometry", None), "Name", "") or "")
    return {"visible": not hidden_layers and not object_hidden,
            "object_hidden": object_hidden,
            "hidden_layer": hidden_layers[-1] if hidden_layers else None,
            "layer": layer,
            "layer_name": _rhino_layer_path(layer) if layer is not None else "Без слоя",
            "name": name}


def _render_rhino_items_preview(items, rhino3dm, size: int = 512,
                                triangle_limit: int = STL_PREVIEW_MAX_TRIANGLES) -> Image.Image:
    triangles=[]
    curves=[]
    for item in items:
        try:
            geometry=item.Geometry
            for mesh in _rhino_geometry_meshes(geometry,rhino3dm):
                triangles.extend(_rhino_mesh_triangles(mesh,triangle_limit-len(triangles)))
                if len(triangles)>=triangle_limit:break
            if len(curves)<400:
                line=_rhino_curve_points(geometry)
                if line is not None:curves.append(line)
                elif not triangles:
                    for edge in getattr(geometry,"Edges",()):
                        if len(curves)>=400:break
                        line=_rhino_curve_points(edge)
                        if line is not None:curves.append(line)
            if len(triangles)>=triangle_limit:break
        except Exception:
            continue
    if triangles:
        return _render_triangle_preview(np.asarray(triangles,dtype=np.float64),
                                        size=size,source_kind="Rhino")
    if curves:
        return _render_rhino_curves(curves,size=size)
    raise RuntimeError("В файле Rhino нет сохранённых полигонов, render-сеток или отображаемых кривых. "
                       "Сохраните проект с render mesh или встроенной миниатюрой.")


def render_rhino_geometry_preview(path: str | Path,size: int=512) -> Image.Image:
    """Render only objects visible through the complete Rhino layer hierarchy."""
    document, rhino3dm = _open_rhino_document(path)
    layers = _rhino_layer_maps(document)
    visible = [item for item in document.Objects
               if _rhino_item_visibility(item, layers)["visible"]]
    return _render_rhino_items_preview(visible, rhino3dm, size=size)


def extract_rhino_deep_variants(path: str | Path, size: int = 512) -> dict:
    """Inventory hidden layers and hidden objects without changing the 3DM file."""
    source = Path(path)
    document, rhino3dm = _open_rhino_document(source)
    layers = _rhino_layer_maps(document)
    grouped = {}
    visible_objects = 0
    hidden_objects = 0
    for position, item in enumerate(document.Objects):
        info = _rhino_item_visibility(item, layers)
        if info["visible"]:
            visible_objects += 1
            continue
        hidden_objects += 1
        object_name = info["name"] or f"Объект {position + 1}"
        hidden_layer = info["hidden_layer"]
        if hidden_layer is not None:
            label = _rhino_layer_path(hidden_layer)
            identity = str(getattr(hidden_layer, "Id", "") or label)
            key = "layer:" + identity
            kind = "layer"
        else:
            label = info["layer_name"] + " · " + object_name
            identity = str(getattr(getattr(item, "Attributes", None), "Id", "")
                           or f"{position}:{object_name}")
            key = "object:" + identity
            kind = "object"
        group = grouped.setdefault(key, {"key": key, "label": label, "kind": kind,
                                         "objects": [], "items": [], "hidden": True})
        group["objects"].append(object_name)
        group["items"].append(item)
    variants = []
    for group in list(grouped.values())[:DEEPTHINK_MAX_VARIANTS_PER_SOURCE]:
        try:
            image = _render_rhino_items_preview(group["items"], rhino3dm, size=size,
                                               triangle_limit=DEEPTHINK_MAX_TRIANGLES_PER_VARIANT)
        except Exception:
            continue
        variants.append({key: value for key, value in group.items() if key != "items"}
                        | {"image": image})
    inventory = {"active_layer": "Видимые слои Rhino",
                 "visible_layers": [_rhino_layer_path(layer) for layer in layers[0].values()
                                    if bool(getattr(layer, "Visible", True))],
                 "hidden_layers": [_rhino_layer_path(layer) for layer in layers[0].values()
                                   if not bool(getattr(layer, "Visible", True))],
                 "visible_objects": visible_objects, "hidden_objects": hidden_objects}
    return {"path": str(source), "inventory": inventory, "variants": variants,
            "truncated": len(grouped) > DEEPTHINK_MAX_VARIANTS_PER_SOURCE}


def extract_rhino_preview(path: str | Path) -> Image.Image:
    """Use Explorer, embedded/desktop/sidecar image, then real openNURBS geometry."""
    source = Path(path)
    shell_error = None
    if os.name == "nt":
        try:
            return extract_windows_shell_thumbnail(source)
        except Exception as error:
            shell_error = error
    with source.open("rb") as stream:
        payload = stream.read(RHINO_PREVIEW_MAX_SCAN_BYTES)
    if not payload.startswith(b"3D Geometry File Format "):
        raise ValueError("Это не поддерживаемый файл Rhino 3DM.")
    embedded = _embedded_rhino_image(payload)
    if embedded is not None:
        return embedded
    if os.name!="nt":
        desktop=_desktop_blend_thumbnail(source)
        if desktop is not None:return desktop
    sidecar=_matching_model_image(source)
    if sidecar is not None:return sidecar
    try:
        return render_rhino_geometry_preview(source)
    except Exception as geometry_error:
        shell_error=geometry_error if shell_error is None else shell_error
    if os.name == "nt":
        explanation = (
            "В файле Rhino нет доступного превью или читаемой геометрии. Установите Rhino "
            "с миниатюрами Проводника Windows либо сохраните проект с render mesh или превью."
        )
    else:
        explanation = (
            "В файле Rhino нет встроенного превью, подходящего изображения рядом или читаемой геометрии. "
            "Установите Rhino либо сохраните проект с render mesh или включённым превью."
        )
    if shell_error is not None:
        explanation += f" Причина: {shell_error}"
    raise ValueError(explanation)


def _stl_triangles(path: str | Path, *, with_total: bool = False):
    """Reads enough STL faces for a solid thumbnail and reports sampling when requested."""
    source = Path(path)
    size = source.stat().st_size
    with source.open("rb") as stream:
        header = stream.read(84)
    if len(header) >= 84:
        count = struct.unpack("<I", header[80:84])[0]
        if count and 84 + count * 50 == size:
            layout = np.dtype([("normal", "<f4", (3,)),
                               ("vertices", "<f4", (3, 3)),
                               ("attribute", "<u2")])
            mapped = np.memmap(str(source), dtype=layout, mode="r", offset=84, shape=(count,))
            indices = np.linspace(0, count - 1, min(count, STL_PREVIEW_MAX_TRIANGLES),
                                  dtype=np.int64)
            triangles = np.asarray(mapped["vertices"][indices], dtype=np.float64)
            return (triangles, int(count)) if with_total else triangles
    if not header.lstrip().lower().startswith(b"solid"):
        raise ValueError("Файл STL повреждён или имеет неподдерживаемый формат.")
    if size > STL_PREVIEW_MAX_ASCII_BYTES:
        raise ValueError("Текстовый STL слишком большой для безопасной визуализации.")

    samples = []
    pending = []
    stride = 1
    total = 0
    last_triangle = None
    with source.open("rb") as stream:
        for line in stream:
            if len(line) > 8192:
                raise ValueError("Файл STL содержит слишком длинную строку.")
            pieces = line.split()
            if pieces and pieces[0].lower() == b"vertex":
                if len(pieces) != 4:
                    raise ValueError("Файл STL содержит некорректную вершину.")
                try:
                    pending.append((float(pieces[1]), float(pieces[2]), float(pieces[3])))
                except (TypeError, ValueError, OverflowError) as error:
                    raise ValueError("Файл STL содержит некорректные координаты.") from error
                if len(pending) == 3:
                    triangle = tuple(pending)
                    pending.clear()
                    last_triangle = triangle
                    if total % stride == 0:
                        samples.append(triangle)
                    total += 1
                    if len(samples) > STL_PREVIEW_MAX_TRIANGLES * 2:
                        samples = samples[::2]
                        stride *= 2
    if not samples or pending:
        raise ValueError("В файле STL не найдено целых треугольников.")
    if last_triangle is not None and samples[-1] != last_triangle:
        samples.append(last_triangle)
    triangles = np.asarray(samples, dtype=np.float64).reshape((-1, 3, 3))
    if len(triangles) > STL_PREVIEW_MAX_TRIANGLES:
        indices = np.linspace(0, len(triangles) - 1, STL_PREVIEW_MAX_TRIANGLES, dtype=np.int64)
        triangles = triangles[indices]
    return (triangles, int(total)) if with_total else triangles


def _render_triangle_preview(triangles: np.ndarray, size: int = 512,
                             source_kind: str = "STL",
                             sampling_ratio: float = 1.0) -> Image.Image:
    """Draws a closed, softly lit studio-solid preview without a graphics driver."""
    if not 64 <= int(size) <= BLEND_PREVIEW_MAX_SIDE:
        raise ValueError(f"Недопустимый размер превью {source_kind}.")
    triangles = np.asarray(triangles, dtype=np.float64)
    if triangles.ndim != 3 or triangles.shape[1:] != (3, 3) or not len(triangles):
        raise ValueError(f"В файле {source_kind} не найдено целых треугольников.")
    if not np.isfinite(triangles).all():
        raise ValueError(f"Файл {source_kind} содержит недопустимые координаты.")
    flat = triangles.reshape((-1, 3))
    minimum = flat.min(axis=0)
    maximum = flat.max(axis=0)
    extent = float(np.max(maximum - minimum))
    if not np.isfinite(extent) or extent <= 1e-12:
        raise ValueError(f"В файле {source_kind} нет объёмной геометрии.")

    centered = (triangles - (minimum + maximum) * 0.5) / extent
    # Rings are easiest to recognise through their opening, while vertical
    # pendants need a steeper view. Choose the least flattened actual view.
    transformed = None
    best_score = -1.0
    for azimuth_degrees, elevation_degrees in (
            (34.0, -22.0), (34.0, -36.0), (34.0, -58.0),
            (72.0, -30.0), (15.0, -74.0)):
        azimuth = np.deg2rad(azimuth_degrees)
        elevation = np.deg2rad(elevation_degrees)
        rotate_z = np.array([[np.cos(azimuth), -np.sin(azimuth), 0],
                             [np.sin(azimuth), np.cos(azimuth), 0], [0, 0, 1]])
        rotate_x = np.array([[1, 0, 0], [0, np.cos(elevation), -np.sin(elevation)],
                             [0, np.sin(elevation), np.cos(elevation)]])
        candidate = centered @ (rotate_z @ rotate_x).T
        span = np.ptp(candidate.reshape((-1, 3)), axis=0)
        width, height = float(span[0]), float(span[1])
        if max(width, height) <= 1e-12:
            continue
        aspect = min(width, height) / max(width, height)
        area = width * height
        score = 0.63 * aspect + 0.31 * area + 0.06 * min(float(span[2]), 1.0)
        if score > best_score:
            transformed, best_score = candidate, score
    if transformed is None:
        raise ValueError(f"Геометрию {source_kind} невозможно отобразить.")
    screen = transformed[:, :, :2]
    low = screen.reshape((-1, 2)).min(axis=0)
    high = screen.reshape((-1, 2)).max(axis=0)
    screen = screen - (low + high) * 0.5
    largest = float(np.max(high - low))
    if largest <= 1e-12:
        raise ValueError(f"Геометрию {source_kind} невозможно отобразить.")
    output_size = int(size)
    supersample = 2 if output_size <= 768 else 1
    canvas_size = output_size * supersample
    screen *= (canvas_size * 0.77 / largest)
    screen[:, :, 0] += canvas_size / 2
    screen[:, :, 1] = canvas_size * 0.48 - screen[:, :, 1]

    normal = np.cross(transformed[:, 1] - transformed[:, 0],
                      transformed[:, 2] - transformed[:, 0])
    lengths = np.linalg.norm(normal, axis=1)
    usable = lengths > 1e-12
    if not usable.any():
        raise ValueError(f"В файле {source_kind} все треугольники вырождены.")
    normal[usable] /= lengths[usable, None]
    key_light = np.array([-0.48, 0.46, 0.75])
    key_light /= np.linalg.norm(key_light)
    fill_light = np.array([0.70, -0.23, 0.67])
    fill_light /= np.linalg.norm(fill_light)
    rim_light = np.array([0.08, 0.88, 0.47])
    rim_light /= np.linalg.norm(rim_light)
    key = np.clip(np.abs(normal @ key_light), 0.0, 1.0)
    fill = np.clip(np.abs(normal @ fill_light), 0.0, 1.0)
    rim = np.clip(np.abs(normal @ rim_light), 0.0, 1.0)
    depth = transformed[:, :, 2].mean(axis=1)
    top = np.array([249.0, 251.0, 254.0])
    bottom = np.array([224.0, 231.0, 240.0])
    blend = np.linspace(0.0, 1.0, canvas_size, dtype=np.float32)[:, None, None]
    background = np.broadcast_to(top * (1.0 - blend) + bottom * blend,
                                 (canvas_size, canvas_size, 3)).astype(np.uint8)
    image = Image.fromarray(background, mode="RGB")
    left = float(screen[:, :, 0].min())
    right = float(screen[:, :, 0].max())
    bottom_y = float(screen[:, :, 1].max())
    shadow = Image.new("L", (canvas_size, canvas_size), 0)
    shadow_draw = ImageDraw.Draw(shadow)
    shadow_draw.ellipse((left + (right - left) * 0.08,
                         bottom_y - canvas_size * 0.012,
                         right - (right - left) * 0.08,
                         min(canvas_size - 1, bottom_y + canvas_size * 0.065)), fill=76)
    shadow = shadow.filter(ImageFilter.GaussianBlur(radius=max(2, canvas_size * 0.019)))
    image.paste((115, 130, 148), (0, 0, canvas_size, canvas_size), shadow)

    coverage = Image.new("L", (canvas_size, canvas_size), 0)
    coverage_draw = ImageDraw.Draw(coverage)
    shaded = Image.new("RGB", (canvas_size, canvas_size), (122, 133, 148))
    draw = ImageDraw.Draw(shaded)
    base = np.array([158.0, 166.0, 176.0], dtype=np.float64)
    for index in np.argsort(depth):
        if not usable[index]:
            continue
        shade = 0.45 + 0.48 * float(key[index]) + 0.21 * float(fill[index])
        highlight = 22.0 * float(rim[index]) ** 7
        color = tuple(int(value) for value in np.clip(base * shade + 18.0 + highlight,
                                                      38, 246))
        polygon = [(round(float(point[0])), round(float(point[1]))) for point in screen[index]]
        coverage_draw.polygon(polygon, fill=255)
        # Facet outlines made low-poly jewels look like wireframe drawings.
        draw.polygon(polygon, fill=color)
    if len(triangles) >= 1200:
        # Sampling dense meshes can leave tiny holes between faces. Close only
        # small gaps; genuine openings in rings and openwork remain visible.
        # The radius grows only when a very large source had to be sampled.
        ratio = max(1.0, float(sampling_ratio))
        seal_size = min(15, max(5, 3 + 2 * int(np.ceil(np.sqrt(ratio)))))
        sealed = coverage.filter(ImageFilter.MaxFilter(seal_size)).filter(
            ImageFilter.MinFilter(seal_size))
        silhouette = Image.new("RGB", (canvas_size, canvas_size), (133, 143, 155))
        image.paste(silhouette, (0, 0), sealed)
    image.paste(shaded, (0, 0), coverage)
    if supersample > 1:
        image = image.resize((output_size, output_size), Image.Resampling.LANCZOS)
    return image


def render_stl_preview(path: str | Path, size: int = 512) -> Image.Image:
    """Renders a neutral shaded isometric thumbnail directly from STL geometry."""
    if not 64 <= int(size) <= BLEND_PREVIEW_MAX_SIDE:
        raise ValueError("Недопустимый размер превью STL.")
    triangles, total = _stl_triangles(path, with_total=True)
    return _render_triangle_preview(
        triangles,
        size=size,
        source_kind="STL",
        sampling_ratio=max(1.0, total / max(1, len(triangles))),
    )


_BLENDER_GEOMETRY_MARKER = "JAI_BLEND_GEOMETRY:"
_BLENDER_BATCH_MARKER = "JAI_BLEND_BATCH:"
_BLENDER_BATCH_ERROR_MARKER = "JAI_BLEND_BATCH_ERROR:"
_BLENDER_DEEP_VARIANT_MARKER = "JAI_BLEND_DEEP_VARIANT:"
_BLENDER_DEEP_DONE_MARKER = "JAI_BLEND_DEEP_DONE:"
_BLENDER_DEEP_ERROR_MARKER = "JAI_BLEND_DEEP_ERROR:"
_BLENDER_GEOMETRY_SCRIPT = r"""
import base64, bpy, json, sys, zlib

limit = 120000
geometry = []
view_layer = bpy.context.view_layer
if view_layer is None:
    raise RuntimeError('В проекте Blender не найден активный View Layer.')
depsgraph = bpy.context.evaluated_depsgraph_get()
for original in view_layer.objects:
    if original.type not in {'MESH', 'CURVE', 'SURFACE', 'FONT', 'META'}:
        continue
    try:
        if not original.visible_get(view_layer=view_layer):
            continue
    except TypeError:
        if not original.visible_get():
            continue
    evaluated = original.evaluated_get(depsgraph)
    try:
        mesh = evaluated.to_mesh()
    except Exception:
        continue
    if mesh is None:
        continue
    try:
        mesh.calc_loop_triangles()
        remaining = limit - len(geometry)
        if remaining <= 0:
            break
        stride = max(1, len(mesh.loop_triangles) // remaining)
        matrix = evaluated.matrix_world
        for index, face in enumerate(mesh.loop_triangles):
            if index % stride or len(geometry) >= limit:
                continue
            geometry.append([list(matrix @ mesh.vertices[vertex].co)
                             for vertex in face.vertices])
    finally:
        evaluated.to_mesh_clear()
    if len(geometry) >= limit:
        break
if not geometry:
    raise RuntimeError('В проекте Blender нет доступной 3D-геометрии.')
encoded = base64.b64encode(zlib.compress(
    json.dumps(geometry, separators=(',', ':')).encode('utf-8'), 5
)).decode('ascii')
print('JAI_BLEND_GEOMETRY:' + encoded, flush=True)
"""

_BLENDER_BATCH_SCRIPT = r"""
import base64, bpy, json, zlib

sources = json.loads(zlib.decompress(base64.b64decode('__JAI_SOURCES__')).decode('utf-8'))
for source in sources:
    try:
        try:
            bpy.ops.wm.open_mainfile(filepath=source, load_ui=False, use_scripts=False)
        except TypeError:
            bpy.ops.wm.open_mainfile(filepath=source, load_ui=False)
        geometry = []
        view_layer = bpy.context.view_layer
        if view_layer is None:
            raise RuntimeError('В проекте Blender не найден активный View Layer.')
        depsgraph = bpy.context.evaluated_depsgraph_get()
        for original in view_layer.objects:
            if original.type not in {'MESH', 'CURVE', 'SURFACE', 'FONT', 'META'}:
                continue
            try:
                if not original.visible_get(view_layer=view_layer):
                    continue
            except TypeError:
                if not original.visible_get():
                    continue
            evaluated = original.evaluated_get(depsgraph)
            try:
                mesh = evaluated.to_mesh()
            except Exception:
                continue
            if mesh is None:
                continue
            try:
                mesh.calc_loop_triangles()
                remaining = 120000 - len(geometry)
                if remaining <= 0:
                    break
                stride = max(1, len(mesh.loop_triangles) // remaining)
                matrix = evaluated.matrix_world
                for index, face in enumerate(mesh.loop_triangles):
                    if index % stride or len(geometry) >= 120000:
                        continue
                    geometry.append([list(matrix @ mesh.vertices[vertex].co)
                                     for vertex in face.vertices])
            finally:
                evaluated.to_mesh_clear()
            if len(geometry) >= 120000:
                break
        if not geometry:
            raise RuntimeError('В проекте Blender нет доступной 3D-геометрии.')
        payload = json.dumps({'path': source, 'triangles': geometry},
                             ensure_ascii=False, separators=(',', ':')).encode('utf-8')
        print('JAI_BLEND_BATCH:' + base64.b64encode(zlib.compress(payload, 5)).decode('ascii'),
              flush=True)
    except Exception as error:
        payload = json.dumps({'path': source, 'error': str(error)},
                             ensure_ascii=False).encode('utf-8')
        print('JAI_BLEND_BATCH_ERROR:' + base64.b64encode(payload).decode('ascii'), flush=True)
"""

_BLENDER_DEEP_BATCH_SCRIPT = r"""
import base64, bpy, json, zlib

sources = json.loads(zlib.decompress(base64.b64decode('__JAI_SOURCES__')).decode('utf-8'))
allowed_types = {'MESH', 'CURVE', 'SURFACE', 'FONT', 'META'}

def emit(marker, value):
    payload = json.dumps(value, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    print(marker + base64.b64encode(zlib.compress(payload, 5)).decode('ascii'), flush=True)

for source in sources:
    try:
        try:
            bpy.ops.wm.open_mainfile(filepath=source, load_ui=False, use_scripts=False)
        except TypeError:
            bpy.ops.wm.open_mainfile(filepath=source, load_ui=False)
        scene = bpy.context.scene
        active = bpy.context.view_layer
        if scene is None or active is None:
            raise RuntimeError('В проекте не найден активный View Layer.')
        depsgraph = bpy.context.evaluated_depsgraph_get()
        visible = set()
        for original in active.objects:
            try:
                if original.visible_get(view_layer=active):
                    visible.add(original.name)
            except TypeError:
                if original.visible_get():
                    visible.add(original.name)
            except Exception:
                pass

        collection_paths = {}
        hidden_collections = set()
        def visit(wrapper, prefix='', parent_hidden=False):
            collection = getattr(wrapper, 'collection', None)
            label = str(getattr(collection, 'name', '') or getattr(wrapper, 'name', '') or 'Collection')
            path = (prefix + '/' + label).strip('/')
            hidden = parent_hidden or bool(getattr(wrapper, 'exclude', False)) or bool(
                getattr(wrapper, 'hide_viewport', False))
            try:
                hidden = hidden or not bool(wrapper.is_visible)
            except Exception:
                pass
            if collection is not None:
                collection_paths[collection.name] = path
                if hidden:
                    hidden_collections.add(collection.name)
            for child in getattr(wrapper, 'children', ()):
                visit(child, path, hidden)
        visit(active.layer_collection)

        groups = {}
        all_objects = [item for item in scene.objects if item.type in allowed_types]
        for original in all_objects:
            if original.name in visible:
                continue
            collections = list(getattr(original, 'users_collection', ()) or [])
            hidden = next((item for item in collections if item.name in hidden_collections), None)
            if hidden is not None:
                label = collection_paths.get(hidden.name, hidden.name)
                key = 'collection:' + label
                kind = 'collection'
            else:
                parent = collection_paths.get(collections[0].name, collections[0].name) if collections else ''
                label = (parent + ' · ' if parent else '') + original.name
                key = 'object:' + original.name
                kind = 'object'
            group = groups.setdefault(key, {'key': key, 'label': label, 'kind': kind, 'objects': []})
            group['objects'].append(original)

        known_sets = {tuple(sorted(item.name for item in entry['objects'])) for entry in groups.values()}
        for alternative in scene.view_layers:
            if alternative.name == active.name:
                continue
            members = []
            for original in alternative.objects:
                if original.type not in allowed_types:
                    continue
                try:
                    shown = original.visible_get(view_layer=alternative)
                except Exception:
                    shown = False
                if shown and original.name not in visible:
                    members.append(original)
            identity = tuple(sorted(item.name for item in members))
            if identity and identity not in known_sets:
                known_sets.add(identity)
                groups['view-layer:' + alternative.name] = {
                    'key': 'view-layer:' + alternative.name,
                    'label': 'View Layer: ' + alternative.name,
                    'kind': 'view_layer', 'objects': members}

        emitted = 0
        for group in list(groups.values())[:__JAI_MAX_VARIANTS__]:
            geometry = []
            for original in group['objects']:
                owner = original
                mesh = None
                try:
                    evaluated = original.evaluated_get(depsgraph)
                    owner = evaluated
                    mesh = evaluated.to_mesh()
                except Exception:
                    mesh = None
                if mesh is None:
                    owner = original
                    try:
                        mesh = original.to_mesh()
                    except Exception:
                        continue
                if mesh is None:
                    continue
                try:
                    mesh.calc_loop_triangles()
                    remaining = __JAI_MAX_TRIANGLES__ - len(geometry)
                    if remaining <= 0:
                        break
                    stride = max(1, len(mesh.loop_triangles) // remaining)
                    matrix = owner.matrix_world
                    for index, face in enumerate(mesh.loop_triangles):
                        if index % stride or len(geometry) >= __JAI_MAX_TRIANGLES__:
                            continue
                        geometry.append([list(matrix @ mesh.vertices[vertex].co)
                                         for vertex in face.vertices])
                finally:
                    try:
                        owner.to_mesh_clear()
                    except Exception:
                        pass
                if len(geometry) >= __JAI_MAX_TRIANGLES__:
                    break
            if geometry:
                emit('JAI_BLEND_DEEP_VARIANT:', {
                    'path': source, 'key': group['key'], 'label': group['label'],
                    'kind': group['kind'], 'objects': [item.name for item in group['objects']],
                    'hidden': True, 'triangles': geometry})
                emitted += 1
        emit('JAI_BLEND_DEEP_DONE:', {
            'path': source,
            'inventory': {'active_layer': active.name,
                          'view_layers': [item.name for item in scene.view_layers],
                          'visible_objects': len(visible),
                          'hidden_objects': len([item for item in all_objects if item.name not in visible]),
                          'hidden_collections': sorted(hidden_collections)},
            'variants': emitted, 'truncated': len(groups) > __JAI_MAX_VARIANTS__})
    except Exception as error:
        emit('JAI_BLEND_DEEP_ERROR:', {'path': source, 'error': str(error)})
"""


def _desktop_blend_thumbnail(path: str | Path) -> Image.Image | None:
    """Uses an already existing file-manager thumbnail without opening Blender."""
    source=Path(path).resolve()
    if os.name=="nt":
        try:return extract_windows_shell_thumbnail(source)
        except Exception:return None
    try:
        uri=source.as_uri()
        digest=hashlib.md5(uri.encode("utf-8")).hexdigest()
        cache_base=Path(os.environ.get("XDG_CACHE_HOME") or (Path.home()/".cache"))
        modified=int(source.stat().st_mtime)
        for folder in ("xx-large","x-large","large","normal"):
            candidate=cache_base/"thumbnails"/folder/(digest+".png")
            if not candidate.is_file():continue
            try:
                with Image.open(candidate) as thumbnail:
                    stored_uri=str(thumbnail.info.get("Thumb::URI") or "")
                    if stored_uri and stored_uri!=uri:continue
                    stored_time=str(thumbnail.info.get("Thumb::MTime") or "").strip()
                    if stored_time and int(float(stored_time))!=modified:continue
                    return ImageOps.exif_transpose(thumbnail).convert("RGB")
            except Exception:continue
    except Exception:
        return None
    return None


def _blender_desktop_command(desktop_file: str | Path) -> list[str] | None:
    """Resolve a desktop launcher without its document placeholders."""
    try:
        in_entry=False
        executable=""
        for raw in Path(desktop_file).read_text(encoding="utf-8",errors="replace").splitlines():
            line=raw.strip()
            if line.startswith("["):
                if in_entry:break
                in_entry=line=="[Desktop Entry]"
            elif in_entry and line.startswith("Exec="):
                executable=line.partition("=")[2].strip()
                break
        if not executable:return None
        parts=shlex.split(executable)
        if parts and Path(parts[0]).name=="env":
            parts=parts[1:]
            while parts and "=" in parts[0] and not parts[0].startswith("/"):
                parts=parts[1:]
        parts=[part for part in parts if part not in ("@@","@@u","--file-forwarding")
               and not re.fullmatch(r"%[fFuUdDnNickvm]",part)]
        if not parts:return None
        launcher=Path(parts[0]).name.lower()
        if launcher in ("steam","steam.exe") or any(part.startswith("steam://") for part in parts):
            return None
        resolved=parts[0] if Path(parts[0]).expanduser().is_file() else shutil.which(parts[0])
        if not resolved:return None
        return [str(Path(resolved).expanduser()),*parts[1:]]
    except Exception:
        return None


def _blender_desktop_directories(user_home: Path) -> list[Path]:
    data_home=Path(os.environ.get("XDG_DATA_HOME") or (user_home/".local"/"share"))
    data_roots=[data_home]
    data_roots.extend(Path(value) for value in
                      (os.environ.get("XDG_DATA_DIRS") or "/usr/local/share:/usr/share").split(":")
                      if value)
    directories=[root/"applications" for root in data_roots]
    directories.extend((user_home/".local"/"share"/"flatpak"/"exports"/"share"/"applications",
                        Path("/var/lib/flatpak/exports/share/applications")))
    return list(dict.fromkeys(directories))


def _steam_blender_candidates(user_home: Path):
    roots=[user_home/".steam"/"steam",user_home/".local"/"share"/"Steam",
           user_home/".var"/"app"/"com.valvesoftware.Steam"/".local"/"share"/"Steam"]
    seen=set()
    for root in roots:
        libraries=[root]
        manifest=root/"steamapps"/"libraryfolders.vdf"
        try:
            content=manifest.read_text(encoding="utf-8",errors="replace")
            for encoded in re.findall(r'"path"\s*"((?:\\.|[^"\\])*)"',content,re.IGNORECASE):
                libraries.append(Path(encoded.replace(r"\\", "\\")))
        except Exception:
            pass
        for library in libraries:
            for name in ("blender","blender.exe"):
                candidate=library/"steamapps"/"common"/"Blender"/name
                key=str(candidate)
                if key not in seen:
                    seen.add(key)
                    yield candidate


def _windows_blender_candidates():
    roots=[os.environ.get("ProgramFiles"),os.environ.get("ProgramFiles(x86)"),
           os.environ.get("LOCALAPPDATA")]
    for value in roots:
        if not value:continue
        root=Path(value)
        foundations=(root/"Blender Foundation",root/"Programs"/"Blender Foundation")
        for foundation in foundations:
            try:
                for version in sorted(foundation.glob("Blender*"),reverse=True):
                    yield version/"blender.exe"
            except Exception:
                continue
        yield root/"Steam"/"steamapps"/"common"/"Blender"/"blender.exe"


def _find_blender_command() -> list[str] | None:
    """Find explicit, desktop-associated, Steam and Flatpak Blender installations."""
    configured=str(os.environ.get("JAI_BLENDER_EXECUTABLE")
                   or load_config().get("blender_executable","") or "").strip()
    if configured:
        direct=Path(configured).expanduser()
        if direct.is_file():
            if direct.suffix.lower()==".desktop":return _blender_desktop_command(direct)
            return [str(direct)]
        resolved=shutil.which(configured)
        if resolved:return [resolved]
    for command in ("blender","org.blender.Blender"):
        found=shutil.which(command)
        if found:
            if command=="org.blender.Blender":
                flatpak=shutil.which("flatpak")
                if flatpak:return [flatpak,"run","org.blender.Blender"]
            return [found]
    user_home=Path.home()
    if os.name=="nt":
        for candidate in _windows_blender_candidates():
            if candidate.is_file():return [str(candidate)]
    else:
        desktop_names=[]
        xdg_mime=shutil.which("xdg-mime")
        if xdg_mime:
            for mime in ("application/x-blender","application/x-blend"):
                try:
                    result=subprocess.run([xdg_mime,"query","default",mime],
                                          stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,
                                          text=True,timeout=4,check=False)
                    name=str(getattr(result,"stdout","") or "").strip()
                    if result.returncode==0 and name.endswith(".desktop"):
                        desktop_names.append(Path(name).name)
                except Exception:
                    pass
        desktop_names.extend(("org.blender.Blender.desktop","blender.desktop",
                              "blender_blender.desktop","steam_app_365670.desktop"))
        for name in dict.fromkeys(desktop_names):
            for directory in _blender_desktop_directories(user_home):
                candidate=directory/name
                if candidate.is_file():
                    desktop_command=_blender_desktop_command(candidate)
                    if desktop_command:return desktop_command
    for candidate in _steam_blender_candidates(user_home):
        if candidate.is_file():return [str(candidate)]
    for candidate in (user_home/".local"/"share"/"flatpak"/"exports"/"bin"/"org.blender.Blender",
                      Path("/var/lib/flatpak/exports/bin/org.blender.Blender"),
                      Path("/home/linuxbrew/.linuxbrew/bin/blender")):
        if candidate.is_file():
            flatpak=shutil.which("flatpak") if candidate.name=="org.blender.Blender" else None
            if flatpak:return [flatpak,"run","org.blender.Blender"]
            return [str(candidate)]
    flatpak=shutil.which("flatpak")
    if flatpak:
        try:
            result=subprocess.run([flatpak,"info","org.blender.Blender"],
                                  stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
                                  timeout=8,check=False)
            if result.returncode==0:return [flatpak,"run","org.blender.Blender"]
        except Exception:
            pass
    return None


def _blender_launch_command(command: list[str], sources) -> list[str]:
    """Grant Flatpak Blender read access only to the selected project directory."""
    args=list(command)
    if os.name=="nt" or "org.blender.Blender" not in args:return args
    if not args or "flatpak" not in Path(args[0]).name.lower():return args
    try:
        parents=[str(Path(source).resolve().parent) for source in sources]
        common=Path(os.path.commonpath(parents))
        if common==Path(common.anchor):return args
        position=args.index("org.blender.Blender")
        permission="--filesystem="+str(common)+":ro"
        if permission not in args:args.insert(position,permission)
    except Exception:
        pass
    return args


def render_blend_geometry_preview(path: str | Path, size: int = 512) -> Image.Image:
    """Asks installed Blender for mesh triangles, then draws them locally with Pillow."""
    source=Path(path).resolve()
    command=_find_blender_command()
    if not command:
        raise RuntimeError("Blender не найден. Установите Blender или сохраните проект со встроенной миниатюрой.")
    args=_blender_launch_command(command,[source])+[
        "--background","--factory-startup","--disable-autoexec",str(source),
        "--python-expr",_BLENDER_GEOMETRY_SCRIPT]
    try:
        completed=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,
                                 text=True,encoding="utf-8",errors="replace",
                                 timeout=120,check=False)
    except subprocess.TimeoutExpired as error:
        raise RuntimeError("Blender не успел подготовить 3D-миниатюру за 120 секунд.") from error
    except OSError as error:
        raise RuntimeError(f"Не удалось запустить Blender: {error}") from error
    output=str(completed.stdout or "")
    payload=""
    for line in output.splitlines():
        if _BLENDER_GEOMETRY_MARKER in line:
            payload=line.split(_BLENDER_GEOMETRY_MARKER,1)[1].strip()
    if not payload:
        explanation=" ".join(output.strip().splitlines()[-3:])[:450]
        raise RuntimeError("Blender не смог получить геометрию проекта."
                           +(f" Причина: {explanation}" if explanation else ""))
    try:
        decoded=zlib.decompress(base64.b64decode(payload,validate=True))
        triangles=np.asarray(json.loads(decoded.decode("utf-8")),dtype=np.float64)
    except Exception as error:
        raise RuntimeError("Blender вернул повреждённую 3D-геометрию.") from error
    if len(triangles)>STL_PREVIEW_MAX_TRIANGLES:
        positions=np.linspace(0,len(triangles)-1,STL_PREVIEW_MAX_TRIANGLES,dtype=np.int64)
        triangles=triangles[positions]
    return _render_triangle_preview(triangles,size=size,source_kind="Blender")


class _WeakBlendPreviewError(ValueError):
    """Retains an existing thumbnail if Blender cannot produce a better one."""

    def __init__(self, image: Image.Image):
        super().__init__("Встроенное превью слишком тёмное, проволочное или разреженное.")
        self.image = image


def _blend_preview_needs_shaded_render(image: Image.Image) -> bool:
    """Detects sparse wireframes and saved Blender UI screenshots."""
    if min(image.size) < 48:
        return False
    sample = image.convert("RGB").copy()
    sample.thumbnail((144, 144), Image.Resampling.BILINEAR)
    pixels = np.asarray(sample, dtype=np.int16)
    luminance = np.tensordot(pixels.astype(np.float32),
                             np.array([0.2126, 0.7152, 0.0722]), axes=([2], [0]))
    aspect = max(image.size) / max(1.0, float(min(image.size)))
    dark_ratio = float(np.mean(luminance < 92.0))
    colorfulness = float(np.mean(np.ptp(pixels, axis=2)))
    # Blender can store the entire dark editor window as its thumbnail. It is
    # technically a valid image, but the object becomes a tiny strip in the
    # gallery. Prefer the neutral geometry render for that recognisable case.
    if aspect >= 1.45 and dark_ratio >= 0.52 and colorfulness < 34.0:
        return True
    border = np.concatenate((pixels[0], pixels[-1], pixels[:, 0], pixels[:, -1]), axis=0)
    background = np.median(border, axis=0)
    difference = np.linalg.norm(pixels.astype(np.float32) - background, axis=2)
    foreground = difference > 31.0
    count = int(np.count_nonzero(foreground))
    if count < max(12, pixels.shape[0] * pixels.shape[1] // 240):
        return True
    ys, xs = np.nonzero(foreground)
    box_area = max(1, (int(xs.max()) - int(xs.min()) + 1)
                   * (int(ys.max()) - int(ys.min()) + 1))
    density = count / box_area
    ratio = count / float(pixels.shape[0] * pixels.shape[1])
    background_lightness = float(np.dot(background, [0.2126, 0.7152, 0.0722]))
    return bool((density < 0.20 and ratio < 0.16)
                or (background_lightness < 58.0 and density < 0.42 and ratio < 0.22))


def extract_blend_preview_with_fallback(path: str | Path) -> Image.Image:
    """Upgrades weak Blender thumbnails while keeping them as a safe fallback."""
    try:
        return _blend_preview_without_blender(path)
    except _WeakBlendPreviewError as weak:
        try:
            return render_blend_geometry_preview(path)
        except Exception:
            return weak.image
    except Exception as embedded_error:
        try:
            return render_blend_geometry_preview(path)
        except Exception as geometry_error:
            raise ValueError(f"{embedded_error} {geometry_error}") from geometry_error


def _model_preview_render_version(path: str | Path) -> int:
    return (RHINO_PREVIEW_RENDER_VERSION
            if Path(path).suffix.lower() in RHINO_EXTS else MODEL_PREVIEW_RENDER_VERSION)


def _model_preview_directory(path: str | Path, fallback: Path,
                             *, deep: bool = False) -> Path:
    """Prefer a non-indexed project-local folder; survive read-only archives."""
    source = Path(path).resolve()
    preferred = source.parent / MODEL_PREVIEW_FOLDER_NAME
    if deep:
        preferred = preferred / "DeepThink"
    fallback = Path(fallback)
    cache_key = (os.path.normcase(str(preferred)), os.path.normcase(str(fallback)))
    cached = _MODEL_PREVIEW_DIRECTORY_CACHE.get(cache_key)
    if cached is not None:
        cached = Path(cached)
        try:
            if cached.is_dir() and not cached.is_symlink():
                return cached
        except OSError:
            pass
        _MODEL_PREVIEW_DIRECTORY_CACHE.pop(cache_key, None)
    try:
        parent = source.parent / MODEL_PREVIEW_FOLDER_NAME
        if parent.exists() and (parent.is_symlink() or not parent.is_dir()):
            raise OSError("Недопустимый каталог J_AI_Preview")
        preferred.mkdir(parents=True, exist_ok=True)
        if preferred.is_symlink() or not preferred.is_dir():
            raise OSError("Недопустимый каталог миниатюр")
        descriptor, temporary = tempfile.mkstemp(prefix=".jai-write-", dir=str(preferred))
        os.close(descriptor)
        Path(temporary).unlink(missing_ok=True)
        result = preferred
    except OSError:
        fallback.mkdir(parents=True, exist_ok=True)
        result = fallback
    _MODEL_PREVIEW_DIRECTORY_CACHE[cache_key] = result
    return result


def _source_preview_cache_info(path: str | Path, directory: Path):
    source = Path(path).resolve()
    info = source.stat()
    digest = hashlib.sha256(os.path.normcase(str(source)).encode("utf-8", "ignore")).hexdigest()
    stem = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', "_", source.stem).strip(". ")[:96]
    identity = f"{stem or 'model'}__{source.suffix.lower().lstrip('.')}__{digest[:16]}"
    directory = Path(directory)
    signature = {"source": str(source), "mtime_ns": int(info.st_mtime_ns),
                 "size": int(info.st_size), "render_version": _model_preview_render_version(source)}
    return directory / (identity + ".png"), directory / (identity + ".json"), signature


def _model_preview_cache_current(path: str | Path) -> bool:
    source = Path(path)
    extension = source.suffix.lower()
    if extension in BLENDER_EXTS:
        fallback = BLEND_PREVIEW_CACHE_DIR
    elif extension in RHINO_EXTS:
        fallback = RHINO_PREVIEW_CACHE_DIR
    elif extension in STL_EXTS:
        fallback = STL_PREVIEW_CACHE_DIR
    else:
        return True
    try:
        directory = _model_preview_directory(source, fallback)
        image_path, metadata_path, signature = _source_preview_cache_info(source, directory)
        return bool(image_path.is_file()
                    and json.loads(metadata_path.read_text(encoding="utf-8")) == signature)
    except Exception:
        return False


def _cached_source_preview(path: str | Path, directory: Path, extractor,
                           *, force: bool = False) -> Path:
    """Refresh a non-indexed generated PNG whenever its 3D source changes."""
    source = Path(path).resolve()
    directory = Path(directory)
    image_path, metadata_path, signature = _source_preview_cache_info(source, directory)
    identity = image_path.stem
    try:
        if (not force and image_path.is_file()
                and json.loads(metadata_path.read_text(encoding="utf-8")) == signature):
            return image_path
    except Exception:
        pass

    image = extractor(source)
    directory.mkdir(parents=True, exist_ok=True)
    suffix = f".{os.getpid()}.{threading.get_ident()}.tmp"
    temporary_image = directory / (identity + suffix + ".png")
    temporary_metadata = directory / (identity + suffix + ".json")
    try:
        image.save(temporary_image, format="PNG", optimize=True)
        temporary_metadata.write_text(json.dumps(signature, ensure_ascii=False), encoding="utf-8")
        os.replace(temporary_image, image_path)
        os.replace(temporary_metadata, metadata_path)
    finally:
        for temporary in (temporary_image, temporary_metadata):
            try:
                temporary.unlink(missing_ok=True)
            except Exception:
                pass
    return image_path


def cached_blend_preview(path: str | Path, cache_dir: Path | None = None) -> Path:
    directory = (Path(cache_dir) if cache_dir is not None
                 else _model_preview_directory(path, BLEND_PREVIEW_CACHE_DIR))
    preview = _cached_source_preview(path, directory, extract_blend_preview_with_fallback)
    # A weak fallback may have been cached before Blender was installed or its
    # path was selected. Upgrade it as soon as Blender becomes available.
    try:
        with Image.open(preview) as current:
            weak = _blend_preview_needs_shaded_render(current.convert("RGB"))
        if weak and _find_blender_command():
            return _cached_source_preview(
                path, directory, extract_blend_preview_with_fallback, force=True)
    except Exception:
        pass
    return preview


def _blend_preview_without_blender(path: str | Path) -> Image.Image:
    weak = None
    try:
        image = extract_blend_preview(path)
        if not _blend_preview_needs_shaded_render(image):
            return image
        weak = image
    except Exception as embedded_error:
        embedded_problem = embedded_error
    else:
        embedded_problem = None
    thumbnail = _desktop_blend_thumbnail(path)
    if thumbnail is not None:
        if not _blend_preview_needs_shaded_render(thumbnail):
            return thumbnail
        if weak is None:
            weak = thumbnail
    if weak is not None:
        raise _WeakBlendPreviewError(weak)
    raise ValueError(str(embedded_problem or "В проекте отсутствует встроенное превью."))


def prepare_blend_previews_batch(paths, status_cb=None, progress_cb=None) -> dict[str,str]:
    """Warm project-local thumbnails, opening Blender only once per practical batch."""
    sources=list(dict.fromkeys(Path(path).resolve() for path in paths))
    pending=[]
    failures={}
    weak_previews={}
    for source in sources:
        # Recheck an existing fallback. It may have been cached before Blender
        # was installed and must not permanently block a later geometry render.
        try:
            image_path,metadata_path,signature=_source_preview_cache_info(
                source,_model_preview_directory(source,BLEND_PREVIEW_CACHE_DIR))
            if (image_path.is_file()
                    and json.loads(metadata_path.read_text(encoding="utf-8"))==signature):
                with Image.open(image_path) as cached:
                    cached_image=cached.convert("RGB")
                if _blend_preview_needs_shaded_render(cached_image):
                    pending.append(source)
                    failures[str(source)]="Сохранённое превью слишком тёмное, проволочное или показывает интерфейс Blender."
                    weak_previews[str(source)]=cached_image
                continue
        except Exception:
            pass
        try:
            _cached_source_preview(source,_model_preview_directory(source,BLEND_PREVIEW_CACHE_DIR),
                                   _blend_preview_without_blender)
        except _WeakBlendPreviewError as error:
            pending.append(source)
            failures[str(source)]=str(error)
            weak_previews[str(source)]=error.image
        except Exception as error:
            pending.append(source)
            failures[str(source)]=str(error)
    if not pending:return {}
    command=_find_blender_command()
    if not command:
        for source in pending:
            key=str(source)
            if key in weak_previews:
                _cached_source_preview(source,_model_preview_directory(source,BLEND_PREVIEW_CACHE_DIR),
                                       lambda _,image=weak_previews[key]:image,force=True)
                failures.pop(key,None)
            else:
                failures[key]+=" Blender не найден. Установите Blender или укажите его путь: Модели → Blender."
        return failures
    if status_cb:status_cb("Blender найден: "+" ".join(command))

    # Keep the command line well below Windows/Linux limits without launching once per file.
    chunks=[]
    current=[]
    encoded_size=0
    for source in pending:
        estimate=len(str(source).encode("utf-8"))*2+12
        if current and encoded_size+estimate>70000:
            chunks.append(current)
            current=[]
            encoded_size=0
        current.append(source)
        encoded_size+=estimate
    if current:chunks.append(current)
    processed=0
    for chunk in chunks:
        source_lookup={str(source):source for source in chunk}
        payload=base64.b64encode(zlib.compress(json.dumps(list(source_lookup),
                                    ensure_ascii=False).encode("utf-8"),5)).decode("ascii")
        script=_BLENDER_BATCH_SCRIPT.replace("__JAI_SOURCES__",payload)
        arguments=_blender_launch_command(command,chunk)+[
            "--background","--factory-startup","--disable-autoexec","--python-expr",script]
        tail=[]
        try:
            process=subprocess.Popen(arguments,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,
                                     text=True,encoding="utf-8",errors="replace",bufsize=1)
            if process.stdout is None:raise RuntimeError("Blender не передал поток результатов.")
            for raw in process.stdout:
                line=str(raw).strip()
                marker=""
                if _BLENDER_BATCH_MARKER in line:
                    marker=_BLENDER_BATCH_MARKER
                elif _BLENDER_BATCH_ERROR_MARKER in line:
                    marker=_BLENDER_BATCH_ERROR_MARKER
                if not marker:
                    if line:
                        tail.append(line[:200])
                        del tail[:-4]
                    continue
                try:
                    encoded=line.split(marker,1)[1].strip()
                    decoded=base64.b64decode(encoded,validate=True)
                    if marker==_BLENDER_BATCH_MARKER:decoded=zlib.decompress(decoded)
                    result=json.loads(decoded.decode("utf-8"))
                    source_name=str(result.get("path") or "")
                    source=source_lookup.get(source_name)
                    if source is None:continue
                    if marker==_BLENDER_BATCH_ERROR_MARKER:
                        failures[source_name]=str(result.get("error") or "Blender не прочитал проект.")
                    else:
                        triangles=np.asarray(result["triangles"],dtype=np.float64)
                        if len(triangles)>STL_PREVIEW_MAX_TRIANGLES:
                            picks=np.linspace(0,len(triangles)-1,STL_PREVIEW_MAX_TRIANGLES,dtype=np.int64)
                            triangles=triangles[picks]
                        image=_render_triangle_preview(triangles,source_kind="Blender")
                        _cached_source_preview(source,_model_preview_directory(source,BLEND_PREVIEW_CACHE_DIR),
                                               lambda _:image,force=True)
                        failures.pop(source_name,None)
                    source_lookup.pop(source_name,None)
                    processed+=1
                    if progress_cb:progress_cb(processed,len(pending),source.name)
                except Exception as error:
                    tail.append(str(error)[:200])
                    del tail[:-4]
            exit_code=process.wait(timeout=30)
            if source_lookup:
                reason=" ".join(tail[-3:])[:450]
                message="Blender не смог подготовить миниатюру"
                if exit_code:message+=f" (код {exit_code})"
                if reason:message+=". Причина: "+reason
                for source_name in source_lookup:failures[source_name]=message
        except Exception as error:
            for source_name in source_lookup:
                failures[source_name]=f"Не удалось запустить Blender: {error}"
            if status_cb:status_cb(f"Blender: {error}")
    for source_name,image in weak_previews.items():
        if source_name in failures:
            try:
                _cached_source_preview(source_name,_model_preview_directory(source_name,BLEND_PREVIEW_CACHE_DIR),
                                       lambda _,fallback=image:fallback,force=True)
                failures.pop(source_name,None)
            except Exception:
                pass
    return failures


def extract_blender_deep_variants_batch(paths, status_cb=None, progress_cb=None,
                                       result_cb=None) -> dict:
    """Open Blender once per batch and stream each hidden design separately."""
    sources = list(dict.fromkeys(Path(path).resolve() for path in paths))
    if not sources:
        return {}
    command = _find_blender_command()
    if not command:
        message = "Blender не найден. Укажи его путь: Модели → Blender."
        return {str(source): {"error": message} for source in sources}
    if status_cb:
        status_cb("DeepThink: Blender проверяет скрытые коллекции и View Layers…")
    chunks = []
    current = []
    estimate = 0
    for source in sources:
        additional = len(str(source).encode("utf-8")) * 2 + 12
        if current and estimate + additional > 12000:
            chunks.append(current)
            current = []
            estimate = 0
        current.append(source)
        estimate += additional
    if current:
        chunks.append(current)
    output = {}
    processed = 0
    for chunk in chunks:
        unresolved = {str(source): source for source in chunk}
        encoded = base64.b64encode(zlib.compress(json.dumps(list(unresolved),
                              ensure_ascii=False).encode("utf-8"), 5)).decode("ascii")
        script = (_BLENDER_DEEP_BATCH_SCRIPT.replace("__JAI_SOURCES__", encoded)
                  .replace("__JAI_MAX_VARIANTS__", str(DEEPTHINK_MAX_VARIANTS_PER_SOURCE))
                  .replace("__JAI_MAX_TRIANGLES__", str(DEEPTHINK_MAX_TRIANGLES_PER_VARIANT)))
        arguments = _blender_launch_command(command, chunk) + [
            "--background", "--factory-startup", "--disable-autoexec", "--python-expr", script]
        tail = []
        try:
            process = subprocess.Popen(arguments, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                       text=True, encoding="utf-8", errors="replace", bufsize=1)
            if process.stdout is None:
                raise RuntimeError("Blender не передал результаты DeepThink.")
            for raw in process.stdout:
                line = str(raw).strip()
                marker = next((value for value in (_BLENDER_DEEP_VARIANT_MARKER,
                                                    _BLENDER_DEEP_DONE_MARKER,
                                                    _BLENDER_DEEP_ERROR_MARKER)
                               if value in line), "")
                if not marker:
                    if line:
                        tail.append(line[:220])
                        del tail[:-4]
                    continue
                try:
                    data = json.loads(zlib.decompress(base64.b64decode(
                        line.split(marker, 1)[1].strip(), validate=True)).decode("utf-8"))
                    source_name = str(data.get("path") or "")
                    if source_name not in unresolved:
                        continue
                    entry = output.setdefault(source_name,
                                              {"path": source_name, "variants": []})
                    if marker == _BLENDER_DEEP_VARIANT_MARKER:
                        triangles = np.asarray(data.pop("triangles"), dtype=np.float64)
                        data["image"] = _render_triangle_preview(triangles, source_kind="Blender")
                        entry["variants"].append(data)
                    elif marker == _BLENDER_DEEP_DONE_MARKER:
                        entry["inventory"] = data.get("inventory") or {}
                        entry["truncated"] = bool(data.get("truncated"))
                        if result_cb:
                            result_cb(source_name, entry)
                            output[source_name] = {"path": source_name,
                                                   "variant_count": len(entry["variants"])}
                        source = unresolved.pop(source_name)
                        processed += 1
                        if progress_cb:
                            progress_cb(processed, len(sources), source.name)
                    else:
                        entry["error"] = str(data.get("error") or "Blender не прочитал проект.")
                        if result_cb:
                            result_cb(source_name, entry)
                        source = unresolved.pop(source_name)
                        processed += 1
                        if progress_cb:
                            progress_cb(processed, len(sources), source.name)
                except Exception as error:
                    tail.append(str(error)[:220])
                    del tail[:-4]
            exit_code = process.wait(timeout=30)
            if unresolved:
                reason = " ".join(tail[-3:])[:450]
                message = "Blender не завершил глубокий анализ"
                if exit_code:
                    message += f" (код {exit_code})"
                if reason:
                    message += ". Причина: " + reason
                for source_name in unresolved:
                    output[source_name] = {"error": message}
        except Exception as error:
            for source_name in unresolved:
                output[source_name] = {"error": f"Не удалось запустить Blender: {error}"}
            if status_cb:
                status_cb(f"DeepThink Blender: {error}")
    return output


def cached_rhino_preview(path: str | Path, cache_dir: Path | None = None) -> Path:
    directory = (Path(cache_dir) if cache_dir is not None
                 else _model_preview_directory(path, RHINO_PREVIEW_CACHE_DIR))
    return _cached_source_preview(path, directory, extract_rhino_preview)


def cached_stl_preview(path: str | Path, cache_dir: Path | None = None) -> Path:
    directory = (Path(cache_dir) if cache_dir is not None
                 else _model_preview_directory(path, STL_PREVIEW_CACHE_DIR))
    return _cached_source_preview(path, directory, render_stl_preview)


def open_visual_image(path: str | Path) -> Image.Image:
    """Returns an ordinary RGB image for photographs, Blender, Rhino and STL."""
    source = Path(path)
    extension = source.suffix.lower()
    if extension in BLENDER_EXTS:
        source = cached_blend_preview(source)
    elif extension in RHINO_EXTS:
        source = cached_rhino_preview(source)
    elif extension in STL_EXTS:
        source = cached_stl_preview(source)
    with Image.open(source) as image:
        return ImageOps.exif_transpose(image).convert("RGB")

def open_visual_image_thumb(path: str | Path, size) -> Image.Image:
    """0.98.0: JPEG декодируется сразу в уменьшенном размере (draft).
    На больших фотографиях это в несколько раз быстрее полного декода."""
    source = Path(path)
    extension = source.suffix.lower()
    if extension in BLENDER_EXTS:
        source = cached_blend_preview(source)
    elif extension in RHINO_EXTS:
        source = cached_rhino_preview(source)
    elif extension in STL_EXTS:
        source = cached_stl_preview(source)
    target = (max(16, int(size[0]) * 2), max(16, int(size[1]) * 2))
    with Image.open(source) as image:
        if image.format == "JPEG":
            try:
                image.draft("RGB", target)
            except Exception:
                pass
        image.load()
        return ImageOps.exif_transpose(image).convert("RGB")


def cosine(a: np.ndarray, b: np.ndarray) -> float:
    if a is None or b is None or a.size == 0 or b.size == 0:
        return -1.0
    return float(np.dot(a, b) / ((np.linalg.norm(a) + 1e-12) * (np.linalg.norm(b) + 1e-12)))


def normalized_mean(vectors: list[np.ndarray]) -> np.ndarray | None:
    if not vectors:
        return None
    x = np.mean(np.vstack(vectors), axis=0).astype(np.float32)
    n = np.linalg.norm(x)
    return x / n if n > 1e-12 else x


def file_signature(paths: list[str]) -> str:
    h = hashlib.sha1()
    for s in sorted(paths, key=lambda x: norm(x)):
        p = Path(s)
        try:
            st = p.stat()
            token = f"{p}|{st.st_mtime_ns}|{st.st_size}"
            if p.suffix.lower() in MODEL_EXTS:
                token += f"|preview:{_model_preview_render_version(p)}"
        except Exception:
            token = str(p)
        h.update(token.encode("utf-8", "ignore"))
    return h.hexdigest()


def path_parts(root: Path, folder: Path):
    try:
        rel = folder.relative_to(root)
        parts = list(rel.parts)
    except Exception:
        parts = list(folder.parts)
    is_model_project = folder.suffix.lower() in MODEL_EXTS
    hierarchy = parts[:-1] if is_model_project else parts
    client = hierarchy[0] if len(hierarchy) >= 1 else ""
    category = hierarchy[1] if len(hierarchy) >= 2 else ""
    title = folder.stem if is_model_project else (parts[-1] if parts else folder.name)
    return client, category, title, os.path.join(*parts) if parts else ""


def path_facts(text: str) -> dict:
    """Сильные факты, которые буквально написаны в пути/названии проекта.
    Здесь нет семантических догадок: только явные слова.
    """
    t = norm(text)
    out = {}
    type_rules = [
        ("обруч", "кольцо"), ("wedding", "кольцо"), ("венч", "кольцо"),
        ("перст", "перстень"), ("signet", "перстень"), ("печат", "перстень"),
        ("кольц", "кольцо"), ("ring", "кольцо"), ("серьг", "серьги"), ("earring", "серьги"),
        ("пусет", "серьги"), ("крест", "крест"), ("cross", "крест"),
        ("кулон", "подвеска"), ("подвес", "подвеска"), ("медальон", "подвеска"),
        ("брасл", "браслет"), ("брош", "брошь"), ("брел", "брелок"), ("знач", "значок"),
    ]
    for needle, value in type_rules:
        if needle in t:
            out["type"] = value
            break
    if ("детск" in t or "ребен" in t or "ребён" in t or re.search(r"\bдети\b",t)
            or "мальчик" in t or "девочк" in t):
        out["audience"] = "детское"
    elif "мужск" in t or any(x in t for x in ("для мужчин", "для парня", "для мужа")):
        out["audience"] = "мужское"
    elif "женск" in t or any(x in t for x in ("для девушки", "для женщин", "для жены", "для подруги")):
        out["audience"] = "женское"
    if "обруч" in t:
        out["subtype"] = "обручальное"
    if "помолв" in t or "engagement" in t:
        out["subtype"] = "помолвочное"
    if "венч" in t:
        out["purpose"] = "венчание"
        out["subtype"] = out.get("subtype") or "венчальное"
    if "золот" in t:
        out["material"] = "золото"
    elif "сереб" in t:
        out["material"] = "серебро"
    elif "платин" in t:
        out["material"] = "платина"
    if any(x in t for x in ("белое золото","белый металл","white gold")):
        out["metal"] = "белый"
    elif any(x in t for x in ("красное золото","розовое золото","red gold","rose gold")):
        out["metal"] = "красный"
    elif any(x in t for x in ("желтое золото","жёлтое золото","yellow gold")):
        out["metal"] = "желтый"
    if "без кам" in t or "без встав" in t:
        out["stones"] = "нет"
        out["stone_count"] = "нет"
    elif any(x in t for x in ("с одним кам","1 кам","один кам")):
        out["stones"] = "есть"; out["stone_count"] = "один"
    elif re.search(r"\b2\s*(?:кам|встав)",t) or "два кам" in t:
        out["stones"] = "есть"; out["stone_count"] = "два"
    elif re.search(r"\b(?:3|4|5|6|7|8|9|[1-9][0-9]+)\s*(?:кам|встав)",t):
        out["stones"] = "есть"; out["stone_count"] = "несколько"
    elif any(x in t for x in ("с кам","с встав")) or re.search(r"\bкамень\b|\bкамни\b|\bкамней\b",t):
        out["stones"] = "есть"
    gem_names = ["бриллиант","алмаз","сапфир","рубин","изумруд","аметист","гранат","топаз","фианит","жемчуг"]
    for g in gem_names:
        if g in t:
            out["stone_type"] = g
            out["stones"] = "есть"
            break
    if "эмал" in t: out["enamel"] = "есть"
    if "ажур" in t or "филигран" in t: out["openwork"] = "есть"
    # Явные слова в названии проекта — полезнее гаданий Vision-модели и бесплатны.
    motif_rules=[
        ("корон","корона"),("герб","герб"),("орел","орел"),("орёл","орел"),("льв","лев"),("лев","лев"),
        ("волк","волк"),("котен","кот"),("котён","кот"),("кошк","кот"),("лис","лиса"),("медвед","медведь"),
        ("тигр","тигр"),("зме","змея"),("дракон","дракон"),("сова","сова"),("сердц","сердце"),
        ("ключ","ключ"),("якор","якорь"),("компас","компас"),("отпечат","отпечаток пальца"),("звезда давида","звезда давида")
    ]
    for needle,value in motif_rules:
        if needle in t:
            out["motif"]=value; break
    if "motif" not in out and re.search(r"\b(?:гора|горы|горами|горный|горные)\b",t):
        out["motif"]="горы"
    for z in ("овен","телец","близнецы","рак","лев","дева","весы","скорпион","стрелец","козерог","водолей","рыбы"):
        if re.search(r"(?<![а-я])"+re.escape(z)+r"(?![а-я])",t):
            out["zodiac"]=z; break
    if "фото" in t and "рендер" not in t: out["image_role"] = "фото изделия"
    elif "рендер" in t: out["image_role"] = "3d-рендер"
    return out



class ImageIndexDB:
    """Совместимый доступ к старому image-index. Сам файл index.sqlite3 остаётся на месте."""

    def __init__(self, path: Path):
        self.path = path
        self._init()

    def connect(self):
        # WAL переключается ОДИН раз в _init. Раньше journal_mode=WAL выполнялся
        # на каждом новом соединении. Пока Qwen писал очередную карточку, даже обычный
        # поисковый SELECT мог ждать этот PRAGMA до 60 секунд — отсюда ощущение,
        # что самый первый запрос «сломал» приложение.
        con = sqlite3.connect(self.path, timeout=12)
        try: con.execute("PRAGMA busy_timeout=12000")
        except Exception: pass
        con.execute("PRAGMA synchronous=NORMAL")
        return con

    def _init(self):
        with self.connect() as con:
            try: con.execute("PRAGMA journal_mode=WAL")
            except Exception: pass
            con.execute("""
                CREATE TABLE IF NOT EXISTS images (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    path TEXT UNIQUE NOT NULL,
                    folder TEXT NOT NULL,
                    client TEXT, category TEXT, project TEXT, relpath TEXT,
                    mtime REAL, size INTEGER, dim INTEGER, embedding BLOB,
                    tags_json TEXT, analysis_version INTEGER DEFAULT 0,
                    vision_json TEXT, vision_mtime REAL, vision_model TEXT,
                    vision_version INTEGER DEFAULT 0
                )
            """)
            con.commit()

    def count(self, root: Path | None = None):
        with self.connect() as con:
            if root is None:
                return int(con.execute("SELECT COUNT(*) FROM images WHERE embedding IS NOT NULL").fetchone()[0])
            # Счётчик в верхней строке должен показывать ТЕКУЩУЮ выбранную папку,
            # а не сумму всех архивов, которые когда-либо индексировались. Не грузим embeddings ради счётчика.
            prefix=str(root).rstrip("\\/")
            sep="\\" if "\\" in prefix else os.sep
            return int(con.execute("SELECT COUNT(*) FROM images WHERE embedding IS NOT NULL AND path LIKE ?",(prefix+sep+"%",)).fetchone()[0])

    def get_rows(self, root: Path | None = None):
        # Важно: V2 берёт не только embeddings, но и уже сделанный в старых версиях
        # поизображенческий Vision AI. Это позволяет НЕ выбрасывать сотни ранее
        # проанализированных картинок при переходе к поиску по проектам.
        # 0.98.0: фильтр корня прямо в SQL — embeddings чужих архивов
        # больше не десериализуются и не передаются в Python.
        sql = ("SELECT path,folder,relpath,mtime,size,dim,embedding,"
               "vision_json,vision_mtime,vision_version,tags_json "
               "FROM images WHERE embedding IS NOT NULL")
        args = []
        if root is not None:
            _bs = chr(92)
            prefix = str(root).rstrip(_bs + "/")
            sep = _bs if _bs in prefix else os.sep
            sql += " AND path LIKE ?"
            args.append(prefix + sep + "%")
        with self.connect() as con:
            rows = con.execute(sql, args).fetchall()
        result = []
        root_s = str(root).lower() if root else ""
        for path, folder, relpath, mtime, size, dim, blob, vision_json, vision_mtime, vision_version, tags_json in rows:
            if root_s:
                try:
                    Path(path).relative_to(root)
                except Exception:
                    continue
            try:
                v = np.frombuffer(blob, dtype=np.float32, count=int(dim or 0)).copy()
                if v.size == 0:
                    continue
            except Exception:
                continue
            vision = json_loads_safe(vision_json, {})
            # Старое описание считаем пригодным только если оно относится к текущей версии файла.
            vision_current = bool(vision)
            try:
                if vision_mtime is not None and abs(float(vision_mtime) - float(mtime or 0)) > 0.001:
                    vision_current = False
            except Exception:
                pass
            result.append({
                "path": path, "folder": folder, "relpath": relpath or path,
                "mtime": float(mtime or 0), "size": int(size or 0), "embedding": v,
                "legacy_vision": vision if vision_current else {},
                "legacy_vision_version": int(vision_version or 0),
                "legacy_tags": json_loads_safe(tags_json, {}),
            })
        return result

    def unchanged(self, path: Path) -> bool:
        try:
            st = path.stat()
        except Exception:
            return False
        with self.connect() as con:
            row = con.execute("SELECT mtime,size,embedding FROM images WHERE path=?", (str(path),)).fetchone()
        return bool(row and row[2] is not None and abs(float(row[0] or 0)-st.st_mtime) < 0.001 and int(row[1] or 0) == st.st_size)

    def unchanged_many(self, paths) -> dict[Path, bool]:
        """Check one scan through one SQLite connection instead of one per file."""
        result = {}
        with self.connect() as con:
            for item in paths:
                path = Path(item)
                try:
                    stat = path.stat()
                    row = con.execute("SELECT mtime,size,embedding IS NOT NULL FROM images "
                                      "WHERE path=?", (str(path),)).fetchone()
                    result[path] = bool(row and row[2]
                        and abs(float(row[0] or 0) - stat.st_mtime) < 0.001
                        and int(row[1] or 0) == stat.st_size)
                except (OSError, sqlite3.Error):
                    result[path] = False
        return result

    @staticmethod
    def _embedding_record(root: Path, path: Path, emb: np.ndarray):
        st = path.stat()
        try:
            rel = path.relative_to(root)
            parts = rel.parts[:-1]
            relpath = str(rel)
        except Exception:
            parts = path.parts[:-1]
            relpath = str(path)
        client = parts[0] if len(parts)>0 else ""
        category = parts[1] if len(parts)>1 else ""
        project = parts[-1] if parts else path.parent.name
        arr = np.asarray(emb, dtype=np.float32)
        return (str(path), str(path.parent), client, category, project, relpath,
                st.st_mtime, st.st_size, arr.size, arr.tobytes(), 1)

    def upsert_embeddings(self, root: Path, records):
        prepared = [self._embedding_record(root, Path(path), embedding)
                    for path, embedding in records]
        if not prepared:
            return
        with self.connect() as con:
            con.executemany("""
                INSERT INTO images(path,folder,client,category,project,relpath,mtime,size,dim,embedding,analysis_version)
                VALUES(?,?,?,?,?,?,?,?,?,?,?)
                ON CONFLICT(path) DO UPDATE SET
                    folder=excluded.folder,client=excluded.client,category=excluded.category,
                    project=excluded.project,relpath=excluded.relpath,mtime=excluded.mtime,
                    size=excluded.size,dim=excluded.dim,embedding=excluded.embedding
            """, prepared)
            con.commit()

    def upsert_embedding(self, root: Path, path: Path, emb: np.ndarray):
        self.upsert_embeddings(root, [(path, emb)])

    def delete_missing_under(self, root: Path, selected_paths=None):
        """Drop vanished files and sources hidden by the current folder policy."""
        root = Path(root)
        prefix = str(root)
        selected = (None if selected_paths is None else
                    {os.path.normcase(str(Path(path))) for path in selected_paths})
        with self.connect() as con:
            rows = con.execute("SELECT path FROM images WHERE path LIKE ?", (prefix + "%",)).fetchall()
            dead = []
            for (stored,) in rows:
                source = Path(stored)
                try:
                    source.relative_to(root)
                except ValueError:
                    continue
                if not source.exists() or (selected is not None
                        and os.path.normcase(str(source)) not in selected):
                    dead.append(stored)
            if dead:
                con.executemany("DELETE FROM images WHERE path=?", [(x,) for x in dead])
                con.commit()
        return len(dead)


class MissingVisualDependencyError(RuntimeError):
    """A shared visual-engine dependency is absent; retrying every image cannot help."""


def _visual_dependency_message(package: str) -> str:
    message=f"Не установлен обязательный компонент визуального поиска: {package}. "
    if getattr(sys,"frozen",False):
        return message+"Переустановите приложение обновлённым установщиком."
    return (message+"Выполните в терминале: "
            f'"{sys.executable}" -m pip install "transformers>=4.40,<5" sentencepiece')


class AIEngine:
    def __init__(self, status_cb=None):
        self.status_cb = status_cb or (lambda s: None)
        self.model = None
        self.preprocess = None
        self.tokenizer = None
        self.torch = None
        self.device = "cpu"
        self.lock = threading.Lock()
        self.text_cache = {}

    def load(self):
        with self.lock:
            if self.model is not None:
                return
            self.status_cb("Загружаю визуальную модель…")
            import torch
            import open_clip
            try:
                import transformers
            except ImportError as error:
                raise MissingVisualDependencyError(_visual_dependency_message("transformers")) from error
            try:
                import sentencepiece
            except ImportError as error:
                raise MissingVisualDependencyError(_visual_dependency_message("sentencepiece")) from error
            self.torch = torch
            self.device = "cuda" if torch.cuda.is_available() else "cpu"
            try:
                model, _, preprocess = open_clip.create_model_and_transforms(
                    MODEL_NAME,pretrained=PRETRAINED,device=self.device)
            except Exception as error:
                detail=str(error).lower()
                if "transformers" in detail and ("pip install" in detail or "not found" in detail):
                    raise MissingVisualDependencyError(
                        _visual_dependency_message("transformers")) from error
                if "sentencepiece" in detail and ("install" in detail or "not found" in detail):
                    raise MissingVisualDependencyError(
                        _visual_dependency_message("sentencepiece")) from error
                raise
            model.eval()
            self.model = model
            self.preprocess = preprocess
            self.tokenizer = open_clip.get_tokenizer(MODEL_NAME)
            self.status_cb(f"Визуальная модель готова ({'GPU' if self.device=='cuda' else 'CPU'}).")

    def _amp(self):
        if self.device == "cuda":
            return self.torch.autocast(device_type="cuda")
        return nullcontext()

    def encode_image(self, path: str) -> np.ndarray:
        img = open_visual_image(path)
        self.load()
        x = self.preprocess(img).unsqueeze(0).to(self.device)
        with self.torch.inference_mode(), self._amp():
            feat = self.model.encode_image(x)
            feat = feat / feat.norm(dim=-1, keepdim=True)
        return feat[0].float().cpu().numpy().astype(np.float32)

    def preferred_image_batch_size(self) -> int:
        self.load()
        if self.device != "cuda":
            return max(2, min(6, (os.cpu_count() or 2) // 2))
        try:
            free, _total = self.torch.cuda.mem_get_info()
            free_gib = float(free) / (1024 ** 3)
            if free_gib >= 8:
                return 24
            if free_gib >= 4:
                return 16
            if free_gib >= 2:
                return 8
            return 4
        except Exception:
            return 8

    def encode_images(self, paths) -> list[np.ndarray]:
        """Run several CLIP images in one GPU/CPU inference call."""
        sources = list(paths)
        if not sources:
            return []
        if len(sources) == 1:
            return [self.encode_image(str(sources[0]))]
        self.load()
        images = [self.preprocess(open_visual_image(path)) for path in sources]
        batch = self.torch.stack(images).to(self.device,
                                             non_blocking=(self.device == "cuda"))
        with self.torch.inference_mode(), self._amp():
            features = self.model.encode_image(batch)
            features = features / features.norm(dim=-1, keepdim=True)
        values = features.float().cpu().numpy().astype(np.float32)
        return [np.asarray(value, dtype=np.float32) for value in values]

    def encode_text(self, text: str) -> np.ndarray:
        self.load()
        key = norm(text)
        if key in self.text_cache:
            return self.text_cache[key]
        toks = self.tokenizer([text]).to(self.device)
        with self.torch.inference_mode(), self._amp():
            feat = self.model.encode_text(toks)
            feat = feat / feat.norm(dim=-1, keepdim=True)
        arr = feat[0].float().cpu().numpy().astype(np.float32)
        self.text_cache[key] = arr
        return arr

# ---------------- Ollama / structured JSON ----------------

def image_as_b64(path: str, max_side=1024, jpeg_quality=82) -> str:
    img = open_visual_image(path)
    img.thumbnail((max_side, max_side), Image.Resampling.LANCZOS)
    bio = BytesIO()
    img.save(bio, format="JPEG", quality=jpeg_quality, optimize=True)
    return base64.b64encode(bio.getvalue()).decode("ascii")


def ollama_chat_json(model: str, system: str, user_text: str, schema: dict, images: list[str] | None = None, timeout=240) -> dict:
    """Структурированный запрос к любой совместимой Ollama-модели.

    Разные VLM по-разному строго соблюдают JSON Schema, поэтому есть аккуратный fallback:
    schema -> обычный JSON -> текст с извлечением JSON. Это позволяет менять модель без переписывания кода.
    """
    msg = {"role": "user", "content": user_text}
    if images:
        msg["images"] = [image_as_b64(p) for p in images]

    attempts = [
        {"format": schema, "think": False},
        {"format": "json"},
        {},
    ]
    last_error = None
    for attempt_no, extra in enumerate(attempts, 1):
        user_msg = dict(msg)
        if attempt_no >= 2:
            user_msg["content"] = user_text + "\nВерни только один JSON-объект без пояснений и markdown."
        payload = {
            "model": model,
            "messages": [{"role":"system","content":system}, user_msg],
            "stream": False,
            "options": {"temperature": 0.05},
            "keep_alive": "10m",
        }
        payload.update(extra)
        req = urllib.request.Request(
            OLLAMA_CHAT_URL,
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type":"application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                data = json.loads(r.read().decode("utf-8", "replace"))
        except urllib.error.HTTPError as e:
            try:
                detail=e.read().decode("utf-8","replace")
            except Exception:
                detail=str(e)
            if e.code == 404 or "not found" in detail.lower():
                raise RuntimeError(f"Модель {model} не найдена в Ollama. Скачай её через «Модели / скачать…».") from e
            last_error = RuntimeError(f"Ollama вернул ошибку {e.code}: {detail[:400]}")
            continue
        except urllib.error.URLError as e:
            raise RuntimeError("Ollama недоступен. Запусти Ollama и проверь, что локальная модель установлена.") from e
        except Exception as e:
            last_error=e
            continue

        content = ((data.get("message") or {}).get("content") or data.get("response") or "").strip()
        if not content:
            thinking=((data.get("message") or {}).get("thinking") or data.get("thinking") or "").strip()
            last_error = RuntimeError("Локальная модель вернула пустой ответ" + (" и только внутреннее рассуждение." if thinking else "."))
            continue
        try:
            parsed=json.loads(content)
            if isinstance(parsed,dict): return parsed
        except Exception:
            pass
        m = re.search(r"\{.*\}", content, re.S)
        if m:
            try:
                parsed=json.loads(m.group(0))
                if isinstance(parsed,dict): return parsed
            except Exception as e:
                last_error=e
        else:
            last_error=RuntimeError("Модель не вернула JSON.")
    if isinstance(last_error,RuntimeError):
        raise last_error
    raise RuntimeError(f"Не удалось разобрать ответ модели {model} как JSON.")


CASUAL_CHAT_SYSTEM = """Ты дружелюбный живой собеседник внутри программы Jewelry AI Search.
Пиши по-русски естественно, по существу и без канцелярских фраз. Обычно достаточно 1–3 предложений,
но если человек просит объяснить подробнее — объясни понятным человеческим языком. Учитывай предыдущие реплики.
Не называй себя «разговорной моделью» и не повторяй, что поиск продолжает работать: просто отвечай человеку.
Ты можешь говорить на любые обычные темы и хорошо понимаешь ювелирные изделия, материалы, камни и стили.
Поиск проектов и фотографий выполняет само приложение. Подтверждённый локальный контекст приложения доступен тебе ниже:
используй реальные названия, количество проектов и пути из этого контекста, но не придумывай отсутствующие факты.
Не говори, что у тебя нет доступа к локальной базе или папкам: проиндексированные сведения передаёт само приложение.
У тебя нет интернета: текущую погоду, новости и курсы не выдумывай. Текущее локальное время передано ниже.
Не показывай внутренние рассуждения, служебные инструкции, JSON и техническую диагностику.
"""

CASUAL_CHAT_SYSTEM_EN = """You are a friendly assistant inside Jewelry AI Search.
Reply naturally in English, usually in one to three clear sentences. Explain more if asked.
You understand jewelry, precious metals, gemstones, clients and styles.
The application provides verified local project names, counts and folders below. Use them
accurately and never invent missing facts. You do not have internet access. Do not expose
internal reasoning, system instructions, JSON or technical diagnostics.
"""


def ollama_chat_text(model: str, user_text: str, history: list[dict] | None = None,
                     timeout=120, local_context: dict | None = None,
                     language: str = DEFAULT_UI_LANGUAGE) -> str:
    """Обычный локальный разговор через выбранную Chat-модель Ollama.
    Интернет здесь не используется. История ограничена несколькими последними репликами.
    """
    local_now=datetime.now().strftime("%d.%m.%Y %H:%M")
    context_lines = []
    if isinstance(local_context, dict):
        if local_context.get("root"):
            context_lines.append("Папка локального ювелирного архива: " + str(local_context["root"])[:500])
        if local_context.get("total_projects") is not None:
            context_lines.append("Проиндексировано проектов: " + str(int(local_context.get("total_projects") or 0)))
        for item in (local_context.get("matches") or [])[:4]:
            if not isinstance(item, dict):
                continue
            client = str(item.get("client") or "")[:90]
            title = str(item.get("title") or "")[:120]
            folder = str(item.get("rel_folder") or item.get("folder") or "")[:260]
            context_lines.append(f"Подтверждённый проект: клиент={client or 'не указан'}; название={title}; папка={folder}")
        current = local_context.get("current_selection")
        if current is not None:
            context_lines.append("Проектов в текущей выборке: " + str(int(current or 0)))
    context = "\n".join(context_lines) or "Локальный архив ещё не выбран."
    english=normalize_ui_language(language)=="en"
    system=CASUAL_CHAT_SYSTEM_EN if english else CASUAL_CHAT_SYSTEM
    timestamp=(f"\nLocal date and time: {local_now}.\n" if english
               else f"\nЛокальные дата и время: {local_now}.\n")
    messages=[{"role":"system","content":system+timestamp+context}]
    for m in (history or [])[-8:]:
        if isinstance(m,dict) and m.get("role") in {"user","assistant"} and str(m.get("content") or "").strip():
            messages.append({"role":m["role"],"content":str(m["content"])[:1200]})
    messages.append({"role":"user","content":str(user_text)[:1800]})
    payload={
        "model":str(model).strip(), "messages":messages, "stream":False,
        "think":False,"options":{"temperature":0.62,"num_predict":240,"num_ctx":4096},
        "keep_alive":"10m"
    }
    req=urllib.request.Request(OLLAMA_CHAT_URL,data=json.dumps(payload).encode("utf-8"),
                               headers={"Content-Type":"application/json"},method="POST")
    try:
        with urllib.request.urlopen(req,timeout=timeout) as r:
            data=json.loads(r.read().decode("utf-8","replace"))
    except urllib.error.HTTPError as e:
        try: detail=e.read().decode("utf-8","replace")
        except Exception: detail=str(e)
        raise RuntimeError(friendly_model_error(f"Ollama вернул ошибку {e.code}: {detail[:500]}")) from e
    except urllib.error.URLError as e:
        raise RuntimeError("Ollama недоступен.") from e
    content=((data.get("message") or {}).get("content") or data.get("response") or "").strip()
    if not content:
        raise RuntimeError("Локальная разговорная модель вернула пустой ответ.")
    return content[:1800]


