    def global_manual_stats(self) -> tuple[int,int]:
        """Сколько ручных учебных проектов/фактов накоплено во ВСЕХ ранее открытых архивах."""
        with self.connect() as con:
            row=con.execute("SELECT COUNT(DISTINCT project_id), COUNT(*) FROM project_manual_labels").fetchone()
        return int(row[0] or 0), int(row[1] or 0)

    def global_manual_training_examples(self) -> list[dict]:
        """Ручные примеры со всех корней на этом компьютере.

        Это и есть общий преподаватель 0.45: если пользователь разметил проект в D:\\R.kiselev,
        эти подтверждённые факты автоматически участвуют в обучении новой папки, не требуя .jaik.
        """
        grouped={}
        with self.connect() as con:
            rows=con.execute("""
                SELECT p.id,p.root,p.portable_key,p.dim,p.embedding
                FROM projects p
                WHERE p.embedding IS NOT NULL AND p.dim IS NOT NULL AND (
                    EXISTS(SELECT 1 FROM project_manual_labels m WHERE m.project_id=p.id)
                    OR EXISTS(
                        SELECT 1 FROM connected_knowledge_manual m
                        JOIN connected_knowledge_sources s ON s.source_id=m.source_id AND s.enabled=1
                        WHERE m.portable_key=p.portable_key
                    )
                )
                ORDER BY p.id
            """).fetchall()
        labels_by_project=self._manual_map_for_ids([int(row[0]) for row in rows])
        for pid,root,portable_key,dim,blob in rows:
            try:
                vec=np.frombuffer(blob,dtype=np.float32,count=int(dim or 0)).copy() if blob and dim else None
            except Exception:
                vec=None
            labels=labels_by_project.get(int(pid),{})
            if vec is None or not vec.size or not labels:
                continue
            grouped[int(pid)]={"project_id":int(pid),"root":str(root or ""),
                               "portable_key":str(portable_key or ""),
                               "embedding":vec,"labels":labels}
        # На случай старых дублей одного и того же проекта оставляем один учебный пример.
        out=[]; seen=set()
        for ex in grouped.values():
            labels=ex.get("labels") or {}
            key=(ex.get("portable_key") or "", json.dumps(labels,ensure_ascii=False,sort_keys=True))
            if key[0] and key in seen:
                continue
            if key[0]: seen.add(key)
            out.append(ex)
        return out

    def has_any_training_knowledge(self) -> bool:
        gp,_=self.global_manual_stats()
        if gp:
            return True
        with self.connect() as con:
            return bool(con.execute("SELECT 1 FROM portable_training_examples LIMIT 1").fetchone()
                        or con.execute("""
                            SELECT 1 FROM connected_knowledge_examples e
                            JOIN connected_knowledge_sources s ON s.source_id=e.source_id AND s.enabled=1
                            LIMIT 1
                        """).fetchone()
                        or con.execute("""
                            SELECT 1 FROM connected_knowledge_manual m
                            JOIN connected_knowledge_sources s ON s.source_id=m.source_id AND s.enabled=1
                            JOIN projects p ON p.portable_key=m.portable_key
                            LIMIT 1
                        """).fetchone())

    def manual_neighbor_hints(self, project_id: int, limit: int = 4, min_similarity: float = 0.62) -> list[dict]:
        """Ближайшие ручные примеры из любых ранее открытых папок.

        Передаём их Vision-модели только как подсказки предметной области. Само изображение остаётся
        главным источником истины; так старые исправления начинают помогать НОВЫМ изображениям.
        """
        p=self.get(int(project_id),attach_facts=False)
        vec=self._normalize_vec(p.get("embedding") if p else None)
        if vec is None:
            return []
        scored=[]
        for ex in self.global_manual_training_examples():
            if int(ex.get("project_id") or -1)==int(project_id):
                continue
            ev=self._normalize_vec(ex.get("embedding"))
            if ev is None or ev.size!=vec.size:
                continue
            sim=float(np.dot(vec,ev))
            if sim < float(min_similarity):
                continue
            scored.append((sim,ex))
        scored.sort(key=lambda x:x[0],reverse=True)
        out=[]
        for sim,ex in scored[:max(1,int(limit or 4))]:
            out.append({"similarity":sim,"labels":ex.get("labels") or {}})
        return out

