# 0.52: интерфейс обучения теперь строится вокруг тегов. Внутри БД сохраняем
# структурные факты, чтобы поиск оставался точным, но пользователю не нужно заполнять анкету.
TAG_CORE_FIELDS = (
    "type","subtype","audience","metal_mode","metal","material","stones","stone_count","center_stone",
    "stone_type","stone_color","stone_shape","stone_size","openwork","enamel","mass","width","shape",
    "composition","image_role","motif","style","ornament","zodiac"
)
TAG_EXCLUSIVE_FIELDS = {
    "type","subtype","audience","metal_mode","material","stones","stone_count","center_stone",
    "stone_size","openwork","enamel","mass","width","shape","composition","image_role"
}


# 0.91.2: теги, которые не несут смысла и не должны показываться
# пользователю как AI-предложения или сохраняться как ручные теги.
_USELESS_LITERAL_TAGS = frozenset({
    "нет", "не", "no", "false", "none", "null", "n/a", "na",
    "неизвестно", "unknown", "unclear", "не применимо", "неприменимо",
    "0", "-", "\u2014", "\u043d/\u0434", "\u043d\u0434",
})

def _tag_dedupe(values):
    out=[]
    for x in values or []:
        x=norm(x)
        if not x:
            continue
        if x in _USELESS_LITERAL_TAGS:
            continue
        if not any(tag_terms_equivalent(x,y) for y in out):
            out.append(x)
    return out


def move_tag_between_fields(tag: str, positive, negative, target: str = "positive") -> tuple[list[str],list[str]]:
    """Moves a quick tag to the selected editor and removes it from the opposite one."""
    tag=norm(tag)
    pos=_tag_dedupe(positive)
    neg=_tag_dedupe(negative)
    if not tag:
        return pos,neg
    if str(target).lower() in {"negative","neg","minus","отрицательные"}:
        pos=[x for x in pos if not tag_terms_equivalent(x,tag)]
        if not any(tag_terms_equivalent(x,tag) for x in neg): neg.append(tag)
    else:
        neg=[x for x in neg if not tag_terms_equivalent(x,tag)]
        if not any(tag_terms_equivalent(x,tag) for x in pos): pos.append(tag)
    return _tag_dedupe(pos),_tag_dedupe(neg)


def fact_to_user_tag(key: str, value: str) -> str:
    """Человекочитаемый тег из внутреннего структурного факта."""
    key=str(key or "")
    v=canon(key,value)
    if not v: return ""
    if v=="нет":
        # Осмысленные отрицания оставляем: их полезно кликнуть в панели.
        if key=="stones": return "без камней"
        if key=="stone_count": return "без камней"
        if key=="center_stone": return "без центрального камня"
        if key=="openwork": return "без ажура"
        if key=="enamel": return "без эмали"
        # 0.91.2: любое другое field=нет превращалось в мусорный тег "нет".
        # Больше не показываем его ни в панели AI, ни в ручных тегах.
        return ""
    if key=="metal":
        return {
            "белый":"белый металл","желтый":"желтый металл","красный":"красный металл",
            "черный":"черный металл","комбинированный":"комбинированный металл"
        }.get(v,v)
    if key=="stones": return "камни есть" if v=="есть" else "без камней"
    if key=="stone_count":
        return {"один":"1 камень","два":"2 камня","несколько":"несколько камней","много":"много камней"}.get(v,v)
    if key=="center_stone": return "центральный камень" if v=="есть" else "без центрального камня"
    if key=="stone_color": return f"камень {v}"
    if key=="stone_shape": return f"камень {v}"
    if key=="stone_size": return f"{v} камень"
    if key=="shape": return f"форма {v}"
    if key=="openwork": return "ажур" if v=="есть" else "без ажура"
    if key=="enamel": return "эмаль" if v=="есть" else "без эмали"
    if key in {"tag","not_tag","motif","style","ornament","zodiac"}: return v
    return v


def manual_labels_to_user_tags(labels: dict) -> tuple[list[str], list[str]]:
    positive=[]
    negative=[]
    labels=labels or {}
    for key,vals in labels.items():
        if key=="not_tag":
            negative.extend(norm(x) for x in vals or [] if norm(x))
            continue
        if key=="tag":
            positive.extend(norm(x) for x in vals or [] if norm(x))
            continue
        # motif/style/ornament могут дублировать универсальный tag — dedupe ниже уберёт повторы.
        for val in vals or []:
            t=fact_to_user_tag(key,val)
            if t: positive.append(t)
    return _tag_dedupe(positive), _tag_dedupe(negative)


def positive_tag_structured_targets(raw: str) -> list[tuple[str,str]]:
    """Осторожно раскладывает свободный положительный тег по внутренним полям.

    Сам тег ВСЕГДА остаётся в универсальном поле tag. В структуру кладём только достаточно
    однозначные вещи, чтобы строка «серебро, бриллиант, круг, матовый» не превращалась
    в случайную анкету. Неоднозначные «круг/белый/красный» остаются обычными тегами,
    если пользователь не уточнил «камень»/«металл»/«форма».
    """
    t=norm(raw)
    if not t: return []
    out=[]
    def add(k,v):
        cv=canon(k,v)
        if cv and (k,cv) not in out: out.append((k,cv))

    # Явные конструкции прежде всего.
    stone_no=any(x in t for x in ("без кам", "камней нет", "камня нет"))
    if stone_no:
        add("stones","нет"); add("stone_count","нет")
    elif t in {"камни есть","камень есть","с камнями","с камнем","камни"}:
        add("stones","есть")
    if re.search(r"(^|\s)1\s*кам",t) or "один кам" in t or "с одним кам" in t:
        add("stones","есть"); add("stone_count","один")
    elif re.search(r"(^|\s)2\s*кам",t) or "два кам" in t or "двумя кам" in t:
        add("stones","есть"); add("stone_count","два")
    elif "несколько кам" in t:
        add("stones","есть"); add("stone_count","несколько")
    elif "много кам" in t:
        add("stones","есть"); add("stone_count","много")
    if "без централь" in t: add("center_stone","нет")
    elif "центральн" in t and "кам" in t: add("center_stone","есть"); add("stones","есть")

    if "бел" in t and "металл" in t: add("metal","белый")
    if ("желт" in t or "жёлт" in t) and "металл" in t: add("metal","желтый")
    if ("красн" in t or "розов" in t) and "металл" in t: add("metal","красный")
    if ("черн" in t or "чёрн" in t) and "металл" in t: add("metal","черный")
    if "комбинирован" in t and "металл" in t: add("metal","комбинированный")

    if "без ажур" in t: add("openwork","нет")
    elif "ажур" in t or "филигран" in t: add("openwork","есть")
    if "без эмал" in t: add("enamel","нет")
    elif "эмал" in t: add("enamel","есть")

    if t.startswith("форма "):
        add("shape",t.split(" ",1)[1])
    if "кам" in t and not stone_no:
        # Для слов с явным контекстом камня допускаем цвет/форму/размер.
        for key in ("stone_type","stone_color","stone_shape","stone_size"):
            table=ALIASES.get(key,{}) or {}
            for alias,val in sorted(table.items(),key=lambda kv:len(kv[0]),reverse=True):
                if alias and alias in t and canon(key,val)!="нет":
                    add(key,val); add("stones","есть"); break

    # Для ручных тегов здесь принципиально НЕ используем fuzzy-сопоставление между разными
    # категориями: «обручальное» не должно случайно стать «массивным». Опечатки всё равно
    # понимает поиск; структурный слот присваиваем только по точному известному alias/значению.
    def exact_value(key):
        table=ALIASES.get(key,{}) or {}
        if t in table: return table[t]
        vals=set(table.values())
        return t if t in vals else ""
    exact_keys=("type","subtype","audience","material","metal_mode","mass","width","image_role","composition","motif","style","ornament","zodiac")
    if not stone_no: exact_keys=exact_keys+("stone_type",)
    for key in exact_keys:
        cv=exact_value(key)
        if cv: add(key,cv)

    # Разговорные устойчивые формы.
    if any(x in t for x in ("детск","для детей")): add("audience","детское")
    if "обручал" in t or "свадебн" in t: add("type","кольцо"); add("subtype","обручальное")
    if "помолв" in t: add("type","кольцо"); add("subtype","помолвочное")
    if "венчан" in t: add("type","кольцо"); add("subtype","венчальное")
    return out


def ai_confidence_palette(conf: float) -> tuple[str,str]:
    """Фон/текст для AI-тега. Ручные теги не красятся: они считаются подтверждёнными."""
    try: c=float(conf)
    except Exception: c=0.0
    if c>=0.90: return "#C8E6C9", "#145A20"       # зелёный
    if c>=0.75: return "#E2F0D9", "#2E5D22"       # светло-зелёный
    if c>=0.60: return "#FFF2CC", "#7A5200"       # жёлтый
    if c>=0.45: return "#FCE4D6", "#8A3D00"       # оранжевый
    return "#F8D7DA", "#8B1E24"                  # красный

# 0.43: подтипы зависят от типа изделия. Нелепые пары вроде
# «подвеска + помолвочное» больше не проходят ни из ручной карточки, ни из AI-прогноза.
TYPE_SUBTYPE_OPTIONS = {
    "кольцо":["НЕТ","обручальное","помолвочное","венчальное","печатка","именное"],
    "перстень":["НЕТ","печатка","именное"],
    "серьги":["НЕТ","пусеты","именное"],
    "подвеска":["НЕТ","медальон","именное"],
    "крест":["НЕТ","именное"],
    "браслет":["НЕТ","именное"],
    "брошь":["НЕТ","именное"],
    "брелок":["НЕТ","именное"],
    "значок":["НЕТ","именное"],
    "застежка":["НЕТ"],
    "комплект":["НЕТ"],
}

def allowed_subtypes_for_type(item_type: str) -> list[str]:
    t=canon("type",item_type) if item_type else ""
    return list(TYPE_SUBTYPE_OPTIONS.get(t,["НЕТ"]))

def subtype_is_compatible(item_type: str, subtype: str) -> bool:
    st=canon("subtype",subtype)
    if not st or st=="нет":
        return True
    allowed={canon("subtype",x) for x in allowed_subtypes_for_type(item_type)}
    return st in allowed


def _runtime_project_path_facts(project:dict)->dict:
    cached=project.get("_runtime_path_facts")
    if isinstance(cached,dict):
        return cached
    try:
        cached=path_facts(" ".join([project.get("client",""),project.get("category",""),
                                      project.get("title",""),project.get("rel_folder","")]))
    except Exception:
        cached={}
    project["_runtime_path_facts"]=cached
    return cached


def project_type_for_rules(project: dict) -> str:
    """Самый надёжный известный тип без рекурсивного обращения к поиску."""
    if "_project_rule_type" in project:
        return str(project.get("_project_rule_type") or "")
    manual=(project.get("manual_labels") or {}).get("type") or []
    if manual:
        t=canon("type",manual[0])
        if t:
            project["_project_rule_type"]=t
            return t
    pf=dict(project.get("path_facts") or {})
    pf.update({k:v for k,v in _runtime_project_path_facts(project).items() if v})
    if pf.get("type"):
        t=canon("type",pf.get("type"))
        if t:
            project["_project_rule_type"]=t
            return t
    for vv in (project.get("vision") or {}, project.get("legacy_vision") or {}):
        vals=_vision_values(vv,"type") if isinstance(vv,dict) else []
        if vals:
            result=canon("type",vals[0]); project["_project_rule_type"]=result
            return result
    project["_project_rule_type"]=""
    return ""

def tag_terms_equivalent(a: str, b: str) -> bool:
    """Синонимы + склонения + небольшие опечатки для ручных +/- тегов."""
    a,b=norm(a),norm(b)
    if not a or not b: return False
    if fuzzy_phrase_in_text(a,b) or fuzzy_phrase_in_text(b,a):
        return True
    for key in ("type","subtype","motif","style","ornament","zodiac","material","metal","metal_mode","stone_type","stone_color","shape"):
        ca,cb=canon(key,a),canon(key,b)
        # Считаем синонимом только если хотя бы один вариант реально известен таблице alias.
        known_a = a in (ALIASES.get(key,{}) or {}) or ca in set((ALIASES.get(key,{}) or {}).values())
        known_b = b in (ALIASES.get(key,{}) or {}) or cb in set((ALIASES.get(key,{}) or {}).values())
        if known_a and known_b and ca and cb and ca==cb:
            return True
    return False

def manual_negative_tags(project: dict) -> list[str]:
    vals=(project.get("manual_labels") or {}).get("not_tag") or []
    # 0.93.3: помеченные связки учитываются отдельно в hard_match_project
    # и не должны запрещать отдельные слова через отрицательные теги.
    return [norm(x) for x in vals if norm(x) and not norm(x).startswith("⟦связка⟧")]

def negative_tag_structured_targets(raw: str) -> list[tuple[str,str]]:
    """Пытаемся понять, какой ТОЧНЫЙ слот пользователь отрицает свободным тегом.

    Это делает «Нет: дети, детское» не просто текстовым запретом одной карточки,
    а учебным отрицательным примером audience=детское. Для неизвестного слова остаётся tag.
    """
    t=norm(raw)
    if not t: return []
    out=[]
    def add(k,v):
        cv=canon(k,v)
        pair=(k,cv)
        if cv and pair not in out: out.append(pair)

    # Сначала самые однозначные категории. Подтип важнее общего типа:
    # «обручалка» = отрицание subtype=обручальное, а не запрет вообще всех колец.
    subtype_cv=_known_alias_value("subtype",t)
    if subtype_cv: add("subtype",subtype_cv)
    for key in ("audience","purpose","material","metal","metal_mode","stones","mass","width","openwork","enamel",
                "motif","ornament","style","zodiac","image_role"):
        cv=_known_alias_value(key,t)
        if cv: add(key,cv)
    # Для камней/форм используем только точный alias: слишком мягкое сравнение способно
    # принять, например, «кулон» за «кушон», а отрицательные знания должны быть особенно осторожными.
    stone_context=any(x in t for x in ("кам", "встав"))
    table=ALIASES.get("stone_type",{}) or {}
    if t in table: add("stone_type",table[t])
    if stone_context:
        for key in ("stone_color","stone_shape","stone_size","stone_count"):
            table=ALIASES.get(key,{}) or {}
            if t in table: add(key,table[t])
    else:
        table=ALIASES.get("shape",{}) or {}
        if t in table: add("shape",table[t])
    # Общий тип добавляем только для действительно типового слова, а не если это уже известный подтип.
    if not subtype_cv:
        table=ALIASES.get("type",{}) or {}
        if t in table:
            add("type",table[t])
        else:
            type_stems=(("кольц","кольцо"),("перст","перстень"),("печат","перстень"),("серьг","серьги"),("серег","серьги"),
                        ("подвес","подвеска"),("кулон","подвеска"),("крест","крест"),("брасл","браслет"),
                        ("брош","брошь"),("брел","брелок"),("знач","значок"),("застеж","застежка"),("застёж","застежка"),("комплект","комплект"))
            for stem,val in type_stems:
                if stem in t:
                    add("type",val); break

    # Разговорные формы, которых может не быть в точном словаре aliases.
    if any(x in t for x in ("детск","для детей","ребен","ребён","мальчик","девоч")): add("audience","детское")
    if any(x in t for x in ("женск","для женщин","девушк")): add("audience","женское")
    if any(x in t for x in ("мужск","для мужчин")): add("audience","мужское")
    if "обручал" in t or "свадебн" in t: add("subtype","обручальное")
    if "помолв" in t: add("subtype","помолвочное")
    if "венчан" in t: add("subtype","венчальное")
    if "ажур" in t or "филигран" in t: add("openwork","есть")
    if "эмал" in t: add("enamel","есть")
    if "кам" in t and not any(x in t for x in ("без кам", "камней нет", "камня нет")): add("stones","есть")
    if any(x in t for x in ("без кам", "камней нет", "камня нет")): add("stones","нет")
    return out

def learned_negative_matches(project: dict, term: str, key: str|None=None) -> bool:
    learned=project.get("learned_exclusions") or {}
    term=norm(term)
    if not term: return False
    # Если пользователь на этой карточке вручную подтвердил противоположное, никакой переносимый минус не действует.
    if key:
        positives=(project.get("manual_labels") or {}).get(key) or []
        if any(compatible_value(key,x,term) for x in positives):
            return False
        for item in learned.get(key) or []:
            try: conf=float(item.get("confidence",0.0) or 0.0)
            except Exception: conf=0.0
            if conf < 0.72: continue
            val=str(item.get("value") or "")
            if compatible_value(key,val,term):
                return True
    for item in learned.get("tag") or []:
        try: conf=float(item.get("confidence",0.0) or 0.0)
        except Exception: conf=0.0
        if conf < 0.74: continue
        if tag_terms_equivalent(str(item.get("value") or ""),term):
            return True
    return False

def negative_tag_matches(project: dict, term: str, key: str|None=None) -> bool:
    term=norm(term)
    if not term: return False
    # Ручной минус на самой карточке — абсолютный.
    for neg in manual_negative_tags(project):
        if tag_terms_equivalent(neg,term):
            return True
        if key:
            for nk,nv in negative_tag_structured_targets(neg):
                if nk==key and compatible_value(key,nv,term):
                    return True
            a,b=canon(key,neg),canon(key,term)
            if a and b and a==b:
                return True
    return learned_negative_matches(project,term,key)


# ---------------- Language normalizer: склонения, синонимы и небольшие опечатки ----------------
_RU_ENDINGS = tuple(sorted({
    "иями","ями","ами","ого","его","ому","ему","ыми","ими","ая","яя","ое","ее","ые","ие",
    "ой","ей","ый","ий","ую","юю","ых","их","ам","ям","ах","ях","ом","ем","ов","ев","ей",
    "а","я","ы","и","у","ю","е","о","ь"
}, key=len, reverse=True))
_QUERY_VOCAB_CACHE = None


@lru_cache(maxsize=32768)
def _simple_ru_stem(word: str) -> str:
    w=norm(word)
    if len(w) <= 3:
        return w
    for end in _RU_ENDINGS:
        if len(w)-len(end) >= 3 and w.endswith(end):
            return w[:-len(end)]
    return w


def _levenshtein_limited(a: str, b: str, limit: int = 2) -> int:
    """Маленький Levenshtein без внешних библиотек. Нужен только для коротких поисковых слов."""
    if abs(len(a)-len(b)) > limit:
        return limit+1
    prev=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        cur=[i]
        row_min=i
        for j,cb in enumerate(b,1):
            v=min(cur[-1]+1,prev[j]+1,prev[j-1]+(ca!=cb))
            cur.append(v); row_min=min(row_min,v)
        if row_min>limit:
            return limit+1
        prev=cur
    return prev[-1]


@lru_cache(maxsize=65536)
def _word_close(a: str, b: str) -> bool:
    a,b=norm(a),norm(b)
    if not a or not b:
        return False
    if a==b:
        return True
    sa,sb=_simple_ru_stem(a),_simple_ru_stem(b)
    if len(sa)>=3 and sa==sb and min(len(a),len(b))>=4:
        return True
    if len(sa)>=4 and (sa.startswith(sb) or sb.startswith(sa)) and min(len(sa),len(sb))>=3:
        return True
    if min(len(a),len(b)) < 5:
        return False
    limit=2 if max(len(a),len(b))>=6 else 1
    if _levenshtein_limited(a,b,limit) <= limit:
        return True
    ratio=SequenceMatcher(None,a,b).ratio()
    threshold=0.80 if max(len(a),len(b))>=7 else 0.84
    return ratio >= threshold


def _query_vocab() -> list[str]:
    global _QUERY_VOCAB_CACHE
    if _QUERY_VOCAB_CACHE is not None:
        return _QUERY_VOCAB_CACHE
    words=set()
    for table in ALIASES.values():
        for x in list(table.keys())+list(table.values()):
            for tok in re.findall(r"[a-zа-я0-9]+",norm(x)):
                if len(tok)>=4:
                    words.add(tok)
    words.update({
        "пошути", "шутка", "анекдот",
        "покажи","найди","оставь","убери","исключи","кольца","кольцо","перстни","перстень",
        "кулоны","кулон","подвески","подвеска","браслеты","браслет","серьги","крестики","крест",
        "обручальные","обручалка","обручалки","свадебные","помолвочные","помолвка","венчальные","золото","золотое","серебро","платина",
        "желтое","желтый","красное","красный","розовое","розовый","белое","белый",
        "камень","камни","каменем","эмаль","ажур","филигрань","массивные","нежные","круглые",
        "blender","блендер","блендера","blend","stl","стл","rhino","рино","3dm"
    })
    _QUERY_VOCAB_CACHE=sorted(words)
    return _QUERY_VOCAB_CACHE


def normalize_query_language(text: str) -> str:
    """Исправляет только очевидные небольшие опечатки для ПОИСКОВОГО разбора.
    Исходная реплика в чате не меняется. Склонения сводятся мягко через простые русские основы.
    """
    t=norm(text)
    vocab=_query_vocab()
    out=[]
    for tok in re.findall(r"[a-zа-я0-9]+|[^a-zа-я0-9]+",t):
        if not re.fullmatch(r"[a-zа-я0-9]+",tok) or len(tok)<5 or tok.isdigit():
            out.append(tok); continue
        # Если слово уже понятно по общей основе, не ломаем его.
        stem=_simple_ru_stem(tok)
        stem_matches=[v for v in vocab if _simple_ru_stem(v)==stem]
        if stem_matches:
            out.append(min(stem_matches,key=lambda v:abs(len(v)-len(tok))))
            continue
        best=None; best_score=0.0; best_dist=99
        for v in vocab:
            # Опечатка не должна менять смысл обычного слова. Требуем хотя бы ту же первую букву:
            # это сохраняет «падвески» -> «подвески», но не превращает «только» в «кольцо».
            if not v or v[0] != tok[0]:
                continue
            if abs(len(v)-len(tok))>2:
                continue
            limit=2 if max(len(v),len(tok))>=6 else 1
            dist=_levenshtein_limited(tok,v,limit)
            score=SequenceMatcher(None,tok,v).ratio()
            if dist < best_dist or (dist==best_dist and score>best_score):
                best,best_score,best_dist=v,score,dist
        threshold=0.80 if len(tok)>=7 else 0.84
        acceptable = best is not None and (best_dist <= (2 if len(tok)>=6 else 1) or best_score>=threshold)
        out.append(best if acceptable else tok)
    return "".join(out)


def fuzzy_phrase_in_text(phrase: str, text: str) -> bool:
    """Мягкое совпадение для тегов/семантики: понимает склонение и одну небольшую опечатку."""
    phrase=norm(phrase); text=norm(text)
    if not phrase or not text:
        return False
    # Most indexed tags are literal matches. Tokenizing an entire Qwen card before
    # this cheap check dominated new-query latency on five-thousand-project bases.
    if phrase in text:
        return True
    p=[x for x in re.findall(r"[a-zа-я0-9]+",phrase) if len(x)>=3]
    if not p:
        return False
    w=[x for x in re.findall(r"[a-zа-я0-9]+",text) if len(x)>=3]
    if len(p)==1:
        return any(_word_close(p[0],x) for x in w)
    for i in range(0,max(0,len(w)-len(p)+1)):
        if all(_word_close(a,b) for a,b in zip(p,w[i:i+len(p)])):
            return True
    return False


def _known_alias_value(key: str, raw: str) -> str:
    """Возвращает канонический тег только если raw действительно похож на известный alias."""
    v=norm(raw)
    table=ALIASES.get(key,{}) or {}
    if v in table:
        return table[v]
    for a,c in table.items():
        if fuzzy_phrase_in_text(v,a) and fuzzy_phrase_in_text(a,v):
            return c
    return ""

def canon(key: str, value: str) -> str:
    return _canon_cached(str(key),norm(value))


@lru_cache(maxsize=65536)
def _canon_cached(key: str, v: str) -> str:
    if v in UNKNOWN_WORDS:
        return ""
    table = ALIASES.get(key, {})
    if v in table:
        return table[v]
    # мягкий поиск алиаса внутри многословного ответа модели
    for a, c in sorted(table.items(), key=lambda kv: len(kv[0]), reverse=True):
        if len(a) >= 4 and a in v:
            return c
    # 0.42: склонения и небольшая опечатка в одном слове/короткой фразе.
    # Это особенно важно для ручных тегов и запросов вроде «куллны», «падвески».
    if table and len(v) >= 4:
        candidates=[]
        for a,c in table.items():
            if len(a)<4: continue
            if fuzzy_phrase_in_text(v,a) and fuzzy_phrase_in_text(a,v):
                candidates.append((len(a),c))
        if candidates:
            candidates.sort(reverse=True)
            return candidates[0][1]
    return v


def _vision_values(v: dict, key: str) -> list[str]:
    result=[]
    def add(x, alias_key=None):
        if isinstance(x,list):
            for z in x: add(z,alias_key)
            return
        z=canon(alias_key or key,x)
        if z and z not in result: result.append(z)
    if key == "type":
        _it_cross = canon("type", v.get("item_type"))
        _mot_cross = [canon("motif", x) for x in (v.get("motifs") or [])]
        _rel_cross = [norm(x) for x in (v.get("religious_symbols") or [])]
        if _it_cross == "подвеска" and ("крест" in _mot_cross or any("крест" in x for x in _rel_cross)):
            add("крест", "type")
        else:
            add(v.get("item_type"), "type")
    elif key == "audience": add(v.get("audience"),"audience")
    elif key == "subtype": add(v.get("item_subtypes") or v.get("subtype"),"subtype")
    elif key == "purpose": add(v.get("purposes") or v.get("purpose"),"purpose")
    elif key == "image_role": add(v.get("image_roles") or v.get("image_role"),"image_role")
    elif key == "material": add(v.get("materials") or v.get("material"),"material")
    elif key == "metal": add(v.get("metal_colors") or v.get("metal_color"),"metal")
    elif key == "metal_mode":
        add(v.get("metal_mode"),"metal_mode")
        if not result:
            colors=[]
            for raw in (v.get("metal_colors") or []):
                c=canon("metal",raw)
                if c and c not in colors: colors.append(c)
            mixed=norm(v.get("mixed_metal"))
            if "комб" in mixed or mixed in {"да","yes","true","mixed"} or "комбинированный" in colors or len([x for x in colors if x!="комбинированный"])>=2:
                add("комбинированное","metal_mode")
            elif len([x for x in colors if x!="комбинированный"])==1:
                add("одноцветное","metal_mode")
    elif key == "insert_color": add(v.get("insert_colors") or v.get("main_colors"),"stone_color")
    elif key == "stones": add(v.get("stone_presence"),"stones")
    elif key == "stone_count": add(v.get("stone_count"),"stone_count")
    elif key == "center_stone": add(v.get("center_stone"),"center_stone")
    elif key == "stone_type":
        if canon("stones",v.get("stone_presence"))=="нет": add("нет","stone_type")
        else: add(v.get("stone_types") or v.get("stone_type"))
    elif key == "stone_color":
        if canon("stones",v.get("stone_presence"))=="нет": add("нет","stone_color")
        else: add(v.get("stone_colors") or v.get("stone_color"),"stone_color")
    elif key == "stone_shape":
        if canon("stones",v.get("stone_presence"))=="нет": add("нет","stone_shape")
        else: add(v.get("stone_shapes") or v.get("stone_shape"),"stone_shape")
    elif key == "stone_size":
        if canon("stones",v.get("stone_presence"))=="нет": add("нет","stone_size")
        else: add(v.get("stone_sizes") or v.get("stone_size"),"stone_size")
    elif key == "shape": add(v.get("overall_shapes") or v.get("overall_shape"),"shape")
    elif key == "stone_position": add(v.get("stone_positions") or v.get("stone_position"))
    elif key == "stone_rows": add(v.get("stone_rows"))
    elif key == "mass": add(v.get("visual_mass"),"mass")
    elif key == "width": add(v.get("band_width"),"width")
    elif key == "motif": add(v.get("motifs")); add(v.get("motif_classes"))
    elif key == "ornament": add(v.get("ornament_tags"))
    elif key == "style": add(v.get("style_tags")); add(v.get("semantic_traits"))
    elif key == "tag":
        # generic manual hot-words are intentionally NOT filled from VLM here
        pass
    elif key == "enamel": add(v.get("enamel"),"enamel")
    elif key == "openwork": add(v.get("openwork"),"openwork")
    elif key == "zodiac": add(v.get("zodiac_signs"))
    elif key == "text": add(v.get("visible_text")); add(v.get("text_types"))
    elif key == "composition": add(v.get("composition"),"composition")
    return result


