# 0.95.5: известные имена клиентов и брендов в канонической форме.
_CLIENT_NAME_ALIASES = {
    "ванклиф": "ван клиф", "ванклив": "ван клиф", "ванклев": "ван клиф",
    "ванклифф": "ван клиф", "vancleef": "ван клиф", "vancleefarpels": "ван клиф",
    "картье": "картье", "cartier": "картье",
    "булгари": "булгари", "bvlgari": "булгари", "bulgari": "булгари",
    "тиффани": "тиффани", "tiffany": "тиффани",
    "шопард": "шопард", "chopard": "шопард",
    "ролекс": "ролекс", "rolex": "ролекс",
    "патек": "патек", "patek": "патек",
}


def _normalize_client_name(raw: str) -> str:
    """0.95.5: приводит имя клиента к канону, прощая слитное написание и опечатки."""
    t = norm(raw).strip()
    if not t:
        return ""
    if t in _CLIENT_NAME_ALIASES:
        return _CLIENT_NAME_ALIASES[t]
    joined = t.replace(" ", "")
    if joined in _CLIENT_NAME_ALIASES:
        return _CLIENT_NAME_ALIASES[joined]
    for alias, canonical in _CLIENT_NAME_ALIASES.items():
        if _word_close(joined, alias) or _word_close(t, alias):
            return canonical
        if fuzzy_phrase_in_text(t, alias) or fuzzy_phrase_in_text(alias, t):
            return canonical
    return t


def _expand_catalog_query_terms(terms: list) -> list:
    """0.95.5: добавляет канонические варианты имён к терминам каталог-поиска."""
    out = []
    seen = set()
    for term in terms or []:
        nt = norm(term)
        if nt and nt not in seen:
            seen.add(nt)
            out.append(nt)
        canonical = _normalize_client_name(term)
        if not canonical:
            continue
        nc = norm(canonical)
        if nc and nc != nt:
            if nc not in seen:
                seen.add(nc)
                out.append(nc)
            for part in nc.split():
                if part and part not in seen:
                    seen.add(part)
                    out.append(part)
    return out



def local_catalog_query_terms(text: str) -> list[str]:
    """Extracts likely names/order labels while ignoring jewelry and conversational words."""
    terms = []
    for token in re.findall(r"[a-zа-я0-9]+", norm(text)):
        if len(token) < 3 or token.isdigit() or token in _LOCAL_CATALOG_STOP_WORDS:
            continue
        if any(token.startswith(stem) for stem in _LOCAL_CATALOG_GENERIC_STEMS):
            continue
        if token not in terms:
            terms.append(token)
    return terms[:5]


_STRUCTURAL_QUICK_KEYS = {
    "type", "audience", "subtype", "purpose", "material", "metal", "metal_mode",
    "stones", "stone_count", "center_stone", "stone_type", "stone_color",
    "stone_shape", "stone_size", "shape", "mass", "width", "openwork", "enamel",
    "composition", "image_role", "source_format", "insert_color",
    "stone_position", "stone_rows",
}


def _quick_plan_has_structural(quick) -> bool:
    """0.93.3: локальный разбор уже понял ювелирные условия запроса."""
    if not isinstance(quick, dict):
        return False
    for group in ("must", "must_not"):
        for cond in quick.get(group) or []:
            parsed = parse_condition(str(cond))
            if parsed and parsed[0] in _STRUCTURAL_QUICK_KEYS:
                return True
    return False


def local_catalog_lookup_requested(text: str, current_state: dict | None = None) -> bool:
    """Recognizes questions about a real indexed person, order, project or folder."""
    original = str(text or "")
    normalized = norm(original)
    # Названия технических форматов — фильтр базы, а не имя клиента/заказа.
    if source_format_conditions(normalized) != ([],[]):
        return False
    # 0.90.7: "покажи все X" / "покажи всех X" — это уточнение текущей
    # выборки, а не попытка найти клиента с именем "все славянские".
    if re.match(r"^(покажи|покажите|найди|найдите)\s+(?:всё|все|всех)\b", normalized):
        return False
    # "без <чего-угодно>" — это фильтр (исключение), а не имя заказа/клиента.
    if re.search(r"(?:^|\s)без(?:\s|$)", normalized):
        return False
    if not local_catalog_query_terms(original):
        return False
    if any(re.search(pattern, normalized) for pattern in (
        r"\b(?:наш[её]л|нашла|нашли|найд[иие]|искал|искала|ищу|отыщи|покажи|покажите|показывай)\b",
        r"\b(?:где|кому|чей|чья|чьи|у\s+кого)\b",
        r"\b(?:заказ|заказы|заказал|заказывал|заказано|заказан|клиент|проект|папк|архив|локальн)",
        r"\b(?:дела(?:л|ла|ли|ем|ет|ют)|сдела(?:л|ла|ли|но|ны|ть)|"
        r"работа(?:л|ла|ли|ем|ет|ют)|изготов(?:ил|ила|или|лено))\b",
    )):
        return True
    proper_names = re.findall(r"(?<![a-zа-яёА-ЯЁ])[А-ЯЁ][а-яё]{2,}", original)
    return bool(proper_names and ("?" in original or re.match(r"^\s*а\s+", normalized)))


_FILENAME_FRAGMENT_PATTERNS = (
    # «покажи все файлы, в имени которых есть буквы ED»
    r"\b(?:имени|именах|названии|названиях)\b.{0,80}?"
    r"\b(?:есть|содерж\w*|встреча\w*)\b\s*"
    r"(?:букв\w*|символ\w*|сочетани\w*|строк\w*|текст\w*)?\s*"
    r"[«\"']?([a-zа-яё0-9][a-zа-яё0-9_.-]{0,63})",
    # «покажи файлы с JUR в имени»
    r"\bфайл\w*\b.{0,24}?\b(?:с|со)\b\s*"
    r"[«\"']?([a-zа-яё0-9][a-zа-яё0-9_.-]{0,63})[»\"']?\s+"
    r"(?:в\s+)?\b(?:имени|именах|названии|названиях)\b",
    # «найди ED в названиях файлов»
    r"\b(?:найд\w*|покаж\w*|ищ\w*)\b.{0,24}?"
    r"[«\"']?([a-zа-яё0-9][a-zа-яё0-9_.-]{0,63})[»\"']?\s+"
    r"(?:в\s+)?\b(?:имени|именах|названии|названиях)\b",
)


def filename_fragment_query(text: str) -> str:
    """Extracts a literal filename fragment, preserving short codes like ED or JUR."""
    original = str(text or "").strip()
    if not original or not re.search(
            r"\b(?:имени|именах|названии|названиях)\b", original, re.IGNORECASE):
        return ""
    grammar = {
        "буква", "буквы", "букв", "символ", "символы", "строка", "строки",
        "текст", "название", "названия", "имя", "имени", "файл", "файлы",
    }
    for pattern in _FILENAME_FRAGMENT_PATTERNS:
        match = re.search(pattern, original, re.IGNORECASE | re.DOTALL)
        if not match:
            continue
        fragment = match.group(1).strip(" \t\r\n.,:;!?…«»\"'")
        if fragment and fragment.casefold() not in grammar:
            return fragment
    return ""


def project_filename_candidates(project: dict) -> list[str]:
    """Returns actual indexed basenames without treating parent folders as filenames."""
    names = []
    title = str(project.get("title") or "").strip()
    folder = str(project.get("folder") or "").strip()
    if title:
        names.append(title)
    if folder and Path(folder).suffix.lower() in INDEXABLE_EXTS:
        names.append(Path(folder).name)
    for field in ("image_paths", "representatives"):
        paths = project.get(field) or []
        if isinstance(paths, str):
            paths = [paths]
        for raw in paths:
            value = str(raw or "").strip()
            if value:
                names.append(Path(value).name)
    result = []
    seen = set()
    for name in names:
        key = name.casefold()
        if key and key not in seen:
            seen.add(key)
            result.append(name)
    return result


def filename_fragment_matches(projects: list[dict], fragment: str) -> list[dict]:
    """Case-insensitive literal substring matching against indexed file basenames."""
    needle = str(fragment or "").strip().casefold()
    if not needle:
        return []
    matches = []
    for project in projects or []:
        matched_names = [name for name in project_filename_candidates(project)
                         if needle in name.casefold()]
        if matched_names:
            item = dict(project)
            item["_filename_matches"] = matched_names
            matches.append(item)
    return matches


def jewelry_gift_intent(text: str) -> bool:
    normalized = norm(text)
    people = any(re.search(pattern, normalized) for pattern in (
        r"\bдевушк", r"\bженщин", r"\bподруг", r"\bневест", r"\bжен(?:е|ы|у)\b",
        r"\bмам(?:е|у|ы)\b", r"\bсестр", r"\bдочер", r"\bпарн", r"\bмужчин",
        r"\bмуж(?:у|а)\b", r"\bпап(?:е|у|ы)\b", r"\bотц", r"\bбрат", r"\bсын",
        r"\bреб[её]н", r"\bдевоч", r"\bмальчик",
    ))
    gift = any(x in normalized for x in ("подар", "подобрать", "подбери", "подойдет", "подойдёт",
                                         "посоветуй", "присмотр", "вариант", "что-то для", "что нибудь для"))
    return bool(people and (gift or "для " in normalized or "есть" in normalized))


_SOURCE_FORMAT_PATTERNS = (
    ("image",r"(?<![a-zа-я0-9])(?:jpg|jpeg|png|webp)(?![a-zа-я0-9])"),
    ("blender",r"(?<![a-zа-я0-9])(?:blender|blend|блендер\w*)(?![a-zа-я0-9])"),
    ("stl",r"(?<![a-zа-я0-9])(?:stl|стл)(?![a-zа-я0-9])"),
    ("rhino",r"(?<![a-zа-я0-9])(?:rhino|рино|3dm)(?![a-zа-я0-9])"),
)


def source_format_conditions(text: str) -> tuple[list[str],list[str]]:
    """Understands exact file-format requests and negation without asking Qwen."""
    t=norm(text)
    positive=[]; negative=[]
    negative_before=re.compile(
        r"(?:не\s+показывай|не\s+показывать|не|без|кроме|убери|убрать|исключи|исключить)"
        r"(?:\s+[a-zа-я0-9]+){0,3}\s*$")
    for value,pattern in _SOURCE_FORMAT_PATTERNS:
        for match in re.finditer(pattern,t):
            before=t[max(0,match.start()-55):match.start()]
            target=negative if negative_before.search(before) else positive
            if value not in target: target.append(value)
    negative_set=set(negative)
    positive=[value for value in positive if value not in negative_set]
    return positive,negative


_METAL_COLORS_LOCAL = {"белый", "желтый", "красный", "черный", "комбинированный"}
_STONE_COLORS_LOCAL = {"синий", "зеленый", "голубой", "фиолетовый", "сине-фиолетовый",
                       "розовый", "прозрачный", "оранжевый", "белый", "черный", "желтый", "красный"}
_COLOR_ALIASES_LOCAL = {
    "бел": ("белый",),
    "желт": ("желтый",), "жёлт": ("желтый",),
    "красн": ("красный",), "розов": ("красный",),
    "черн": ("черный",), "чёрн": ("черный",),
    "син": ("синий",), "голуб": ("голубой",),
    "зелен": ("зеленый",), "зелён": ("зеленый",),
    "фиолет": ("фиолетовый",), "сине-фиолет": ("сине-фиолетовый",),
    "прозрач": ("прозрачный",), "оранж": ("оранжевый",),
}

def _smart_refine_plan(text, current_state):
    """0.90.6: разбор уточнений, которые quick_plan не поймал."""
    t = norm(text)
    if not t:
        return None
    st = current_state or {}
    has_ctx = bool(st.get("must") or st.get("must_not") or st.get("semantic")
                   or st.get("exclude_groups"))
    must = []; must_not = []; semantic = []

    m_leave = re.match(r"^(?:оставь|оставить|покажи|показать|мне|нужны|нужно)\s+(?:только\s+)?(?:с\s+)?(.+)$", t)
    if has_ctx and m_leave and _REFINE_VERBS_RX.match(t):
        body = m_leave.group(1).strip()
        body = re.sub(r"^(?:с\s+|с\s+одним\s+|с\s+одной\s+|в\s+)", "", body)
        body = re.sub(r"\s+цветом$|\s+цвета$", "", body)
        _add_colors_and_tags(body, must, must_not, semantic, st)
        if must or must_not or semantic:
            return {"action":"search","scope":"current",
                    "must":[f"{k}:{v}" for k,v in must],
                    "must_not":[f"{k}:{v}" for k,v in must_not],
                    "exclude_group":[],"prefer":[],"avoid":[],
                    "semantic":semantic,"semantic_not":[],
                    "remove_keys":[],"limit":0,"reply":"","time_filter":{}}

    m_exists = re.search(r"(?:^|\s)(?:есть(?:\s+что[\-\s]?то)?|у\s+тебя\s+есть)\s+(.+?)[\?\s]*$", t)
    if has_ctx and m_exists:
        body = m_exists.group(1).strip(" ?.")
        tags = []
        for tok in re.findall(r"[a-zа-я0-9]+", body):
            if len(tok) < 4 or tok.isdigit(): continue
            if any(tok.startswith(s) for s in ("эт","так","как","что","весь","всё","все","мне","тебе")):
                continue
            tags.append(tok)
        if tags:
            for tok in tags[:2]:
                must.append(("tag", tok))
            return {"action":"search","scope":"current",
                    "must":[f"{k}:{v}" for k,v in must],
                    "must_not":[],"exclude_group":[],"prefer":[],"avoid":[],
                    "semantic":[],"semantic_not":[],
                    "remove_keys":[],"limit":0,"reply":"","time_filter":{}}

    m_show_all = re.match(r"^(?:покажи|покажите|найди|найдите)\s+(?:всё|все|всех)\s+(.+)$", t)
    if has_ctx and m_show_all:
        body = m_show_all.group(1).strip()
        if len(body.split()) <= 3:
            _add_colors_and_tags(body, must, must_not, semantic, st)
            if must or semantic:
                return {"action":"search","scope":"current",
                        "must":[f"{k}:{v}" for k,v in must],
                        "must_not":[],"exclude_group":[],"prefer":[],"avoid":[],
                        "semantic":semantic,"semantic_not":[],
                        "remove_keys":[],"limit":0,"reply":"","time_filter":{}}

    return None


def _add_colors_and_tags(body, must, must_not, semantic, st):
    if not body: return
    has_stone_ctx = bool((st.get("must") or {}).get("stone_type")
                         or (st.get("must") or {}).get("stone_color")
                         or (st.get("must") or {}).get("stones"))
    has_metal_ctx = bool((st.get("must") or {}).get("metal")
                         or (st.get("must") or {}).get("metal_mode"))
    stone_word = any(w in body for w in ("камень","камн","встав","самоцвет"))
    metal_word = any(w in body for w in ("металл","золот","серебр","платин"))
    for stem, values in _COLOR_ALIASES_LOCAL.items():
        if stem in body:
            col = values[0]
            if stone_word and col in _STONE_COLORS_LOCAL:
                must.append(("stone_color", col))
            elif metal_word and col in _METAL_COLORS_LOCAL:
                must.append(("metal", col))
            elif col in _METAL_COLORS_LOCAL and has_metal_ctx:
                must.append(("metal", col))
            elif col in _STONE_COLORS_LOCAL and has_stone_ctx:
                must.append(("stone_color", col))
            elif col in _METAL_COLORS_LOCAL:
                must.append(("metal", col))
            elif col in _STONE_COLORS_LOCAL:
                must.append(("stone_color", col))
            break
    for key in ("ornament","style","motif","zodiac"):
        table = ALIASES.get(key, {}) or {}
        for alias, cv in table.items():
            if len(alias) >= 4 and alias in body:
                must.append((key, cv))
                break
    m_no = re.search(r"без\s+(?:с\s+|одного\s+|одной\s+)?([a-zа-я0-9]+)", body)
    if m_no:
        tag = m_no.group(1)
        if len(tag) >= 4:
            must_not.append(("tag", tag))
    known = set()
    for k in ("ornament","style","motif","zodiac"):
        for alias in (ALIASES.get(k, {}) or {}): known.add(alias)
    known.update(_COLOR_ALIASES_LOCAL.keys())
    for tok in re.findall(r"[a-zа-я0-9]+", body):
        if len(tok) < 5 or tok.isdigit(): continue
        if any(tok.startswith(k) for k in known): continue
        if any(tok.startswith(s) for s in ("цвет","что","как","это","такой","весь","все")):
            continue
        if not any(t[1] == tok for t in must):
            must.append(("tag", tok))
            break


def quick_plan(text: str, current_state: dict | None = None) -> dict | None:
    """Мгновенный разбор частых команд. Сложный язык остаётся Qwen, но типовые поиски
    не должны ждать модель и ощущаются почти как Everything после индексации."""
    t=normalize_query_language(text).strip(" .!?…")
    if not t: return None
    selected_time=project_time_filter(text)
    def plan(action="search",scope="current",must=None,must_not=None,exclude_group=None,prefer=None,avoid=None,semantic=None,semantic_not=None,remove=None,reply=""):
        return sanitize_plan({"action":action,"scope":scope,"must":must or [],"must_not":must_not or [],"exclude_group":exclude_group or [],
                              "prefer":prefer or [],"avoid":avoid or [],"semantic":semantic or [],"semantic_not":semantic_not or [],
                              "remove_keys":remove or [],"limit":0,"reply":reply,
                              "time_filter":selected_time if action=="search" else {}})

    if t in {"назад","верни прошлый поиск","верни предыдущий поиск","верни прошлую выборку","как было"}: return plan("undo",reply="Возвращаю предыдущую выборку.")
    if t in {"вперед","вперёд","верни вперед","верни вперёд"}: return plan("redo",reply="Возвращаю следующую выборку.")
    if t in {"новый поиск","сбрось поиск","сброс","очисти поиск","начать заново","начни заново"}: return plan("reset","new",reply="Начинаем заново.")
    if t in {"покажи похожие","покажи кандидатов","покажи сомнительные","похожие"}: return plan("show_candidates",reply="Показываю возможные совпадения.")
    if t in {"покажи еще","покажи ещё","еще","ещё","еще есть","ещё есть","а еще есть","а ещё есть","есть еще","есть ещё"}: return plan("show_more",reply="Показываю ещё.")
    if t in {"покажи все","покажи всю базу","покажи все что есть","покажи всё что есть","вся база","все украшения","всё украшения"}: return plan("show_all","new",reply="Показываю всю базу.")
    if t in {"что есть","а что есть","что вообще есть","а что вообще есть","какие украшения есть","что у тебя есть","что в базе","а что тут есть","что тут есть"}: return plan("summary","current",reply="Сейчас кратко расскажу, что есть.")

    # Обычный человеческий разговор не должен случайно превращаться в поисковый фильтр.
    if t in {"привет","здравствуй","здравствуйте","ты тут","ты здесь","ты на месте","как дела","спасибо","спасибо тебе","ок","понял","поняла","хорошо"}:
        replies={
            "ты тут":"Да 🙂",
            "ты здесь":"Да 🙂",
            "ты на месте":"Да 🙂",
            "спасибо":"Пожалуйста 🙂",
            "спасибо тебе":"Пожалуйста 🙂",
        }
        return plan("chat",reply=replies.get(t,"Я здесь 🙂"))
    if any(x in t for x in ("ты общаться умеешь","ты умеешь общаться","ты глупый","тупой","туповат","скучно")):
        return plan("chat",reply="Умею 🙂 Пиши как обычно.")

    # Явно разговорные темы отдаём локальной Chat-модели, а не превращаем в случайный
    # semantic-поиск по ювелирной базе. Актуальные данные она честно не выдумывает.
    casual_markers=(
        "погод","температур на улице","как настроение","как ты","что думаешь","как считаешь",
        "расскажи анекдот","анекдот","пошути","шутк","фильм","музык","книг","новост","курс валют",
        "который час","сколько времени","любишь","тебе нравится","поговорим","поболтаем"
    )
    if any(x in t for x in casual_markers) and not jewelry_gift_intent(t):
        return None

    # Новая тема vs уточнение.
    refine_prefix=bool(re.match(r"^(только|оставь|оставить|убери|убрать|исключи|не показывай|не хочу|не надо|не нужно|не нужны|не нужен|без|а теперь только|из них только)\b",t))
    new_prefix=bool(re.match(r"^(тогда просто|теперь просто|ладно|ну ладно|давай теперь|покажи|найди|хочу|нужны|нужно)\b",t))
    negative_prefix=bool(re.match(r"^(убери|убрать|исключи|не показывай|не хочу|не надо|не нужно|не нужны|не нужен)\b",t))

    # Формат файла — точный локальный признак. Эти команды всегда проверяют реальные
    # расширения путей, не Qwen-теги и не слова из названий проектов.
    source_positive,source_negative=source_format_conditions(t)
    if source_positive or source_negative:
        current_format_scope=bool(re.match(
            r"^(оставь|оставить|из них|среди них|убери|убрать|исключи|исключить|не показывай|без)\b",t))
        scope="current" if current_format_scope else "new"
        return plan("search",scope,
                    must=[f"source_format:{value}" for value in source_positive],
                    must_not=[f"source_format:{value}" for value in source_negative],
                    reply="Показываю проекты нужного формата.")

    # Сравнительные предпочтения — не фильтр.
    if ("больше" in t or "лучше" in t or "предпочт" in t) and any(x in t for x in ("бел","красн","желт","жёлт")):
        prefer=[]; avoid=[]
        if "бел" in t: prefer.append("metal:белый")
        # конструкция «белого больше чем красного» — красный лишь понижаем в рейтинге
        if "красн" in t: avoid.append("metal:красный")
        if ("желт" in t or "жёлт" in t) and not prefer: prefer.append("metal:желтый")
        return plan("search","current",prefer=prefer,avoid=avoid,reply="Понял это как предпочтение, а не жёсткий фильтр.")

    must=[]; must_not=[]; prefer=[]; avoid=[]; semantic=[]; semantic_not=[]
    # 0.90.11: "не X" внутри фразы — исключение, а не требование.
    # Пример: "только белые не комбинированные" -> must_not[комбинированное].
    # Смотрим на "не" (с любым словом до 40 символов вперёд), исключая случаи
    # "не только", "не более", "не меньше", "не хуже" и т.п.
    _negation_inside = bool(re.search(
        r"(?:^|[\s,;])(?:не|без)\s+(?!только\b|более\b|менее\b|больше\b|"
        r"меньше\b|хуже\b|лучше\b|позже\b|раньше\b|долго\b|давно\b|"
        r"очень\b|очень\b|совсем\b|совсем\b|сильно\b|слабо\b|могу\b|"
        r"хочу\b|надо\b|нужно\b)\S",
        t))
    # Тип изделия: здесь нужна высокая точность. Старый общий fuzzy-механизм иногда принимал
    # «одноцветные» за «кольца». Поэтому сначала ищем понятные основы, а опечатку разрешаем
    # только внутри одного похожего слова, а не между произвольными фразами.
    type_hit=None
    type_patterns=[
        (("перст","печат","signet"),"перстень"),
        (("серьг","серег","сереж","пусет","гвоздик","earring"),"серьги"),
        (("подвес","кулон","медальон","pendant"),"подвеска"),
        (("крест","cross"),"крест"),(("брасл","bracelet"),"браслет"),
        (("брош","brooch"),"брошь"),(("брел","keychain"),"брелок"),
        (("значок","badge"),"значок"),(("застеж","застёж","clasp"),"застежка"),
        (("комплект","набор","set"),"комплект"),
        (("кольц","колец","колеч","ring"),"кольцо"),
    ]
    for stems,val in type_patterns:
        if any(st in t for st in stems):
            type_hit=val; break
    if not type_hit:
        words=[w for w in re.findall(r"[a-zа-я0-9]+",t) if len(w)>=4]
        typo_targets=[("кольцо","кольцо"),("перстень","перстень"),("серьги","серьги"),("подвеска","подвеска"),("кулон","подвеска"),
                      ("крест","крест"),("браслет","браслет"),("брошь","брошь"),("брелок","брелок"),("значок","значок")]
        for w in words:
            for sample,val in typo_targets:
                lim=1 if max(len(w),len(sample))<7 else 2
                if abs(len(w)-len(sample))<=2 and _levenshtein_limited(w,sample,lim)<=lim:
                    type_hit=val; break
            if type_hit: break
    # Самостоятельные «обручалки/помолвочные/венчальные» считаем кольцами.
    # Это одновременно улучшает понимание смысла и помогает отличать новый глобальный поиск от уточнения.
    if not type_hit and any(st in t for st in ("обручал","помолв","венчан","свадебн")):
        type_hit="кольцо"
    if type_hit:
        target=f"type:{type_hit}"
        (must_not if negative_prefix else must).append(target)
    if ("обручал" in t or "свадебн" in t) and not negative_prefix: must.append("subtype:обручальное")
    if "помолв" in t and not negative_prefix: must.append("subtype:помолвочное")
    # 0.98.3: пользовательское определение: венчальные / на предложение /
    # «руки и сердца» = классическое женское кольцо с одним центральным камнем.
    if ("венчан" in t or "на предложение" in t or "предложение руки" in t
            or "руки и сердца" in t or "руку и сердце" in t) and not negative_prefix:
        must += ["subtype:помолвочное", "center_stone:есть"]
        if not any(k.startswith("audience:") for k in must):
            must.append("audience:женское")

    # Audience includes natural gift wording rather than only formal catalog labels.
    audience_hit = ""
    if "детск" in t or "для детей" in t or "ребен" in t or "ребён" in t or any(x in t for x in ("для девочки", "для мальчика")):
        audience_hit = "детское"
    elif ("женск" in t or "для женщин" in t or "девушк" in t or "подруг" in t
          or "невест" in t or "дочер" in t or re.search(r"\b(?:жен[еыу]|мам[еуы]|сестр[еыу])\b", t)):
        audience_hit = "женское"
    elif ("мужск" in t or "для мужчин" in t or "для мужчины" in t or "парн" in t
          or re.search(r"\b(?:муж[уа]|пап[еуы]|отц[ау]|брат[ау]|сын[ау])\b", t)):
        audience_hit = "мужское"
    if audience_hit:
        (must_not if negative_prefix else must).append(f"audience:{audience_hit}")

    # material + metal. Сначала определяем материал, затем один или несколько допустимых цветов.
    if "серебр" in t:
        (must_not if negative_prefix else must).append("material:серебро")
    elif "платин" in t:
        (must_not if negative_prefix else must).append("material:платина")
    elif "золот" in t:
        (must_not if negative_prefix else must).append("material:золото")
        colors=[]
        if "бел" in t: colors.append("белый")
        if "красн" in t or "розов" in t: colors.append("красный")
        if "желт" in t or "жёлт" in t: colors.append("желтый")
        for c in colors:
            (must_not if negative_prefix else must).append(f"metal:{c}")
    elif any(x in t for x in ("белый металл","белого металла")):
        (must_not if negative_prefix else must).append("metal:белый")
    elif "красный металл" in t or "розовый металл" in t:
        (must_not if negative_prefix else must).append("metal:красный")
    elif "желтый металл" in t or "жёлтый металл" in t:
        (must_not if negative_prefix else must).append("metal:желтый")

    # Разговорные цветовые прилагательные перед типом изделия: «белые серьги», «красные кольца».
    # Если рядом явно говорится о камне/вставке/эмали, цвет относится не к металлу.
    color_context_is_stone = any(x in t for x in ("камн","кам ","встав","эмал"))
    # 0.46: короткое уточнение после готовой выборки: «кулоны» -> «оставь белые».
    # Здесь слово «белые» относится к цвету металла, даже если пользователь не повторил слово «кулоны».
    # Если он пишет «белые камни/вставки», цвет по-прежнему относится к камню.
    has_current_subject = bool((current_state or {}).get("must") or (current_state or {}).get("semantic"))
    short_feature_only = bool(has_current_subject and not type_hit and len(t.split()) <= 4)
    color_refine = bool(has_current_subject and (refine_prefix or short_feature_only))
    if (type_hit or color_refine) and not color_context_is_stone and not any(k.startswith("metal:") for k in must+must_not):
        if re.search(r"\bбел(ый|ая|ое|ые|ого|ую|ых|ыми|ым)\b",t): (must_not if negative_prefix else must).append("metal:белый")
        elif re.search(r"\bкрасн(ый|ая|ое|ые|ого|ую|ых|ыми|ым)\b",t) or re.search(r"\bрозов(ый|ая|ое|ые|ого|ую|ых|ыми|ым)\b",t): (must_not if negative_prefix else must).append("metal:красный")
        elif re.search(r"\bжелт(ый|ая|ое|ые|ого|ую|ых|ыми|ым)\b",t) or re.search(r"\bжёлт(ый|ая|ое|ые|ого|ую|ых|ыми|ым)\b",t): (must_not if negative_prefix else must).append("metal:желтый")

    # Одноцветность / двухцветность — отдельный физический признак, а не догадка по слову «золото».
    if any(x in t for x in ("одноцвет", "одного цвета", "один цвет")):
        _neg_mode_oc = negative_prefix or bool(re.search(r"(?:^|[\s,;])(?:не|без)\s+(?:одноцвет\w*|одноцветн\w*)", t))
        (must_not if _neg_mode_oc else must).append("metal_mode:одноцветное")
    elif any(x in t for x in ("двухцвет", "два цвета", "комбинированн", "комбинированый", "разноцветный металл")):
        _neg_mode_cb = negative_prefix or _negation_inside
        (must_not if _neg_mode_cb else must).append("metal_mode:комбинированное")

    # stones / inserts / gemstones
    if "без кам" in t or "без встав" in t:
        must.append("stones:нет")
    elif (("одн" in t or "1 " in t) and "кам" in t) or ("одиночн" in t and "кам" in t):
        must += ["stones:есть","stone_count:один"]
    elif (("дв" in t or "2 " in t) and "кам" in t):
        must += ["stones:есть","stone_count:два"]
    elif "с кам" in t or "с встав" in t:
        _neg_st = negative_prefix or bool(re.search(r"(?:^|[\s,;])(?:не|без)\s+(?:с\s+)?(?:кам\w*|встав\w*)", t))
        (must_not if _neg_st else must).append("stones:есть")
    if "белой встав" in t or "белая встав" in t: must.append("insert_color:белый")
    if "центральн" in t and "кам" in t: must.append("center_stone:есть")
    if "крупн" in t and "кам" in t: must.append("stone_size:крупный")
    if "мелк" in t and "кам" in t: must.append("stone_size:мелкий")
    if "овал" in t and "кам" in t: must.append("stone_shape:овал")
    if "круг" in t and "кам" in t: must.append("stone_shape:круг")
    if "груш" in t and "кам" in t: must.append("stone_shape:груша")
    if "сердц" in t and "кам" in t: must.append("stone_shape:сердце")

    # Общая форма изделия. Важное отличие: "круглый камень" остаётся stone_shape,
    # а "круглые кулоны / оставь только круглые" = shape.
    if "кам" not in t:
        if "кругл" in t or re.search(r"\bкруг\b",t): (must_not if negative_prefix else must).append("shape:круг")
        elif "оваль" in t or "овальн" in t: (must_not if negative_prefix else must).append("shape:овал")
        elif "квадрат" in t: (must_not if negative_prefix else must).append("shape:квадрат")
        elif "прямоуголь" in t: (must_not if negative_prefix else must).append("shape:прямоугольник")

    gem_rules=[
        (("бриллиант","алмаз","diamond"),"бриллиант"), (("сапфир","sapphire"),"сапфир"),
        (("рубин","ruby"),"рубин"), (("изумруд","emerald"),"изумруд"), (("аметист","amethyst"),"аметист"),
        (("гранат",),"гранат"), (("топаз",),"топаз"), (("фианит",),"фианит"), (("жемчуг",),"жемчуг")
    ]
    # "покажи без рубина" / "без сапфира" / "не нужны рубины" — это ИСКЛЮЧЕНИЕ,
    # даже когда фраза не начинается с "убери"/"не показывай".
    gem_negated = negative_prefix or bool(re.search(
        r"(?:^|\s)без(?:\s+\S+){0,4}\s+(?:"
        r"рубин\w*|сапфир\w*|изумруд\w*|бриллиант\w*|алмаз\w*|"
        r"аметист\w*|гранат\w*|топаз\w*|фианит\w*|жемчуг\w*)", t))
    for words,g in gem_rules:
        if any(w in t for w in words):
            target=f"stone_type:{g}"
            (must_not if gem_negated else must).append(target)
            if not gem_negated and "stones:нет" not in must: must.append("stones:есть")
            break
    if "кам" in t or "встав" in t or any(g in t for g in ("сапфир","рубин","изумруд","бриллиант","алмаз","аметист","гранат","топаз","фианит","жемчуг")):
        color_hits=[]
        if "сине-фиолет" in t: color_hits.append("сине-фиолетовый")
        else:
            if "син" in t: color_hits.append("синий")
            if "голуб" in t: color_hits.append("голубой")
            if "фиолет" in t: color_hits.append("фиолетовый")
        if "красн" in t: color_hits.append("красный")
        if "зелен" in t or "зелён" in t: color_hits.append("зеленый")
        if "прозрач" in t or "бесцвет" in t: color_hits.append("прозрачный")
        if "черн" in t or "чёрн" in t: color_hits.append("черный")
        if "розов" in t: color_hits.append("розовый")
        for c in list(dict.fromkeys(color_hits)):
            (must_not if negative_prefix else must).append(f"stone_color:{c}")

    # Буквальные мотивы и знаки — это точные слоты, а не субъективный стиль.
    motif_rules=[
        (("корон",),"корона"), (("герб",),"герб"), (("орел","орёл","орл"),"орел"), (("лев","льв"),"лев"),
        (("волк","волч"),"волк"), (("котен","котён","кошка","кошк","кот ","котом"),"кот"), (("лис",),"лиса"), (("медвед",),"медведь"),
        (("тигр",),"тигр"), (("зме",),"змея"), (("дракон",),"дракон"), (("сова","совой"),"сова"),
        (("сердц",),"сердце"), (("гора","горы"),"горы"), (("ключ",),"ключ"), (("якор",),"якорь"), (("компас",),"компас"), (("отпечат",),"отпечаток пальца"),
        (("звезда давида",),"звезда давида")
    ]
    for words,m in motif_rules:
        if any(w in t for w in words):
            if m=="лев" and any(x in t for x in ("зодиак","знак зодиака","гороскоп")):
                continue
            (must_not if negative_prefix else must).append(f"motif:{m}")

    zodiac_names=("овен","телец","близнецы","рак","лев","дева","весы","скорпион","стрелец","козерог","водолей","рыбы")
    if "зодиак" in t:
        # Если знак не назван — оставляем это семантическим пожеланием, Qwen-планировщик при необходимости уточнит.
        pass
    zodiac_context=any(x in t for x in ("зодиак","знак зодиака","гороскоп"))
    for z in zodiac_names:
        if re.search(rf"\b{re.escape(z)}\b",t):
            if z=="лев" and not zodiac_context:
                continue
            (must_not if negative_prefix else must).append(f"zodiac:{z}")
            break

    # Тип исходного изображения: полезно для запросов «покажи именно фото, не рендеры».
    if "рендер" in t:
        (must_not if negative_prefix or "не рендер" in t else must).append("image_role:3d-рендер")
    if "фото" in t and "фотограф" not in t:
        (must_not if negative_prefix else must).append("image_role:фото изделия")

    # Явные физические/технические признаки. «Без ...» — это именно отсутствие/исключение,
    # а не положительное требование (раньше здесь были неприятные противоречия).
    if "без эмал" in t: must.append("enamel:нет")
    elif "эмал" in t:
        _neg_em = negative_prefix or bool(re.search(r"(?:^|[\s,;])(?:не|без)\s+эмал", t))
        (must_not if _neg_em else must).append("enamel:есть")
    if "без ажур" in t or "без филигран" in t: must.append("openwork:нет")
    elif "ажур" in t or "филигран" in t:
        _neg_op = negative_prefix or bool(re.search(r"(?:^|[\s,;])(?:не|без)\s+(?:ажур\w*|филигран\w*)", t))
        (must_not if _neg_op else must).append("openwork:есть")
    if "широк" in t: (must_not if negative_prefix else must).append("width:широкое")
    if "узк" in t: (must_not if negative_prefix else must).append("width:узкое")
    if "массив" in t:
        if "без массив" in t: must_not.append("mass:массивное")
        else:
            _neg_ms = negative_prefix or bool(re.search(r"(?:^|[\s,;])(?:не|без)\s+массивн\w*", t))
            (must_not if _neg_ms else must).append("mass:массивное")

    # subjective appearance = ranking, not exclusion.
    soft_map=[("нежн","нежное"),("воздуш","воздушное"),("легк","легкое"),("лёгк","легкое"),
              ("брутал","брутальное"),("минимал","минималистичное"),("лаконич","лаконичное"),
              ("соврем","современное"),("необыч","необычное"),("винтаж","винтажное"),
              ("классич","классическое"),("романтич","романтичное"),("геометр","геометричное"),("строг","строгое")]
    for needle,value in soft_map:
        if needle in t and value not in semantic: semantic.append(value)

    # Остаток человеческой фразы используем только как МЯГКИЙ смысл/название проекта.
    # Так «кольцо Властелина колец» не превращается просто в «все кольца».
    known_stems=(
        "покаж","найд","нашел","хоч","нуж","есть","тогда","теперь","просто","остав","убер","исключ","только","без","с",
        "посовет","подар","подобр","подбер","подход","подойд","выбра","вариант","что","нибудь",
        "украшен","ювелир","кольц","обруч","перст","печат","серьг","подвес","кулон","крест","брасл","брош","брел","знач",
        "женск","мужск","детск","девуш","женщин","подруг","невест","жене","маме","сестр","дочер","парн","мужчин","мужу","папе","отц","брат","сын","ребен","ребён","девоч","мальчик",
        "золот","серебр","платин","металл","бел","красн","розов","желт","жёлт","черн","чёрн","одноцвет","двухцвет","комбинирован",
        "кам","встав","одн","дв","бриллиант","алмаз","сапфир","рубин","изумруд","аметист","гранат","топаз","фианит","жемчуг",
        "овал","круг","кругл","квадрат","прямоуголь","груш","крупн","мелк","централь","эмал","ажур","филигран","широк","узк","массив",
        "нежн","воздуш","легк","лёгк","брутал","минимал","лаконич","соврем","необыч","винтаж","классич","романтич","геометр","строг",
        "корон","герб","орл","лев","льв","волк","волч","кот","кошк","лис","медвед","тигр","зме","дракон","сова","сердц","гора","ключ","якор","компас","отпечат",
        "зодиак","знак","гороскоп","овен","телец","близнец","рак","дева","весы","скорпион","стрелец","козерог","водолей","рыбы",
        "фото","рендер","референс","эскиз","скриншот","файл","blender","blend","блендер","stl","стл","rhino","рино","3dm",
        "делал","дела","сдела","работ","заказ","папк","изготов","прошл","предыдущ","текущ","последн","недавн",
        "недел","месяц","сегодня","вчера","позавчера","суток","дней","числ","период","дат"
    )
    residual=[]
    _RESIDUAL_SKIP = {
        "этого","этот","эти","этой","этом","такие","такое","какие","который","которые",
        "вообще","обычное","обычные","можно","пожалуйста","нибудь","чего","своей","моей",
        "твоей","кого","чтобы","чтоб","было","были","есть","весь","вся","всё","все",
        "которых","которым","которыми","которой","этому","этим","этими","этих",
        "себя","тебе","меня","нам","вам","них","ним","ими","она","оно","они",
        "дай","давай","давайте","плиз","спасибо","здесь","там","тут","тогда","теперь",
    }
    for tok in re.findall(r"[a-zа-я0-9]+",t):
        if len(tok)<4 or tok.isdigit(): continue
        if any(tok.startswith(st) or st.startswith(tok) for st in known_stems): continue
        if tok in _RESIDUAL_SKIP: continue
        residual.append(tok)
    if residual:
        # 0.90.5: универсальная логика для любых слов.
        # 1) Если слово уже в ALIASES (ornament/style/motif/zodiac) — точный фильтр.
        # 2) Одиночное/парное незнакомое слово — точный фильтр tag:слово.
        # 3) Длинная фраза (3+) — prefer[tag:...] + semantic (мягче).
        _residual_matched = False
        for _tok in residual[:3]:
            _matched_slot = False
            for _key in ("ornament","style","motif","zodiac"):
                _table = ALIASES.get(_key, {}) or {}
                for _alias, _cv in _table.items():
                    if _word_close(_tok, _alias) or _word_close(_tok, _cv):
                        _target = f"{_key}:{_cv}"
                        _bucket = must_not if negative_prefix else must
                        if _target not in _bucket:
                            _bucket.append(_target)
                        _matched_slot = True
                        _residual_matched = True
                        break
                if _matched_slot: break
            if _matched_slot: continue
            if len(residual) <= 2:
                _target = f"tag:{_tok}"
                _bucket = must_not if negative_prefix else must
                if _target not in _bucket:
                    _bucket.append(_target)
                _residual_matched = True
            else:
                _target = f"tag:{_tok}"
                if _target not in prefer and _target not in avoid:
                    prefer.append(_target)
        if not _residual_matched or len(residual) > 2:
            phrase=" ".join(residual[:5])
            if phrase and phrase not in semantic: semantic.append(phrase)

    # Команда «убери ...» — одно СОСТАВНОЕ исключение.
    # «убери кольца с сапфиром» не должно удалить все кольца и все сапфиры по отдельности.
    exclude_group=[]
    if negative_prefix:
        exclude_group=list(dict.fromkeys((must_not or []) + (must or [])))
        must=[]; must_not=[]

    # 0.90.6: попытка умного разбора уточнения, если обычные условия не сработали.
    if not (must or must_not or exclude_group or prefer or avoid or semantic or semantic_not or selected_time):
        try:
            _smart = _smart_refine_plan(t, current_state)
            if _smart:
                return _smart
        except Exception:
            pass

    if must or must_not or exclude_group or prefer or avoid or semantic or semantic_not or selected_time:
        # Важная логика диалога:
        #   «перстни» / «покажи перстни» = новая тема;
        #   «а кулоны?» = заменить только тип в текущей выборке, сохранив остальные признаки;
        #   «тогда просто перстни» = точно сбросить все старые условия.
        continuation_type = bool(type_hit and re.match(r"^а\s+",t))
        # 0.90.4: "в славянском стиле", "в стиле модерн", "стиль барокко"
        # при активной выборке — уточнение, а не новая тема.
        style_refinement = bool(re.search(
            r"(?:^|\s)(?:в\s+\S+\s+стиле|в\s+стиле\s+\S+|стиль\s+\S+)", t))
        bare_without = bool(re.match(r"^(покажи|покажите|найди|найдите|оставь|оставить)\s+без\b", t))
        _has_ctx = bool(
            (current_state or {}).get("must") or
            (current_state or {}).get("must_not") or
            (current_state or {}).get("semantic") or
            (current_state or {}).get("exclude_groups")
        )
        if re.match(r"^(тогда|теперь)\s+просто\b",t) or re.match(r"^просто\s+",t):
            scope="new"
        elif refine_prefix or continuation_type or style_refinement or bare_without:
            scope="current"
        elif _has_ctx and re.match(r"^(покажи|покажите|найди|найдите)\b",t) and not type_hit:
            scope="current"
        elif type_hit or new_prefix or audience_hit or jewelry_gift_intent(t):
            scope="new"
        else:
            scope="current"
        return plan("search",scope,must=must,must_not=must_not,exclude_group=exclude_group,prefer=prefer,avoid=avoid,semantic=semantic,semantic_not=semantic_not,reply="Понял запрос.")
    return None


def local_conversation_reply(text: str, now: datetime | None = None) -> str:
    """Handles tiny everyday requests immediately, including the real local clock."""
    t=norm(text).strip(" .!?…")
    if not t:
        return ""
    current=now or datetime.now()
    clock_patterns=(
        r"\bсколько\s+врем(?:ени|я)?\b",r"\bкоторый\s+(?:сейчас\s+)?час\b",
        r"\b(?:текущее|точное)\s+время\b",r"\bвремя\s+сейчас\b",r"\bподскажи\s+время\b"
    )
    if any(re.search(pattern,t) for pattern in clock_patterns):
        return f"Сейчас {current.strftime('%H:%M')} по времени вашего компьютера."
    if any(re.search(pattern,t) for pattern in (
        r"\bкакое\s+сегодня\s+число\b",r"\bкакая\s+(?:сегодня\s+)?дата\b",
        r"\bсегодняшн(?:яя|юю)\s+дат",r"\bкакой\s+сегодня\s+день\b"
    )):
        weekdays=("понедельник","вторник","среда","четверг","пятница","суббота","воскресенье")
        return f"Сегодня {current.strftime('%d.%m.%Y')}, {weekdays[current.weekday()]}."
    if t in {"ты тут","ты здесь","ты на месте","ты со мной","ты работаешь"}:
        return "Да, я здесь. Могу помочь с украшениями или просто поговорить."
    if t in {"привет","здравствуй","здравствуйте","добрый день","добрый вечер","доброе утро"}:
        return "Привет! Чем могу помочь — найти украшение или просто поболтать?"
    if t in {"спасибо","спасибо тебе","благодарю","большое спасибо"}:
        return "Пожалуйста! Обращайся, если понадобится помощь."
    return ""


_REFINE_VERBS_RX = re.compile(
    r"^(оставь|оставить|убери|убрать|исключи|исключить|не\s+показывай|"
    r"только|без|добавь|добавить|из\s+них|из\s+этих|среди\s+них|"
    r"а\s+теперь|теперь|дальше|ещё|еще)\b")

_QUESTION_SEARCH_RX = re.compile(
    r"(?:^|\s)(?:есть(?:\s+что[\-\s]?то|\s+ли)?|у\s+тебя\s+есть|"
    r"покажи|покажите|найди|найдите|показать|найти)(?:\s|$)",
    re.IGNORECASE)

def should_use_casual_qwen(text: str, quick: dict | None, current_state: dict | None = None) -> bool:
    """0.90.6: уточнения и вопросы-поиск больше не уходят в casual Qwen."""
    t=norm(text)
    if not t:
        return False
    if local_conversation_reply(t):
        return True
    if quick and quick.get("action")=="chat":
        return True
    if quick and quick.get("action")=="search" and quick.get("time_filter"):
        return False

    # 0.92.1: явные разговорные просьбы не должны становиться поиском даже
    # при активной выборке. Раньше «расскажи шутку» после любого поиска
    # превращался в запрос тегов, и программа переставала шутить.
    strong_casual=(
        "шутк", "пошути", "анекдот", "поговорим", "поболтаем",
        "как дела", "как ты", "как настроение", "чем занимаешься",
        "погод", "курс валют", "новост", "фильм", "музык", "книг",
    )
    if any(x in t for x in strong_casual) and not jewelry_gift_intent(t):
        return True
    st = current_state or {}
    has_ctx = bool(st.get("must") or st.get("must_not") or st.get("semantic")
                   or st.get("exclude_groups"))
    if has_ctx:
        if _REFINE_VERBS_RX.match(t):
            return False
        if _QUESTION_SEARCH_RX.search(t):
            return False
        if len(t.split()) <= 6:
            return False

    jewelry_stems=(
        "кольц","перст","печат","серьг","подвес","кулон","крест","брасл","брош","брел",
        "камн","камень","камни","бриллиант","сапфир","рубин","изумруд","эмал","ажур","золот","серебр",
        "металл","матов","детск","женск","мужск","обруч","помолв","венчан","корон",
        "герб","мотив","рендер","фото","ювелир","украшен","проект","архив","каталог",
        "тег","выборк","покажи похож","найди похож","по картинк","девушк","женщин",
        "подруг","невест","парн","мужчин","клиент","заказ","папк","локальн",
        "мусульман","православн","христиан","иудейск","буддийск","масонск","рыцарск","готическ",
    )
    if any(x in t for x in jewelry_stems) or jewelry_gift_intent(t):
        return False
    if any(x in t for x in ("кто такой","кто такая","кто такие","что такое","почему ","зачем ",
                             "как работает","как устроен","что думаешь","как считаешь","объясни",
                             "помоги написать","напиши мне","придумай рассказ","расскажи о ","расскажи про ")):
        return True
    conversation_markers=(
        "как ты","как дела","как настроение","чем занимаешься","расскажи",
        "придумай","посоветуй","поговорим","поболтаем","мне груст","мне весел",
        "спасибо","привет","здравств","анекдот","пошути","новост","погод","курс валют",
        "который час","сколько времен","сколько время","фильм","музык","книг","рецепт"
    )
    if any(x in t for x in conversation_markers):
        return True
    return len(t.split())>=6

def apply_plan(state:dict,plan:dict,previous_state:dict|None=None)->dict:
    if plan["scope"]=="new": s=blank_state()
    elif plan["scope"]=="previous" and previous_state is not None: s=clone_state(previous_state)
    else: s=clone_state(state)
    for key in plan.get("remove_keys",[]):
        for group in ("must","must_not","prefer","avoid"): s[group].pop(key,None)
        cleaned=[]
        for ex in s.get("exclude_groups") or []:
            if not isinstance(ex,dict): continue
            ex=dict(ex); ex.pop(key,None)
            if ex: cleaned.append(ex)
        s["exclude_groups"]=cleaned

    def apply_group(group_name,items,replace=True):
        grouped={}
        for raw in items:
            c=parse_condition(raw)
            if c: grouped.setdefault(c[0],[]).append(c[1])
        for k,vals in grouped.items():
            vals=list(dict.fromkeys(v for v in vals if v))
            if replace: s[group_name][k]=vals
            else:
                s[group_name].setdefault(k,[])
                for v in vals:
                    if v not in s[group_name][k]: s[group_name][k].append(v)
        return grouped

    pos=apply_group("must",plan.get("must",[]),True)
    neg=apply_group("must_not",plan.get("must_not",[]),False)
    pref=apply_group("prefer",plan.get("prefer",[]),True)
    avoid=apply_group("avoid",plan.get("avoid",[]),True)

    ex_group={}
    for raw in plan.get("exclude_group",[]) or []:
        c=parse_condition(raw)
        if c:
            ex_group.setdefault(c[0],[])
            if c[1] not in ex_group[c[0]]: ex_group[c[0]].append(c[1])
    if ex_group:
        s.setdefault("exclude_groups",[]).append(ex_group)

    # Positive/banned contradictions of same value cancel the older side.
    for k,vals in pos.items():
        if k in s["must_not"]:
            s["must_not"][k]=[x for x in s["must_not"][k] if x not in vals]
            if not s["must_not"][k]: s["must_not"].pop(k,None)
    for k,vals in neg.items():
        if k in s["must"]:
            s["must"][k]=[x for x in s["must"][k] if x not in vals]
            if not s["must"][k]: s["must"].pop(k,None)

    # Зависимые слоты. В чате новое утверждение должно ЗАМЕНЯТЬ старое, а не создавать
    # невозможную комбинацию вроде «без камней + один камень».
    stone_detail_keys={"stone_count","center_stone","stone_type","stone_color","stone_shape","stone_size","stone_position","stone_rows","insert_color"}
    positive_stone_detail = any(k in pos for k in stone_detail_keys)
    if "stones" in pos:
        stone_value=(pos.get("stones") or [""])[0]
        if stone_value=="нет":
            for k in stone_detail_keys:
                s["must"].pop(k,None); s["must_not"].pop(k,None); s["prefer"].pop(k,None); s["avoid"].pop(k,None)
        elif stone_value=="есть":
            if (s["must"].get("stone_count") or [])==["нет"]: s["must"].pop("stone_count",None)
    elif positive_stone_detail:
        # «один овальный камень» автоматически означает, что камень есть.
        s["must"]["stones"]=["есть"]
        s["must_not"].pop("stones",None)
    if "stone_count" in pos and (pos.get("stone_count") or [""])[0]=="нет":
        s["must"]["stones"]=["нет"]
        for k in stone_detail_keys-{"stone_count"}: s["must"].pop(k,None)

    # 0.90.9: смена типа камня или цвета камня — заменяет противоположную
    # характеристику. "с сапфиром" после "с красным камнем" не должно
    # сохранять stone_color:красный — иначе поиск ищет красные сапфиры.
    if "stone_type" in pos and "stone_color" not in pos:
        s["must"].pop("stone_color",None)
        s["must_not"].pop("stone_color",None)
    if "stone_color" in pos and "stone_type" not in pos:
        s["must"].pop("stone_type",None)
        s["must_not"].pop("stone_type",None)
    if "stone_type" in pos and "stone_color" in pos:
        pass  # оба заданы явно — оставляем оба

    # Смена материала без нового цвета металла сбрасывает старый цвет.
    # Пример: «красное золото» -> «тогда серебро» не должно оставлять metal=красный.
    if "material" in pos and "metal" not in pos:
        old_material=set((state.get("must") or {}).get("material") or [])
        if old_material and set(pos["material"])!=old_material:
            s["must"].pop("metal",None); s["prefer"].pop("metal",None); s["avoid"].pop("metal",None)

    # If a new concrete product type replaces the old one, stale subtypes/purpose usually stop making sense.
    # We do this only on current-scope replacement, not when type is merely excluded.
    if "type" in pos and plan.get("scope")=="current":
        old_types=set((state.get("must") or {}).get("type") or [])
        if old_types and set(pos["type"])!=old_types:
            s["must"].pop("subtype",None); s["must"].pop("purpose",None)

    if plan.get("semantic"):
        if plan["scope"]=="new": s["semantic"]=[]
        for x in plan["semantic"]:
            x=norm(x)
            if x and x not in s["semantic"]: s["semantic"].append(x)
    if plan.get("semantic_not"):
        for x in plan["semantic_not"]:
            x=norm(x)
            if x and x not in s["semantic_not"]: s["semantic_not"].append(x)
    if plan.get("time_filter"):
        s["time_filter"]=_sanitize_project_time_filter(plan["time_filter"])
    s["label"]=describe_state(s)
    return s


# ---------------- Search engine V2.4: slot-state + learned negative neighbors ----------------

def project_is_currently_analyzed(p:dict, model:str|None=None)->bool:
    ok = bool(p.get("vision")) and int(p.get("vision_version",0))>=PROJECT_VISION_VERSION and p.get("vision_signature")==p.get("source_signature")
    if ok and model:
        ok = str(p.get("vision_model") or "").strip() == str(model or "").strip()
    return ok


def _condition_match_uncached(p:dict,key:str,expected_values:list[str]):
    """Трёхзначная логика YES / NO / UNKNOWN.
    Ключевой принцип 0.30: несовпавшее значение многозначного поля НЕ доказывает отсутствие искомого.
    0.43: ручной отрицательный тег — это явное NO для соответствующего понятия.
    """
    if key=="source_format":
        expected={canon(key,value) for value in expected_values or [] if canon(key,value)}
        actual=set(project_source_formats(p))
        if actual & expected:
            value=sorted(actual & expected)[0]
            return "yes",1.0,[(value,1.0,"реальное расширение файла")]
        return "no",1.0,[(value,1.0,"реальное расширение файла") for value in sorted(actual)]
    for expected in expected_values or []:
        if negative_tag_matches(p,expected,key):
            return "no",1.0,[(norm(expected),1.0,"ручной/обученный отрицательный пример")]
    # Предметная здравость: подтверждённое обручальное/помолвочное/венчальное кольцо
    # не считаем детским только потому, что Vision где-то увидел «детский» стиль.
    if key=="audience" and any(canon("audience",x)=="детское" for x in expected_values or []):
        manual_a=(p.get("manual_labels") or {}).get("audience") or []
        if not any(canon("audience",x)=="детское" for x in manual_a):
            sub_ev=project_evidence(p,"subtype")
            if any(canon("subtype",v) in {"обручальное","помолвочное","венчальное"} and c>=0.70 for v,c,_ in sub_ev):
                return "no",0.94,[("детское",0.94,"ювелирная логика: взрослый свадебный подтип")]
    ev=project_evidence(p,key)
    # 0.98.2: венчальное = помолвочное ИЛИ классика с центральным камнем.
    # Пользовательское определение: венчальные кольца в архиве выглядят
    # как классика с одним центральным камнем (иногда с мелкими боковыми).
    if key == "subtype":
        for _expv in expected_values:
            if canon("subtype", _expv) == "венчальное":
                for _se in project_evidence(p, "subtype"):
                    if canon("subtype", _se[0]) == "помолвочное":
                        ev = ev + [(_se[0], max(0.80, float(_se[1] or 0)), _se[2])]
                for _ce in project_evidence(p, "center_stone"):
                    if canon("center_stone", _ce[0]) == "есть":
                        ev = ev + [("есть", 0.75, "венчальное=классика с камнем")]
    # 0.95.3: крест сильнее подвески. Если есть уверенный крест, убираем
    # «подвеска» из доказательств: пользователь считает крест крестом.
    if key == "type":
        _cross_ev = [x for x in ev if canon(key, x[0]) == "крест" and float(x[1] or 0) >= 0.65]
        if _cross_ev:
            ev = [x for x in ev if canon(key, x[0]) != "подвеска"]
    # 0.98.1: свободное слово запроса (tag) дополнительно смотрит в мотивы,
    # стили, орнаменты и зодиак, но ТОЛЬКО при совпадении основы слова
    # (череп / черепом / черепа -> одна основа). Fuzzy-сравнение с именем
    # проекта убрано: именно оно давало ложные точные совпадения.
    # Уверенность доказательства должна быть >= 0.70.
    if key == "tag":
        _expected_stems = {_simple_ru_stem(norm(e)) for e in expected_values if norm(e)}
        _expected_stems.discard("")
        for _extra_key in ("motif", "style", "ornament", "zodiac"):
            for _ev in project_evidence(p, _extra_key):
                _cv = norm(_ev[0])
                if not _cv or float(_ev[1] or 0) < 0.70:
                    continue
                if _simple_ru_stem(_cv) in _expected_stems:
                    ev = ev + [(_cv, float(_ev[1]), _ev[2])]
    if not ev:
        return "unknown",0.0,[]
    compatible=[]; incompatible=[]
    for value,conf,source in ev:
        if any(compatible_value(key,value,e) for e in expected_values): compatible.append((value,conf,source))
        else: incompatible.append((value,conf,source))
    if compatible:
        best=max(compatible,key=lambda x:x[1])
        # Самообучение — второй эксперт, а не хозяин истины. Если оно спорит с более сильным
        # независимым источником (путь/ручная карточка/Vision), точного совпадения нет.
        if best[2]=="Jewelry AI":
            strong_conflicts=[x for x in incompatible if x[2] != "Jewelry AI" and x[1]>=0.70]
            if strong_conflicts:
                strongest=max(strong_conflicts,key=lambda x:x[1])
                if strongest[1] >= best[1]-0.04:
                    return "unknown",best[1],[best,strongest]
        # Слабая догадка не превращается в точный факт. Для Jewelry AI порог выше,
        # потому что его 0.51-0.57 специально означают «кандидат».
        yes_threshold=0.70 if best[2]=="Jewelry AI" else 0.58
        if best[1] >= yes_threshold:
            return "yes",best[1],[best]
        return "unknown",best[1],[best]
    # Явное ручное/обученное «нет» у зависимого каменного признака — это настоящее отрицание,
    # а не UNKNOWN. Поэтому проект без камня больше не пролезает в «сапфир / крупный камень».
    if key in {"stone_type","stone_color","stone_shape","stone_size"} and incompatible:
        explicit_no=[x for x in incompatible if canon(key,x[0])=="нет"]
        if explicit_no:
            strongest=max(explicit_no,key=lambda x:x[1])
            if strongest[1] >= 0.58:
                return "no",strongest[1],explicit_no
    # 0.90.9: soft cross-check stone_type по совместимому stone_color.
    # Пользователь ищет "сапфир" — он ожидает увидеть синие/голубые камни,
    # даже если AI не решился назвать минерал. Это даёт 1-2 балла ниже прямого
    # совпадения, но выше порога "неизвестно".
    if key == "stone_type":
        wanted = {canon(key, x) for x in (expected_values or [])}
        color_ev = project_evidence(p, "stone_color")
        for w in wanted:
            hints = GEM_COLOR_HINTS.get(w, set())
            if not hints: continue
            best_color_conf = 0.0
            best_color_value = ""
            for cv, cc, cs in color_ev:
                if canon("stone_color", cv) in hints and float(cc) >= 0.70:
                    if float(cc) > best_color_conf:
                        best_color_conf = float(cc)
                        best_color_value = cv
            if best_color_conf > 0:
                soft_conf = min(0.72, best_color_conf)
                return "yes", soft_conf, [(best_color_value, soft_conf,
                                           "совместимый цвет, не минерал")]

    # 0.91.1: гибридное правило для mineral.
    #
    # Пользователь ищет «сапфир», карточка проекта называет «рубин» с высокой
    # уверенностью, а «сапфира» в ней нет вовсе. В 0.91.0 такая карточка
    # оставалась в «неизвестно» и попадала в «похожие». Это защита от ложного
    # пропуска, но на практике она слишком широкая: 363 кандидата на 8 точных.
    #
    # Правило ниже делает компромисс. Явное уверенное противоречие (другой
    # минерал, >=0.85) — это уже не «неизвестно», а «нет»: проект выпадает
    # и из точных, и из похожих. Молчание карточки или неуверенное
    # предположение (<0.85) по-прежнему «неизвестно» → кандидат в «похожих».
    #
    # Порог 0.85 выбран так, чтобы этот блок срабатывал только на том уровне
    # уверенности, где сам Qwen уже считает факт установленным, а не гадает.
    # Пограничные случаи 0.75–0.85 остаются кандидатами, как и раньше.
    if key == "stone_type" and incompatible and not compatible:
        other_stones = [x for x in incompatible
                        if canon(key, x[0]) not in {"", "нет"}]
        if other_stones:
            strongest_other = max(other_stones, key=lambda x: x[1])
            try: strong_conf = float(strongest_other[1] or 0.0)
            except Exception: strong_conf = 0.0
            if strong_conf >= 0.85:
                return "no", strong_conf, other_stones

    # Только скалярное/взаимоисключающее поле может доказать NO своим другим значением.
    # 0.95.3: крест и подвеска взаимоисключающи даже при средней уверенности.
    # Визуально крест на цепочке модели часто называют подвеской; пользователь считает крест крестом.
    if key == "type" and incompatible:
        _cross = {"крест", "подвеска"}
        _strongest = max(incompatible, key=lambda x: x[1])
        if canon(key, _strongest[0]) in _cross and _strongest[1] >= 0.65:
            return "no", _strongest[1], incompatible
    if key in EXCLUSIVE_FACT_KEYS and incompatible:
        strongest=max(incompatible,key=lambda x:x[1])
        if strongest[1] >= 0.82:
            return "no",strongest[1],incompatible
    return "unknown",max([x[1] for x in incompatible] or [0.0]),incompatible


def _condition_match(p:dict,key:str,expected_values:list[str]):
    cache=p.get("_search_condition_cache")
    if not isinstance(cache,dict):
        return _condition_match_uncached(p,key,expected_values)
    token=(str(key),tuple(sorted(canon(key,x) for x in expected_values or [])))
    if token not in cache:
        cache[token]=_condition_match_uncached(p,key,expected_values)
    return cache[token]


def hard_match_project(p:dict,state:dict):
    unknown=[]; reasons=[]; score=0.0
    for key,expected in (state.get("must") or {}).items():
        status,conf,ev=_condition_match(p,key,expected)
        if status=="no": return "reject",unknown,reasons,-999.0
        if status=="yes": reasons.append(key); score += 1.15 + conf*0.65
        else: unknown.append(key); score += 0.08
    for key,banned in (state.get("must_not") or {}).items():
        status,conf,ev=_condition_match(p,key,banned)
        if status=="yes" and conf>=0.68:
            return "reject",unknown,reasons,-999.0
        if status=="no":
            reasons.append("без "+key); score += 0.65 + conf*0.25
        else:
            # Для одиночного исключения удаляем подтверждённые совпадения, остальные сохраняем.
            reasons.append("не найдено "+key); score += 0.10

    # Составные исключения: проект удаляется только если ВСЕ признаки группы подтверждены вместе.
    for group in state.get("exclude_groups") or []:
        if not isinstance(group,dict) or not group:
            continue
        matched=[]; failed=False
        for key,vals in group.items():
            status,conf,_=_condition_match(p,key,vals)
            if status=="yes" and conf>=0.62:
                matched.append((key,conf))
            else:
                failed=True; break
        if not failed and len(matched)==len(group):
            return "reject",unknown,reasons,-999.0
        score += 0.04
    # 0.93.3: запрет по связке условий. Карточка отвергается только если
    # текущий запрос покрывает ВСЮ сохранённую связку (type+цвет+камни+...),
    # а не отдельное слово из неё.
    for neg in (p.get("manual_labels") or {}).get("not_tag") or []:
        nn=norm(neg)
        if not nn.startswith("⟦связка⟧"):
            continue
        body=nn[len("⟦связка⟧"):].strip()
        if not body:
            continue
        covered=True
        for part in body.split("+"):
            part=part.strip()
            if ":" not in part:
                covered=False; break
            k,v=part.split(":",1)
            k=k.strip(); v=v.strip()
            if k=="semantic":
                if v not in [norm(x) for x in (state.get("semantic") or [])]:
                    covered=False; break
            else:
                vals={canon(k,x) for x in (state.get("must") or {}).get(k) or []}
                if canon(k,v) not in vals:
                    covered=False; break
        if covered:
            return "reject",unknown,reasons,-999.0
    return ("candidate" if unknown else "exact"),unknown,reasons,score


def preference_score(p:dict,state:dict)->float:
    score=0.0
    for key,vals in (state.get("prefer") or {}).items():
        status,conf,_=_condition_match(p,key,vals)
        if status=="yes": score += 0.75*max(0.5,conf)
        elif status=="no": score -= 0.22*max(0.5,conf)
    for key,vals in (state.get("avoid") or {}).items():
        status,conf,_=_condition_match(p,key,vals)
        if status=="yes": score -= 0.48*max(0.5,conf)
        elif status=="no": score += 0.18*max(0.5,conf)
    return score


QWEN_SEARCH_FIELDS = (
    "item_type","item_subtypes","audience","purposes","image_roles","composition",
    "materials","metal_colors","metal_mode","insert_colors","stone_presence","stone_count",
    "center_stone","stone_types","stone_colors","stone_shapes","stone_sizes","stone_positions",
    "setting_styles","stone_rows","band_width","visual_mass","overall_shapes","openwork","enamel",
    "motifs","motif_classes","zodiac_signs","religious_symbols","text_types","visible_text",
    "surface_tags","ornament_tags","style_tags","semantic_traits","search_tags","description",
    "evidence_notes",
)
QWEN_TAG_FIELDS = (
    "search_tags","style_tags","semantic_traits","surface_tags","ornament_tags",
    "motifs","motif_classes","zodiac_signs","religious_symbols","visible_text",
)


def _text_values(value):
    if isinstance(value,dict):
        for child in value.values():
            yield from _text_values(child)
    elif isinstance(value,(list,tuple,set)):
        for child in value:
            yield from _text_values(child)
    elif isinstance(value,str):
        value=value.strip()
        if value: yield value


def _qwen_tags_from_vision(vision:dict)->dict:
    """Compact tag part of a Qwen card, persisted in the local fingerprint."""
    vision=vision or {}
    out={}
    for key in QWEN_TAG_FIELDS:
        vals=[]
        for raw in _text_values(vision.get(key)):
            cleaned=norm(raw)
            if cleaned and cleaned not in UNKNOWN_WORDS and cleaned not in vals:
                vals.append(cleaned)
        if vals: out[key]=vals
    return out


def _fingerprint_search_text(tags,vision)->str:
    """Normalized, ready-to-search local text; no Ollama/OpenCLIP call is needed."""
    parts=[]
    for raw in _text_values(tags or {}): parts.append(raw)
    vision=vision or {}
    for key in QWEN_SEARCH_FIELDS:
        for raw in _text_values(vision.get(key)): parts.append(raw)
    return norm(" ".join(dict.fromkeys(x for x in parts if x)))


def _fingerprint_is_current(project:dict,fp:dict)->bool:
    if not fp:
        return False
    source_signature=str(project.get("source_signature") or "")
    fp_hash=str(fp.get("file_hash") or "")
    # 0.91: merged multi-model fingerprints always carry the project's source
    # signature at the time each card was written; if it matches, the cached
    # card is current. Falls back to the active-card equality test for legacy
    # databases whose fingerprints pre-date the source_signature convention.
    if source_signature and fp_hash:
        return source_signature==fp_hash
    if (project.get("vision") and fp.get("vision")
            and (fp.get("vision") or {})==(project.get("vision") or {})):
        return True
    return project_is_currently_analyzed(project) and bool(project.get("vision"))


def _qwen_fingerprint_evidence(vision:dict)->dict:
    """Turns a local Qwen fingerprint into the same evidence shape as Jewelry Index."""
    vision=vision or {}
    result={}
    base=_clamp01(vision.get("confidence",0.72),0.72)
    def add(key,value,conf):
        value=canon(key,value)
        if not value: return
        bucket=result.setdefault(key,[])
        item=(value,float(max(0.0,min(1.0,conf))),"Qwen-отпечаток")
        old=next((i for i,x in enumerate(bucket) if x[0]==value),None)
        if old is None: bucket.append(item)
        elif bucket[old][1] < item[1]: bucket[old]=item
    for key in INDEXED_FACT_KEYS:
        if key in {"not_tag","tag"}:
            continue
        conf=_vision_field_confidence(vision,key,base)
        if conf < MIN_AI_FACT_CONF.get(key,0.58):
            continue
        for value in _vision_values(vision,key): add(key,value,conf)
        for value,text_conf in _explicit_vision_text_evidence(vision,key): add(key,value,text_conf)
    # search/style tags are Qwen's free vocabulary.  They must be available both
    # to semantic ranking and to an explicit custom-tag filter.
    tag_conf=max(0.60,min(0.78,base*0.88))
    for raw in _text_values(_qwen_tags_from_vision(vision)):
        add("tag",raw,tag_conf)
    return result


def _with_local_qwen_fingerprint(project:dict,fp:dict|None)->dict:
    item=dict(project)
    item["fingerprint_used"]=False
    if not fp or not _fingerprint_is_current(item,fp):
        if fp: item["fingerprint_stale"]=True
        return item
    vision=fp.get("vision") or {}
    tags=fp.get("tags") or _qwen_tags_from_vision(vision)
    search_text=str(fp.get("search_text") or "") or _fingerprint_search_text(tags,vision)
    item["fingerprint_used"]=True
    item["qwen_used"]=bool(search_text or vision or tags)
    item["ai_tags"]=tags
    # For merged multi-model fingerprints vision is empty on purpose; keep the
    # active model's card in vision_json so the gallery/diagnostics stay useful.
    if vision:
        item["vision_json"]=vision
    elif not item.get("vision_json"):
        item["vision_json"]=item.get("vision") or {}
    item["_qwen_text"]=search_text
    item["_qwen_evidence_map"]=fp.get("evidence_map") or _qwen_fingerprint_evidence(vision)
    # 0.92: консенсус моделей для автоматического обучения
    item["_consensus_map"]=fp.get("consensus_map") or {}
    item["_fingerprint_updated_at"]=float(fp.get("updated_at") or 0.0)
    if fp.get("models"):
        item["_models_active"]=list(fp["models"])
    return item


def project_text_blob(p:dict)->str:
    """Текст только для мягкого семантического ранжирования. Он НЕ участвует в точных фильтрах Jewelry Index."""
    cached=p.get("_search_text_blob")
    if isinstance(cached,str):
        return cached
    parts=[p.get("title",""),p.get("category",""),p.get("client",""),p.get("rel_folder","")]
    for v in [p.get("vision") or {}, p.get("legacy_vision") or {}]:
        for key in ("semantic_traits","style_tags","search_tags","ornament_tags","motifs","motif_classes","description"):
            x=v.get(key)
            if isinstance(x,list): parts.extend(str(z) for z in x)
            elif x: parts.append(str(x))
    # Ручные и обученные факты тоже участвуют в мягком семантическом ранжировании.
    for k,v,c,source in (p.get("indexed_facts") or []):
        if k in {"style","motif","ornament","tag","mass","width","type","audience","material","metal","metal_mode"} and float(c or 0)>=0.50:
            parts.append(str(v))
    # This is the local, normalized Qwen fingerprint.  In v0.74 it was attached
    # under ai_tags/vision_json but never read here, so Qwen changed only the status.
    if p.get("_qwen_text"): parts.append(str(p["_qwen_text"]))
    else:
        for raw in _text_values(p.get("ai_tags") or {}): parts.append(raw)
        for raw in _text_values(p.get("vision_json") or {}): parts.append(raw)
    result=norm(" ".join(parts))
    p["_search_text_blob"]=result
    return result


GEM_COLOR_HINTS = {
    "сапфир":{"синий","голубой","сине-фиолетовый"},
    "рубин":{"красный","розовый"},
    "изумруд":{"зеленый"},
    "аметист":{"фиолетовый","сине-фиолетовый"},
    "гранат":{"красный"},
    "топаз":{"голубой","синий","желтый"},
}


def candidate_context_bonus(p:dict,state:dict)->float:
    """Мягкие подсказки только для порядка кандидатов; никогда не превращают их в точные совпадения."""
    bonus=0.0
    stone_types=(state.get("must") or {}).get("stone_type") or []
    if stone_types:
        colors=set(project_actual(p,"stone_color"))
        stones=set(project_actual(p,"stones"))
        for g in stone_types:
            hints=GEM_COLOR_HINTS.get(canon("stone_type",g),set())
            if colors & hints:
                bonus += 0.72
            if "есть" in stones:
                bonus += 0.10
    # Неопределённый подтип кольца всё равно лучше искать среди колец, чем среди случайных изделий.
    if (state.get("must") or {}).get("subtype") and any(compatible_value("type",x,"кольцо") for x in project_actual(p,"type")):
        bonus += 0.20
    return bonus




def ai_tag_score(project: dict, state: dict) -> float:
    """Бонус именно от локальных тегов Qwen, отдельно от общего текста проекта."""
    terms = [norm(x) for x in (state.get("semantic") or []) if norm(x)]
    if not terms:
        return 0.0
    blob=norm(project.get("_qwen_text") or "")
    if not blob:
        blob=_fingerprint_search_text(project.get("ai_tags") or {},project.get("vision_json") or {})
    if not blob:
        return 0.0
    cache=project.setdefault("_search_phrase_cache",{})
    hits=0
    for term in terms:
        token=("qwen",term)
        if token not in cache:
            cache[token]=fuzzy_phrase_in_text(term,blob)
        if cache[token]: hits+=1
    return min(0.42, (hits / max(1, len(terms))) * 0.42)


def semantic_score(p:dict,state:dict,ai:AIEngine|None=None,query_vec:np.ndarray|None=None)->float:
    terms=[norm(x) for x in state.get("semantic",[]) if norm(x)]
    neg=[norm(x) for x in state.get("semantic_not",[]) if norm(x)]
    if not terms and not neg: return 0.0
    text=project_text_blob(p)
    cache=p.setdefault("_search_phrase_cache",{})
    def matches(term):
        token=("all",term)
        if token not in cache:
            cache[token]=fuzzy_phrase_in_text(term,text)
        return cache[token]
    lexical=sum(1.0 for t in terms if matches(t))/max(1,len(terms))
    lexical_neg=sum(1.0 for t in neg if matches(t))/max(1,len(neg)) if neg else 0.0
    clip=0.0
    if query_vec is not None and p.get("embedding") is not None: clip=max(0.0,cosine(query_vec,p["embedding"]))
    return lexical*0.58 + clip*0.42 - lexical_neg*0.75


# Кеш результатов J-AI поиска. Не заменяет индекс: хранит уже рассчитанные выдачи запросов.
_SEARCH_RESULT_CACHE = {}
_SEARCH_RESULT_CACHE_MAX = 128
_SEARCH_CONTEXT_CACHE = {}
_SEARCH_CONTEXT_CACHE_MAX = 6
_PROJECT_SOURCE_TIME_CACHE = {}
SEARCH_ALGORITHM_VERSION = 6

_SEARCH_CACHE_META_KEYS = (
    "match_unknown","match_reasons","semantic_score","preference_score","context_bonus",
    "ai_tag_score","rank_score","fingerprint_used","qwen_used",
)


def _augment_search_context_with_all_models(prepared):
    """0.91 model-agnostic enrichment.

    Reads every current (matching source_signature, matching version) vision
    card from project_vision_runs for the projects in the prepared list and
    merges them into _qwen_evidence_map / _qwen_text / ai_tags.

    This closes the two cases that a single active-model fingerprint cannot
    cover on its own:
      * the user ran Qwen, then switched the active model to Gemma — the
        Qwen card is still in project_vision_runs and must stay searchable;
      * a database from an older version that only had one card per project.

    Manual labels are still authoritative; they live in project_manual_labels
    and are consulted first by project_evidence, so this merge cannot override
    the user.
    """
    ids=[int(p["id"]) for p in prepared if p.get("id") is not None]
    if not ids:
        return
    runs_map={}
    try:
        con=sqlite3.connect(str(PROJECT_DB_PATH),timeout=30)
        try:
            for pos in range(0,len(ids),700):
                chunk=ids[pos:pos+700]
                qs=",".join("?" for _ in chunk)
                rows=con.execute(f"""
                    SELECT v.project_id,v.model,v.vision_json,v.vision_version,v.source_signature
                    FROM project_vision_runs v JOIN projects p ON p.id=v.project_id
                    WHERE v.project_id IN ({qs})
                      AND v.vision_version>=?
                      AND v.source_signature=p.source_signature
                """,chunk+[PROJECT_VISION_VERSION]).fetchall()
                for pid,model,vjson,version,ssig in rows:
                    vision=json_loads_safe(vjson,{})
                    if not isinstance(vision,dict) or not vision:
                        continue
                    runs_map.setdefault(int(pid),[]).append((str(model or ""),vision))
        finally:
            con.close()
    except Exception:
        return
    for project in prepared:
        pid=project.get("id")
        if pid is None:
            continue
        runs=runs_map.get(int(pid)) or []
        if not runs:
            continue
        existing_models=set(project.get("_models_active") or [])
        extra=[r for r in runs if r[0] and r[0] not in existing_models]
        if not extra:
            continue
        merged_evidence=dict(project.get("_qwen_evidence_map") or {})
        merged_text_parts=[str(project.get("_qwen_text") or "")]
        merged_tags=dict(project.get("ai_tags") or {})
        active_models=list(existing_models)
        for model,vision in runs:
            if model and model not in active_models:
                active_models.append(model)
            ev=_qwen_fingerprint_evidence(vision)
            for key,items in ev.items():
                bucket=merged_evidence.setdefault(str(key),[])
                for value,conf,source in items or []:
                    cv=canon(str(key),value)
                    if not cv: continue
                    label=str(source)
                    if model and model not in label:
                        label=label+" ["+model+"]"
                    existing=next((i for i,x in enumerate(bucket) if x[0]==cv),None)
                    try: cf=float(conf or 0.0)
                    except Exception: cf=0.0
                    if existing is None:
                        bucket.append((cv,cf,label))
                    elif float(bucket[existing][1])<cf:
                        bucket[existing]=(cv,cf,label)
            tags=_qwen_tags_from_vision(vision)
            for tk,tv in (tags or {}).items():
                if isinstance(tv,list):
                    lst=merged_tags.setdefault(str(tk),[])
                    for v in tv:
                        if v not in lst: lst.append(v)
            text=_fingerprint_search_text(tags,vision)
            if text: merged_text_parts.append(text)
        project["_qwen_evidence_map"]=merged_evidence
        project["_qwen_text"]=" ".join(dict.fromkeys(x for x in merged_text_parts if x))
        project["ai_tags"]=merged_tags
        project["qwen_used"]=True
        project["fingerprint_used"]=True
        project["_models_active"]=sorted(set(m for m in active_models if m))


def _get_search_context(projects:list[dict])->dict:
    token=id(projects)
    context=_SEARCH_CONTEXT_CACHE.get(token)
    if context is not None and context.get("source") is projects:
        return context
    try: AI_FINGERPRINT_CACHE.sync_from_projects(projects)
    except Exception: pass
    try:
        fingerprints=AI_FINGERPRINT_CACHE.get_many([p.get("id") for p in projects if p.get("id") is not None])
    except Exception:
        fingerprints={}
    prepared=[]
    for p in projects:
        if p.get("id") is not None:
            item=_with_local_qwen_fingerprint(p,fingerprints.get(int(p.get("id"))))
        else:
            item=dict(p)
        item["_search_condition_cache"]={}
        item["_search_phrase_cache"]={}
        prepared.append(item)
    # 0.91: pull in every model's current card so switching the active
    # Vision model never hides the other models' work.
    try: _augment_search_context_with_all_models(prepared)
    except Exception: pass
    context={
        "source":projects,"prepared":prepared,"by_id":{p.get("id"):p for p in prepared},
        "signature":_search_data_signature(prepared),
        "fingerprint_loaded":sum(1 for p in prepared if p.get("fingerprint_used")),
        "completed":[],
    }
    _SEARCH_CONTEXT_CACHE[token]=context
    if len(_SEARCH_CONTEXT_CACHE)>_SEARCH_CONTEXT_CACHE_MAX:
        _SEARCH_CONTEXT_CACHE.pop(next(iter(_SEARCH_CONTEXT_CACHE)))
    return context


def _state_refines(previous:dict,current:dict)->bool:
    previous=previous or {}; current=current or {}
    old_time=_sanitize_project_time_filter(previous.get("time_filter"))
    new_time=_sanitize_project_time_filter(current.get("time_filter"))
    if old_time:
        # A top-N result is not a safe parent pool for a different refinement.
        if old_time.get("latest_limit") or not new_time:
            return False
        if old_time.get("start") and float(new_time.get("start") or 0.0)<float(old_time["start"]):
            return False
        if old_time.get("end") and (not new_time.get("end")
                or float(new_time["end"])>float(old_time["end"])):
            return False
    old_must=previous.get("must") or {}; new_must=current.get("must") or {}
    for key,values in old_must.items():
        old={canon(key,x) for x in values or []}; new={canon(key,x) for x in new_must.get(key,[]) or []}
        if old and (not new or not new.issubset(old)):
            return False
    old_banned=previous.get("must_not") or {}; new_banned=current.get("must_not") or {}
    for key,values in old_banned.items():
        old={canon(key,x) for x in values or []}; new={canon(key,x) for x in new_banned.get(key,[]) or []}
        if not old.issubset(new):
            return False
    old_sem={norm(x) for x in previous.get("semantic",[]) if norm(x)}
    new_sem={norm(x) for x in current.get("semantic",[]) if norm(x)}
    if not old_sem.issubset(new_sem):
        return False
    old_groups={json.dumps(x,ensure_ascii=False,sort_keys=True) for x in previous.get("exclude_groups",[]) or []}
    new_groups={json.dumps(x,ensure_ascii=False,sort_keys=True) for x in current.get("exclude_groups",[]) or []}
    return old_groups.issubset(new_groups)


def _remember_search_result(context:dict,state:dict,result,complete=True):
    if not complete:
        return
    ids={p.get("id") for group in result for p in group if p.get("id") is not None}
    rows=context.setdefault("completed",[])
    rows.append({"state":clone_state(state),"ids":ids})
    if len(rows)>48:
        del rows[:-48]


def _refined_search_pool(context:dict,state:dict):
    best=None
    for entry in context.get("completed",[]) or []:
        ids=entry.get("ids") or set()
        if len(ids)>=len(context.get("prepared") or []):
            continue
        if _state_refines(entry.get("state") or {},state):
            if best is None or len(ids)<len(best):
                best=ids
    if best is None:
        return context.get("prepared") or [],False
    return [p for p in context.get("prepared") or [] if p.get("id") in best],True


def _search_data_signature(projects:list[dict])->str:
    """Invalidates repeat-query caches when local facts or fingerprints change."""
    h=hashlib.sha1()
    for p in sorted(projects,key=lambda x:str(x.get("id",""))):
        stable={
            "id":p.get("id"), "project_key":p.get("project_key"),
            "source":p.get("source_signature"), "vision":p.get("vision_signature"),
            "vision_model":p.get("vision_model"), "facts":len(p.get("indexed_facts") or []),
            "manual":p.get("manual_labels") or {}, "learned":p.get("learned_predictions") or {},
            "excluded":p.get("learned_exclusions") or {}, "path":p.get("path_facts") or {},
            "fingerprint":p.get("_fingerprint_updated_at",0),
        }
        h.update(json.dumps(stable,ensure_ascii=False,sort_keys=True,default=str).encode("utf-8","ignore"))
        h.update(b"\n")
    return h.hexdigest()


def _search_cache_snapshot(result)->dict:
    def group(items):
        out=[]
        for item in items:
            meta={k:item.get(k) for k in _SEARCH_CACHE_META_KEYS if k in item}
            out.append({"id":item.get("id"),"meta":meta})
        return out
    return {"version":SEARCH_ALGORITHM_VERSION,"exact":group(result[0]),"candidates":group(result[1])}


def _restore_search_cache(saved,projects:list[dict]):
    if not isinstance(saved,dict) or saved.get("version")!=SEARCH_ALGORITHM_VERSION:
        return None
    by_id={str(p.get("id")):p for p in projects}
    def group(rows):
        if not isinstance(rows,list): raise ValueError("bad search cache")
        out=[]
        for row in rows:
            base=by_id.get(str((row or {}).get("id")))
            if base is None: raise ValueError("stale search cache")
            item=dict(base); item.update((row or {}).get("meta") or {}); out.append(item)
        return out
    try:
        return group(saved.get("exact")),group(saved.get("candidates"))
    except Exception:
        return None


def _attach_project_source_times(projects:list[dict]):
    """Read real source modification times from the existing local image index."""
    pending=[]
    for project in projects:
        try:
            existing=float(project.get("source_mtime") or 0.0)
        except (TypeError,ValueError,OverflowError):
            existing=0.0
        if existing>0:
            continue
        identity=(str(project.get("id") or ""),str(project.get("source_signature") or ""))
        if identity in _PROJECT_SOURCE_TIME_CACHE:
            project["source_mtime"]=_PROJECT_SOURCE_TIME_CACHE[identity]
        else:
            pending.append((identity,project))
    if not pending:
        return
    sources={}
    for _,project in pending:
        paths=project.get("image_paths") or project.get("representatives") or []
        if isinstance(paths,str):paths=[paths]
        for raw in paths:
            path=str(raw or "").strip()
            if path:sources.setdefault(path,[]).append(project)
    modified={}
    if sources:
        try:
            with closing(sqlite3.connect(str(IMAGE_DB_PATH),timeout=12)) as connection:
                paths=list(sources)
                for offset in range(0,len(paths),650):
                    chunk=paths[offset:offset+650]
                    placeholders=",".join("?" for _ in chunk)
                    rows=connection.execute(
                        f"SELECT path,mtime FROM images WHERE path IN ({placeholders})",chunk)
                    for path,mtime in rows:
                        try:modified[str(path)]=float(mtime or 0.0)
                        except (TypeError,ValueError,OverflowError):continue
        except (OSError,sqlite3.Error):
            modified={}
    for identity,project in pending:
        paths=project.get("image_paths") or project.get("representatives") or []
        if isinstance(paths,str):paths=[paths]
        timestamps=[]
        for raw in paths:
            path=str(raw or "").strip()
            stamp=float(modified.get(path) or 0.0)
            if stamp<=0:
                try:stamp=float(Path(path).stat().st_mtime)
                except OSError:continue
            if stamp>0 and np.isfinite(stamp):timestamps.append(stamp)
        project["source_mtime"]=max(timestamps,default=0.0)
        _PROJECT_SOURCE_TIME_CACHE[identity]=project["source_mtime"]
    if len(_PROJECT_SOURCE_TIME_CACHE)>100000:
        _PROJECT_SOURCE_TIME_CACHE.clear()

def search_projects(projects:list[dict],state:dict,ai:AIEngine|None=None):
    JAI_SEARCH_STATS.update({"index_used": False, "index_candidates": 0, "total_candidates": len(projects), "qwen_checked": 0,
                             "fingerprint_loaded": 0,"prefix_cache_used":False})
    context=_get_search_context(projects)
    prepared=context["prepared"]
    selected_time=_sanitize_project_time_filter(state.get("time_filter"))
    if selected_time:
        _attach_project_source_times(prepared)
    JAI_SEARCH_STATS["fingerprint_loaded"]=context["fingerprint_loaded"]

    # Быстрый повторный поиск: одинаковый запрос к неизменному индексу берём из кеша.
    try:
        cache_material=json.dumps(state, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        cache_material=str(state)
    cache_key=hashlib.sha1((f"search-v{SEARCH_ALGORITHM_VERSION}|"+cache_material+"|"+context["signature"]).encode("utf-8")).hexdigest()
    if cache_key in _SEARCH_RESULT_CACHE:
        JAI_SEARCH_STATS["qwen_checked"]=context["fingerprint_loaded"]
        return _SEARCH_RESULT_CACHE[cache_key]
    # Persistent cache: repeat queries after restart do not recalculate all projects.
    try:
        saved = AI_FINGERPRINT_CACHE.get_search(cache_key)
        restored=_restore_search_cache(saved,prepared)
        if restored is not None:
            _SEARCH_RESULT_CACHE[cache_key]=restored
            JAI_SEARCH_STATS["qwen_checked"]=context["fingerprint_loaded"]
            _remember_search_result(context,state,restored,complete=True)
            return restored
    except Exception:
        pass

    semantic_terms=state.get("semantic") or []
    qvec=None
    # Search must never cold-start OpenCLIP. Loading the visual model on the first text
    # request can take many seconds and looks exactly like a frozen app. If the model is
    # already warm (for example after image search), we may use it as a ranking bonus;
    # otherwise the indexed tags/path/text are enough for an instant response.
    if semantic_terms and ai is not None:
        if getattr(ai,"model",None) is not None:
            try:
                qvec=ai.encode_text("ювелирное изделие, "+", ".join(semantic_terms))
            except Exception:
                qvec=None
        else:
            try:
                _warm_text="ювелирное изделие, "+", ".join(semantic_terms)
                threading.Thread(
                    target=lambda t=_warm_text: _safe_warm_clip(ai,t),
                    daemon=True, name="jai-clip-warmup").start()
            except Exception:
                pass
    # v0.73: narrow the candidate pool through the persistent J-AI vector index
    search_pool,from_prefix=_refined_search_pool(context,state)
    if from_prefix:
        JAI_SEARCH_STATS["prefix_cache_used"]=True
        JAI_SEARCH_STATS["index_used"]=True
        JAI_SEARCH_STATS["index_candidates"]=len(search_pool)
    try:
        if qvec is not None and len(search_pool) > 500:
            if not JAI_VECTOR_INDEX.matches(prepared):
                JAI_VECTOR_INDEX.build(prepared)
            ids = JAI_VECTOR_INDEX.search_ids(qvec, 300)
            if ids:
                # ANN may discard a card whose manual/Qwen facts prove the request.
                # Keep every project that can still pass hard filters; only definite
                # rejects outside the nearest 300 are safe to omit.
                reduced=[]
                for p in search_pool:
                    if p.get("id") in ids or hard_match_project(p,state)[0] != "reject":
                        reduced.append(p)
                if reduced and len(reduced) < len(search_pool):
                    search_pool=reduced
                    JAI_SEARCH_STATS["index_used"] = True
                    JAI_SEARCH_STATS["index_candidates"] = len(reduced)
    except Exception:
        search_pool=prepared
    exact=[]; candidates=[]
    for p in search_pool:
        if selected_time:
            modified=float(p.get("source_mtime") or 0.0)
            if modified<=0:
                continue
            if selected_time.get("start") and modified<float(selected_time["start"]):
                continue
            if selected_time.get("end") and modified>=float(selected_time["end"]):
                continue
        if p.get("fingerprint_used"):
            JAI_SEARCH_STATS["qwen_checked"] += 1
        status,unknown,reasons,hard_score=hard_match_project(p,state)
        if status=="reject": continue
        # Ручная строка «Нет» сильнее мягкого CLIP/семантического сходства.
        if any(negative_tag_matches(p,t) for t in semantic_terms):
            continue
        sem=semantic_score(p,state,ai,qvec) if (semantic_terms or state.get("semantic_not")) else 0.0
        pref=preference_score(p,state)
        # Knowledge bonus is deliberately small: an unanalyzed project can still win from path/type evidence.
        knowledge=0.16 if project_is_currently_analyzed(p) else (0.07 if p.get("legacy_vision") else 0.0)
        item=dict(p); item["match_unknown"]=unknown; item["match_reasons"]=reasons
        context_bonus=candidate_context_bonus(p,state)
        item["semantic_score"]=sem; item["preference_score"]=pref; item["context_bonus"]=context_bonus
        ai_bonus = ai_tag_score(item, state)
        item["ai_tag_score"] = ai_bonus
        personal=0.0
        if _PERSONAL_WEIGHTS:
            for _k in reasons:
                for _v in project_actual(p,_k)[:2]:
                    personal+=_PERSONAL_WEIGHTS.get(_k+":"+_v,0.0)
        item["rank_score"]=hard_score + pref + sem*1.20 + ai_bonus + knowledge + context_bonus + personal - len(unknown)*0.10
        # Subjective terms should rank, not annihilate. Very poor semantics become candidates, not hard rejects.
        if semantic_terms and sem<0.06 and status=="exact":
            status="candidate"; item["match_unknown"]=list(item["match_unknown"])+["стиль"]
        (exact if status=="exact" else candidates).append(item)
    if selected_time.get("sort_desc"):
        exact.sort(key=lambda x:(float(x.get("source_mtime") or 0.0),
                                 x.get("rank_score",0),x.get("title","")),reverse=True)
        candidates.sort(key=lambda x:(float(x.get("source_mtime") or 0.0),
                                      x.get("rank_score",0),-len(x.get("match_unknown",[])),
                                      x.get("title","")),reverse=True)
    else:
        exact.sort(key=lambda x:(x.get("rank_score",0),x.get("title","")),reverse=True)
        candidates.sort(key=lambda x:(x.get("rank_score",0),-len(x.get("match_unknown",[])),x.get("title","")),reverse=True)
    if selected_time.get("latest_limit"):
        limit=int(selected_time["latest_limit"])
        exact=exact[:limit]
        candidates=candidates[:limit]
    result=(exact,candidates)
    _SEARCH_RESULT_CACHE[cache_key]=result
    # The pool can only omit projects already proven to be hard rejects, so this is
    # a complete result and is safe as the basis for refinements and persistent cache.
    _remember_search_result(context,state,result,complete=True)
    try:
        AI_FINGERPRINT_CACHE.save_search(cache_key, _search_cache_snapshot(result))
    except Exception:
        pass
    if len(_SEARCH_RESULT_CACHE)>_SEARCH_RESULT_CACHE_MAX:
        _SEARCH_RESULT_CACHE.pop(next(iter(_SEARCH_RESULT_CACHE)))
    return result

def similarity_projects(projects: list[dict], source: dict, limit=60, threshold_mode="auto"):
    """Визуально + по подтверждённым ювелирным признакам.

    Старый вариант смотрел только CLIP-вектор, поэтому рядом с детской подвеской могли оказаться
    кольца и кресты просто из-за похожего фона/рендера. 0.45 сохраняет визуальность, но сильно
    предпочитает тот же тип изделия и общие подтверждённые признаки.
    """
    vec = source.get("embedding")
    if vec is None:
        return []
    keys=("type","audience","subtype","material","metal","stones","stone_count","motif","openwork","enamel","mass","width")
    weights={"type":0.18,"audience":0.08,"subtype":0.10,"material":0.04,"metal":0.04,"stones":0.05,
             "stone_count":0.04,"motif":0.12,"openwork":0.05,"enamel":0.05,"mass":0.03,"width":0.03}
    exclusive={"type","audience","subtype","stones","stone_count","openwork","enamel","mass","width"}
    def facts(p,key):
        return {canon(key,v) for v,c,_ in project_evidence(p,key) if canon(key,v) and float(c or 0)>=0.70}
    sf={k:facts(source,k) for k in keys}
    out=[]
    for p in projects:
        if p["id"] == source["id"] or p.get("embedding") is None: continue
        visual=cosine(vec,p["embedding"]); score=visual
        for k in keys:
            a=sf.get(k) or set(); b=facts(p,k)
            if not a or not b: continue
            w=weights[k]
            if a & b: score += w
            elif k in exclusive: score -= w*0.75
        out.append((score,visual,p))
    out.sort(key=lambda x:(x[0],x[1]), reverse=True)
    # 0.97.2: limit<=0 — без обрезки, все визуально похожие.
    if limit and int(limit) > 0:
        out = out[:int(limit)]
    # 0.97.3: умная фильтрация по порогу схожести
    if threshold_mode not in ("off", "auto") and out: # 0.97.5: авто-порог больше не режет выдачу изнутри
        similarities = [score for score, visual, p in out]
        threshold = calculate_similarity_threshold(similarities, threshold_mode)
        if threshold > 0:
            full3 = list(out)
            out = [(s, v, p) for s, v, p in out if s >= threshold]
            if not out:
                out = [(s, v, p) for s, v, p in full3[:10]] if similarities else []
    return [dict(p, similarity=visual, smart_similarity=score) for score,visual,p in out]


def calculate_similarity_threshold(similarities, mode="auto"):
    """Автоматически определяет порог отсечения на основе распределения схожести.
    mode: 'auto' = умный поиск разрыва, 'strict' = высокий порог,
          'relaxed' = низкий порог, 'off' = без фильтра.
    """
    if not similarities or mode == "off":
        return 0.0
    import numpy as np
    arr = np.array(sorted(similarities, reverse=True))
    if mode == "strict":
        return 0.75
    elif mode == "relaxed":
        return 0.55
    if len(arr) < 10:
        return 0.60
    half = len(arr) // 2
    diffs = np.diff(arr[:half])
    if len(diffs) > 0:
        big_drop_idx = int(np.argmin(diffs))
        if diffs[big_drop_idx] < -0.08:
            return float(arr[big_drop_idx + 1]) + 0.02
    mean = float(np.mean(arr[:min(100, len(arr))]))
    std = float(np.std(arr[:min(100, len(arr))]))
    threshold = max(0.50, mean - std * 0.5)
    return min(0.85, threshold)


def image_query_projects(projects: list[dict], image_path: str, ai: AIEngine,
                         limit=60, text_hint: str = "", project_db=None, threshold_mode="auto"):
    """0.90: multi-vector max-similarity + optional image+text fusion."""
    q = ai.encode_image(image_path)
    hint=str(text_hint or "").strip()
    if hint:
        try:
            t_vec=ai.encode_text(hint)
            q=(q*0.75 + t_vec*0.25).astype(np.float32)
            n=float(np.linalg.norm(q))
            if n>1e-9: q=q/n
        except Exception:
            pass
    vectors_map={}
    if project_db is not None and hasattr(project_db,"representative_vectors_many"):
        try:
            vectors_map=project_db.representative_vectors_many(
                [p.get("id") for p in projects if p.get("id") is not None])
        except Exception:
            vectors_map={}
    # 0.98.0: одно матричное умножение + np.maximum.reduceat вместо цикла
    # по каждому проекту: representatives всех проектов складываются в одну матрицу.
    qf=np.asarray(q,dtype=np.float32).reshape(-1)
    qn=float(np.linalg.norm(qf))
    if qn>1e-12:
        qf=(qf/qn).astype(np.float32)
    keep=[]; mats=[]; sizes=[]
    for p in projects:
        pid=p.get("id")
        vecs=vectors_map.get(int(pid)) if pid is not None else None
        emb=None
        if vecs is not None and getattr(vecs,"size",0):
            emb=np.asarray(vecs,dtype=np.float32)
            if emb.ndim!=2 or int(emb.shape[1])!=int(qf.size):
                emb=None
        if emb is None and p.get("embedding") is not None:
            emb=np.asarray(p["embedding"],dtype=np.float32).reshape(1,-1)
        if emb is None or emb.ndim!=2 or int(emb.shape[1])!=int(qf.size):
            continue
        keep.append(p); mats.append(emb); sizes.append(int(emb.shape[0]))
    if not keep:
        out=[]
    else:
        M=np.vstack(mats)
        norms=np.linalg.norm(M,axis=1,keepdims=True)
        norms[norms<1e-12]=1.0
        M=(M/norms).astype(np.float32)
        sims=M @ qf
        starts=np.cumsum([0]+sizes)[:-1]
        grouped=np.maximum.reduceat(sims,starts)
        out=[(float(s),p) for s,p in zip(grouped,keep)]
    out.sort(key=lambda x:x[0], reverse=True)
    # 0.97.2: limit<=0 означает «без обрезки» — показываем все похожие.
    if limit and int(limit) > 0:
        out = out[:int(limit)]
    # 0.97.3: умная фильтрация по порогу схожести
    if threshold_mode not in ("off", "auto") and out: # 0.97.5: авто-порог больше не режет выдачу изнутри
        similarities = [s for s, p in out]
        threshold = calculate_similarity_threshold(similarities, threshold_mode)
        if threshold > 0:
            full = list(out)
            out = [(s, p) for s, p in out if s >= threshold]
            if not out:
                out = [(s, p) for s, p in full[:10]] if similarities else []
    return [dict(p, similarity=s) for s,p in out]


def qwen_rerank_projects(query_text, items, model, keep=0, batch=25, timeout=60):
    """0.90: listwise rerank of the head via local Qwen, one request."""
    query=str(query_text or "").strip()
    if not query or not items or not model:
        return items
    head=list(items[:max(1,int(batch))])
    tail=list(items[len(head):])
    if len(head)<2:
        return items
    lines=[]
    for i,p in enumerate(head,1):
        title=str(p.get("title") or "")[:70]
        cat=str(p.get("category") or "")[:30]
        desc=""
        v=p.get("vision") or {}
        if isinstance(v,dict):
            desc=str(v.get("description") or "")[:140]
        bits=[f"{i}. {title}"]
        if cat: bits.append(f"[{cat}]")
        if desc: bits.append(desc)
        lines.append(" ".join(bits))
    prompt=("Запрос пользователя: "+query+"\n\n"
            "Ниже пронумерованные ювелирные проекты. Верни ТОЛЬКО JSON вида "
            '{"order": [<номера от самого релевантного к менее релевантному>]}.\n\n'
            +"\n".join(lines))
    schema={"type":"object",
            "properties":{"order":{"type":"array","items":{"type":"integer"}}},
            "required":["order"]}
    try:
        data=ollama_chat_json(
            model,
            "Ты ранжируешь ювелирные проекты по релевантности запросу. "
            "Не пересказывай, только номер.",
            prompt, schema, timeout=timeout)
    except Exception:
        return items
    order=data.get("order") if isinstance(data,dict) else None
    if not isinstance(order,list):
        return items
    seen=set(); new_head=[]
    for raw in order:
        try: i=int(raw)-1
        except Exception: continue
        if 0<=i<len(head) and i not in seen:
            seen.add(i); new_head.append(head[i])
    for i,p in enumerate(head):
        if i not in seen:
            new_head.append(p)
    result=new_head+tail
    return result[:keep] if keep else result


def _ollama_reachable(timeout: float = 1.2) -> bool:
    try:
        with urllib.request.urlopen(OLLAMA_VERSION_URL, timeout=float(timeout)) as r:
            r.read(64)
        return True
    except Exception:
        return False


def _safe_warm_clip(ai, text: str) -> None:
    try: ai.encode_text(str(text or "ювелирное изделие"))
    except Exception: pass


def unsafe_index_root_message(root: Path) -> str:
    """Reject whole Linux system trees while still allowing Windows work-drive roots."""
    try:
        chosen=Path(root).expanduser().resolve()
    except Exception:
        return "Не удалось определить выбранную рабочую папку."
    if os.name!="nt":
        blocked={Path("/"),Path("/home"),Path("/usr"),Path("/var"),Path("/etc"),
                 Path("/run"),Path("/proc"),Path("/sys"),Path("/dev"),Path("/tmp")}
        if chosen in blocked:
            return (f"Выбрана системная папка {chosen}. Чтобы не просматривать весь компьютер, "
                    "укажи конкретную папку с ювелирными проектами.")
    return ""


def image_files_under(root: Path):
    root=Path(root)
    error=unsafe_index_root_message(root)
    if error:raise ValueError(error)
    real_root=root.resolve()
    for base, dirs, files in os.walk(root,topdown=True,followlinks=False):
        kept=[]
        for name in dirs:
            if name.startswith(".") or name.casefold() in INDEX_IGNORED_DIRS:
                continue
            candidate=Path(base)/name
            try:
                if candidate.is_symlink():
                    continue
                junction=getattr(candidate,"is_junction",None)
                if callable(junction) and junction():
                    continue
                if (candidate/"pyvenv.cfg").is_file():
                    continue
                resolved=candidate.resolve()
                resolved.relative_to(real_root)
                if os.name!="nt" and candidate.is_mount():
                    continue
            except (OSError,ValueError):
                continue
            kept.append(name)
        dirs[:] = sorted(kept, key=str.casefold)
        available = []
        for name in files:
            p=Path(base)/name
            if p.suffix.lower() not in INDEXABLE_EXTS:
                continue
            try:
                p.resolve().relative_to(real_root)
            except (OSError,ValueError):
                continue
            available.append(p)

        pictures = sorted((source for source in available
                           if source.suffix.lower() in IMAGE_EXTS),
                          key=lambda source: source.name.casefold())
        if pictures:
            # A real render/photo describes the project better than every
            # technical model in the same folder, regardless of its filename.
            yield from pictures
            continue

        # Distinct 3D files remain separate cards. Different formats of the same
        # named model collapse into STL -> Blender -> Rhino, without requiring
        # special letters, prefixes or preview suffixes in any filename.
        chosen = {}
        for source in sorted(available, key=lambda item: (
                MODEL_SOURCE_PRIORITY.get(item.suffix.lower(), 99),
                item.name.casefold(), str(item))):
            chosen.setdefault(source.stem.casefold(), source)
        yield from sorted(chosen.values(), key=lambda item: (
            MODEL_SOURCE_PRIORITY.get(item.suffix.lower(), 99),
            item.name.casefold(), str(item)))


def deep_model_files_under(root: Path):
    """Find every Blender/Rhino source, including folders represented by photos/STL."""
    root = Path(root)
    error = unsafe_index_root_message(root)
    if error:
        raise ValueError(error)
    real_root = root.resolve()
    for base, dirs, files in os.walk(root, topdown=True, followlinks=False):
        kept = []
        for name in dirs:
            if name.startswith(".") or name.casefold() in INDEX_IGNORED_DIRS:
                continue
            candidate = Path(base) / name
            try:
                if candidate.is_symlink():
                    continue
                junction = getattr(candidate, "is_junction", None)
                if callable(junction) and junction():
                    continue
                if (candidate / "pyvenv.cfg").is_file():
                    continue
                candidate.resolve().relative_to(real_root)
                if os.name != "nt" and candidate.is_mount():
                    continue
            except (OSError, ValueError):
                continue
            kept.append(name)
        dirs[:] = sorted(kept, key=str.casefold)
        for name in sorted(files, key=str.casefold):
            source = Path(base) / name
            if source.suffix.lower() not in BLENDER_EXTS | RHINO_EXTS:
                continue
            try:
                if source.is_symlink():
                    continue
                source.resolve().relative_to(real_root)
            except (OSError, ValueError):
                continue
            yield source


def parse_deepthink_request(text: str) -> dict | None:
    """Only explicit layer/inside requests can expose private hidden CAD cards."""
    original = str(text or "").strip()
    normalized = norm(original)
    if not normalized:
        return None
    model_context = bool(re.search(r"(?:blend(?:er)?|бленд\w*|3dm|rhino|рино|файл\w*)",
                                   normalized))
    layers_context = bool(re.search(r"(?:сло[йяеёи]\w*|коллекци\w*|вариант\w*|объект\w*|view\s*layer)",
                                    normalized))
    concealed = bool(re.search(r"(?:скрыт\w*|невидим\w*|отключ[её]\w*|неактив\w*)",
                               normalized))
    inside = bool(re.search(r"(?:внутри|внутренн\w*|вс[её]\s+сло\w*|друг\w+\s+сло\w*)",
                            normalized))
    deep_word = "deepthink" in normalized or "дипсинк" in normalized
    visible = bool(re.search(r"(?:активн\w*|видим\w*)", normalized))
    if visible and layers_context and not concealed and not inside:
        mode = "visible"
    elif (deep_word or (concealed and (layers_context or model_context or
                                      bool(re.search(r"(?:покаж|найд|найт|ищ)", normalized))))
          or (inside and model_context)):
        mode = "hidden"
    else:
        return None
    source_format = ("blend" if re.search(r"(?:blend(?:er)?|бленд\w*)", normalized)
                     else "3dm" if re.search(r"(?:3dm|rhino|рино)", normalized) else "")
    file_ids = []
    for match in re.finditer(r"(?<![\w])(?:[a-zа-яё][\w-]*\d[\w-]*|\d+[a-zа-яё][\w-]*)"
                             r"(?:\.(?:blend|3dm))?(?![\w])", normalized, re.IGNORECASE):
        identity = match.group(0)
        if identity not in {"3dm"} and identity not in file_ids:
            file_ids.append(identity)
    semantic = normalized
    for identity in file_ids:
        semantic = re.sub(r"(?<!\w)" + re.escape(identity) + r"(?!\w)", " ", semantic)
    semantic = re.sub(r"\b(?:покаж\w*|показ\w*|найд\w*|найт\w*|ищ\w*|остав\w*|"
                      r"посмотр\w*|откро\w*|открой\w*|что|которые|котор\w*|есть|"
                      r"вс[еёехи]*|только|внутри|внутренн\w*|скрыт\w*|невидим\w*|"
                      r"неактив\w*|отключ[её]\w*|активн\w*|видим\w*|сло[йяеёи]\w*|"
                      r"коллекци\w*|вариант\w*|объект\w*|файл\w*|blend(?:er)?|"
                      r"бленд\w*|3dm|rhino|рино|deepthink|view|layer|друг\w*)\b", " ", semantic)
    semantic = " ".join(word for word in semantic.split()
                        if word not in {"в", "во", "на", "из", "по", "у", "и", "с", "со", "для"})
    return {"mode": mode, "source_format": source_format,
            "file_ids": file_ids, "semantic": semantic}


def deep_variant_project(variant: dict, preview_path: Path | None = None) -> dict:
    source = Path(str(variant.get("source_path") or ""))
    label = str(variant.get("layer_name") or "Скрытый слой")
    objects = [str(value) for value in variant.get("object_names") or [] if str(value)]
    signature = str(variant.get("source_signature") or "") + "|" + str(variant.get("variant_key") or "")
    vision = dict(variant.get("vision") or {})
    current = bool(vision and int(variant.get("vision_version") or 0) >= PROJECT_VISION_VERSION)
    title = (str(variant.get("parent_title") or source.stem) + " · " + label).strip()
    project = {"id": -int(variant["variant_id"]), "_deep_variant": True,
               "_deep_variant_id": int(variant["variant_id"]),
               "_deep_parent_id": int(variant["project_id"]),
               "_deep_layer_name": label, "_deep_objects": objects,
               "_deep_source_format": str(variant.get("source_format") or ""),
               "root": str(variant.get("root") or ""), "project_key": "deep:" + signature,
               "folder": str(source), "client": str(variant.get("client") or ""),
               "category": str(variant.get("category") or ""), "title": title,
               "rel_folder": " ".join([str(variant.get("rel_folder") or ""),
                                        label, " ".join(objects)]).strip(),
               "image_count": 1, "image_paths": [str(source)],
               "representatives": [str(preview_path)] if preview_path is not None else [],
               "source_signature": signature,
               "embedding": variant.get("embedding"),
               "path_facts": path_facts(" ".join([source.stem, label] + objects)),
               "legacy_vision": {}, "legacy_count": 0, "vision": vision,
               "vision_model": str(variant.get("vision_model") or ""),
               "vision_version": int(variant.get("vision_version") or 0),
               "vision_signature": signature if current else "",
               "manual_labels": {}, "learned_predictions": {}, "learned_exclusions": {}}
    project["indexed_facts"] = compute_project_facts(project)
    evidence = {}
    for key, value, confidence, source_name in project["indexed_facts"]:
        evidence.setdefault(str(key), []).append((canon(str(key), str(value)),
                                                  float(confidence or 0), source_name))
    project["_evidence_map"] = evidence
    if current:
        tags = _qwen_tags_from_vision(vision)
        project.update({"qwen_used": True, "ai_tags": tags, "vision_json": vision,
                        "_qwen_text": _fingerprint_search_text(tags, vision),
                        "_qwen_evidence_map": _qwen_fingerprint_evidence(vision)})
    return project


def search_deep_variant_projects(variants: list[dict], request: dict,
                                 project_db: ProjectDB, ai: AIEngine | None = None,
                                 progress_cb=None) -> list[dict]:
    semantic = str(request.get("semantic") or "").strip()
    file_ids = [norm(value).removesuffix(".blend").removesuffix(".3dm")
                for value in request.get("file_ids") or []]
    chosen = []
    for variant in variants:
        if request.get("source_format") and variant.get("source_format") != request["source_format"]:
            continue
        if file_ids:
            searchable = norm(" ".join((Path(variant["source_path"]).stem,
                                        variant.get("parent_title") or "",
                                        variant.get("layer_name") or "")))
            if not all(identity in searchable for identity in file_ids):
                continue
        chosen.append(variant)
    if not chosen:
        return []
    query_vec = None
    if semantic and ai is not None:
        try:
            if progress_cb:
                progress_cb("DeepThink: сопоставляю скрытые объекты…")
            query_vec = ai.encode_text("ювелирное изделие, " + semantic)
        except Exception:
            query_vec = None
    state = blank_state()
    if semantic:
        try:
            plan = quick_plan(semantic, state)
            if plan and plan.get("action", "search") == "search":
                state = apply_plan(state, sanitize_plan(plan), state)
        except Exception:
            pass
        if not state.get("semantic"):
            state["semantic"] = [semantic]
    ranked = []
    for variant in chosen:
        project = deep_variant_project(variant)
        status, unknown, reasons, hard_score = hard_match_project(project, state)
        if status == "reject":
            continue
        score = semantic_score(project, state, ai, query_vec) if semantic else 0.0
        bonus = ai_tag_score(project, state) if semantic else 0.0
        project.update({"match_unknown": unknown, "match_reasons": reasons,
                        "semantic_score": score, "ai_tag_score": bonus,
                        "rank_score": hard_score + score * 1.2 + bonus
                                      + (0.16 if project_is_currently_analyzed(project) else 0)})
        if semantic and score < 0.035 and not bonus:
            continue
        ranked.append(project)
    ranked.sort(key=lambda item: (float(item.get("rank_score") or 0),
                                  item.get("title") or ""), reverse=True)
    for project in ranked:
        project["representatives"] = [str(project_db.materialize_deep_variant(
            int(project["_deep_variant_id"])))]
    return ranked


def deep_source_signature(source: Path) -> str:
    stat = Path(source).stat()
    return f"{int(stat.st_mtime_ns)}:{int(stat.st_size)}:deep{DEEPTHINK_INDEX_VERSION}"


def deep_source_parent_projects(projects: list[dict]) -> dict:
    exact = {}
    folders = {}
    stems = {}
    for project in projects:
        project_id = int(project["id"])
        folder = Path(str(project.get("folder") or ""))
        if folder.suffix.lower() in MODEL_EXTS:
            exact[os.path.normcase(str(folder))] = project_id
            stems.setdefault((os.path.normcase(str(folder.parent)),
                              folder.stem.casefold()), project_id)
        else:
            folders[os.path.normcase(str(folder))] = project_id
        for raw in project.get("image_paths") or []:
            path = Path(str(raw))
            if path.suffix.lower() in MODEL_EXTS:
                exact[os.path.normcase(str(path))] = project_id
                stems.setdefault((os.path.normcase(str(path.parent)),
                                  path.stem.casefold()), project_id)
    return {"exact": exact, "folders": folders, "stems": stems}


def deep_parent_project_id(source: Path, lookup: dict) -> int | None:
    source = Path(source)
    identity = os.path.normcase(str(source))
    parent = os.path.normcase(str(source.parent))
    value = (lookup["exact"].get(identity)
             or lookup["folders"].get(parent)
             or lookup["stems"].get((parent, source.stem.casefold())))
    return int(value) if value is not None else None


def _encode_deep_preview(image: Image.Image, ai: AIEngine) -> tuple[bytes, np.ndarray]:
    stream = BytesIO()
    image.convert("RGB").save(stream, format="PNG", optimize=True)
    payload = stream.getvalue()
    DEEP_PREVIEW_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(prefix="deep-index-", suffix=".png",
                                     dir=str(DEEP_PREVIEW_CACHE_DIR), delete=False) as temporary:
        temporary.write(payload)
        temporary_path = Path(temporary.name)
    try:
        embedding = ai.encode_image(str(temporary_path))
    finally:
        try:
            temporary_path.unlink()
        except OSError:
            pass
    return payload, np.asarray(embedding, dtype=np.float32).reshape(-1)


def index_deep_model_sources(root: Path, project_db: ProjectDB, ai: AIEngine,
                             status_cb=None, progress_cb=None) -> dict:
    status_cb = status_cb or (lambda text: None)
    progress_cb = progress_cb or (lambda done, total, name: None)
    sources = list(deep_model_files_under(root))
    project_db.prune_deep_sources(root, sources)
    lookup = deep_source_parent_projects(project_db.all(root, analyzed_only=False))
    pending = {}
    for source in sources:
        parent_id = deep_parent_project_id(source, lookup)
        if parent_id is None:
            continue
        try:
            signature = deep_source_signature(source)
        except OSError:
            continue
        if not project_db.deep_source_current(root, source, signature, parent_id):
            pending[str(source.resolve())] = {"source": source, "project_id": parent_id,
                                              "signature": signature}
    stats = {"sources": len(sources), "changed_sources": 0, "variants": 0,
             "total_variants": project_db.deep_inventory_count(root),
             "errors": 0, "first_errors": []}
    if not pending:
        return stats

    def fail(source_name, message):
        stats["errors"] += 1
        explanation = f"{Path(source_name).name}: {message}"
        if len(stats["first_errors"]) < 5:
            stats["first_errors"].append(explanation)
        status_cb("DeepThink: " + explanation)

    def save_result(source_name, result):
        entry = pending.get(str(Path(source_name).resolve()))
        if entry is None:
            return
        if result.get("error"):
            fail(source_name, result["error"])
            return
        ready = []
        for variant in result.get("variants") or []:
            try:
                image, embedding = _encode_deep_preview(variant["image"], ai)
                ready.append({key: value for key, value in variant.items() if key != "image"}
                             | {"preview_png": image, "embedding": embedding})
            except MissingVisualDependencyError:
                raise
            except Exception as error:
                fail(source_name, f"скрытый вариант {variant.get('label', '')}: {error}")
        source = entry["source"]
        count = project_db.replace_deep_source(root, entry["project_id"], source,
                    "blend" if source.suffix.lower() in BLENDER_EXTS else "3dm",
                    entry["signature"], result.get("inventory") or {}, ready,
                    bool(result.get("truncated")))
        stats["changed_sources"] += 1
        stats["variants"] += count

    blends = [entry["source"] for entry in pending.values()
              if entry["source"].suffix.lower() in BLENDER_EXTS]
    processed = 0
    if blends:
        def blend_progress(done, total, name):
            progress_cb(done, len(pending), name)
        results = extract_blender_deep_variants_batch(blends, status_cb, blend_progress,
                                                      result_cb=save_result)
        for source_name, result in results.items():
            if result.get("error"):
                # Blender-reported errors have already reached the streaming callback.
                if not any(Path(source_name).name in value for value in stats["first_errors"]):
                    fail(source_name, result["error"])
        processed += len(blends)
    for entry in pending.values():
        source = entry["source"]
        if source.suffix.lower() not in RHINO_EXTS:
            continue
        try:
            status_cb(f"DeepThink: проверяю скрытые слои Rhino · {source.name}")
            save_result(str(source.resolve()), extract_rhino_deep_variants(source))
        except MissingVisualDependencyError:
            raise
        except Exception as error:
            fail(str(source), error)
        processed += 1
        progress_cb(processed, len(pending), source.name)
    stats["total_variants"] = project_db.deep_inventory_count(root)
    return stats


def font_for_catalog(size=28):
    candidates = [
        r"C:\Windows\Fonts\arial.ttf", r"C:\Windows\Fonts\segoeui.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"
    ]
    for p in candidates:
        try:
            if Path(p).exists(): return ImageFont.truetype(p,size)
        except Exception: pass
    return ImageFont.load_default()


def _draw_catalog_pattern(draw: ImageDraw.ImageDraw, page_w: int, page_h: int):
    # Very light, almost watermark-like jewelry pattern: rings + earrings.
    ring="#EEF1F6"; faint="#F5F7FA"
    for y in range(44,page_h,225):
        for x in range(52,page_w,280):
            r=17
            draw.ellipse((x-r,y-r,x+r,y+r),outline=ring,width=2)
            draw.ellipse((x-r+7,y-r+7,x+r-7,y+r-7),outline=faint,width=1)
            ex=x+105
            draw.ellipse((ex-11,y-20,ex+11,y+2),outline=ring,width=2)
            draw.line((ex,y+2,ex,y+26),fill=ring,width=2)
            draw.ellipse((ex-10,y+20,ex+10,y+40),outline=ring,width=2)


def create_catalog(selected: list[dict], destination: str):
    if not selected:
        raise ValueError("Нет выбранных проектов")
    cell_w,cell_h=560,410; cols=2
    rows=(len(selected)+cols-1)//cols; margin=40
    page_w=margin*2+cols*cell_w; page_h=margin*2+rows*cell_h
    page=Image.new("RGB",(page_w,page_h),"#FBFCFE"); draw=ImageDraw.Draw(page)
    _draw_catalog_pattern(draw,page_w,page_h)
    for i,p in enumerate(selected):
        row,col=divmod(i,cols); x=margin+col*cell_w; y=margin+row*cell_h
        box=(x+12,y+12,x+cell_w-12,y+cell_h-12)
        draw.rounded_rectangle((box[0]+4,box[1]+5,box[2]+4,box[3]+5),radius=20,fill="#F0F2F6")
        draw.rounded_rectangle(box,radius=20,fill="#FFFFFF",outline="#E6EAF1",width=2)
        rep=(p.get("representatives") or p.get("image_paths") or [None])[0]
        if rep and Path(rep).exists():
            img=open_visual_image(rep)
            img.thumbnail((cell_w-80,cell_h-70),Image.Resampling.LANCZOS)
            ix=x+(cell_w-img.width)//2; iy=y+(cell_h-img.height)//2
            page.paste(img,(ix,iy))
    ext=Path(destination).suffix.lower()
    if ext==".pdf":page.save(destination,"PDF",resolution=150)
    else:page.save(destination,"JPEG",quality=95)


def _terminate_process_tree(proc, timeout=4.0):
    """Best-effort hard stop for a background worker and all of its descendants.
    On Windows a plain Popen.terminate() may leave the worker/native children alive;
    taskkill /T /F is much more reliable for this desktop-app use case.
    """
    if proc is None:
        return
    try:
        if proc.poll() is not None:
            return
    except Exception:
        return
    if os.name == "nt":
        try:
            flags=getattr(subprocess,"CREATE_NO_WINDOW",0)
            subprocess.run(["taskkill","/PID",str(proc.pid),"/T","/F"],
                           stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
                           timeout=max(1.0,float(timeout)),creationflags=flags,check=False)
        except Exception:
            try: proc.kill()
            except Exception: pass
    else:
        try: proc.terminate()
        except Exception: pass
    try:
        proc.wait(timeout=max(0.5,float(timeout)))
    except Exception:
        try: proc.kill()
        except Exception: pass
        try: proc.wait(timeout=1.0)
        except Exception: pass

# ---------------- Background worker process (0.50) ----------------

def _worker_emit(kind: str, **payload):
    """JSONL protocol between the heavyweight worker and the Tk GUI."""
    try:
        msg={"kind":kind, **payload}
        # PyInstaller workers on Windows can inherit a legacy OEM code page even
        # when the parent requests UTF-8. ASCII JSON survives every console/pipe
        # encoding; json.loads restores the original Cyrillic text in the GUI.
        print("JAI_EVENT "+json.dumps(msg,ensure_ascii=True,separators=(",",":")), flush=True)
    except Exception:
        pass




def run_background_worker(mode: str, root_s: str, extra_args: list[str] | None=None) -> int:
    """Heavy local work outside the GUI process.
    Small committed image batches preserve safe restart while avoiding SQLite overhead.
    """
    root=Path(root_s)
    extra_args=list(extra_args or [])
    image_db=ImageIndexDB(IMAGE_DB_PATH)
    project_db=ProjectDB(PROJECT_DB_PATH)
    def status(text):
        _worker_emit("status", text=str(text))
    try:
        if mode=="index":
            root_error=unsafe_index_root_message(root)
            if root_error:raise RuntimeError(root_error)
            _worker_emit("progress", pct=1.0, text=f"Сканирую выбранную папку: {root}")
            files=list(image_files_under(root))
            total=len(files)
            changed=skipped=errors=0
            first_errors=[]
            blend_count=sum(1 for path in files if path.suffix.lower() in BLENDER_EXTS)
            rhino_count=sum(1 for path in files if path.suffix.lower() in RHINO_EXTS)
            stl_count=sum(1 for path in files if path.suffix.lower() in STL_EXTS)
            model_count=sum(1 for path in files if path.suffix.lower() in MODEL_EXTS)
            ai=AIEngine(status)
            suffix=(f" · Blender: {blend_count}" if blend_count else "")
            if rhino_count:suffix+=f" · Rhino: {rhino_count}"
            if stl_count:suffix+=f" · STL: {stl_count}"
            _worker_emit("progress", pct=3.0, text=f"Проверяю изображения и 3D-модели: 0/{total}{suffix}")
            all_unchanged=(image_db.unchanged_many(files)
                           if callable(getattr(image_db,"unchanged_many",None))
                           else {path:image_db.unchanged(path) for path in files})
            model_unchanged={path:all_unchanged.get(path,False) for path in files
                             if path.suffix.lower() in MODEL_EXTS}
            refresh_models={path for path,current in model_unchanged.items()
                            if current and not _model_preview_cache_current(path)}
            if refresh_models:
                status(f"Обновляю улучшенные shaded-превью 3D-моделей: {len(refresh_models)}")
            changed_blends=[path for path in files
                            if path.suffix.lower() in BLENDER_EXTS
                            and (not model_unchanged[path] or path in refresh_models)]
            blend_failures={}
            if changed_blends:
                def blend_progress(done,count,name):
                    _worker_emit("progress",pct=3.0+12.0*done/max(1,count),
                                 text=f"Blender готовит превью: {done}/{count} · {name}")
                blend_failures=prepare_blend_previews_batch(changed_blends,status,blend_progress)
            waiting=[]
            batch_size=8
            aborted=False
            has_changed=any(not all_unchanged.get(path,False) or path in refresh_models
                            for path in files)
            choose_batch=getattr(ai,"preferred_image_batch_size",None)
            if has_changed and callable(choose_batch):
                try:
                    batch_size=max(1,min(32,int(choose_batch())))
                    status(f"Ускоренная индексация: {'GPU' if ai.device=='cuda' else 'CPU'} "
                           f"· пакет {batch_size} изображений")
                except Exception as error:
                    status(f"Пакетная индексация переключена на безопасный режим: {error}")
                    batch_size=1

            def remember_error(path,error):
                nonlocal errors,aborted
                errors+=1
                explanation=f"{path.name}: {error}"
                if errors<=5:
                    first_errors.append(explanation)
                    status(f"Не удалось обработать {explanation}")
                if isinstance(error,MissingVisualDependencyError):
                    status("Индексация остановлена: отсутствует общий компонент визуального поиска.")
                    aborted=True

            def flush_waiting():
                nonlocal changed,waiting
                current=waiting
                waiting=[]
                if not current or aborted:return
                encode_batch=getattr(ai,"encode_images",None)
                store_batch=getattr(image_db,"upsert_embeddings",None)
                if len(current)>1 and callable(encode_batch):
                    try:
                        embeddings=encode_batch([str(path) for path in current])
                        if len(embeddings)!=len(current):
                            raise RuntimeError("Визуальная модель вернула неполный пакет")
                        pairs=list(zip(current,embeddings))
                        if callable(store_batch):
                            store_batch(root,pairs)
                        else:
                            for path,embedding in pairs:
                                image_db.upsert_embedding(root,path,embedding)
                        changed+=len(current)
                        return
                    except MissingVisualDependencyError as error:
                        remember_error(current[0],error)
                        return
                    except Exception as error:
                        if "out of memory" in str(error).lower():
                            try:ai.torch.cuda.empty_cache()
                            except Exception:pass
                        status("Проверяю проблемный пакет по одному изображению…")
                for path in current:
                    if aborted:break
                    try:
                        embedding=ai.encode_image(str(path))
                        image_db.upsert_embedding(root,path,embedding)
                        changed+=1
                    except Exception as error:
                        remember_error(path,error)

            for i,path in enumerate(files,1):
                if all_unchanged.get(path,False) and path not in refresh_models:
                    skipped+=1
                else:
                    blend_error=blend_failures.get(str(path.resolve()))
                    if blend_error:
                        remember_error(path,RuntimeError(blend_error))
                    else:
                        waiting.append(path)
                    if len(waiting)>=batch_size:
                        flush_waiting()
                if i%5==0 or i==total:
                    if i==total:flush_waiting()
                    start=15.0 if changed_blends else 3.0
                    pct=start + ((75.0-start)*i/max(1,total))
                    _worker_emit("progress",pct=pct,text=f"Индексирую: {i}/{total} · новых {changed}")
                if aborted:break
            removed_sources=image_db.delete_missing_under(root,files)
            _worker_emit("progress", pct=76.0, text="Собираю проекты…")
            def proj_progress(done,ptotal,text):
                pct=76.0 + 14.0*done/max(1,ptotal)
                shown=str(text)
                if "/" not in shown:
                    shown=f"{shown}: {done}/{ptotal}"
                _worker_emit("progress",pct=pct,text=shown)
            n=sync_projects(root,image_db,project_db,status,proj_progress)
            deep_result = {"sources": 0, "changed_sources": 0, "variants": 0,
                           "total_variants": 0, "errors": 0, "first_errors": []}
            if bool(load_config().get("deepthink_enabled", False)):
                _worker_emit("progress", pct=90.0,
                             text="DeepThink: проверяю скрытые слои Blender и Rhino…")
                def deep_progress(done, count, name):
                    _worker_emit("progress", pct=90.0 + 8.0 * done / max(1, count),
                                 text=f"DeepThink: {done}/{count} · {name}")
                deep_result = index_deep_model_sources(root, project_db, ai, status, deep_progress)
            learn_result=None; learn_error=""
            if project_db.has_any_training_knowledge():
                try:
                    learning_start = 98.0 if bool(load_config().get("deepthink_enabled", False)) else 90.0
                    _worker_emit("progress",pct=learning_start,text="Применяю базовый учебник Jewelry AI…")
                    def lp(pct,text):
                        _worker_emit("progress",pct=learning_start+
                                     (100.0-learning_start)*float(pct)/100.0,text=str(text))
                    learn_result=project_db.train_local_jewelry_ai(root,progress_cb=lp)
                except Exception as e:
                    learn_error=str(e)
            _worker_emit("progress",pct=100.0,text="Индексация завершена")
            _worker_emit("done",mode=mode,changed=changed,skipped=skipped,errors=errors,projects=n,
                         scanned=total,blend_files=blend_count,rhino_files=rhino_count,
                         stl_files=stl_count,model_files=model_count,
                         compute_device=str(getattr(ai,"device","cpu")),
                         batch_size=batch_size,
                         removed_sources=removed_sources,
                         first_errors=first_errors,learn_result=learn_result,learn_error=learn_error,
                         deep_sources=deep_result["sources"],
                         deep_changed_sources=deep_result["changed_sources"],
                         deep_variants=deep_result["variants"],
                         deep_total_variants=deep_result["total_variants"],
                         deep_errors=deep_result["errors"],
                         deep_first_errors=deep_result["first_errors"])
            return 0
        if mode=="sync":
            _worker_emit("progress",pct=2.0,text="Собираю проекты из готового индекса…")
            def proj_progress(done,ptotal,text):
                shown=str(text)
                if "/" not in shown:
                    shown=f"{shown}: {done}/{ptotal}"
                _worker_emit("progress",pct=2.0+78.0*done/max(1,ptotal),text=shown)
            n=sync_projects(root,image_db,project_db,status,proj_progress)
            learn_result=None
            try:
                stats=project_db.learning_stats(root)
                if project_db.has_any_training_knowledge() and int(stats.get("predicted_projects",0) or 0)==0:
                    def lp(pct,text): _worker_emit("progress",pct=80.0+0.20*float(pct),text=str(text))
                    learn_result=project_db.train_local_jewelry_ai(root,progress_cb=lp)
            except Exception:
                learn_result=None
            _worker_emit("progress",pct=100.0,text="Подготовка базы завершена")
            _worker_emit("done",mode=mode,projects=n,learn_result=learn_result)
            return 0
        if mode=="train":
            _worker_emit("progress",pct=1.0,text="Переобучение: подготовка")
            result=project_db.train_local_jewelry_ai(root,progress_cb=lambda pct,text:_worker_emit("progress",pct=float(pct),text=str(text)))
            try: project_db.export_knowledge(root,AUTO_KNOWLEDGE_PATH)
            except Exception: pass
            _worker_emit("progress",pct=100.0,text="Переобучение завершено")
            _worker_emit("done",mode=mode,result=result)
            return 0
        if mode=="vision":
            model=(extra_args[0].strip() if extra_args else "") or DEFAULT_VISION_MODEL
            try:
                limit=int(extra_args[1]) if len(extra_args)>1 else 0
            except Exception:
                limit=0
            pending=project_db.pending_analysis(root,model)
            deep_pending=(project_db.pending_deep_analysis(root,model)
                          if bool(load_config().get("deepthink_enabled",False)) else [])
            if limit>0:
                pending=pending[:limit]
                deep_pending=deep_pending[:max(0,limit-len(pending))]
            total=len(pending)+len(deep_pending)
            if not total:
                _worker_emit("progress",pct=100.0,text=f"Vision-анализ: всё уже готово ({model})")
                _worker_emit("done",mode=mode,model=model,ok=0,errors=0,total=0,remaining=0)
                return 0
            _worker_emit("progress",pct=0.5,text=f"Проверяю запуск {model}…")
            try:
                ollama_probe_model(model,vision=True,timeout=90)
            except Exception as e:
                raise RuntimeError(f"{model} не запустилась: {friendly_model_error(str(e))}")
            ok=0; deep_ok=0; errors=0; last_error=""; checkpoint_ids=[]
            for i,pid in enumerate(pending,1):
                p=project_db.get(pid)
                if not p:
                    errors+=1; continue
                title=str(p.get("title") or "проект")
                pct=1.0 + 98.0*(i-1)/max(1,total)
                # 0.91.2: подставляем реальную модель, а не жёсткое "Qwen".
                _worker_emit("progress",pct=pct,
                             text=f"AI-анализ {model}: {i}/{total} · {title}")
                reps=project_vision_paths(p,3)
                if not reps:
                    errors+=1; last_error="У проекта нет доступных изображений."
                    continue
                try:
                    hints=project_db.manual_neighbor_hints(pid,limit=4)
                    try:
                        data=analyze_project_with_vision_model(reps,model,hints)
                    except Exception as first_error:
                        if is_model_start_error(str(first_error)):
                            raise
                        data=analyze_project_with_vision_model(reps[:1],model,hints)
                    project_db.set_vision(pid,data,model)
                    checkpoint_ids.append(int(pid))
                    ok+=1
                except Exception as e:
                    errors+=1; last_error=friendly_model_error(str(e))
                    if is_model_start_error(last_error):
                        raise RuntimeError(last_error)
                # Карточка каждого проекта уже сохранена в SQLite. Даже жёсткая остановка
                # не отбрасывает предыдущие результаты. Раз в 5 проектов сообщаем GUI,
                # чтобы новые карточки становились доступны поиску ещё до конца марафона.
                if i%5==0 or i==total:
                    _worker_emit("checkpoint",mode=mode,model=model,ok=ok,errors=errors,done=i,total=total,
                                 project_ids=list(checkpoint_ids))
                    checkpoint_ids=[]
            for offset,variant_id in enumerate(deep_pending,1):
                number=len(pending)+offset
                variant=project_db.deep_variant(variant_id)
                if variant is None:
                    errors+=1
                    continue
                title=str(variant.get("layer_name") or "скрытый слой")
                pct=1.0+98.0*(number-1)/max(1,total)
                # 0.91.2: реальная модель вместо жёсткого "Qwen".
                _worker_emit("progress",pct=pct,
                             text=f"DeepThink · AI-анализ {model}: {number}/{total} · {title}")
                try:
                    preview=project_db.materialize_deep_variant(variant_id)
                    hints=project_db.manual_neighbor_hints(int(variant["project_id"]),limit=4)
                    data=analyze_project_with_vision_model([str(preview)],model,hints)
                    project_db.set_deep_vision(variant_id,data,model)
                    deep_ok+=1
                except Exception as error:
                    errors+=1
                    last_error=friendly_model_error(str(error))
                    if is_model_start_error(last_error):
                        raise RuntimeError(last_error)
                if number%5==0 or number==total:
                    _worker_emit("checkpoint",mode=mode,model=model,ok=ok+deep_ok,
                                 errors=errors,done=number,total=total,project_ids=[])
            remaining=max(0,len(project_db.pending_analysis(root,model)))
            if bool(load_config().get("deepthink_enabled",False)):
                remaining+=len(project_db.pending_deep_analysis(root,model))
            _worker_emit("progress",pct=100.0,
                         text=f"Vision-анализ завершён · готово {ok+deep_ok}/{total}")
            _worker_emit("done",mode=mode,model=model,ok=ok,deep_ok=deep_ok,
                         errors=errors,total=total,remaining=remaining,last_error=last_error)
            return 0
        raise ValueError(f"Неизвестный worker mode: {mode}")
    except Exception as e:
        _worker_emit("error",mode=mode,message=str(e),traceback=traceback.format_exc())
        return 2

