    def _set_initial_chat_width(self):
        try:
            total=max(1000,self.winfo_width())
            _saved_sash=int(self.cfg.get("chat_sash") or 0)
            if _saved_sash>=400:
                self.main_pan.sashpos(0,min(_saved_sash,total-260))
            else:
                self.main_pan.sashpos(0,max(650,total-330))
        except Exception:
            pass

