    def start_interactive_guide(self):
        previous = getattr(self, "_interactive_guide", None)
        if previous is not None:
            previous.close()
        try:
            self.deiconify()
            self.lift()
            self.update_idletasks()
        except (AttributeError, tk.TclError):
            pass
        guide = InteractiveApplicationGuide(self, self._interactive_guide_steps())
        self._interactive_guide = guide
        try:
            guide.start()
        except (AttributeError, tk.TclError):
            guide.close()
            raise
        return guide

    # ---------- helpers ----------
    def begin_query_activity(self,text="Думаю над запросом…"):
        self._query_activity_token += 1
        self._active_query_token=self._query_activity_token
        self._query_started_at[self._active_query_token]=time.perf_counter()
        self.query_activity_var.set(str(text or "Думаю…"))
        try:
            self.query_activity.grid()
            self.query_progress.grid()
            self.query_progress.start(12)
            self.send_btn.configure(text="Стоп",state="normal")
        except Exception:
            pass
        return self._active_query_token

    def update_query_activity(self,text,token=None):
        if token is not None and token!=self._query_activity_token:
            return
        if self._chat_busy:
            try:self.query_activity_var.set(str(text or "Ищу…"))
            except Exception:pass

    def end_query_activity(self):
        try:
            self.query_progress.stop()
            self.query_progress.grid_remove()
            self.query_activity.grid_remove()
        except Exception:
            pass
        self.query_activity_var.set("")

    def cancel_chat_request(self):
        if not self._chat_busy:
            return
        # Python-поток/HTTP Ollama насильно не убиваем: просто инвалидируем его token.
        # Даже если старый ответ придёт позже, он уже не сможет изменить экран.
        self._query_started_at.pop(self._query_activity_token,None)
        self._local_lookup_context.pop(self._query_activity_token,None)
        self._query_activity_token += 1
        self._active_query_token=self._query_activity_token
        self._chat_busy=False
        self.end_query_activity()
        try:self.send_btn.configure(text="Найти",state="normal")
        except Exception:pass
        self.set_status("Запрос остановлен.")
        self.chat_append("AI","Запрос остановлен.","muted")

    def finish_chat_request(self,token=None):
        if token is not None and token!=self._query_activity_token:
            return
        self._query_started_at.pop(token if token is not None else self._query_activity_token,None)
        self._chat_busy=False
        try:self.send_btn.configure(text="Найти",state="normal")
        except Exception:pass
        self.end_query_activity()
        if not self._training_active:
            self.set_status("Готово.")

    def set_status(self,text): self.status_var.set(text)
    def set_status_threadsafe(self,text):
        try: self.after(0,lambda:self.status_var.set(text))
        except Exception: pass

    def set_chat_activity(self,text="",kind="work",auto_hide_ms=0):
        self._chat_activity_token += 1
        token=self._chat_activity_token
        msg=str(text or "").strip()
        if not msg:
            self.chat_activity_var.set("")
            try:
                self.chat_activity.grid_remove()
                self.chat_progress.grid_remove()
            except Exception:
                pass
            return
        palette={
            "train":("#FFF2CC","#8A5200"),
            "index":("#E8F0FE","#174EA6"),
            "vision":("#EDE7F6","#5E35B1"),
            "done":("#E6F4EA","#176B2C"),
            "error":("#FCE8E6","#B3261E"),
            "work":("#EEF1F4","#444444"),
        }
        bg,fg=palette.get(kind,palette["work"])
        self.chat_activity.configure(bg=bg,fg=fg)
        self.chat_activity_var.set(msg)
        self.chat_activity.grid()
        self.chat_progress.grid()
        if auto_hide_ms:
            def hide_if_same():
                if token==self._chat_activity_token:
                    self.set_chat_activity("")
            self.after(int(auto_hide_ms),hide_if_same)

    def _progress_watchdog_tick(self):
        """Keep the user informed even while the numeric percent rounds to the same value.

        This does not claim the worker is healthy: it explicitly shows how long ago the
        background process last sent a progress event. That makes a real stall obvious.
        """
        try:
            if self.heavy_work_active() and self._progress_base_activity:
                age=max(0,int(time.time()-float(self._progress_last_event_at or time.time())))
                msg=self._progress_base_activity
                if age>=2:
                    msg += f" · отклик {age}с назад"
                self.chat_activity_var.set(msg)
            self.after(1000,self._progress_watchdog_tick)
        except Exception:
            try: self.after(1500,self._progress_watchdog_tick)
            except Exception: pass

    def set_progress(self,done=0,total=0,text=""):
        total=max(0.0,float(total or 0)); done=max(0.0,float(done or 0))
        pct=(100.0*min(done,total)/total) if total else 0.0
        self.progress_var.set(pct)
        raw=str(text or "").strip()
        if not raw:
            self.progress_text_var.set("")
            self._progress_base_activity=""
            self._progress_activity_kind="work"
            self._progress_started_at=0.0
            self.set_chat_activity("")
            return
        label=raw
        # One decimal is intentional: on a 5k-project archive integer 80% can stay
        # on screen for hundreds of projects even though the worker is progressing.
        pct_text=("100%" if pct>=99.95 else f"{pct:.1f}%")
        if total and label:
            label=f"{label} — {pct_text}"
        self.progress_text_var.set(label)
        self._progress_last_event_at=time.time()
        if not self._progress_started_at or pct<=0.01:
            self._progress_started_at=self._progress_last_event_at
        low=norm(raw)
        base=""; kind="work"
        if raw:
            if "переобуч" in low or ("jewelry ai" in low and "уч" in low):
                if pct>=100 or "заверш" in low:
                    base=f"✓ Jewelry AI обучен — {pct_text}"; kind="done"
                else:
                    base=f"● Jewelry AI обучается — {pct_text}"; kind="train"
            elif ("индекс" in low or "подготовка папки" in low or "собираю проект" in low
                  or "сканир" in low or "проверяю изображ" in low or "применяю базовый учебник" in low):
                base=f"● Индексация — {pct_text}"; kind="index"
            elif "ai-анализ" in low or "проверяю запуск" in low:
                base=f"● Vision-анализ — {pct_text}"; kind="vision"
            else:
                base=f"● {raw} — {pct_text}"; kind="work"

            # Show the actual sub-stage after the percentage.  This is the part the
            # old UI threw away, e.g. 'Собираю проекты: 1480/5079'.
            detail=raw
            # Avoid pointless duplication for generic operation labels.
            generic={"индексация","подготовка базы","jewelry ai обучается","ai-анализ"}
            if norm(detail) not in generic and detail:
                base += f" · {detail}"
            self._progress_base_activity=base
            self._progress_activity_kind=kind
            auto_hide=5000 if kind=="done" else 0
            self.set_chat_activity(base,kind,auto_hide)

    def set_progress_threadsafe(self,done=0,total=0,text=""):
        try: self.after(0,lambda d=done,t=total,x=text:self.set_progress(d,t,x))
        except Exception: pass


    def heavy_work_active(self):
        local=bool(self.local_process and self.local_process.poll() is None)
        thread=bool(self.worker and self.worker.is_alive())
        return local or thread

    def _launch_local_worker(self, mode: str, root: Path, extra_args: list[str] | None=None):
        if self.heavy_work_active():
            messagebox.showinfo("Занято","Сейчас уже выполняется тяжёлая операция.")
            return False
        # Use CUDA whenever available; otherwise use normal CPU batch processing.
        if getattr(sys,"frozen",False):
            # PyInstaller executable dispatches worker mode through its own argv.
            args=[sys.executable,"--jai-worker",mode,str(root)]
        else:
            args=[sys.executable,str(Path(__file__).resolve()),"--jai-worker",mode,str(root)]
        if extra_args:
            args.extend(str(x) for x in extra_args)
        creationflags=0
        if os.name=="nt":
            creationflags=getattr(subprocess,"CREATE_NO_WINDOW",0)
        env=os.environ.copy()
        env["PYTHONUTF8"]="1"
        env["PYTHONIOENCODING"]="utf-8"
        try:
            proc=subprocess.Popen(args,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,
                                  text=True,encoding="utf-8",errors="replace",bufsize=1,
                                  creationflags=creationflags,env=env)
            self.local_process=proc
        except Exception as e:
            self.local_process=None
            messagebox.showerror("Фоновая операция",str(e)); return False
        self.local_process_kind=mode
        self.local_process_stopped=False
        self.set_busy(True)
        label={"index":"Индексация","sync":"Подготовка базы","train":"Jewelry AI обучается","vision":"Vision-анализ"}.get(mode,"Фоновая операция")
        self.set_progress(0,100,label)
        def reader(proc=proc):
            # Важно держать локальную ссылку на subprocess. Обработчик события done
            # очищает self.local_process в GUI-потоке, пока reader ещё дочитывает stdout.
            # Раньше из-за этого после успешного завершения возникало:
            # 'NoneType' object has no attribute 'wait'.
            got_done=False
            try:
                stream=proc.stdout
                if stream is not None:
                    for raw in stream:
                        line=raw.strip()
                        if not line.startswith("JAI_EVENT "):
                            continue
                        try: ev=json.loads(line[len("JAI_EVENT "):])
                        except Exception: continue
                        kind=ev.get("kind")
                        if kind=="progress":
                            pct=float(ev.get("pct",0) or 0); text=str(ev.get("text") or label)
                            self.after(0,lambda p=pct,t=text:self.set_progress(p,100,t))
                        elif kind=="status":
                            text=str(ev.get("text") or "")
                            self.after(0,lambda t=text:self.set_status(t))
                        elif kind=="checkpoint":
                            self.after(0,lambda e=ev,p=proc:self._local_worker_checkpoint(e,p))
                        elif kind=="done":
                            got_done=True
                            self.after(0,lambda e=ev,p=proc:self._local_worker_done(e,p))
                        elif kind=="error":
                            got_done=True
                            self.after(0,lambda e=ev,p=proc:self._local_worker_error(e,p))
                code=proc.wait()
                # Если это всё ещё текущий процесс и протокольного done/error не было,
                # значит worker действительно завершился неожиданно.
                if not got_done and self.local_process is proc and not self.local_process_stopped:
                    self.after(0,lambda c=code,p=proc:self._local_worker_error({"message":f"Фоновый процесс завершился с кодом {c}"},p))
            except Exception as e:
                if self.local_process is proc and not self.local_process_stopped:
                    self.after(0,lambda err=e,p=proc:self._local_worker_error({"message":str(err)},p))
        self.local_reader_thread=threading.Thread(target=reader,daemon=True)
        self.local_reader_thread.start()
        return True

    def _local_worker_checkpoint(self,ev,proc=None):
        # Во время длинного Qwen-марафона каждые несколько проектов обновляем
        # только кэш/счётчики. Поиск остаётся доступен и уже видит новые карточки.
        if proc is not None and self.local_process is not proc:
            return
        try:
            ids=ev.get("project_ids") or []
            root=self.current_root()
            if root and ids:
                self.project_db.refresh_cached_projects(root,ids)
            else:
                self.project_db.invalidate()
            self.update_counts()
        except Exception:
            pass

    def _play_completion_chime(self):
        try:
            if os.name=="nt":
                import winsound
                if not self._completion_sound_data:
                    self._completion_sound_data=make_completion_chime()
                # winsound explicitly rejects SND_MEMORY | SND_ASYNC. Keep the UI
                # responsive by playing the memory WAV synchronously in its own thread.
                flags=winsound.SND_MEMORY|getattr(winsound,"SND_NODEFAULT",0)
                data=self._completion_sound_data
                threading.Thread(target=lambda:winsound.PlaySound(data,flags),daemon=True,
                                 name="jai-completion-chime").start()
            else:
                self.bell()
        except Exception:
            pass

    def _local_worker_done(self,ev,proc=None):
        # Игнорируем запоздалое событие от уже заменённого/остановленного worker.
        if proc is not None and self.local_process is not proc:
            return
        mode=ev.get("mode") or self.local_process_kind
        self.local_process=None; self.local_process_kind=None
        self.set_busy(False); self.update_counts(); self.set_status("Готово.")
        if mode=="index":
            msg=f"Индекс готов · проектов {ev.get('projects',0)} · новых/изменённых {ev.get('changed',0)}"
            scanned=int(ev.get("scanned",0) or 0)
            blend_files=int(ev.get("blend_files",0) or 0)
            rhino_files=int(ev.get("rhino_files",0) or 0)
            stl_files=int(ev.get("stl_files",0) or 0)
            removed_sources=int(ev.get("removed_sources",0) or 0)
            errors=int(ev.get("errors",0) or 0)
            if blend_files:msg+=f" · Blender-файлов {blend_files}"
            if rhino_files:msg+=f" · Rhino 3DM {rhino_files}"
            if stl_files:msg+=f" · STL {stl_files}"
            deep_total=int(ev.get("deep_total_variants",0) or 0)
            deep_new=int(ev.get("deep_variants",0) or 0)
            deep_errors=int(ev.get("deep_errors",0) or 0)
            if deep_total or int(ev.get("deep_sources",0) or 0):
                msg+=f" · DeepThink: скрытых вариантов {deep_total}"
                if deep_new:msg+=f" (новых {deep_new})"
            if deep_errors:
                msg+=f" · ошибок DeepThink {deep_errors}"
            if removed_sources:msg+=f" · убрано устаревших дублей {removed_sources}"
            if errors:msg+=f" · не удалось обработать {errors}"
            if not scanned:
                msg+=("\nВ выбранной папке не найдено .blend, .3dm, .stl или изображений. "
                      "Проверь путь и расширения файлов.")
            elif errors:
                details=list(ev.get("first_errors") or [])
                if details:msg+="\nПричина: "+str(details[0])
            if deep_errors:
                details=list(ev.get("deep_first_errors") or [])
                if details:msg+="\nDeepThink: "+str(details[0])
            lr=ev.get("learn_result") or {}
            if lr: msg+=f" · Jewelry AI: {lr.get('predicted_projects',0)} проектов"
            self.chat_append("AI",msg,"muted" if errors or not scanned else "done")
            self._play_completion_chime()
            if describe_state(self.current_state)!="вся база":
                self.perform_state_search("обновлённая выборка",push=False)
            else:
                self.show_all_projects(push=True,chat=False)
        elif mode=="sync":
            if not self.history: self.show_all_projects(push=True,chat=False)
        elif mode=="train":
            completed_root=self._training_root or (str(self.current_root()) if self.current_root() else "")
            self._training_active=False; self._training_root=None
            # The worker owns another SQLite connection/process. Drop the GUI copy
            # so switched knowledge sources immediately affect the visible search.
            self.project_db.invalidate()
            result=ev.get("result") or {}
            device=(f"GPU · {result.get('device_name','CUDA')}" if result.get("compute_device")=="cuda" else "CPU")
            self.chat_append("AI",f"Обучение готово · примеров: {result.get('trained_projects',0)} · {device}","done")
            try:
                if describe_state(self.current_state)!="вся база": self.perform_state_search("обновлённая выборка",push=False)
                else: self.show_all_projects(push=False,chat=False)
            except Exception: self.refresh_cards()
            if completed_root:
                self._schedule_automatic_training_archives(Path(completed_root))
        elif mode=="vision":
            self.project_db.invalidate(); self.update_counts()
            ok=int(ev.get("ok",0) or 0); errors=int(ev.get("errors",0) or 0); remaining=int(ev.get("remaining",0) or 0)
            deep_ok=int(ev.get("deep_ok",0) or 0)
            self.chat_append("AI",f"Vision готов · новых карточек {ok}"
                             +(f" · скрытых DeepThink {deep_ok}" if deep_ok else "")
                             +(f" · ошибок {errors}" if errors else "")
                             +(f" · осталось {remaining}" if remaining else ""),"done")
            try:
                if self.current_state and describe_state(self.current_state)!="вся база": self.perform_state_search("обновлённая выборка",push=False)
                else: self.show_all_projects(push=False,chat=False)
            except Exception: self.refresh_cards()

    def _local_worker_error(self,ev,proc=None):
        # Запоздалая ошибка старого процесса не должна ломать новый процесс в GUI.
        if proc is not None and self.local_process is not proc:
            return
        self.local_process=None; self.local_process_kind=None
        self._training_active=False; self._training_root=None
        self.set_busy(False); self.update_counts()
        msg=str(ev.get("message") or "Неизвестная ошибка")
        self.set_chat_activity("✕ Ошибка фоновой операции","error",7000)
        self.chat_append("AI","Фоновая операция остановилась: "+msg,"ai")

    def current_root(self) -> Path | None:
        s=self.root_var.get().strip()
        if not s: return None
        p=Path(s)
        return p if p.exists() and p.is_dir() else None

    def update_counts(self):
        root=self.current_root()
        try: imgs=self.image_db.count(root) if root else self.image_db.count()
        except Exception: imgs=0
        if root:
            try:
                projs=self.project_db.count(root); analyzed=self.project_db.analyzed_count(root, self.vision_model_var.get().strip() or DEFAULT_VISION_MODEL); known=self.project_db.knowledge_count(root); facts=self.project_db.fact_count(root)
            except Exception: projs=analyzed=known=facts=0
        else: projs=analyzed=known=facts=0
        short_model=(self.vision_model_var.get().strip() or DEFAULT_VISION_MODEL)
        try:
            manual_projects,manual_facts=self.project_db.manual_stats(root) if root else (0,0)
            global_manual_projects,global_manual_facts=self.project_db.global_manual_stats()
            lstats=self.project_db.learning_stats(root) if root else {"predicted_projects":0}
        except Exception:
            manual_projects=manual_facts=global_manual_projects=global_manual_facts=0; lstats={"predicted_projects":0}
        self.count_var.set(
            f"Изображений: {imgs} | Проектов: {projs} | Ручных здесь: {manual_projects} | Базовый учебник: {global_manual_projects} | "
            f"Jewelry AI: {lstats.get('predicted_projects',0)} | {short_model}: {analyzed}/{projs}"
        )
        # Никогда автоматически не включаем «Только AI-разобранные»: при частичном анализе
        # это раньше незаметно сужало поиск, например с 61 проекта до 7.

    def set_busy(self,busy:bool):
        self.stop_btn.configure(state="normal" if busy else "disabled")
        try:
            self.index_btn.configure(state="disabled" if busy else "normal", text="Идёт операция…" if busy else "Обновить индекс")
        except Exception:
            pass
        if not busy:
            self.set_progress(0,0,"")

    def choose_root(self):
        if self.heavy_work_active():
            messagebox.showinfo("Операция идёт","Пока идёт обучение/индексация, можно искать и общаться в чате, но папку базы лучше не менять. Дождись завершения или нажми «Прервать».")
            return
        path=filedialog.askdirectory(title="Выберите папку с ювелирным архивом",initialdir=self.root_var.get() or None)
        if not path: return
        root_error=unsafe_index_root_message(Path(path))
        if root_error:
            messagebox.showwarning("Выбери папку с проектами",root_error)
            return
        self.root_var.set(path)
        self.cfg["root"]=path; save_config(self.cfg)
        self.new_search(clear_chat=False)
        self.startup_sync()

    def _restore_last_search_async(self):
        snapshot=load_last_search_snapshot()
        root=self.current_root()
        if not snapshot or not root:
            return
        stored=str(snapshot.get("root") or "")
        if os.path.normcase(os.path.normpath(stored))!=os.path.normcase(os.path.normpath(str(root))):
            return
        ids=list(snapshot.get("result_ids") or [])+list(snapshot.get("candidate_ids") or [])
        if not ids:
            return
        self._session_restore_pending=True
        def job():
            try:
                projects=self.project_db.projects_by_ids(root,ids)
                self.after(0,lambda rows=projects,snap=snapshot,expected=str(root):
                           self._apply_restored_last_search(rows,snap,expected))
            except Exception:
                try:self.after(0,lambda:setattr(self,"_session_restore_pending",False))
                except Exception:pass
        threading.Thread(target=job,daemon=True,name="jai-restore-session").start()

    def _apply_restored_last_search(self,projects,snapshot,expected_root):
        self._session_restore_pending=False
        root=self.current_root()
        if not root or str(root)!=str(expected_root):
            return
        if self.history and any(norm(x.get("query")) not in {"","вся база"} for x in self.history):
            return
        by_id={int(p["id"]):p for p in projects}
        results=[by_id[int(i)] for i in snapshot.get("result_ids",[]) if int(i) in by_id]
        candidates=[by_id[int(i)] for i in snapshot.get("candidate_ids",[]) if int(i) in by_id]
        if not results and not candidates:
            return
        self.history=[]; self.history_pos=-1
        self.current_state=clone_state(snapshot.get("state") or blank_state())
        self.current_candidates=candidates
        self.ai_only_var.set(bool(snapshot.get("ai_only",False)))
        self._restoring_last_search=True
        try:
            self.set_results(
                results,snapshot.get("title") or "Последний поиск",push=True,
                state=self.current_state,query=snapshot.get("query") or "последний поиск",
                visible_count=int(snapshot.get("visible_count") or self.limit_var.get()),
                display_formats=(snapshot.get("display_formats")
                                 if "display_formats" in snapshot else None),
            )
        finally:
            self._restoring_last_search=False
        query=str(snapshot.get("query") or snapshot.get("title") or "последний поиск")
        self.chat_append("AI",f"Восстановил последний поиск: «{query}» · проектов {len(results)}.","muted")

    def _startup_disk_revision(self):
        """0.95.0: фоновая ревизия при запуске, не чаще раза в 12 часов."""
        if not bool(self.cfg.get("auto_revision", True)):
            return
        try:
            last = float(self.cfg.get("last_revision_at") or 0.0)
        except Exception:
            last = 0.0
        if time.time() - last < 12 * 3600:
            return
        def job():
            try:
                removed, _ret = run_disk_revision(self.cfg)
                self.cfg["last_revision_at"] = time.time()
                save_config(self.cfg)
                if removed:
                    freed = sum(int(x[2] or 0) for x in removed)
                    self.after(0, lambda: self.chat_append(
                        "AI", "Ревизия диска при запуске: удалено устаревших копий %d (%s)."
                        % (len(removed), human_size(freed)), "muted"))
            except Exception:
                pass
        threading.Thread(target=job, daemon=True, name="jai-disk-revision").start()

    def _save_revision_settings(self, retention_vars):
        self.cfg["retention"] = {key: int(retention_vars[key].get()) for key in retention_vars}
        self.cfg["auto_revision"] = bool(self.auto_revision_var.get())
        save_config(self.cfg)

    def _schedule_startup_vacuum(self, retention_vars=None):
        self.cfg["vacuum_on_next_start"] = True
        if retention_vars:
            self._save_revision_settings(retention_vars)
        else:
            save_config(self.cfg)
        messagebox.showinfo("Ревизия диска",
            "Сжатие рабочих баз (VACUUM) выполнится при следующем запуске программы, "
            "до открытия баз. Первый запуск после этого может занять на минуту-две больше.")

    def _disk_usage_summary(self):
        out = {"system": 0, "knowledge": 0, "updates": 0, "previews": 0,
               "previews_local": 0}
        for directory in _archive_directories():
            for path in Path(directory).glob("Jewelry_AI_ЛИЧНЫЙ_ПОЛНЫЙ_РЕЗЕРВ_*.zip"):
                try: out["system"] += path.stat().st_size
                except OSError: pass
            for path in Path(directory).glob("Jewelry_AI_ЗНАНИЯ_ДЛЯ_ОБМЕНА_*.zip"):
                try: out["knowledge"] += path.stat().st_size
                except OSError: pass
        for path in Path(APPLICATION_UPDATE_DIR).rglob("*"):
            if path.is_file():
                try: out["updates"] += path.stat().st_size
                except OSError: pass
        for directory in (BLEND_PREVIEW_CACHE_DIR, RHINO_PREVIEW_CACHE_DIR,
                          STL_PREVIEW_CACHE_DIR, DEEP_PREVIEW_CACHE_DIR):
            for path in Path(directory).rglob("*"):
                if path.is_file():
                    try: out["previews"] += path.stat().st_size
                    except OSError: pass
        # 0.95.1: основной объём 3D-превью лежит рядом с проектами (J_AI_Preview),
        # а не в центральном кэше. Считаем его по базе, без обхода всего архива.
        try:
            for directory in self.project_db.distinct_model_preview_dirs():
                for path in directory.rglob("*"):
                    if path.is_file():
                        try:
                            out["previews_local"] += path.stat().st_size
                        except OSError:
                            pass
        except Exception:
            pass

        return out

    def _refresh_revision_info(self):
        def job():
            totals = self._disk_usage_summary()
            text = ("Резервы: %s · знания: %s · обновления: %s · "
                    "3D-превью: %s · кэш превью: %s"
                    % (human_size(totals["system"]), human_size(totals["knowledge"]),
                       human_size(totals["updates"]),
                       human_size(totals.get("previews_local", 0)),
                       human_size(totals["previews"])))
            self.after(0, lambda: self.revision_info_var.set(text))
        threading.Thread(target=job, daemon=True, name="jai-revision-info").start()

    def _preview_disk_revision(self, retention_vars):
        self._save_revision_settings(retention_vars)
        def job():
            removed, ret = run_disk_revision(self.cfg, dry_run=True)
            freed = sum(int(x[2] or 0) for x in removed)
            self.after(0, lambda: messagebox.showinfo(
                "Ревизия диска",
                "Будет удалено устаревших файлов: %d (%s).\n\n"
                "Личных резервов старше последних %d, архивов знаний старше %d,\n"
                "версий программы кроме последних %d и активной, кэш превью старше %d дней.\n"
                "Свежие копии и рабочие базы не трогаются.\n"
                "3D-превью рядом с проектами (папки J_AI_Preview) ревизия не удаляет — "
                "они ускоряют открытие карточек и хранятся вместе с архивом."
                % (len(removed), human_size(freed), ret["system"], ret["knowledge"],
                   ret["updates"], ret["preview_days"])))
        threading.Thread(target=job, daemon=True, name="jai-revision-preview").start()

    def _run_disk_revision_now(self, retention_vars):
        self._save_revision_settings(retention_vars)
        if not messagebox.askyesno(
                "Ревизия диска",
                "Удалить устаревшие резервные копии, старые версии обновлений и старый кэш превью сейчас?"):
            return
        def job():
            removed, _ret = run_disk_revision(self.cfg)
            freed = sum(int(x[2] or 0) for x in removed)
            self.after(0, lambda: (
                self.chat_append("AI", "Ревизия диска: удалено %d устаревших файлов (%s)."
                                 % (len(removed), human_size(freed)), "done"),
                self._refresh_revision_info()))
        threading.Thread(target=job, daemon=True, name="jai-revision-now").start()


    def startup_sync(self):
        self.update_counts()
        root=self.current_root()
        if not root or self.heavy_work_active(): return
        if self.cfg.pop("skip_startup_sync_once",False):
            save_config(self.cfg)
            try:
                count=self.project_db.count(root)
            except Exception:
                count=0
            if count:
                self.set_status(f"Резервная база подключена: {count} проектов без переиндексации.")
                if not self.history and not self._session_restore_pending:
                    self.show_all_projects(push=True,chat=False)
                return
        # 0.50: сборка проектов/применение Учебника идёт в ОТДЕЛЬНОМ процессе.
        # Даже на огромной базе Tk-интерфейс не должен получать «Не отвечает».
        self._launch_local_worker("sync",root)

    def _startup_done(self,n,learn_result=None):
        self.set_busy(False); self.update_counts(); self.set_status(f"Готово. Проектов V2: {n}.")
        if learn_result:
            self.chat_append("AI",f"Применил базовый учебник Jewelry AI к этой папке: прогнозов для {learn_result.get('predicted_projects',0)} проектов. Qwen не запускался.","ai")
        if not self.history:
            self.show_all_projects(push=True,chat=False)

    def stop_work(self):
        if self.local_process and self.local_process.poll() is None:
            self.local_process_stopped=True
            proc=self.local_process
            mode=self.local_process_kind
            _terminate_process_tree(proc)
            self.local_process=None; self.local_process_kind=None
            self._training_active=False; self._training_root=None
            self.set_busy(False); self.update_counts(); self.set_status("Остановлено.")
            if mode=="index":
                self.chat_append("AI","Индексация остановлена. Уже готовые изображения сохранены — следующий запуск продолжит с них.","done")
            elif mode=="vision":
                self.project_db.invalidate(); self.update_counts()
                self.chat_append("AI","Vision-анализ остановлен. Уже готовые карточки сохранены — потом продолжим со следующего проекта.","done")
            else:
                self.chat_append("AI","Фоновая операция остановлена.","done")
            return
        self.stop_event.set(); self.set_status("Останавливаю после текущей операции…")

    def _main_window_hwnd(self):
        if os.name!="nt":return 0
        try:
            from ctypes import wintypes
            user32=ctypes.windll.user32
            user32.GetAncestor.argtypes=[wintypes.HWND,wintypes.UINT]
            user32.GetAncestor.restype=wintypes.HWND
            self.update_idletasks()
            child=int(self.winfo_id())
            return int(user32.GetAncestor(wintypes.HWND(child),2) or child)  # GA_ROOT
        except Exception:
            return 0

    def _start_tray(self):
        if self._real_exit or os.name!="nt" or self._tray is not None:return
        try:
            self._tray=WindowsTrayIcon(self._tray_queue,self._main_window_hwnd(),APP_NAME)
            self._tray.start()
            self.after(120,self._check_tray_ready)
        except Exception:
            self._tray=None; self._tray_ready=False
            try:(APP_DIR/"tray_error.log").write_text(traceback.format_exc(),encoding="utf-8")
            except Exception:pass
            if self._startup_hidden_for_tray:
                self._startup_hidden_for_tray=False
                self.restore_from_tray()

    def _check_tray_ready(self):
        if self._real_exit or self._tray is None:return
        if self._tray.ready.is_set():
            self._tray_ready=True
            self._startup_hidden_for_tray=False
            # Only now change X from normal close to "hide to tray".
            # If tray creation ever fails, the app keeps the stable close behavior.
            try:self.protocol("WM_DELETE_WINDOW", self.hide_to_tray)
            except Exception:pass
            return
        if self._tray.failed.is_set() or not self._tray.is_alive():
            self._tray_ready=False
            if self._startup_hidden_for_tray:
                self._startup_hidden_for_tray=False
                self.restore_from_tray()
            return
        try:self.after(120,self._check_tray_ready)
        except Exception:pass

    def _poll_tray_commands(self):
        if self._real_exit:return
        latest_hover=None
        try:
            # Coalesce a burst of Explorer WM_MOUSEMOVE notifications. Only the
            # newest hover position matters; processing old queued positions was
            # able to start a stale delay after the popup had already disappeared.
            while True:
                cmd=self._tray_queue.get_nowait()
                if isinstance(cmd,tuple) and cmd and cmd[0]=="HOVER":
                    latest_hover=cmd
                    continue
                if cmd=="SHOW":
                    self._hide_tray_search_popup()
                    self.restore_from_tray()
                elif cmd=="TOGGLE":
                    self._hide_tray_search_popup()
                    self.toggle_from_tray()
                elif cmd=="EXIT":self.exit_app()
        except queue.Empty:
            pass
        except Exception:
            pass
        if latest_hover is not None:
            try:
                if len(latest_hover)>=8:
                    _,x,y,stamp,l,t,r,b=latest_hover[:8]
                    self._on_tray_hover(int(x),int(y),float(stamp),(int(l),int(t),int(r),int(b)))
                else:
                    _,x,y,stamp=latest_hover[:4]
                    self._on_tray_hover(int(x),int(y),float(stamp),None)
            except Exception:
                pass
        try:
            if not getattr(self,"_unified_poll_active",False):
                self.after(100,self._poll_tray_commands)
        except Exception:
            pass

    def _on_tray_hover(self,x:int,y:int,stamp:float|None=None,icon_rect=None):
        """Schedule/show the compact search box above the notification-area icon."""
        if self._real_exit or not self._tray_ready:return
        now=time.monotonic()
        event_at=float(stamp or now)
        # Ignore a mouse-move notification that sat in the cross-thread queue for
        # too long. This is the key fix for the old "appears every other hover" case.
        if now-event_at > 0.24:
            return
        self._tray_hover_last_at=event_at
        self._tray_hover_anchor=(int(x),int(y))
        if icon_rect and len(icon_rect)==4:
            try:self._tray_icon_rect=tuple(int(v) for v in icon_rect)
            except Exception:pass
        if self._tray_search_popup is not None:
            try:
                if self._tray_search_popup.winfo_exists():
                    self._position_tray_search_popup(x,y)
                    return
            except Exception:pass
            self._tray_search_popup=None; self._tray_search_entry=None
        if not self._tray_hover_active:
            self._tray_hover_active=True
            self._tray_hover_generation+=1
            generation=self._tray_hover_generation
            if self._tray_hover_show_after is not None:
                try:self.after_cancel(self._tray_hover_show_after)
                except Exception:pass
                self._tray_hover_show_after=None
            try:
                self._tray_hover_show_after=self.after(
                    int(self._tray_hover_delay_ms),
                    lambda g=generation:self._show_tray_search_popup_if_still_hovered(g)
                )
            except Exception:
                self._tray_hover_show_after=None
                self._tray_hover_active=False
            self._watch_pending_tray_hover(generation)

    def _pointer_over_tray_icon(self,extra=2):
        try:
            mx=int(self.winfo_pointerx()); my=int(self.winfo_pointery())
            rc=self._tray_icon_rect
            if rc and len(rc)==4:
                l,t,r,b=[int(v) for v in rc]
                return l-int(extra)<=mx<=r+int(extra) and t-int(extra)<=my<=b+int(extra)
            # Fallback for shells where Shell_NotifyIconGetRect is unavailable.
            ax,ay=self._tray_hover_anchor
            return abs(mx-int(ax))<=26 and abs(my-int(ay))<=26
        except Exception:
            return False

    def _watch_pending_tray_hover(self,generation:int):
        """Re-arm immediately if the pointer leaves before the popup is visible."""
        self._tray_hover_probe_after=None
        if self._real_exit or not self._tray_ready:return
        if generation!=self._tray_hover_generation or not self._tray_hover_active:return
        if self._tray_search_popup is not None:return
        # Poll the actual tray icon rectangle instead of relying on repeated mouse-move
        # notifications. A completely still pointer must still be a valid hover.
        if not self._pointer_over_tray_icon(extra=3):
            self._reset_tray_hover_arm(cancel_show=True)
            return
        try:self._tray_hover_probe_after=self.after(45,lambda g=generation:self._watch_pending_tray_hover(g))
        except Exception:self._tray_hover_probe_after=None

    def _show_tray_search_popup_if_still_hovered(self,generation=None):
        self._tray_hover_show_after=None
        if self._real_exit or not self._tray_ready:return
        if generation is not None and generation!=self._tray_hover_generation:return
        if not self._tray_hover_active:return
        if not self._pointer_over_tray_icon(extra=3):
            self._reset_tray_hover_arm(cancel_show=False)
            return
        x,y=self._tray_hover_anchor
        self._show_tray_search_popup(x,y)

    def _reset_tray_hover_arm(self,cancel_show=True):
        """Return hover detection to a clean state ready for the very next entrance."""
        self._tray_hover_generation+=1
        self._tray_hover_active=False
        self._tray_hover_last_at=0.0
        if cancel_show and self._tray_hover_show_after is not None:
            try:self.after_cancel(self._tray_hover_show_after)
            except Exception:pass
        self._tray_hover_show_after=None
        if self._tray_hover_probe_after is not None:
            try:self.after_cancel(self._tray_hover_probe_after)
            except Exception:pass
        self._tray_hover_probe_after=None

    def _tray_monitor_work_area(self,x:int,y:int):
        """Return (monitor_rect, work_rect) for the monitor containing the tray icon.
        rcWork is the Windows desktop area *excluding* the taskbar, which lets the
        popup sit cleanly against the taskbar edge instead of overlapping it.
        """
        if os.name=="nt":
            try:
                from ctypes import wintypes
                user32=ctypes.windll.user32
                class MONITORINFO(ctypes.Structure):
                    _fields_=[("cbSize",wintypes.DWORD),("rcMonitor",wintypes.RECT),("rcWork",wintypes.RECT),("dwFlags",wintypes.DWORD)]
                pt=wintypes.POINT(int(x),int(y))
                user32.MonitorFromPoint.argtypes=[wintypes.POINT,wintypes.DWORD]
                user32.MonitorFromPoint.restype=wintypes.HANDLE
                user32.GetMonitorInfoW.argtypes=[wintypes.HANDLE,ctypes.POINTER(MONITORINFO)]
                user32.GetMonitorInfoW.restype=wintypes.BOOL
                mon=user32.MonitorFromPoint(pt,2)  # MONITOR_DEFAULTTONEAREST
                mi=MONITORINFO(); mi.cbSize=ctypes.sizeof(MONITORINFO)
                if mon and user32.GetMonitorInfoW(mon,ctypes.byref(mi)):
                    mr=(int(mi.rcMonitor.left),int(mi.rcMonitor.top),int(mi.rcMonitor.right),int(mi.rcMonitor.bottom))
                    wr=(int(mi.rcWork.left),int(mi.rcWork.top),int(mi.rcWork.right),int(mi.rcWork.bottom))
                    return mr,wr
            except Exception:
                pass
        sw=max(1,int(self.winfo_screenwidth())); sh=max(1,int(self.winfo_screenheight()))
        return (0,0,sw,sh),(0,0,sw,sh)

    def _position_tray_search_popup(self,x:int,y:int):
        pop=self._tray_search_popup
        if pop is None:return
        try:
            w=388; h=76; gap=7
            (ml,mt,mr,mb),(wl,wt,wr,wb)=self._tray_monitor_work_area(x,y)

            # Detect which edge Windows reserved for the taskbar. Position the popup
            # just inside rcWork, like a native flyout, with a tiny breathing gap.
            bottom_taskbar = wb < mb
            top_taskbar = wt > mt
            right_taskbar = wr < mr
            left_taskbar = wl > ml

            if bottom_taskbar:
                px=int(x-w/2); py=wb-h-gap
            elif top_taskbar:
                px=int(x-w/2); py=wt+gap
            elif right_taskbar:
                px=wr-w-gap; py=int(y-h/2)
            elif left_taskbar:
                px=wl+gap; py=int(y-h/2)
            else:
                # Auto-hidden taskbar / unusual shell: fall back to the icon position,
                # but still keep the popup completely inside the monitor work area.
                px=int(x-w/2); py=int(y-h-gap) if y>(mt+mb)/2 else int(y+gap)

            px=max(wl+7,min(wr-w-7,px))
            py=max(wt+7,min(wb-h-7,py))
            pop.geometry(f"{w}x{h}+{px}+{py}")
        except Exception:pass

    def _show_tray_search_popup(self,x:int,y:int):
        if self._real_exit:return
        try:
            if self._tray_search_popup is not None and self._tray_search_popup.winfo_exists():
                self._position_tray_search_popup(x,y); return
        except Exception:pass
        try:
            pop=tk.Toplevel(self)
            self._tray_search_popup=pop
            pop.withdraw()
            pop.overrideredirect(True)
            try:pop.attributes("-topmost",True)
            except Exception:pass
            # Quiet Windows-style flyout: compact, softly translucent and clipped to
            # real rounded corners. There is deliberately no fade-out on mouse leave.
            try:pop.attributes("-alpha",0.01)
            except Exception:pass
            try:pop.configure(bg="#FFFFFF")
            except Exception:pass
            card=tk.Frame(pop,bg="#FFFFFF",bd=0,highlightthickness=0)
            card.pack(fill="both",expand=True)
            top=tk.Frame(card,bg="#FFFFFF")
            top.pack(fill="x",padx=13,pady=(7,1))
            tk.Label(top,text="Jewelry AI Search",bg="#FFFFFF",fg="#303846",font=("Segoe UI",8,"bold")).pack(side="left")
            tk.Label(top,text="поиск",bg="#FFFFFF",fg="#9AA2AE",font=("Segoe UI",7)).pack(side="left",padx=(6,0))
            row=tk.Frame(card,bg="#FFFFFF")
            row.pack(fill="x",padx=13,pady=(1,8))
            entry=tk.Entry(row,font=("Segoe UI",10),relief="flat",bd=0,highlightthickness=1,
                           highlightbackground="#E0E4EA",highlightcolor="#8AA7E8")
            self._tray_search_entry=entry
            entry.pack(side="left",fill="x",expand=True,ipady=4)
            entry.insert(0,"")
            btn=tk.Button(row,text="Найти",command=self._submit_tray_search,relief="flat",bd=0,
                          bg="#1F65E8",fg="#FFFFFF",activebackground="#1858D1",activeforeground="#FFFFFF",
                          font=("Segoe UI",8,"bold"),cursor="hand2",padx=11,pady=4)
            btn.pack(side="left",padx=(8,0))
            entry.bind("<Return>",lambda e:(self._submit_tray_search(),"break")[1])
            entry.bind("<Escape>",lambda e:(self._hide_tray_search_popup(),"break")[1])
            pop.bind("<Escape>",lambda e:(self._hide_tray_search_popup(),"break")[1])
            self._position_tray_search_popup(x,y)
            pop.deiconify(); pop.lift(); pop.update_idletasks()
            self._apply_tray_popup_rounding(pop, radius=18)
            self._fade_in_tray_search_popup(pop)
            # The point of this popup is zero extra clicks: after deliberate hover the user
            # can immediately type. A short hover delay above prevents accidental focus steals.
            try:entry.focus_force()
            except Exception:pass
            self._watch_tray_search_popup()
        except Exception:
            self._tray_search_popup=None; self._tray_search_entry=None
            try:(APP_DIR/"tray_search_error.log").write_text(traceback.format_exc(),encoding="utf-8")
            except Exception:pass

    def _apply_tray_popup_rounding(self,pop,radius=22):
        """Clip the borderless tray popup to real rounded corners on Windows."""
        if os.name!="nt" or pop is None:return
        try:
            hwnd=int(pop.winfo_id())
            w=max(1,int(pop.winfo_width())); h=max(1,int(pop.winfo_height()))
            gdi32=ctypes.windll.gdi32; user32=ctypes.windll.user32
            gdi32.CreateRoundRectRgn.argtypes=[ctypes.c_int,ctypes.c_int,ctypes.c_int,ctypes.c_int,ctypes.c_int,ctypes.c_int]
            gdi32.CreateRoundRectRgn.restype=ctypes.c_void_p
            user32.SetWindowRgn.argtypes=[ctypes.c_void_p,ctypes.c_void_p,ctypes.c_int]
            user32.SetWindowRgn.restype=ctypes.c_int
            rgn=gdi32.CreateRoundRectRgn(0,0,w+1,h+1,int(radius),int(radius))
            if rgn:
                # After successful SetWindowRgn Windows owns the region handle.
                if not user32.SetWindowRgn(hwnd,rgn,1):
                    try:gdi32.DeleteObject(rgn)
                    except Exception:pass
        except Exception:
            pass

    def _fade_in_tray_search_popup(self,pop):
        """Slow, restrained fade similar to native Windows tray flyouts/tooltips."""
        if self._tray_popup_fade_after is not None:
            try:self.after_cancel(self._tray_popup_fade_after)
            except Exception:pass
            self._tray_popup_fade_after=None
        # Starts almost invisible, then eases toward a deliberately translucent 88%.
        # ~270 ms total feels calm without making the search box sluggish.
        steps=(0.05,0.09,0.14,0.21,0.30,0.40,0.51,0.61,0.70,0.77,0.82,0.87,0.88)
        def step(i=0):
            self._tray_popup_fade_after=None
            if pop is not self._tray_search_popup:return
            try:
                if not pop.winfo_exists():return
                pop.attributes("-alpha",steps[i])
            except Exception:return
            if i+1<len(steps):
                try:self._tray_popup_fade_after=self.after(22,lambda:step(i+1))
                except Exception:self._tray_popup_fade_after=None
        step(0)

    def _pointer_in_tray_active_zone(self):
        """Tray icon + popup + the tiny bridge between them count as one hover zone."""
        try:
            mx=int(self.winfo_pointerx()); my=int(self.winfo_pointery())
            ax,ay=self._tray_hover_anchor
            if self._pointer_over_tray_icon(extra=3):
                return True
            pop=self._tray_search_popup
            if pop is None or not pop.winfo_exists():return False
            px=int(pop.winfo_rootx()); py=int(pop.winfo_rooty())
            pw=int(pop.winfo_width()); ph=int(pop.winfo_height())
            if px-2<=mx<=px+pw+2 and py-2<=my<=py+ph+2:
                return True
            # A tiny geometric bridge between the icon and the nearest popup edge keeps
            # the flyout alive only while the pointer crosses the physical gap. This works
            # for bottom/top/left/right taskbars without creating a large invisible zone.
            ax=int(ax); ay=int(ay)
            nx=max(px,min(px+pw,ax)); ny=max(py,min(py+ph,ay))
            left=min(ax,nx)-14; right=max(ax,nx)+14
            top=min(ay,ny)-14; bottom=max(ay,ny)+14
            return left<=mx<=right and top<=my<=bottom
        except Exception:
            return False

    def _pointer_inside_tray_popup(self):
        pop=self._tray_search_popup
        if pop is None:return False
        try:
            if not pop.winfo_exists():return False
            x=int(self.winfo_pointerx()); y=int(self.winfo_pointery())
            px=int(pop.winfo_rootx()); py=int(pop.winfo_rooty())
            pw=int(pop.winfo_width()); ph=int(pop.winfo_height())
            return px<=x<=px+pw and py<=y<=py+ph
        except Exception:return False

    def _watch_tray_search_popup(self):
        self._tray_popup_watch_after=None
        pop=self._tray_search_popup
        if pop is None:return
        try:
            if not pop.winfo_exists():
                self._tray_search_popup=None; self._tray_search_entry=None; return
        except Exception:return
        # Pointer ownership is strict now: as soon as the mouse leaves the icon/popup
        # active zone, hide immediately. Keyboard focus or already typed text does not keep
        # the popup alive against a mouse-leave — exactly like a lightweight tray flyout.
        if not self._pointer_in_tray_active_zone():
            self._hide_tray_search_popup(); return
        try:self._tray_popup_watch_after=self.after(35,self._watch_tray_search_popup)
        except Exception:self._tray_popup_watch_after=None

    def _hide_tray_search_popup(self):
        # Fully re-arm hover before destroying the flyout. This makes the next
        # entrance independent from any timer/event belonging to the previous one.
        self._reset_tray_hover_arm(cancel_show=True)
        if self._tray_popup_watch_after is not None:
            try:self.after_cancel(self._tray_popup_watch_after)
            except Exception:pass
            self._tray_popup_watch_after=None
        if self._tray_popup_fade_after is not None:
            try:self.after_cancel(self._tray_popup_fade_after)
            except Exception:pass
            self._tray_popup_fade_after=None
        pop=self._tray_search_popup
        self._tray_search_popup=None; self._tray_search_entry=None
        if pop is not None:
            try:pop.destroy()
            except Exception:pass

    def _submit_tray_search(self):
        entry=self._tray_search_entry
        try:text=entry.get().strip() if entry is not None else ""
        except Exception:text=""
        if not text:return
        self._hide_tray_search_popup()
        self.restore_from_tray()
        def run():
            if self._real_exit:return
            try:
                # Tray entry is intentionally a fresh search, not a refinement of a hidden old one.
                self.new_search(clear_chat=False)
                if self._chat_busy:
                    self.chat_entry.delete(0,"end"); self.chat_entry.insert(0,text)
                    self.chat_append("AI","Текущий запрос ещё выполняется. Новый запрос уже поставлен в строку поиска.","muted")
                    return
                self.chat_entry.delete(0,"end"); self.chat_entry.insert(0,text)
                self.send_chat()
            except Exception:
                try:(APP_DIR/"tray_search_error.log").write_text(traceback.format_exc(),encoding="utf-8")
                except Exception:pass
        try:self.after(90,run)
        except Exception:run()

    def _watch_minimized_for_tray(self):
        if self._real_exit:return
        try:
            if self._tray_ready and not self._tray_hidden and self.state()=="iconic":
                self._tray_hidden=True
                self.withdraw()
        except Exception:pass
        try:self.after(260,self._watch_minimized_for_tray)
        except Exception:pass

    def hide_to_tray(self):
        if self._real_exit:return
        self._hide_tray_search_popup()
        if getattr(self,"_interactive_guide",None) is not None:
            self._interactive_guide.close()
        if self._tray_ready:
            try:
                self._tray_hidden=True
                self.withdraw()
                return
            except Exception:
                self._tray_hidden=False
        # Failsafe: if tray is unavailable, never make the app unreachable.
        try:self.iconify()
        except Exception:pass

    def restore_from_tray(self):
        if self._real_exit:return
        self._hide_tray_search_popup()
        try:
            self.deiconify(); self.state("normal"); self.update_idletasks(); self.lift()
            try:self.focus_force()
            except Exception:pass
        except Exception:pass
        self._tray_hidden=False

    def toggle_from_tray(self):
        """Single left click on tray icon toggles the main window."""
        if self._real_exit:return
        try:state=str(self.state() or "")
        except Exception:state=""
        if self._tray_hidden or state in ("withdrawn","iconic"):
            self.restore_from_tray()
        else:
            self.hide_to_tray()

    def exit_app(self):
        if self._real_exit:return
        self._hide_tray_search_popup()
        if getattr(self,"_interactive_guide",None) is not None:
            self._interactive_guide.close()
        self._real_exit=True
        try:
            if self._tray:self._tray.stop()
        except Exception:pass
        try:self._thumb_stop.set()
        except Exception:pass
        self.cfg["root"]=self.root_var.get().strip(); self.cfg["vision_model"]=self.vision_model_var.get().strip(); self.cfg["chat_model"]=self.chat_model_var.get().strip(); self.cfg["result_limit"]=self.limit_var.get(); self.cfg["ui_theme"]=self.theme_name
        self.cfg["display_formats"]=[value for value in DISPLAY_SOURCE_FORMATS
                                     if value in self._enabled_display_formats()]
        self.cfg["deepthink_enabled"]=bool(self.deepthink_var.get())
        # 0.98.3: запоминаем окно, разделитель чата и диагностику.
        try:
            if self.state()=="zoomed":
                self.cfg["window_state"]="zoomed"
            else:
                self.cfg["window_state"]="normal"
                self.cfg["window_geometry"]=self.geometry()
            self.cfg["chat_sash"]=int(self.main_pan.sashpos(0))
            self.cfg["diagnostic"]=bool(self.diagnostic_var.get())
        except Exception:
            pass
        save_config(self.cfg)
        if self.local_process and self.local_process.poll() is None:
            self.local_process_stopped=True
            proc=self.local_process
            _terminate_process_tree(proc)
            self.local_process=None; self.local_process_kind=None
        try:self.destroy()
        except Exception:pass

    def on_close(self):
        # Compatibility for older internal calls. Hide only when a real tray exists.
        if self._tray_ready:self.hide_to_tray()
        else:self.exit_app()

    # ---------- index / analysis ----------
    def start_index(self):
        root=self.current_root()
        if not root:
            messagebox.showwarning("Папка базы","Сначала выбери папку базы."); return
        root_error=unsafe_index_root_message(root)
        if root_error:
            messagebox.showwarning("Выбери папку с проектами",root_error); return
        if self.heavy_work_active():
            messagebox.showinfo("Занято","Сейчас уже выполняется тяжёлая операция."); return
        message=f"Обновляю индекс только в папке: {root}. Уже готовые изображения будут пропущены."
        if self.deepthink_var.get():
            message+=" DeepThink дополнительно проверит скрытые слои Blender и Rhino."
        self.chat_append("AI",message,"ai")
        self._launch_local_worker("index",root)

    def _index_done(self,changed,skipped,errors,n,learn_result=None,learn_error=""):
        self.set_busy(False); self.update_counts(); self.set_status("Готово.")
        msg=f"Индекс готов · проектов {n} · новых/изменённых {changed}"
        if errors:msg+=f" · не удалось обработать {errors}"
        if learn_result:
            msg += f" · Jewelry AI применён к {learn_result.get('predicted_projects',0)} проектам"
        elif learn_error:
            msg += " · Jewelry AI не применён"
        self.chat_append("AI",msg,"ai")
        self._play_completion_chime()
        if describe_state(self.current_state)!="вся база":
            self.perform_state_search("обновлённая выборка",push=False)
        else:
            self.show_all_projects(push=True,chat=False)

    def ask_analysis(self):
        root=self.current_root()
        if not root:
            messagebox.showwarning("Папка базы","Сначала выбери папку базы."); return
        model=self.vision_model_var.get().strip() or DEFAULT_VISION_MODEL
        try:
            installed=ollama_installed_models()
        except Exception as e:
            messagebox.showerror("Локальный AI",str(e)); return
        if not ollama_model_is_installed(model,installed):
            if messagebox.askyesno("Модель не скачана",f"Vision-модель {model} пока не установлена в Ollama.\n\nОткрыть окно моделей и скачать её?"):
                self.open_ai_settings()
            return
        pending=self.project_db.pending_analysis(root, model)
        deep_pending=(self.project_db.pending_deep_analysis(root,model)
                      if bool(self.deepthink_var.get()) else [])
        if not pending and not deep_pending:
            messagebox.showinfo("AI-анализ",f"Все текущие проекты уже разобраны моделью {model}.\nМожно выбрать другую Vision-модель в «Модели / скачать…» и сравнить результат."); return
        deep_details=(f"\nСкрытых вариантов DeepThink: {len(deep_pending)}. "
                      "Анализ займёт больше времени." if deep_pending else "")
        ans=messagebox.askyesnocancel(
            "AI-анализ проектов",
            f"Vision-модель: {model}\nНе разобрано этой моделью: {len(pending)} проектов."
            f"{deep_details}\n\nДа — запустить В ФОНЕ и анализировать до остановки/конца базы.\n"
            "Нет — только следующие 20 (тоже в фоне).\nОтмена — ничего не делать.\n\n"
            "Каждая готовая карточка сохраняется сразу. Можно продолжать искать в архиве."
        )
        if ans is None: return
        limit=0 if ans else 20
        self.start_background_vision(model,limit)

    def start_background_vision(self, model: str, limit: int=0):
        root=self.current_root()
        if not root:
            return
        if self.heavy_work_active():
            messagebox.showinfo("Занято","Сейчас уже выполняется тяжёлая операция.")
            return
        mode_text="до остановки" if int(limit or 0)<=0 else f"следующие {int(limit)}"
        self.chat_append("AI",f"Vision запущен в фоне · {model} · {mode_text}.","ai")
        self._launch_local_worker("vision",root,[model,str(int(limit or 0))])

    def start_project_analysis(self,ids:list[int]):
        if self.heavy_work_active():
            messagebox.showinfo("Занято","Сейчас уже выполняется тяжёлая операция."); return
        model=self.vision_model_var.get().strip() or DEFAULT_VISION_MODEL
        self.stop_event.clear(); self.set_busy(True)
        self.chat_append("AI",f"AI-анализ: {len(ids)} проектов.","ai")
        def job():
            ok=0; err=0; last_error=""
            try:
                # Сначала проверяем, что runner выбранной модели вообще запускается.
                # Иначе старое поведение за секунды набирало 20/20 ошибок и выглядело как «очень быстрая Llama».
                try:
                    self.set_status_threadsafe(f"Проверяю запуск {model}…")
                    ollama_probe_model(model, vision=True, timeout=90)
                except Exception as e:
                    last_error=friendly_model_error(str(e))
                    self.after(0,lambda e=last_error:self._analysis_probe_failed(model,e))
                    return
                for i,pid in enumerate(ids,1):
                    if self.stop_event.is_set(): break
                    p=self.project_db.get(pid)
                    if not p: continue
                    reps=project_vision_paths(p,3)
                    if not reps:
                        err+=1; last_error="У проекта нет доступных изображений."; continue
                    self.set_status_threadsafe(f"{model}: проект {i}/{len(ids)} — {p.get('title','')}")
                    self.set_progress_threadsafe(i-1,len(ids),f"AI-анализ {i}/{len(ids)}")
                    try:
                        hints=self.project_db.manual_neighbor_hints(pid,limit=4)
                        try:
                            data=analyze_project_with_vision_model(reps,model,hints)
                        except Exception as first_error:
                            # Если конкретная пачка ракурсов дала пустой/битый JSON, один раз пробуем
                            # самый репрезентативный кадр. Это часто спасает проект без маскировки ошибок модели.
                            if is_model_start_error(str(first_error)):
                                raise
                            data=analyze_project_with_vision_model(reps[:1],model,hints)
                        self.project_db.set_vision(pid,data,model); ok+=1
                    except Exception as e:
                        err+=1; last_error=friendly_model_error(str(e))
                        if is_model_start_error(last_error):
                            break
                    finally:
                        self.set_progress_threadsafe(i,len(ids),f"AI-анализ {i}/{len(ids)}")
                self.after(0,lambda:self._analysis_done(ok,err,model,last_error))
            except Exception as e:
                tb=traceback.format_exc(); self.after(0,lambda e=e,tb=tb:self._worker_error("Ошибка AI-анализа",e,tb))
        self.worker=threading.Thread(target=job,daemon=True); self.worker.start()

    def _analysis_probe_failed(self,model,error):
        self.set_busy(False); self.project_db.invalidate(); self.update_counts(); self.set_status("Модель не запустилась.")
        self.chat_append("AI",f"AI-анализ НЕ начинался. {model} скачана, но не смогла запуститься в Ollama. {friendly_model_error(error)} Старые AI-карточки оставлены как были.","ai")
        messagebox.showerror("Vision-модель не запустилась",f"{model} не удалось запустить.\n\n{friendly_model_error(error)}\n\nНи один проект этой моделью не проанализирован.")

    def _analysis_done(self,ok,err,model="",last_error=""):
        self.set_busy(False); self.ai_only_var.set(False); self.project_db.invalidate(); self.update_counts()
        self.set_status("Готово.")
        if ok==0 and err:
            msg=f"AI-анализ {model or 'Vision-моделью'} не дал ни одной новой карточки: 0 успешно, ошибок {err}. Старые карточки других моделей не потеряны."
        else:
            msg=f"AI-анализ {model or 'Vision-моделью'} завершён: проектов разобрано {ok}, ошибок {err}. Результат этой модели сохранён отдельно — старые карточки других моделей не потеряны."
        if err and last_error:
            msg += f" Последняя ошибка: {friendly_model_error(last_error)}"
        self.chat_append("AI",msg,"ai")
        if ok:
            # Не выкидываем пользователя в отдельный режим из нескольких проектов.
            if self.current_state and describe_state(self.current_state)!="вся база": self.perform_state_search("обновлённая выборка",push=False)
            else: self.show_all_projects(push=False,chat=False)

    def _worker_error(self,title,e,tb=""):
        if "обуч" in norm(title):
            self._training_active=False; self._training_root=None
            self.set_chat_activity("✕ Ошибка обучения", "error", 7000)
        self.set_busy(False); self.set_status("Ошибка.")
        self.chat_append("AI",f"{title}: {e}","ai")
        if self.diagnostic_var.get() and tb:
            self.chat_append("AI",tb,"muted")

    # ---------- settings / db ----------
    def open_ai_settings(self):
        win=tk.Toplevel(self)
