        ttk.Label(intro,text="Vision — смотрит проекты:").grid(row=0,column=0,sticky="w",padx=(0,8),pady=3)
        vision_combo=ttk.Combobox(intro,textvariable=vision_var,state="normal")
        vision_combo.grid(row=0,column=1,sticky="ew",pady=3)
        ttk.Label(intro,text="Чат — понимает твои фразы:").grid(row=1,column=0,sticky="w",padx=(0,8),pady=3)
        chat_combo=ttk.Combobox(intro,textvariable=chat_var,state="normal")
        chat_combo.grid(row=1,column=1,sticky="ew",pady=3)
        ttk.Label(intro,text="Это теперь две независимые роли. Можно, например, оставить Qwen для чата, а MiniCPM дать только изображения.",
                  foreground="#666",wraplength=820).grid(row=2,column=0,columnspan=2,sticky="w",pady=(6,0))

        bar=ttk.Frame(win,padding=(10,0,10,4))
        bar.grid(row=1,column=0,sticky="ew")
        bar.columnconfigure(0,weight=1)
        ttk.Label(bar,textvariable=status_var).grid(row=0,column=0,sticky="w")
        ttk.Label(bar,textvariable=detail_var,foreground="#666").grid(row=1,column=0,sticky="w")

        cat=ttk.LabelFrame(win,text="Каталог моделей — выбери строку и нажми «Скачать выбранную»",padding=7)
        cat.grid(row=2,column=0,sticky="nsew",padx=10,pady=(0,6))
        cat.columnconfigure(0,weight=1); cat.rowconfigure(0,weight=1)
        tree=ttk.Treeview(cat,columns=("tag","size","role","status","note"),show="headings",selectmode="browse")
        tree.heading("tag",text="Ollama-тег"); tree.heading("size",text="Размер"); tree.heading("role",text="Роль"); tree.heading("status",text="Статус"); tree.heading("note",text="Зачем тестируем")
        tree.column("tag",width=205,anchor="w"); tree.column("size",width=80,anchor="center"); tree.column("role",width=105,anchor="center"); tree.column("status",width=135,anchor="center"); tree.column("note",width=430,anchor="w")
        y=ttk.Scrollbar(cat,orient="vertical",command=tree.yview); tree.configure(yscrollcommand=y.set)
        tree.grid(row=0,column=0,sticky="nsew"); y.grid(row=0,column=1,sticky="ns")

        actions=ttk.Frame(cat)
        actions.grid(row=1,column=0,columnspan=2,sticky="ew",pady=(7,0))
        choose_v=ttk.Button(actions,text="Использовать для Vision")
        choose_c=ttk.Button(actions,text="Использовать для чата")
        download_btn=ttk.Button(actions,text="Скачать выбранную")
        refresh_btn=ttk.Button(actions,text="Обновить статусы")
        probe_btn=ttk.Button(actions,text="Проверить запуск")
        choose_v.pack(side="left"); choose_c.pack(side="left",padx=5); download_btn.pack(side="left",padx=5); probe_btn.pack(side="left",padx=5); refresh_btn.pack(side="left")

        quick=ttk.Frame(cat)
        quick.grid(row=2,column=0,columnspan=2,sticky="ew",pady=(7,0))
        ttk.Label(quick,text="Быстро скачать:").pack(side="left")
        quick_qwen=ttk.Button(quick,text="Qwen 3.5 9B — рекомендую")
        quick_qwen.pack(side="left",padx=(6,4))
        quick_gemma=ttk.Button(quick,text="Gemma 4 12B")
        quick_gemma.pack(side="left",padx=4)

        custom=ttk.LabelFrame(win,text="Другие модели Ollama и путь к Blender",padding=8)
        custom.grid(row=3,column=0,sticky="ew",padx=10,pady=(0,6))
        custom.columnconfigure(1,weight=1)
        ttk.Label(custom,text="Тег:").grid(row=0,column=0,sticky="w",padx=(0,6))
        ttk.Entry(custom,textvariable=custom_var).grid(row=0,column=1,sticky="ew")
        custom_download=ttk.Button(custom,text="Скачать")
        custom_download.grid(row=0,column=2,padx=(6,0))
        ttk.Label(custom,text="Например, если позже появится новая модель, просто впиши её Ollama-тег здесь. Код менять не понадобится.",
                  foreground="#666").grid(row=1,column=0,columnspan=3,sticky="w",pady=(5,0))
        ttk.Label(custom,text="Blender:").grid(row=2,column=0,sticky="w",padx=(0,6),pady=(7,0))
        ttk.Entry(custom,textvariable=blender_var).grid(row=2,column=1,sticky="ew",pady=(7,0))
